window.JVVNL_BANKS=window.JVVNL_BANKS||{};JVVNL_BANKS['corporate-accounting']={"slug":"corporate-accounting","name":"Corporate Accounting","count":505,"questions":[{"id":"pyq-260","sourceNumber":260,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"X and Y are partners in a partnership firm without any agreement. X has withdrawn ₹ 55,000 out of his capital as drawings. What is the interest on drawings that may be changed from X by the firm?","options":["Interest at the rate of 6% per month","Interest at the rate of 6% per annum","No interest to be charged","Interest at the rate of 5% per annum"],"answer":2,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why C is correct — No interest:** In the absence of a partnership agreement, the Indian Partnership Act’s default rule does not provide for charging interest on drawings. Interest on drawings is charged only if the partnership deed/agreement provides for it. **Exam cue:** no agreement → no interest on drawings under the default rule.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"7e14e754541f6fabb554e477f6661408f70640f55984c27778205db1ab44e5dd","kind":"pyq"},{"id":"pyq-262","sourceNumber":262,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"_______ is an umbrella organisation for operating retail payments and settlement systems in India, an initiative of Reserve Bank of India (RBI) and India Bank's Association (IBA) under tl1e provisions of the Payment and Settlement Systems Act. 2007.","options":["New Payments Corporation of India","National Payments Corporation of India","Nation Level Payments and Settlement Corporation","National Payments Company oflndia"],"answer":1,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why B is correct — National Payments Corporation of India (NPCI):** NPCI is the umbrella organisation for operating retail payment and settlement systems in India. It was established as an initiative of the Reserve Bank of India and the Indian Banks’ Association and operates under the Payment and Settlement Systems Act, 2007 framework. **Exam cue:** retail payment systems/UPI/RuPay/IMPS → NPCI.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"3933547df5850abcd30bb2772c19958ab2e64a1bc5b995eccebb8bd392052984","kind":"pyq"},{"id":"pyq-263","sourceNumber":263,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Vhich of the following is correct?","options":["Real GDP is the NDP at constant price + Depreciation","Disposable income = Personal income + Personal direct taxes","Disposable income = Personal income + Personal direct","According to the Income Mechod. GNP = Wages and salaries + Rent - Dividends - Undiscributed corporate profits - Mixed incomes + Direct and indirect taxes - Depreciation -Net income from abroad"],"answer":0,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why A is correct:** Gross Domestic Product (GDP) equals Net Domestic Product (NDP) plus depreciation/consumption of fixed capital. Therefore real GDP at constant prices = real NDP at constant prices + depreciation at constant prices. Disposable income is generally personal income minus personal direct taxes, not plus taxes. **Exam cue:** gross = net + depreciation.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"7766f368b226014003c92716763afb1b52ad163e85052c59b96bb2b8ee134d65","kind":"pyq"},{"id":"pyq-264","sourceNumber":264,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following is NOT an agency function of the bank?","options":["Payment of tax","Payment of rent","Collection of dividends","ATM facilities"],"answer":3,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why D is correct — ATM facilities:** Agency services performed by a bank on behalf of customers include payment of taxes or rent and collection of dividends. ATM facilities are a delivery channel/self-service banking facility, not typically classified as an agency function in this traditional classification. **Exam cue:** collecting/paying on customer’s behalf → agency function.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8cdf00246c09e605e2431891b79f5d0980ac0b1aa755f0e8d1301f35d4c99469","kind":"pyq"},{"id":"pyq-265","sourceNumber":265,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following options is an INCORRECT pair considering a firm's balance sheet?","options":["Tangible assets - trademarks","Fictitious assets - discount on issue of shares","Current assets - Bills receivable","Wasting assets - Oi Wells"],"answer":0,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022 | Also from: Corporate Accounting 404 Bank — PYQ: SSC CGL Tier-2 Fin&Eco, 2022-Aug","explanation":"**Why A is correct — incorrect pair:** Trademarks are intangible assets, not tangible assets. Discount on issue of shares was traditionally presented as a fictitious/deferred asset in older exam classifications, though modern financial reporting generally does not treat it as a genuine asset. Bills receivable are current assets, and oil wells are wasting assets. **Exam note:** this is an older balance-sheet classification question.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: SSC CGL Tier-2 Fin&Eco, 2022-Aug","explanation":"Trademarks are INTANGIBLE assets, so that pair is wrong; the other three pairs are correct. [PYQ: SSC CGL Tier-2 Fin&Eco, 2022-Aug]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"4c572122aa62088a1dafb79b98a165016924051e31bc255d3f4ffaee5fa3c00e","kind":"pyq"},{"id":"pyq-266","sourceNumber":266,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The _______ Account shows the distribution of profit after the same has been earned and computed by a partnership firm .","options":["Profit and Loss Appropriation","Trading","Profit and Loss","Manufacturing"],"answer":0,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why A is correct — Profit and Loss Appropriation Account:** The Profit and Loss Appropriation Account shows how an already-earned partnership profit is distributed among partners, including interest on capital, partner salary/commission and the remaining profit share, according to the partnership deed. The Profit and Loss Account first determines net profit. **Exam cue:** calculate profit → P&L; distribute profit → appropriation account.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The _______ Account shows the distribution of profit after the same has been earned and computed by a partnership firm .","options":["Profit and Loss Appropriation","Trading","Profit and Loss","Manufacturing"],"answer":0,"explanation":"**Why A is correct — Profit and Loss Appropriation Account:** The Profit and Loss Appropriation Account shows how an already-earned partnership profit is distributed among partners, including interest on capital, partner salary/commission and the remaining profit share, according to the partnership deed. The Profit and Loss Account first determines net profit. **Exam cue:** calculate profit → P&L; distribute profit → appropriation account.","revision":"original","contentSignature":"410b88f2a6f73a5cade273c4292868974bfeebf97962c2c8cbcef9e4f6ef4d08"}],"contentSignature":"410b88f2a6f73a5cade273c4292868974bfeebf97962c2c8cbcef9e4f6ef4d08","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"pyq"},{"id":"pyq-267","sourceNumber":267,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following is (are an example (s) of fictitious assets? (i) Debit balance of Profit and Loss account (ii) Goodwill","options":["Only (i)","Both (i) and (ii)","Neither (i) nor (ii)","Only (ii)"],"answer":0,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022 | Also from: Corporate Accounting 404 Bank — PYQ: SSC CGL Tier-2 Fin&Eco, 2022-Aug","explanation":"**Why A is correct — Only (i):** A debit balance in the Profit and Loss Account represents accumulated losses and was traditionally classified as a fictitious asset in older exam terminology, although it is not a real resource. Goodwill is an identifiable/intangible asset when recognised under applicable accounting rules, not a fictitious asset. **Exam note:** distinguish old exam terminology from modern presentation.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: SSC CGL Tier-2 Fin&Eco, 2022-Aug","explanation":"A P&L debit balance is a fictitious asset; goodwill is an intangible asset, not fictitious. [PYQ: SSC CGL Tier-2 Fin&Eco, 2022-Aug]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"927daf0a834b9ae83815a185a2cb69dcf8b9e73a32f992410f2defeacc315a6a","kind":"pyq"},{"id":"pyq-268","sourceNumber":268,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Kohler defines Single Entry System as , “A System of book-keeping in which as a rule only records of _____ and of personal accounts are maintained”.","options":["Fixed Assets","Cash","Goodwill","Stock"],"answer":1,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why B is correct — Cash:** Kohler’s description of the single-entry system refers to a bookkeeping system in which, as a rule, only cash and personal accounts are maintained. It is incomplete compared with double-entry bookkeeping because not every transaction is recorded with both debit and credit aspects. **Exam cue:** single entry → mainly cash and personal accounts.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"0bb1d90053b0229e95d65a993c4461b3cb6ad518fcd59e19a50addaefbf13e41","kind":"pyq"},{"id":"pyq-269","sourceNumber":269,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In case of a Partnership Firm, a _____ is prepared to show the distribution of profits among different partners.","options":["Profit & Loss A/c","Partner’s Capital A/c","Drawings A/c","Profit & Loss Appropriation A/c"],"answer":3,"source":"SSC CGL Tier-2 AAO, Sep 2019 | Also from: Corporate Accounting 404 Bank — PYQ: SSC CGL Tier-2 AAO, 2019-Sep","explanation":"**Why D is correct — Profit and Loss Appropriation Account:** A partnership uses the Profit and Loss Appropriation Account to distribute profit among partners in accordance with the partnership agreement. It records appropriations such as partner salary, interest on capital and the allocation of residual profit. **Memory cue:** appropriation = allocation/distribution.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: SSC CGL Tier-2 AAO, 2019-Sep","explanation":"The P&L Appropriation Account distributes net profit - interest on capital, salaries, interest on drawings and the profit share. [PYQ: SSC CGL Tier-2 AAO, 2019-Sep]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"cc399f0c40876dfc823eb3ea863bfb4bd331b72eeaa68d45dcdaec16114d0588","kind":"pyq"},{"id":"pyq-270","sourceNumber":270,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"As per the 2018-19 data published by the Ministry of Statistics & Program Implementation, the share of agriculture & allied sector is _____ % to the Gross Value Added in India.","options":["29.73","54.4","15.87","27.03"],"answer":2,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Data fact:** Agriculture and allied sectors contributed **15.87%** of Gross Value Added in the 2018–19 data series. This is a year- and series-specific statistic, not a current-year share; national-account estimates are revised over time. **Exam tip:** learn the number together with its year.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8ed0d9182b218df4f38eb435a8a5d27312f0f3b3dc77b8fa3523a237fde0fbdd","kind":"pyq"},{"id":"pyq-271","sourceNumber":271,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"______ is the portal which assists the corporate sectors in India with regard to the filing of various compliances in a seamless and transparent manner.","options":["Company Portal","MCA 21","ROC India Portal","MCA 11"],"answer":1,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why B is correct — MCA21:** MCA21 is the Ministry of Corporate Affairs’ electronic portal for company and LLP filings, statutory forms and related compliance services. It was designed to support online filing and more transparent processing of corporate compliances. **Exam cue:** corporate e-filings in India → MCA21.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"7949fd2fb6c3e2cc9f7703773052007067d42b350356d27773ae51f441509a6e","kind":"pyq"},{"id":"pyq-272","sourceNumber":272,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The following information is available for Ravi Corporation EPS – Rs. 4 ROI – 18% Rate of return required by shareholders – 15% What will be the price per share as per Walter model if the payout ratio is 40%?","options":["Rs. 29.87","Rs. 29.33","Rs. 28.80","Rs. 30.63"],"answer":0,"source":"UGC NET Commerce, Oct 2020","explanation":"**Why A is correct — ₹29.87:** Walter’s model: (P=[D+(r/K_e)(E-D)]/K_e). EPS E = ₹4; payout ratio 40%, so dividend D = ₹1.60 and retained earnings = ₹2.40. Return on investment r = 18%; required return (K_e=15%). Price = [₹1.60 + (0.18/0.15 × ₹2.40)]/0.15 = ₹4.48/0.15 ≈ **₹29.87**. **Exam cue:** Walter’s model uses payout, EPS, ROI and cost of equity.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"a713e4d7c9ad3befff246d6c0e8e6b02ea635d4823623487a4e20db6e1eeae81","kind":"pyq"},{"id":"pyq-273","sourceNumber":273,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A Ltd. has a share capital of 5,000 equity shares of Rs. 100 each having a market value of Rs. 150 per share. The company wants to raise additional funds of Rs. 1,20,000 and offers to the existing shareholders the right to apply for a new share at Rs. 120 for every five share held. What would be the value of right?","options":["Rs.5","Rs.6","Rs.6.5","Rs.5.5"],"answer":0,"source":"UGC NET Commerce, Oct 2020 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2020-Oct-E","explanation":"**Why A is correct — ₹5 per right:** A shareholder holds 5 old shares at market value ₹150 each and can buy 1 new share for ₹120. The theoretical ex-rights price = (5 × ₹150 + ₹120) ÷ 6 = ₹145. Value of one right = Cum-right price ₹150 − Ex-rights price ₹145 = **₹5**. **Shortcut:** right value = (market price − subscription price)/(rights needed + 1).","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2020-Oct-E","explanation":"Value of right = (150 - 120)/(5 + 1) = 30/6 = Rs.5 per existing share. [PYQ: UGC NET Commerce, 2020-Oct-E]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c2423217b645704b513aa62b8d7882ae9404318e18a55a042ef09ddb5eb71594","kind":"pyq"},{"id":"pyq-274","sourceNumber":274,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company purchased a machinery on 01-01-2015 for a sum of Rs. 60,000. The retail price index on the date was 150. What is the value of machinery according to CPP method on 31 December 2015 when the price index was 200?","options":["Rs. 1,00,000","Rs. 90,000","Rs. 80,000","Rs. 70,000"],"answer":2,"source":"UGC NET Commerce, Oct 2020","explanation":"**Why C is correct — ₹80,000:** Under the Current Purchasing Power (CPP) method, historical cost is restated by the ratio of current price index to the index at acquisition. Restated value = ₹60,000 × (200/150) = **₹80,000**. **Formula:** historical cost × closing index/original index.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"85acb85de356547cdd51b603bd8d9a93aecc8324f689a68109ae94ef710c2099","kind":"pyq"},{"id":"pyq-275","sourceNumber":275,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"X and Y are partners in a business sharing profits and losses in the ratio of 3:2. They admit Z as a new partner with 1/5 share in the profits. Calculate the new profit-sharing ratio of the partners.","options":["12:8:5","12:8:6","12:7:6","12:3:7"],"answer":0,"source":"UGC NET Commerce, Oct 2020 | Also from: UGC NET Commerce, Mar 2023 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2020-Oct-E","explanation":"X and Y share profits 3:2. Z receives 1/5, leaving 4/5 for X and Y in their old ratio. X = 3/5 × 4/5 = 12/25; Y = 2/5 × 4/5 = 8/25; Z = 1/5 = 5/25. New ratio = 12:8:5 (option A). The earlier key marking option D was inconsistent with the calculation and has been corrected.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"corrected-key","alternateExplanations":[{"source":"UGC NET Commerce, Mar 2023","explanation":"**Why A is correct — 12:8:5:** X and Y share the old profit in the ratio 3:2. Z receives 1/5, leaving 4/5 for X and Y in their old ratio. X = 3/5 × 4/5 = 12/25; Y = 2/5 × 4/5 = 8/25; Z = 1/5 = 5/25. New ratio = **12:8:5**.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded"},{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2020-Oct-E","explanation":"Z takes 5/25; X = 3/5 x 4/5 = 12/25, Y = 2/5 x 4/5 = 8/25 - ratio 12:8:5. [PYQ: UGC NET Commerce, 2020-Oct-E]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"2e32978d0397b40183a474301302ec3b703e86439a6ea717b95e923963ce24e8","kind":"pyq"},{"id":"pyq-276","sourceNumber":276,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following are false? I. Partners are not bound to carry on the business of the firm to the greatest common advantage. II. Where a partner is entitled to interest on capital subscribed by him, such interest shall be payable whether or not there are profits. III. An outgoing partner has a right to claim a share in the profits of the firm till his account is finally settled. IV. A partner may be expelled from the firm only with the consent of all other partners. Choose the correct answer from the options given below:","options":["I, II, IV only","I, III, IV only","II, IV, III only","III, IV only"],"answer":0,"source":"UGC NET Commerce, Oct 2020","explanation":"**Why A is correct — I, II and IV are false:** Partners must carry on the business to the greatest common advantage of all partners. Interest on capital is payable only according to the partnership agreement and is not automatically payable when there are no profits. An outgoing partner may, in certain circumstances, claim a share of profits attributable to the use of their share of property until accounts are settled. Expulsion is valid only when the partnership agreement gives that power and it is exercised in good faith; unanimous consent of all other partners is not an absolute rule in every case. **Legal note:** apply the exact Partnership Act provisions and deed wording.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"9061a39d80edc2df18e7c35127c64f14c738e51d8182089e7c2c3c76b0252eb7","kind":"pyq"},{"id":"pyq-277","sourceNumber":277,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In which of the following stages of product life cycle a company reduces sales promotion to take advantage of heavy consumer demand?","options":["Introduction","Growth","Maturity","Decline"],"answer":2,"source":"UGC NET Commerce, Oct 2020","explanation":"**Why C is the supplied answer — Maturity:** During maturity, sales growth slows and the product is established in the market. Companies may reduce promotional spending relative to the growth stage and focus on defending market share, customer retention and efficient distribution. In introduction, promotion is usually high to create awareness; in decline, the firm may reduce support further or withdraw the product. **Exam cue:** heavy demand/established product → maturity stage.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"1a09fc76d31b3b38726674579dc60fe02ba8139d8ced4703fabcbd93d4e0a43d","kind":"pyq"},{"id":"pyq-279","sourceNumber":279,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The ‘going concern concept’ is the underlying basis for __________.","options":["Disclosing the market value of securities.","Consolidating the accounts of subsidiary companies with those of parent company.","Depreciating fixed assets over their useful lives.","Disclosing the sales and other operating information in the income statement."],"answer":2,"source":"UGC NET Commerce, Oct 2020","explanation":"**Why C is correct — Depreciating fixed assets:** The going-concern concept assumes the business will continue operating for the foreseeable future rather than liquidating immediately. This allows the cost of a fixed asset to be allocated over its useful life through depreciation instead of measuring it solely at a forced-sale value. **Exam cue:** continued use over useful life → depreciation under going concern.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c88b1a88090587376396236e03c24c99ac63f538242b8aee9915e62e2a423086","kind":"pyq"},{"id":"pyq-280","sourceNumber":280,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Match List I with List II List I I. Limited liability partnership II. Particular partnership III. Partnership IV. Mutual agency List II 1. It can be formed with a minimum of two individuals or body corporate through their nominees 2. It is formed for a specific venture or for a particular period 3. It is an association of two or more individuals 4. A partner is both an agent and a principal in a partnership firm Choose the correct answer from the options given below:","options":["I-1, II-2, III-3, IV-4","I-2, II-3, III-1, IV-4","I-2, II-1, III-3, IV-4","I-4, II-2, III-1, IV-3"],"answer":0,"source":"UGC NET Commerce, Oct 2020 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2020-Oct-M","explanation":"**Why A is correct:** An LLP can be formed by at least two individuals or body corporates through their nominees (I–1, subject to the LLP Act’s eligibility rules). A particular partnership is formed for a specific venture or period (II–2). A partnership is an association of two or more persons carrying on business in common with a view to profit (III–3). Mutual agency means each partner can act as agent for the firm and other partners within the business, and is also a principal in relation to the other partners (IV–4).","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2020-Oct-M","explanation":"LLP needs minimum two partners (individuals or bodies corporate); particular partnership is venture-specific; partnership is an association of persons; mutual agency makes a partner agent and principal. [PYQ: UGC NET Commerce, 2020-Oct-M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"7120ec4d93f5ed6529a55aa3ae4dad3c356d09039ec1343b1d86fe018c7dd1c4","kind":"pyq"},{"id":"pyq-281","sourceNumber":281,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following is not a major direct selling company in India?","options":["Eureka Forbes","Amway India Enterprises","Modicare","Hindustan Unilever Ltd."],"answer":3,"source":"UGC NET Commerce, Oct 2020","explanation":"**Why D is the correct answer — Hindustan Unilever Ltd.:** Eureka Forbes, Amway India Enterprises and Modicare are commonly associated with direct-selling business models. Hindustan Unilever is primarily a consumer-goods manufacturer and marketer using broad distribution channels, rather than a direct-selling company in the classification intended by this question. **Exam cue:** direct selling → products sold through individual sellers/distributors rather than conventional retail channels.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"35343a3146e032728b6271f6adcdc1509caefbf278ccd982e3f05ff624acf40f","kind":"pyq"},{"id":"pyq-282","sourceNumber":282,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"To prevent opportunistic takeover of domestic firms amid Covid-19 pandemic, Foreign Direct Investment (FDI) from countries that share borders with India is allowed through","options":["Automatic Route","Government Route","FIPB Route","DPIIT Route"],"answer":1,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why B is correct — Government Route:** Under India’s policy introduced in 2020, entities from countries sharing a land border with India, or where the beneficial owner is situated in or is a citizen of such a country, require government approval for covered investments. The policy was introduced to prevent opportunistic takeovers during the pandemic. **Time-sensitive legal note:** investment rules can be amended; answer according to the source exam’s policy period.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"3e89074e879bc83ab6678d2fd01ed43c096a26a7c7c0ad1c87b93619fe38d50e","kind":"pyq"},{"id":"pyq-283","sourceNumber":283,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In case the purchasing company agrees to act as the agent of the vendor for collection of the book debts, in the books of the purchasing company, the amount of debtors should be credited to","options":["Vendor’s debtors account","Vendor’s suspense account","Debtors account","Creditors account"],"answer":1,"source":"UGC NET Commerce, Nov 2021 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-25M","explanation":"**Why B is correct — Vendor’s suspense account:** If the purchasing company acts as an agent to collect the vendor’s book debts, the collections are not its own sales revenue or ordinary debtor receipts. Where the relevant vendor-specific account cannot be directly credited in the stated bookkeeping arrangement, the source uses the vendor’s suspense account as the temporary balancing account. **Source note:** agency-accounting entries depend on the exact arrangement; check the original textbook’s journal-entry convention.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-25M","explanation":"Debtors collected as agent for the vendor are parked in a vendor suspense account until remitted. [PYQ: UGC NET Commerce, 2021-Nov-25M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"19a0457bc077851ae6135772ee9724523aa64a802935ef96ad4153872345f267","kind":"pyq"},{"id":"pyq-284","sourceNumber":284,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"When the value of “Investment in subsidiary” in the holding company’s balance sheet is more than the book value of the net assets acquired, the difference represents","options":["Capital reserve on consolidation","Goodwill on consolidation","Minority Interest","Post acquisition profit"],"answer":1,"source":"UGC NET Commerce, Nov 2021 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-25M","explanation":"**Why B is correct — Goodwill on consolidation:** If the cost/value of the investment in a subsidiary exceeds the holding company’s share of the book value of identifiable net assets acquired, the difference is generally treated as goodwill on consolidation under the applicable accounting framework. If the investment is below the relevant share of net assets, the difference may be a capital reserve/bargain-purchase gain. **Exam cue:** investment cost above share of net assets → goodwill.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-25M","explanation":"Paying more than the share of net assets bought means the parent paid for the subsidiary's goodwill. [PYQ: UGC NET Commerce, 2021-Nov-25M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"7722cbf4a32e444aa52314a9594e6489981ee10663bf499a5476bec0d5a59146","kind":"pyq"},{"id":"pyq-285","sourceNumber":285,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"X and Y are partners, sharing profits and losses in the ratio of 4:3. They admit Z into the partnership for 1/5th share. X and Y decide to share future profits in the ratio of 2:1. What is the sacrificing ratio of X and Y?","options":["4:3","13:8","8:13","4:17"],"answer":3,"source":"UGC NET Commerce, Nov 2021 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov- 25M","explanation":"**Why D is correct — Sacrificing ratio 4:17:** Old shares: X = 4/7, Y = 3/7. Z receives 1/5, leaving 4/5 for X and Y in their new ratio 2:1. New X = 4/5 × 2/3 = 8/15; new Y = 4/5 × 1/3 = 4/15. Sacrifice: X = 4/7 − 8/15 = 4/105; Y = 3/7 − 4/15 = 17/105. Sacrificing ratio = **4:17**.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov- 25M","explanation":"X new = 2/3 x 4/5 = 8/15, sacrifice = 4/7 - 8/15 = 4/105; Y new = 1/3 x 4/5 = 4/15, sacrifice = 3/7 - 4/15 = 17/105. Ratio 4:17. [PYQ: UGC NET Commerce, 2021-Nov- 25M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"91a2e0dfa993a0dc9d5ee4e0bd72613e55169e26042b6e164083bf0a56ca63e5","kind":"pyq"},{"id":"pyq-286","sourceNumber":286,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"According to the theory of dividend, the firm should follow its investment policy of accepting all positive NPV projects and paying out dividends if and only if, funds are available:","options":["Bird in hand theory","Investor rationality theory","100 percent retention theory","Residual theory"],"answer":3,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why D is correct — Residual theory:** Under the residual dividend theory, the firm first accepts all positive-NPV projects and funds investment needs consistent with its target capital structure. Dividends are paid only from earnings left over after those investment requirements are met. **Memory cue:** investment first; dividend from residual funds.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"30c2033563ba3746d83ca74531db84356b36d8e46ffe16bb42a27514e08e2699","kind":"pyq"},{"id":"pyq-287","sourceNumber":287,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following distinction(s) is/are not correct between public issue and rights issue? (1) In public issue, application for shares are invited from the general public and in rights issue, the shares are offered to existing shareholder. (2) In public issue, there is no question of any over-subscription and in in rights issue the shares may be under subscribed or oversubscribed leading to prorate allotment. (3) The price of public issue is generally less than the market price and in rights issue, the price is deliberately made less than the market price. (4) In a public issue, the communication of the issue is through prospects or advertisements and in rights issue the communication is between the company and the existing numbers of the company. Choose the most appropriate answer from the options given below.","options":["2 only","4 only","1 and 3 only","3 and 4 only"],"answer":0,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why A is correct — statement 2 only:** Public issues invite applications from the general public; rights issues are offered to existing shareholders. A public issue can be oversubscribed and may require proportionate allotment, so statement 2 is incorrect. Public-issue prices are not invariably below market price, while rights issues are often priced below market to make the offer attractive; statements 3 and 4 broadly describe common distinctions. **Exam cue:** both public and rights issues can be under/oversubscribed.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"5b5a0ca79b8253ffd7fc7915fbace80cc0421230c9f562666466afa0c799c8af","kind":"pyq"},{"id":"pyq-289","sourceNumber":289,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Match List I with List II: List I (Method) (a) Lump-sum payment method (b) Net Assets Method (c) Net Payment Method (d) Swap Ratio Method List II (Purchase consideration) (i) Calculated by adding up the total amount (money value) of existing shares, preference shares and cash received from the purchasing company for the shareholders of the vendor company. (ii) On the basis of ratio in which the shares of the transferee company are to be exchanged for the shares of the transferor company (iii) The amount to be paid by the transferee company to transferor company for amalgamation of its business (iv) Arrived at by adding the agreed value of assets taken over and deducting there from the agreed values of liabilities. Choose the correct answer from the options given below.","options":["(a)-(iii), (b)-(ii), (c)-(i), (d)-(iv)","(a)-(iii), (b)-(iv), (c)-(i), (d)-(ii)","(a)-(iv), (b)-(i), (c)-(ii), (d)-(iii)","(a)-(iv), (b)-(ii), (c)-(ii), (d)-(i)"],"answer":1,"source":"UGC NET Commerce, Nov 2021 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-25M","explanation":"**Why B is correct:** Lump-sum payment method identifies the total amount payable for the business (a–iii). Net-assets method calculates agreed value of assets taken over minus agreed liabilities (b–iv). Net-payment method totals the forms of consideration—cash and securities—given to the vendor’s shareholders (c–i). Swap-ratio method uses the ratio at which shares of the transferee are exchanged for shares of the transferor (d–ii). **Exam cue:** net assets = assets less liabilities; swap ratio = share exchange ratio.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-25M","explanation":"Lump sum = fixed amount payable; net assets = assets minus liabilities; net payment = sum of all payments to vendor shareholders; swap ratio = exchange ratio of shares. [PYQ: UGC NET Commerce, 2021-Nov-25M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"cbab1284c5a311d35037f06efdcc6494e70583093e0452fe07daad14b9cd076a","kind":"pyq"},{"id":"pyq-291","sourceNumber":291,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Arrange the following stages of formation of companies in a proper sequence. 1. Promotion stage 2. Raising of share capital stage 3. Incorporation stage 4. Commencement stage 5. Selection of name Choose the correct answer from the options given below.","options":["3, 1, 5, 4, 2","2, 5, 1, 3, 4","1, 5, 3, 2, 4","4, 1, 2, 3, 5"],"answer":2,"source":"UGC NET Commerce, Nov 2021 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-25M","explanation":"**Why C is correct — 1, 5, 3, 2, 4:** The conventional sequence is promotion, selection/reservation of the company name, incorporation, raising share capital where required, and commencement of business after meeting applicable conditions. **Legal note:** under the Companies Act, 2013, the exact steps and commencement requirements differ by company type and have been amended; answer this historical sequence in the source’s exam framing.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-25M","explanation":"Sequence: promotion -> name selection -> incorporation -> raising capital -> commencement of business. [PYQ: UGC NET Commerce, 2021-Nov-25M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"19edf7e6725ac848b516369a336019ac131c72af0187ed8c2b3f6d7d831f2e64","kind":"pyq"},{"id":"pyq-292","sourceNumber":292,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Amalgamation adjustment account is used for recording:","options":["Capital Reserve in the books of the transferee company","General Reserve in the books of the transferee company","Statutory Reserve in the books of the transferee company","Revenue Reserve in the books of the transferee company"],"answer":2,"source":"UGC NET Commerce, Nov 2021 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-25E","explanation":"**Why C is correct — Statutory Reserve:** Under the pooling-of-interests method for amalgamations in the relevant accounting framework, statutory reserves of the transferor may need to be preserved in the transferee’s books. An amalgamation adjustment account is used to maintain that statutory reserve presentation while accounting for the amalgamation. **Exam cue:** statutory reserve preservation → amalgamation adjustment account.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-25E","explanation":"Under the purchase method, statutory reserves of the transferor that must continue are recorded by debiting the amalgamation adjustment account. [PYQ: UGC NET Commerce, 2021-Nov-25E]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"f157ab0310361dca8366e1255f606a0445341367c734e689c7c201766b0df4d6","kind":"pyq"},{"id":"pyq-294","sourceNumber":294,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following are included in person under section 17 (1)? (1) A Hindu Undivided Family (HUF) (2) A company (3) A firm (4) An individual (5) A local authority (6) An association of persons Choose the correct answer from the options given below:","options":["1, 3, 4 and 6 only","3, 4, 5 and 6 only","2, 4, 5 and 6 only","1, 2, 3, 4, 5 and 6 only"],"answer":3,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why D is correct in the intended definition:** The Income-tax Act defines “person” broadly to include an individual, Hindu Undivided Family, company, firm, association of persons/body of individuals and local authority, among other categories. Thus all six listed types are included in the broad definition. **Source correction note:** the definition is in section 2(31), not section 17(1), which appears to be a transcription error in the question.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e2ef99a838893214360ac7fda4f4e55130b06c25c31bd39acdcea91ee0a63f6a","kind":"pyq"},{"id":"pyq-295","sourceNumber":295,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Match List I with List II: List I a. Bonus shares b. Demat shares c. Right issue d. Sweat equity share List II i. Invitation to existing shareholders to purchase additional new shares ii. Issue is made to existing members free of charge iii. Shares issues by a company to its employees/directors at a discount for providing know-how iv. Shares in electronic form Choose the correct answer from the options given below:","options":["a-ii, b-iv, c-i, d-iii","a-ii, b-i, c-iii, d-iv","a-iv, b-iii, c-ii, d-i","a-iv, b-i, c-ii, d-iii"],"answer":0,"source":"UGC NET Commerce, Nov 2021 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-25E","explanation":"**Why A is correct:** Bonus shares are issued to existing members without additional payment (a–ii); demat shares are held in electronic form (b–iv); a rights issue offers additional shares to existing shareholders (c–i); sweat-equity shares may be issued to employees/directors at a discount or for non-cash consideration for know-how, intellectual property or value additions, subject to statutory conditions (d–iii). **Memory cue:** bonus = free; demat = electronic; rights = existing holders; sweat equity = employee/director contribution.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-25E","explanation":"Bonus = free to members; demat = electronic form; rights = invitation to existing shareholders; sweat equity = discount issue to employees/directors for know-how. [PYQ: UGC NET Commerce, 2021-Nov-25E]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"a83ed896c4c3d6929bafaa5443cebfe39f0f8250df49d624593ff4e5a12c46c8","kind":"pyq"},{"id":"pyq-296","sourceNumber":296,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The assets of the Partnership firm, including any sums contributed by the partners to make-up deficiencies of capital at the time of dissolution, shall be applied in the following manner and order: (1) In paying each partner rateably what is due to him for advances as distinguished from capital. (2) In paying to each partner rateably what is due to him on account of capital. (3) In paying the debts of the firm to third parties. (4) Dividing among the partners in the proportion in which they were entitled to share profits. Choose the correct answer from the options given below:","options":["3, 1, 2, 4","3, 2, 1, 4","1, 2, 3, 4","2, 3, 1, 4"],"answer":0,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why A is correct — 3, 1, 2, 4:** On dissolution of a partnership, assets are applied first to debts of the firm to third parties (3), then to partners’ advances distinct from capital (1), then to partners’ capital balances (2), and finally any surplus is divided in the profit-sharing ratio (4). **Memory cue:** outside creditors → partner loans/advances → capital → surplus.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e09067363c30b51f6ca54062d106e0025d45bba5980fb98eb6af5af23f062be5","kind":"pyq"},{"id":"pyq-297","sourceNumber":297,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Given below are two statements: Statement I: If firms are disproportionately powerful, the market leader makes the first move and captures two-thirds of the market share, while the follower firm gets only a third of the market share. Statement II: Oligopolist firms do better by cooperating than following its dominant strategy. In the light of the above statements. choose the most appropriate answer from the options given below:","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"answer":0,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why A is the supplied answer:** Statement I describes a dominant firm/leader capturing a larger share than the follower in the model assumed by the question. Statement II reflects the game-theory idea that oligopolists can earn higher joint profits by cooperating than by each independently following a dominant strategy, though cooperation may be unstable because each firm has an incentive to deviate. **Exam cue:** collusion can maximise joint profit, but it may be difficult to sustain.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e125d719a40a79d6a7678b454b9ddc88c1db32c080df5d47921d7fef24ca747f","kind":"pyq"},{"id":"pyq-298","sourceNumber":298,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which statement is not true about China?","options":["FDI inflows increase by 4%","International M&A increase by 54%","Highest FDI in ICT and Pharmaceutical sector","USD 1.5 Trillion sized economy"],"answer":3,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why D is correct — USD 1.5 trillion economy:** The passage/options are drawn from a historical source about China’s FDI and international M&A. China’s economy is far larger than USD 1.5 trillion, so that statement is the one that is not true in the context of the question. The other statements are year-specific reported figures and should be checked against the original passage. **Exam cue:** passage-based question—use the cited period, not current data.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","revision":"R2","key_repaired":true,"revisionChanged":true,"revisionHistory":[{"question":"Which statement is not true about China?","options":["FDI inflows increase by 4%","International M&A increase by 54%","Highest FDI in ICT and Pharmaceutical sector","USD 1.5 Trillion sized economy Read the following passage and answer the question in the most appropriate manner: (96 – 100) Management theories help organizations to focus, communicate, and evolve. Using management theory in the workplace allows leadership to focus on their main goals. When a management style or theory is implemented, it automatically streamlines the top priorities for the organization. Management theory also allows us to better communicate with people we work with which in turn allows us to work more efficiently. By understanding management theory, basic assumptions about management styles and goals can be assumed and can save time during daily interactions and meetings within an organization. Theories can only reach so far, and management theories are no exception. There is no such thing as a one-size-fits-all management theory. What may work for one organization may not be relevant for another. Therefore. when one theory does not fit a particular situation. it is important to explore the option of developing a new theory that would lead in a new, more applicable direction. While some theories can stand the test of time, other theories may grow to be irrelevant and new theories will develop in their place. From the late 1700s through the early 1900s. the Industrial Revolution brought extraordinary change to the workplace and forever transformed the way companies operate. The Industrial Revolution brought better and faster technology allowing companies to perform more efficiently than ever before and giving them the ability to dramatically increase their output. In order to meet demand, company leadership had to ensure their employees were productive."],"answer":3,"explanation":"**Why D is correct — USD 1.5 trillion economy:** The passage/options are drawn from a historical source about China’s FDI and international M&A. China’s economy is far larger than USD 1.5 trillion, so that statement is the one that is not true in the context of the question. The other statements are year-specific reported figures and should be checked against the original passage. **Exam cue:** passage-based question—use the cited period, not current data.","revision":"original","contentSignature":"37d466f1889ffeba4f8b1576ffd23363962af82cfe16c60688046fea7536686f"}],"contentSignature":"f894a065a3d03c4f86299cb073fce8a4c7517a6789630ddcb35867cc2c214535","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"pyq"},{"id":"pyq-299","sourceNumber":299,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Given below are two statements. One is labelled as Assertion A and the other is labelled as Reason R: Assertion A: The industrial revolution brought better and faster technology allowing companies to perform more efficiently than ever before and gave them ability to dramatically increase their output. Reason R: In order to meet demand, company leadership had to ensure their employees were productive. In the light of the above statements, Choose the most appropriate answer from the options given below:","options":["Both A and R are correct and R is the correct explanation of A","Both A and R are correct and R is NOT the correct explanation of A","A is correct but R is not correct","A is not correct but R is correct"],"answer":1,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why B is correct:** Both statements are true according to the passage: improved technology during the Industrial Revolution increased productive efficiency/output, and management needed to ensure employee productivity to meet the resulting demand. However, statement R describes a managerial response to rising demand; it does not directly explain why technology itself improved efficiency and increased output. **Assertion–reason cue:** both may be true without R explaining A.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"9a90f2087e1d33da9cd83ddda386a9c1ad7d81cdfc6a011ce104e3cb408b0528","kind":"pyq"},{"id":"pyq-301","sourceNumber":301,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"‘A’, ‘B’ and ‘C’ are partners sharing profits in the ratio of 3:2:1. ‘D’ is admitted for 1/6th share and ‘C’ should retain his original share. The sacrificing ratio of A and B will be:","options":["1 : 2","2 : 3","3 : 2","2 : 1"],"answer":2,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why C is correct — 3:2:** Original ratio A:B:C = 3:2:1, so their shares are 1/2, 1/3 and 1/6. C retains the original 1/6 share, and D receives 1/6, leaving A and B to share the remaining 2/3 in the same relative ratio 3:2. New A = 2/5 × 2/3 = 2/5? More directly, A’s new share is 2/5 and B’s is 4/15; sacrifices are A: 1/2 − 2/5 = 1/10 and B: 1/3 − 4/15 = 1/15. Ratio = **3:2**.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"df31c79d00b2722f52d43a0112d213defa8dfd854894d21007188560b8dff3b7","kind":"pyq"},{"id":"pyq-302","sourceNumber":302,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Fill in the blanks. For a holding company, all pre‐acquisition profits/losses of the subsidiary company are ______, while all post‐ acquisition profits/losses of the subsidiary company are _________.","options":["revenue profits/losses, capital profits/losses","capital profits, capital losses","revenue profits, revenue losses","capital profits/losses, revenue profit/losses"],"answer":3,"source":"UGC NET Commerce, Nov 2021 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov- 26M","explanation":"**Why D is correct:** In consolidation, profits earned by a subsidiary before acquisition are generally treated as capital profits because they existed before the holding company acquired its interest. Profits earned after acquisition are revenue profits for consolidation purposes and are considered when allocating post-acquisition results between the group and non-controlling interest. Losses follow the corresponding timing classification. **Exam cue:** pre-acquisition → capital; post-acquisition → revenue.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov- 26M","explanation":"Pre-acquisition profits are capital (part of the net assets purchased); post-acquisition profits are revenue, available to the group. [PYQ: UGC NET Commerce, 2021-Nov- 26M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"5d4cd717fcc8155ff12cd321362380f32570f18f09725f26f1a6f268f1677bb4","kind":"pyq"},{"id":"pyq-303","sourceNumber":303,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"What is the sustainable growth rate of the company that enjoys return on equity is 30 percent and a dividend payout ratio of 40 percent?","options":["12 per cent","18 per cent","30 per cent","40 per cent"],"answer":1,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why B is correct — 18%:** Sustainable growth rate = Return on Equity × Retention ratio. Dividend payout ratio = 40%, so retention ratio = 1 − 0.40 = 60%. Growth rate = 30% × 60% = **18%**, assuming the firm maintains its financial policy and profitability. **Formula:** g = ROE × (1 − payout ratio).","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"6cc908fe5277b2dae50568ebb0ceeb0c91ca35a25f5aeb954dbad14157ad6a7f","kind":"pyq"},{"id":"pyq-304","sourceNumber":304,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The partial integration of agricultural with non‐agricultural income is done in case of:","options":["Firm","Company","Co‐operative society","AOP/BOI"],"answer":3,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why D is correct — AOP/BOI:** Partial integration of agricultural income with non-agricultural income is used for specified categories such as individuals, HUFs, AOPs/BOIs and certain artificial juridical persons, when the statutory conditions are met. Firms and companies are not generally covered by the same partial-integration method. **Tax reminder:** apply the income thresholds and exemption limit for the relevant assessment year.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"92dc9b5851863690a556947a7dadd8909d2d5516f9bf80538cc2b44afdc8b4eb","kind":"pyq"},{"id":"pyq-305","sourceNumber":305,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following order is followed in the issue of shares under the \"Fixed Price Offer Method\"? (1) Issue of a prospectus (2) Receipt by the company of application for share (3) Selection of merchant banker (4) Issue of share certificates (5) Allotment of shares to the applicant Choose the correct answer from the options given below:","options":["1, 4, 5, 3, 2","3, 2, 1, 4, 5","3, 1, 2, 5, 4","5, 2, 1, 3, 4"],"answer":2,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why C is correct — 3, 1, 2, 5, 4:** In the source’s fixed-price issue sequence, select/appoint the merchant banker (3), issue the prospectus (1), receive applications (2), allot shares (5), and issue share certificates (4). The exact legal process varies by issue type and current securities regulations, but the question is testing this conventional sequence. **Memory cue:** appoint → disclose/issue → apply → allot → certificate.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"2363d6537c2506d0cc73a244dc35234ef8ff898d57e2c82c362ca4731a83d27a","kind":"pyq"},{"id":"pyq-306","sourceNumber":306,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Arrange in the sequence, steps in the procedure for calling a statutory meeting of the company (1) Contents of the statutory report (2) A list of members must be produced at the commencement (3) Twenty‐one days’ notice (4) Certification of the statutory report by not less than two directors, one of whom must be the managing director (5) A certified copy of the statutory report must be delivered to the Registrar Choose the correct answer from the options given below:","options":["2, 5, 3, 1, 4","1, 4, 5, 2, 3","4, 3, 2, 1, 5","3, 1, 4, 5, 2"],"answer":3,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why D is the correct sequence:** The sequence is 21 days’ notice (3), preparation of statutory report contents (1), certification by the required directors (4), delivery of a certified copy to the Registrar (5), and production of the members’ list at the meeting (2). **Important legal note:** the statutory meeting requirement is based on the older Companies Act framework and is not a current general requirement under the Companies Act, 2013. Treat this as a historical exam question.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"f8d66beadbe65634fe7683b2449b7aa220f38b3663409a25928d30ae7ab67b7e","kind":"pyq"},{"id":"pyq-307","sourceNumber":307,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Given below are two statements, one is labelled as Assertion A and the other is labelled as Reason R Assertion A: Quick ratio is a more penetrating test of liquidity than the current ratio, yet a high quick ratio does not necessarily imply sound liquidity. Reason R: A company with a high value of quick ratio can suffer from a shortage of funds if it has slow‐paying, doubtful and long duration outstanding debtors In light of the above statements, choose the most appropriate answer from the options given below","options":["Both A and R are correct, and R is the correct explanation of A","Both A and R are correct but R is NOT the correct explanation of A","A is correct but R is not correct","A is not correct but R is correct"],"answer":0,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why A is correct:** The quick ratio excludes inventory and other less-liquid current assets, so it is a stricter liquidity test than the current ratio. However, a high quick ratio can still be misleading if receivables are slow-paying, doubtful or overdue and cannot be converted into cash promptly. The reason therefore explains why a high quick ratio does not automatically guarantee sound liquidity. **Exam cue:** liquidity depends on quality and timing, not just ratio size.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"d3d4a93f388d019eaf9c131435ab34418016cfe0760191e92afad09cc48594e8","kind":"pyq"},{"id":"pyq-308","sourceNumber":308,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Given below are two statements, one is labelled as Assertion A and the other is labelled as Reason R. Assertion A: Two companies with the same general earning power and same general position in an industry, the one paying larger dividend will almost always sell at a higher price Reason R: The discounted value of near dividends is higher than the present worth of distant dividends In light of the above statements, choose the most appropriate answer from the options given below","options":["Both A and R are correct and R is the correct explanation of A","Both A and R are correct but R is NOT the correct explanation of A","A is correct but R is not correct","A is not correct but R is correct"],"answer":0,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why A is the source’s intended answer:** Both statements reflect the traditional “bird-in-the-hand” view: investors may value near-term dividends more highly than uncertain distant returns, which can make dividend-paying firms attractive. However, dividend valuation theories differ, and this assertion is not a universal result under all assumptions; modern finance also recognises that dividend policy may be irrelevant under idealised market assumptions. **Exam note:** answer within the source’s dividend-theory framework.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"bae92d7630ed302c9ba5636be5df2bcd9a6509d8f0e9c11bf4f5399d9f5100c3","kind":"pyq"},{"id":"pyq-309","sourceNumber":309,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Limited liability partnership may be wound up by which one of the following:","options":["Voluntarily","By the Registrar, if the firm fails to file annual return in the prescribed form with the Registrar of Companies within 60 days of closer of the financial year.","By the Tribunal established under the Companies Act, 2013.","Either voluntarily or by the tribunal established under the Companies Act, 2013."],"answer":3,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why D is correct:** An LLP may be wound up voluntarily or by an order of the Tribunal under the applicable Limited Liability Partnership Act framework. Failure to file an annual return within a fixed 60-day period does not mean the Registrar automatically winds up the LLP in the way stated in option B. **Exam cue:** LLP winding-up routes → voluntary or Tribunal, subject to statutory grounds/procedure.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Limited liability partnership may be wound up by which one of the following:","options":["Voluntarily","By the Registrar, if the firm fails to file annual return in the prescribed form with the Registrar of Companies within 60 days of closer of the financial year.","By the Tribunal established under the Companies Act, 2013.","Either voluntarily or by the tribunal established under the Companies Act, 2013."],"answer":3,"explanation":"**Why D is correct:** An LLP may be wound up voluntarily or by an order of the Tribunal under the applicable Limited Liability Partnership Act framework. Failure to file an annual return within a fixed 60-day period does not mean the Registrar automatically winds up the LLP in the way stated in option B. **Exam cue:** LLP winding-up routes → voluntary or Tribunal, subject to statutory grounds/procedure.","revision":"original","contentSignature":"dd58db4fccf5c80a463d6a765032970898098b7fec93638381856299157e426d"}],"contentSignature":"dd58db4fccf5c80a463d6a765032970898098b7fec93638381856299157e426d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"pyq"},{"id":"pyq-310","sourceNumber":310,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The profit for the year before appropriation in a partnership firm. was Rs. 50,000. Shagun, one of the partners, receives a salary of Rs. 4,000 and interest at ten per cent per annum on his capital of Rs. 1,00,000. Amir, the other partner, receives interest on capital at the same rate as Shogun. Amir's capital was Rs. 89,000. They share profits and losses equally. What was the total share of profits credited to Amir's current account?","options":["Rs. 13,550","Rs. 15,350","Rs. 22, 450","Rs. 24,350"],"answer":2,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why C is correct — ₹22,450:** Shagun’s salary = ₹4,000; interest on Shagun’s capital = 10% × ₹1,00,000 = ₹10,000; Amir’s interest = 10% × ₹89,000 = ₹8,900. Residual profit = ₹50,000 − ₹4,000 − ₹10,000 − ₹8,900 = ₹27,100. Amir receives half = ₹13,550, plus interest on capital ₹8,900 = **₹22,450** credited in total. **Exam cue:** appropriate salary/interest first, then divide residual profit.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"65ccdbda46841bd3a99a59a708149e49a10272cab5b3ed27097c657b11b3acdb","kind":"pyq"},{"id":"pyq-311","sourceNumber":311,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The following information with respect to a company is given below: Net profit before tax = Rs. 1,00,000 10% Preference share capital (Rs. 10 each) = Rs. 1,00,000 Equity share capital (Rs. 10 each) = Rs. 1,00,000 Taxation at 50% of Net profit. Which one among the following is the earning per share?","options":["Zero","Rs. 4","Rs. 10","Rs. 40"],"answer":1,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why B is correct — EPS ₹4:** Net profit before tax = ₹1,00,000. Tax at 50% = ₹50,000, so profit after tax = ₹50,000. Preference dividend = 10% × ₹1,00,000 = ₹10,000. Profit available to equity shareholders = ₹40,000. There are 10,000 equity shares of ₹10 each, so EPS = ₹40,000 ÷ 10,000 = **₹4 per share**.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"5407ac942f341ef2f2813336e2e97c8b7d8ff04fa0423cccca039f856d8b8a6c","kind":"pyq"},{"id":"pyq-312","sourceNumber":312,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In comparison to domestic equity investment, foreign equity investment would be preferred if it offers in which of the following situations?","options":["Higher dividend yield and high rate of capital appreciation.","Lower dividend yield and lower rate of capital appreciation.","Higher dividend yield and lower rate of capital appreciation.","Lower dividend yield and high rate of capital appreciation."],"answer":2,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why C is the supplied answer:** The source’s intended comparison favours a foreign investment with a higher dividend yield even if its capital-appreciation rate is lower, because dividend yield is one component of total return. In a real investment decision, compare expected total return, currency risk, tax, liquidity, political risk and diversification—not dividend yield alone. **Exam cue:** dividend yield + capital appreciation together determine expected return.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"93db6869abfb400b3e838186081a8a62187f490d903626e7d69ad96e8693f9fb","kind":"pyq"},{"id":"pyq-314","sourceNumber":314,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Arrange the following in the winding up process of a company by tribunal in chronological sequence from the first to the last. a. Settlement of list of contributories and application of assets. b. Submission of report by company liquidator. c. Petition for winding up. d. Direction of Tribunal on report of company liquidator. e. Appointment of company liquidator. Choose the correct answer from the options given below:","options":["e, b, a, c, d","a, e, b, c, d","c, e, b, d, a","b, d, c, a, e"],"answer":2,"source":"UGC NET Commerce, Oct 2022 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2022- Oct-14M","explanation":"**Why C is correct — c, e, b, d, a:** The winding-up process begins with a petition (c), followed by appointment of the company liquidator (e). The liquidator submits the required report (b); the Tribunal then gives directions on that report (d), after which settlement of contributories and application of assets proceeds (a). **Legal note:** statutory procedure can vary with the applicable law and insolvency framework.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2022- Oct-14M","explanation":"Petition -> liquidator appointed -> liquidator's report -> Tribunal directions -> settlement of contributories and application of assets. [PYQ: UGC NET Commerce, 2022- Oct-14M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"7bc425ee66cfaa650f93bbcaadaac4ca6433c6e0125fdc0b5c55512da41286b6","kind":"pyq"},{"id":"pyq-315","sourceNumber":315,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In Fund Flow Statement, which one of the following is not a valid statement?","options":["It is prepared to know the total sources and their uses in a year.","Dividend received is a source of funds.","Its preparation is at the discretion of the management.","It is useful for external financial management."],"answer":3,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why D is correct — external financial management:** A fund flow statement analyses sources and applications of funds over a period and may be prepared at management’s discretion to understand changes in financial position. It is mainly useful for internal planning and financial management, rather than being a mandatory external financial statement for general users. **Exam cue:** fund flow = sources and uses of funds.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"d968a3d81028c59f4d5eb191c06152b33956a41755a014e5116932f8546a516f","kind":"pyq"},{"id":"pyq-316","sourceNumber":316,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Preference share in India is issued by a company for a maximum period of :","options":["10 years","15 years","20 years","Unlimited period."],"answer":2,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why C is correct — 20 years:** Under the general Companies Act, 2013 rule, preference shares are redeemable within a maximum period of 20 years, with a special exception for certain infrastructure projects subject to prescribed conditions. They are not generally issued as perpetual/unlimited-period preference shares. **Legal note:** remember the exception when answering a current-law question.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"9ef412084b757461585549928fcba884994c33dc4a3dee91141b3d6e2dc0b6dc","kind":"pyq"},{"id":"pyq-319","sourceNumber":319,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"As per Section 68 of the Indian Companies Act, a company may purchase its own shares out of which of the following? (a) Free reserves. (b) Securities premium account. (c) General reserve. (d) Proceeds of any other shares. (e) Proceeds of same kind of shares. Choose the correct answer from the options given below:","options":["a, b, c and e only.","a, b, c and d only.","b, c, d and e only.","a, c, d and e only."],"answer":1,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why B is correct — a, b, c and d only:** Under section 68, buy-back may be financed from free reserves, the securities premium account or proceeds of an issue of shares/securities, subject to statutory conditions. Buy-back cannot be made out of proceeds of an earlier issue of the same kind of shares/securities. General reserve is included within free reserves in the intended exam framing. **Exam cue:** other-source proceeds permitted; same-kind proceeds barred.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c78eb103863e8f54e8ca78eb39e5462bfd08bc9222554a0d2e35cb3f0332306d","kind":"pyq"},{"id":"pyq-320","sourceNumber":320,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following are key assumptions of Gordon's Dividend Model? (a) Ke > br (b) r and Ke are changing. (c) The firm is not all- equity firm. (d) The firm has perpetual life. (e) The retention ratio, once decided, is constant. Choose the correct answer from the options given below:","options":["a, d and e only.","b, c and e only.","a, b and d only.","c, d and e only."],"answer":0,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why A is correct — a, d and e:** Gordon’s dividend-growth model assumes a perpetual firm, a constant retention ratio, stable return on investment and cost of equity, and the condition (K_e > br) so the valuation denominator is positive. It does not assume that r and (K_e) are changing, and the standard model is usually developed for an all-equity firm. **Exam cue:** stable growth assumptions + (K_e > br).","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"9e7e95965112bdf6a717c47bfa7edb2727a07cf969df8ae205f31c3e5f9e72a8","kind":"pyq"},{"id":"pyq-321","sourceNumber":321,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Michael Porter has identified five forces that determine the intrinsic long-term attractiveness of a market. According to the model, which of the following are true? (a) A segment is unattractive if it already contains numerous aggressive competitors. (b) A segment is unattractive if it is stable or declining. (c) A segment is unattractive if it has high entry barriers and low exit barriers. (d) A segment is unattractive if the company's suppliers are able to raise prices. (e) A segment is unattractive when there are actual or potent substitutes for the product. Choose the most appropriate answer from the options given below:","options":["a and b only.","b and c only.","a, c and d only.","a, b, d and e only."],"answer":3,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why D is correct — a, b, d and e:** A market segment is less attractive when rivalry is intense, the market is stable/declining, suppliers can raise prices, or substitutes are readily available. High entry barriers can protect incumbents, while low exit barriers make it easier for firms to leave; that combination is not the stated reason for unattractiveness in option C. **Porter cue:** rivalry, entrants, substitutes, buyer power and supplier power.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"52f5557c15bc63fbed3ce8be42079e4cb1588187a3ebec77eaf945ac3cf365ec","kind":"pyq"},{"id":"pyq-322","sourceNumber":322,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Who among the following are indentified as the Key managerial personnel in the Indian Companies Act 2013? (a) Chief Executive Officer. (b) Whole Time Director. (c) Company Secretary. (d) Chief Risk Officer. (e) Manager Choose the most appropriate answer from the options given below:","options":["a, b and d only.","a and b only.","a, b, c and d only.","a, b, c and e only."],"answer":3,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why D is correct — a, b, c and e:** Key managerial personnel under the Companies Act, 2013 include the CEO/managing director/manager, whole-time director, company secretary and chief financial officer, as well as prescribed officers. Chief Risk Officer is not automatically a KMP merely by holding that title. The listed option D contains CEO, whole-time director, company secretary and manager. **Legal note:** apply the statutory definition and applicable rules.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"0a92c8d22b07e952885fb192daeca3f41cf637cc83a7b6de5176e241a43d4b76","kind":"pyq"},{"id":"pyq-323","sourceNumber":323,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Match List I with List II: List I (Promotional Campaign): (a) #StayStrongMoms (b) #JeetKiOre (c) #LetsunstereotypeIndia (d) #Freedomtolove List II (Company): (i) Pepsin India (ii) Hindustan Uniliver (HUL) (iii) Indian Tobacco Company (ITC) (iv) Brooke Bond India Choose the correct answer from the options given below:","options":["a- iii, b- i, c- iv, d- ii","a- ii, b- iv, c- i, d- iii","a- ii, b- i, c- iii, d- iv","a- i, b- iii, c- iv, d- ii"],"answer":0,"source":"UGC NET Commerce, Oct 2022","explanation":"**Matching (option A):** #StayStrongMoms → ITC (iii), #JeetKiOre → Pepsi India (i), #LetsunstereotypeIndia → Brooke Bond India (iv), and #Freedomtolove → HUL (ii). Campaign names and brand ownership are easy to confuse, so learn each pair carefully.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"0c065592a010874cd7867335250ead436e044a0328d76e787248a4d742b2aa71","kind":"pyq"},{"id":"pyq-324","sourceNumber":324,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Arrange the following steps in the process of GDR Issues: (a) Registration with prescribed authority. (b) Appointment and vesting of shares with the custodian. (c) Approval of the regulatory authorities. (d) Listing of GDR. (e) GDR allotment. Choose the correct answer from the options given below:","options":["c, a, b, e, d","a, b, c, d, e","a, c, b, e, d","b, a, c, d, e"],"answer":2,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why C is the supplied sequence — a, c, b, e, d:** Register the proposed GDR issue with the prescribed authority (a), obtain regulatory approvals (c), appoint a custodian and vest the underlying shares (b), allot the GDRs (e), and list the GDRs (d). The exact steps and authorities depend on the regulatory framework applicable at the time of issue. **Exam cue:** approvals/registration → custody of underlying shares → GDR allotment → listing.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"d0246d24e13773a5065ddd0ebb3132e0cef8be572acc7c678e5d2f84ba83719b","kind":"pyq"},{"id":"pyq-325","sourceNumber":325,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Steps involved in computation of Book Profit under MAT regime are as follows: (a) Arrive NP as per statement of P/L A/C of the company. (b) Specific adjustments in case of merger. (c) Make adjustments pertaining to OCI items. (d) Adjust the book profit with stipulated exclusion and inclusion. (e) Net amount of Book Profit for application. of MAT rate. Choose the correct sequence from the options given below:","options":["a, d, b, c, e","a, b, d, c, e","a, c, b, d, e","a, b, c, d, e"],"answer":0,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why A is the supplied sequence:** Begin with net profit as per the company’s Profit and Loss Account (a), make the stipulated inclusions/exclusions and adjustments to arrive at book profit (d), then account for any specified merger adjustments (b) and OCI adjustments (c), and determine the net book profit to which the MAT rate applies (e). **Tax-law caution:** MAT provisions and adjustments can change; follow the relevant assessment year’s section 115JB and official instructions.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"bfac5cc9f1c0b174cd79cddc407482bbecf6a237f05b84f094ced4086178eee2","kind":"pyq"},{"id":"pyq-327","sourceNumber":327,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following companies cannot be a ‘small company’? A. A holding company or a subsidiary company B. A company registered under Section 8 C. A company or body corporate governed by any Special Act D. One Person Company (OPC) Choose the correct answer from the options given below.","options":["B and C only","A, B and C only","B, C and D only","A and D only"],"answer":1,"source":"UGC NET Commerce, Oct 2022 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2022- Oct-29M","explanation":"**Why B is correct — A, B and C only:** Under the Companies Act definition, a small company excludes a holding company or subsidiary company, a section 8 company and a company/body corporate governed by a special Act, in addition to other statutory exclusions. An OPC can qualify as a small company if it meets the relevant conditions and thresholds. **Legal note:** thresholds and exclusions should be checked against the current Companies Act rules.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2022- Oct-29M","explanation":"Section 2(85) excludes holding/subsidiary companies, Section 8 companies and special-act bodies; an OPC CAN be a small company. [PYQ: UGC NET Commerce, 2022- Oct-29M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"88d3ed6a76e1b61b39e74e918b4045f46e7eac5eaa1736c452675e87ab484060","kind":"pyq"},{"id":"pyq-328","sourceNumber":328,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which one of the following duties is not a general duty of directors of a company?","options":["Duty of good faith in order to promote the object of the company","Duty of due and reasonable care, skill and diligence and shall exercise independent judgement.","Duty to attend Board Meetings","Duty not to delegate or assign his office assignment."],"answer":2,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why C is correct — Duty to attend Board Meetings:** Section 166 of the Companies Act, 2013 expressly includes acting in good faith, exercising due and reasonable care, skill and diligence, independent judgement, and not assigning the office. Attending board meetings is an important practical responsibility but is not worded as a standalone general duty in section 166 in the same way as the listed duties. **Exam cue:** distinguish statutory general duties from good governance practice.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8d4afb88e7322a26c00a1822bb1368ab89e645aba87af5834ab8350a1aaf6866","kind":"pyq"},{"id":"pyq-329","sourceNumber":329,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which among the following information shall be disclosed for all public issues of shares irrespective of their issue price? A. Earning per share B. Dividend payout ratio C. Pre-issue P/E ratio D. Average return on net worth in last 3 years E. Net asset value per share based on last balance sheet Choose the correct answer from the options given below:","options":["A, B, D and E only","A, C, D and E only","B, C, D and E only","A, B, C and D only"],"answer":1,"source":"UGC NET Commerce, Oct 2022 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2022-Oct-29M","explanation":"**Why B is correct — A, C, D and E:** The source’s disclosure set includes earnings per share, pre-issue price/earnings ratio, average return on net worth over the prior three years and net asset value per share based on the latest balance sheet. Dividend payout ratio is not included in the listed mandatory set for this question’s framework. **Regulatory note:** issue-disclosure requirements change; treat this as a source-era SEBI/exam question.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2022-Oct-29M","explanation":"SEBI ICDR basis-for-issue-price disclosures: EPS, pre-issue P/E, average return on net worth and NAV per share - dividend payout ratio is not mandatory. [PYQ: UGC NET Commerce, 2022-Oct-29M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"0c62ef9c10e4efdf0e3f693ce2f7b08d852e76882c1b39042b771f9c94bcd081","kind":"pyq"},{"id":"pyq-330","sourceNumber":330,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Match List I with List II List I (Marketing Concept) A. Brand Equity B. Brand Identity C. Brand Image D. Market Potential List II (Description) I. The maximum possible demand for a product when marketing expenditure in the industry is infinite. II. The mental perception and associations of consumers related to a brand. III. The peculiar distinguishing color, design, label of a brand which distinguish brand of a firm. IV. A pool of goodwill consumers have related to a brand. Choose the correct answer from the options given below. Codes","options":["A-IV, B-III, C-II, D-I","A-I, B-II, C-IV, D-III","A-III, B-I, C-IV, D-II","A-II, B-III, C-I, D-IV"],"answer":0,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why A is correct:** Brand equity is the pool of goodwill/value associated with a brand (A–IV). Brand identity is the distinctive design, colour, label and other elements a company uses to identify the brand (B–III). Brand image is consumers’ mental perception and associations (C–II). Market potential is the maximum possible demand at very high industry marketing expenditure (D–I). **Memory cue:** identity = company creates; image = consumer perceives; equity = accumulated value.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"32c7e2da25d8b19e168df79f3157503f23f1e773c78b304a72b1f8dd8407f037","kind":"pyq"},{"id":"pyq-331","sourceNumber":331,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"When the incoming partner cannot bring premium for goodwill, then the necessary adjustment for goodwill is done through which one of the following?","options":["Goodwill account of the partners","Capital account of the new partners","Balance sheet of the new partnership firm","Profit & Loss Appropriation account"],"answer":1,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why B is the supplied answer — Capital account of the incoming partner:** If the incoming partner cannot pay a separate goodwill premium, the agreed goodwill adjustment may be made through partners’ capital accounts so the old partners are compensated for the share sacrificed. The exact journal entry depends on whether goodwill is raised, retained or written off and on the partnership deed. **Exam note:** use the method taught in the question’s source; do not assume a goodwill asset must remain on the books.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"4a1a3cba78e300564470a6a2c5ae3766750db23ca592aa46a4f4aa4190ff34b4","kind":"pyq"},{"id":"pyq-332","sourceNumber":332,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The information with respect to a company is: EBIT = Rs 35 Lakhs 15% Term loan = Rs. 50 Lakhs Working capital term loan from bank @ 20% = Rs. 30 Lakhs 10% Preference share capital = Rs. 10 lakhs Public deposits accepted @ 14% = Rs. 15 Lakhs Which one among the following is the Interest Coverage Ratio for the company?","options":["0.45","1.98","2.24","2.59"],"answer":2,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why C is correct — 2.24 times:** Interest coverage ratio = EBIT ÷ Finance cost/interest. Interest on term loan = 15% × ₹50 lakh = ₹7.5 lakh; working-capital loan interest = 20% × ₹30 lakh = ₹6 lakh; deposit interest = 14% × ₹15 lakh = ₹2.1 lakh. Total interest = ₹15.6 lakh. ICR = ₹35 lakh ÷ ₹15.6 lakh ≈ **2.24 times**. **Exam cue:** include all stated interest-bearing borrowings.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"aa75b14db815bd5a01a06edeef42aca2e15b8425af990570c9b7a0e63a2450e6","kind":"pyq"},{"id":"pyq-333","sourceNumber":333,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company does not include the value of skills gained by its employees from training programmes in its annual financial statements. Which one of the following accounting concepts is being applied in this case?","options":["Going concern concept","Money measurement concept","Revenue recognition concept","Business entity concept"],"answer":1,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why B is correct — Money measurement concept:** Skills gained by employees are valuable but are not normally recorded as an asset because they cannot be measured and recognised reliably as a controlled monetary resource under the accounting framework. The money-measurement concept limits accounting records to events/items expressible in monetary terms. **Exam cue:** valuable but not reliably measurable in money → not separately recognised.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8d0d26d4fea0962f01e5caf4167cad0095a08e3a813c664926f7f1b0c73289e8","kind":"pyq"},{"id":"pyq-334","sourceNumber":334,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The share capital of an RRB is Subscribed by the Central Government, State Government and Sponsoring Bank in which one of the following ratios?","options":["40:40:20","50:15:35","50:35:15","60:30:10"],"answer":1,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why B is correct — 50:15:35:** The share capital of a Regional Rural Bank is subscribed in the ratio 50% by the Central Government, 15% by the concerned State Government and 35% by the sponsoring bank under the source’s statutory framework. **Memory cue:** Centre 50, State 15, Sponsor bank 35.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"37a7690f52fd949cc10c18cad4257830bf25c01099af2ccd4bbe2fe47cee62ee","kind":"pyq"},{"id":"pyq-335","sourceNumber":335,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Match List I with List II List I Characteristic Business A. Cash Cows B. Crown Jewels C. Fallen Angels D. White Squire List II Description I. The most valuable segments of a company, the parts most Wanted by an acquirer II. A third party friendly to management who helps a company avoid an unwanted takeover with taking over the company on its own III. A BCG term for business segment which have a high market share in low growth markets IV. A bond issued at investment grade whose rating is subsequently dropped to below the investment grade Choose the correct answer from the options given below :","options":["A-II, B-IV, C-I, D-III","A-I, B-IV, C-III, D-II","A-IV, B-III, C-II, D-I","A-III, B-I, C-IV, D-II"],"answer":3,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why D is correct:** Cash cows are BCG business units with high relative market share in low-growth markets (A–III). Crown jewels are the most valuable parts of a company sought by an acquirer (B–I). Fallen angels are bonds downgraded from investment grade to below investment grade (C–IV). A white squire is a friendly investor/third party that helps prevent an unwanted takeover without itself acquiring the entire company (D–II).","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"3a96616cb2505697daaba95fd3dd27c925c7f8cbd427e75e8dff275a13189653","kind":"pyq"},{"id":"pyq-336","sourceNumber":336,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"An Indian company receiving investment from outside India for issuing shares/convertible debentures/preference shares under the FDI scheme should report the details of the inflow to the RBI. What is the time limit for reporting these details to RBI?","options":["Within 10 days from the date of receipt.","Within 15 days from the date of receipt.","Within 30 days from the date of receipt.","Within 45 days from the date of receipt."],"answer":2,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why C is the source’s answer — 30 days:** The source exam’s FDI reporting framework requires the relevant inward-investment receipt details to be reported within the specified 30-day period. Reporting requirements differ by form and event—for example, receipt of funds and issue of shares have distinct reporting steps—so confirm the precise form and current RBI/FEMA directions when applying this in practice. **Exam cue:** retain the 30-day period for this source question, but verify current rules for real transactions.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"64566f480456ad24d1e6176909cfbc7028ad1fa9d4b108aa5a9bac9342f63aae","kind":"pyq"},{"id":"pyq-338","sourceNumber":338,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which one of the following is NOT an advantage of organization structure by product in a manufacturing company?","options":["Places attention and effort on product line.","Requires less persons with general managerial abilities.","Improves coordination of functional activities.","Permits growth and diversity of products."],"answer":2,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why C is correct — Improves coordination of functional activities:** Product-based structure gives each product line greater focus, accountability and room to grow, but it can duplicate functional resources and make coordination across functions less efficient. Therefore improved coordination of functional activities is not necessarily an advantage of product departmentalisation. **Exam cue:** product structure improves product focus but may duplicate functions.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"86e9d739bc14cfc78294aef434053af23478fe4a9fbbf2eee91544a1b5f51885","kind":"pyq"},{"id":"pyq-339","sourceNumber":339,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which one of the following FTA was signed in February 2022 and came into force in May 2022?","options":["AI-ECTA Australia - India Economic Cooperation and Trade Agreement","India-UAE Comprehensive Economic Partnership Agreement (CEPA)","India-Nepal Treaty of Trade","India-Singapore Comprehensive Economic Cooperation Agreement (CECA)"],"answer":1,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why B is correct — India–UAE CEPA:** The India–UAE Comprehensive Economic Partnership Agreement was signed in February 2022 and entered into force on 1 May 2022. The Australia–India ECTA was signed in April 2022 and entered into force in December 2022, so it does not match the dates in the question. **Exam cue:** UAE CEPA → signed Feb 2022, effective May 2022.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"00c15257d8e4732dc75e2c10b5e12d61c00f5f14b65b2e731a996f0b1f0f5ea5","kind":"pyq"},{"id":"pyq-340","sourceNumber":340,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"X and Y are partners in a firm sharing profits in the ratio 4:5. X surrenders 1/4 of his share and Y surrenders 1/5 of his share in favour of Z, the new partner. What will be the new profit-sharing ratio of the firm's partners?","options":["3:4:2","55:44:81","4:5:2","44:55:81"],"answer":0,"source":"UGC NET Commerce, Mar 2023 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2023-Mar-M","explanation":"**Why A is correct — 3:4:2:** X’s old share = 4/9 and he gives up one-fourth of it = 1/9. Y’s old share = 5/9 and he gives up one-fifth of it = 1/9. Z receives both surrendered portions, 2/9. Remaining shares: X = 3/9, Y = 4/9, Z = 2/9. New ratio = **3:4:2**.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2023-Mar-M","explanation":"X gives 4/9 x 1/4 = 1/9, Y gives 5/9 x 1/5 = 1/9; new shares: X 3/9, Y 4/9, Z 2/9 - ratio 3:4:2. [PYQ: UGC NET Commerce, 2023-Mar-M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"1141e628b8d655ac0d694b7a6606bae823679667b9ca1d4fe59ed4889a297438","kind":"pyq"},{"id":"pyq-341","sourceNumber":341,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The current market price of a company’s share is Rs. 90 and the expected dividend per share next year is Rs. 4.50. If the dividends are expected to grow at a constant rate of 8%, the shareholders required rate of return is:","options":["5%","8%","13%","20%"],"answer":2,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why C is correct — 13%:** Under the Gordon dividend-growth model, required return (K_e = D_1/P_0 + g). Next year’s dividend (D_1) = ₹4.50, current market price (P_0) = ₹90, and growth (g) = 8%. Dividend yield = ₹4.50/₹90 = 5%. Required return = 5% + 8% = **13%**.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"777d6841f7863a8f0b215498a0dc08d4ed552454221a378e1efa3d9e150fa72e","kind":"pyq"},{"id":"pyq-342","sourceNumber":342,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A private equity investor plans to invest Rs. 500 million in the equity of a company. The investor requires a return of 25% per annum over a 5-year holding period (FV factor FVF0.25,5 = 3.052). The company's projected year-5 EBITDA is Rs. 800 million, the expected exit EV/EBITDA multiple is 6 times, and net debt at exit is expected to be Rs. 1,200 million. What ownership share must the investor acquire at entry?","options":["30.5%","42.4%","50.0%","25.4%"],"answer":1,"source":"Original replacement question (v3; not attributed to an external exam)","explanation":"**Why B is correct — 42.4% ownership:** Required exit equity value = ₹500 million × 3.052 = ₹1,526 million. Exit enterprise value = EBITDA ₹800 million × 6 = ₹4,800 million. Subtract net debt ₹1,200 million to get exit equity value ₹3,600 million. Required ownership = ₹1,526 million ÷ ₹3,600 million ≈ **42.4%**. This assumes no dilution or other changes in ownership/value.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c0cd38a54855470403d03bac85c5cf22d806d444217820d7e86a27ce6f9d0184","kind":"pyq"},{"id":"pyq-343","sourceNumber":343,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Tax on declared dividend is paid by whom?","options":["Shareholders/ Receiver of the dividend","Manager","Distributor of the dividend","Company"],"answer":0,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why A is correct — Shareholders/recipients:** Under India’s current dividend taxation approach, dividend income is generally taxable in the hands of the shareholder/recipient at the applicable rate, subject to the relevant rules. The company deducts tax at source where required, but that is not the same as the ultimate income-tax liability on the dividend. **Historical note:** older questions may reflect the earlier dividend distribution tax regime.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"72cfc0039841e79974e960aa1a2fb8ef8b35c46947ad9ebe1108b52a645bb22f","kind":"pyq"},{"id":"pyq-344","sourceNumber":344,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following transactions are related to Financing Activities? a. Share issued for cash. b. Dividend distributed to shareholders. c. Sale of machinery. d. Redemption of debentures. e. Provision for depreciation. Choose the correct answer from the options given below: Codes","options":["a and e only","a and c only","a, b and d only","a, b, c and d only"],"answer":2,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why C is correct — a, b and d:** Issuing shares for cash raises finance, paying dividends distributes returns to shareholders, and redeeming debentures repays financing; all are financing cash flows under the conventional cash-flow classification. Sale of machinery is an investing activity, while depreciation is a non-cash expense added back when reconciling operating cash flow under the indirect method. **Memory cue:** share/debt/dividend flows → financing.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"1f4c2f702c49b8cb9dc16ff119a0ea64f777edd449e7b67029903602d82b8e5c","kind":"pyq"},{"id":"pyq-345","sourceNumber":345,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following are to be determined to estimate current market demand? A. Total Market potential B. Area Market potential C. Analyse past sales D. Sales force’s input E. Market share Choose the most appropriate answer from the options given below: Codes","options":["A, C and E only","B, D and E only","A, C and D only","A, B and E only"],"answer":3,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why D is correct — A, B and E:** Estimating current market demand uses total market potential, geographic/area market potential and the company’s likely market share. Past sales figures and sales-force estimates are forecasting inputs rather than measures of current market demand, so they are not part of this combination.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"f23e25a3b622f0ab188e0f8199b4907a252516f23b116d7d1d2f57e1361cc537","kind":"pyq"},{"id":"pyq-346","sourceNumber":346,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Given below are two statements: One is labelled as Assertion A and the other is labelled as Reason R. Assertion ‘A’: When holding company holds more than 50% (but not whole) shares of a company, then the holders of the rest of shares will be known as \"Minority\". Reason ‘R’: Minority interest is calculated by considering proportionate shares and reserves of Holding Company. In the light of the above statements, choose the most appropriate answer from the options given below: Codes","options":["Both A and R are true and R is the correct explanation of A.","Both A and R are true but R is not the correct explanation of A.","A is true but R is false.","A is false but R is true."],"answer":2,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why C is correct:** Statement A is true in the usual consolidation context: shareholders other than the holding company are referred to as non-controlling interest/minority interest. Reason R is false because minority interest is based on the non-controlling shareholders’ proportionate interest in the subsidiary’s net assets/profit, not the holding company’s own reserves. **Exam cue:** NCI = outside shareholders’ share in subsidiary, not parent’s reserves.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e1c8d7b2dd6b6888244643499609b2fa8440b75b0ff66098588a8748b7c612ec","kind":"pyq"},{"id":"pyq-347","sourceNumber":347,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"From the following information compute Return on Capital Employed (ROCE): Net profit after tax Rs. 1,50,000; income tax rate 25%; interest on long-term debt Rs. 30,000; total assets Rs. 8,00,000; current liabilities Rs. 2,00,000.","options":["25%","30%","38.33%","43.33%"],"answer":2,"source":"Original replacement question (v3; not attributed to an external exam)","explanation":"**Why C is correct — 38.33% ROCE:** Net profit after tax = ₹1,50,000 and tax rate is 25%, so profit before tax = ₹1,50,000 ÷ 0.75 = ₹2,00,000. Add long-term interest ₹30,000 to get EBIT ₹2,30,000. Capital employed = Total assets − Current liabilities = ₹8,00,000 − ₹2,00,000 = ₹6,00,000. ROCE = ₹2,30,000/₹6,00,000 × 100 = **38.33%**.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"ee93165a4be3b36d7107354ed63f3b225c9f7386347b5ab823e91c77930b43c9","kind":"pyq"},{"id":"pyq-348","sourceNumber":348,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Given below are two statements: One is labelled as Assertion A and the other is labelled as Reason R. Assertion A: Usually manufacturing companies use sale and lease back arrangement to unlock investment in fixed assets. Reason R: In a sale of lease back arrangement, the companies sell the asset to a leasing company, and lease it back to enjoy the uninterrupted use of asset in their business. In the light of the above statements, choose the most appropriate answer from the options given below:","options":["Both A and R are true and R is the correct explanation of A.","Both A and R are true but R is not the correct explanation of A.","A is true but R is not False","A is false but R is true"],"answer":0,"source":"UGC NET Commerce, Jun 2023","explanation":"**Why A is correct:** In a sale-and-leaseback, a company sells an asset to a leasing company and leases it back, releasing cash tied up in the asset while continuing to use it in operations. This can unlock investment in fixed assets and improve liquidity, although the company takes on lease-payment obligations and accounting consequences. **Exam cue:** sell asset → receive cash → lease it back for continued use.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"1f85cf707c6db49d4ba4de63d98bd564d6c0f456401be4ce3442c5937a7e32c6","kind":"pyq"},{"id":"pyq-351","sourceNumber":351,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Section 61 to 64 of the company act 2013 states ‘Alteration proper’ which includes: a) Cancellation of the unissued shares b) Cancellation of issued shares c) Increase in share capital by issue of new share d) Decrease of share capital by redemption of shares e) Conversion of fully paid shares into stock and vice versa. Choose the most appropriate answer from the options given below:","options":["b, c and d only","a, c and e only","c, d and e only","a, b and c only"],"answer":1,"source":"UGC NET Commerce, Jun 2023","explanation":"**Why B is correct — a, c and e:** Under the Companies Act, 2013, alteration of share capital can include cancelling unissued shares, increasing authorised share capital by issuing new shares, and converting fully paid shares into stock or reconverting stock into shares, subject to the Act and the company’s articles. Cancellation of already-issued shares and reduction of share capital are distinct procedures, not ordinary section 61 alterations in the same way. **Legal note:** follow the exact statutory wording and current amendment.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"a2c2d3ad287b637f8f66aceaeeda5a28686aea15c4e85eb7dc25863a88828d34","kind":"pyq"},{"id":"pyq-352","sourceNumber":352,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Match the list I with list II LIST I (Schedules under the companies Act,2013) A. Schedule-I B. Schedule-II C. Schedule-III D. Schedule-IV LIST II (Underlying themes) I. Computation of Depreciation II. Code for independent directors III. Memorandum of Association IV. Preparation of balance sheet and statement of profit and loss. Choose the correct answer from the option given below.","options":["A-II, B-I, C-IV, D-III","A-III, B-I, C-IV, D-II","A-III, B-IV, C-I, D-II","A-I, B-III, C-II, D-IV"],"answer":1,"source":"UGC NET Commerce, Jun 2023 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2023-Jun-M","explanation":"**Why B is correct:** Schedule I contains model forms for Memorandum and Articles of Association (A–III); Schedule II deals with depreciation (B–I); Schedule III prescribes the format for financial statements such as the balance sheet and statement of profit and loss (C–IV); and Schedule IV contains the code for independent directors (D–II). **Memory cue:** I = MOA/AOA; II = depreciation; III = financial statements; IV = independent directors.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2023-Jun-M","explanation":"Schedule I = model MOA/AOA; Schedule II = depreciation; Schedule III = financial statement formats; Schedule IV = code for independent directors. [PYQ: UGC NET Commerce, 2023-Jun-M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"20bc567ce7ed46ea0d4705477c18de088b9a157a6a82d81e742c0a408797af64","kind":"pyq"},{"id":"pyq-353","sourceNumber":353,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the interventions can be used to manage the anxiety created by mergers and acquisitions. a) Speed-up of the integration process b) Articulate a new vision, common goals and organizational symbols c) Employee counselling and stress management training d) Disengage efforts such as termination ceremonies e) Social support from spouse, friends, supervisors and coworkers Choose the most appropriate answer from the options given below:","options":["A. B and C only","B. C and D only","A. C and E only","A, B and E only"],"answer":2,"source":"UGC NET Commerce, Jun 2023","explanation":"**Why C is the supplied answer — a, c and e:** M&A anxiety can be reduced by accelerating integration where appropriate, providing employee counselling/stress-management training, and encouraging social support from family, peers and supervisors. Articulating a shared vision and common goals can also help integration, while termination ceremonies are not generally a supportive intervention. The option set appears imperfect because B is also a standard change-management intervention; **verify the original key before treating this combination as definitive.**","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"answer-key-review","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"3c589b54586ea59623499970def1fc8634df32d6b9f6bc0665fe685da692ee40","kind":"pyq"},{"id":"pyq-354","sourceNumber":354,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The Competition (Amendment) Act, 2023 revamped the competition Act in which of the following perspectives: a) The CCI needs to be intimated if the value of merger and acquisition deal exceeds Rs. 2000 crores b) The overall timeline for assessment of combination has been reduced to 150 days from 210 days c) \"Exclusive selling agreements\" has been replaced with \"exclusive dealing Agreement\" d) Entities who are not engaged in identical or similar trade shall also be part of an Anti-competitive Agreement under Section 3(3) of the Act e) Anti-competitive conduct like \"tie-up arrangements\" \"re-sale price Maintenance\" and \"exclusive distribution agreement\" have been redefined. Choose the correct answer from the options given below:","options":["a, b and c only","c and e only","a, b, c and d only","a, b, c, d and e"],"answer":3,"source":"UGC NET Commerce, Jun 2023","explanation":"**Why D is the correct answer — all five:** The Competition (Amendment) Act, 2023 introduced changes concerning deal-value thresholds for combinations, shorter review timelines and refinements to provisions addressing anti-competitive agreements and conduct. The question’s descriptions use shorthand, and some statements depend on the detailed amendment wording and commencement dates. **Legal note:** use the Act/rules and CCI guidance for current compliance; this explanation follows the source’s exam framing.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8ca0a3835e7e44abdd9608292695ac46f1507245b9e4d0e2816d146c6def8413","kind":"pyq"},{"id":"pyq-355","sourceNumber":355,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Given below are two statements: Statement I: Certificate of incorporation is conclusive evidence that all the requirements of the Companies Act have been complied with in respect of registration. Statement II: After incorporation, if the company makes a fresh contract in terms of the preincorporation contract, the liability of the promoters shall come to an end. In the light of the above statements, choose the correct answer from the options given below:","options":["Both Statement I and Statement II are true","Both Statement I and Statement are false","Statement I is true but Statement II is false","Statement I is false but Statement II is true"],"answer":0,"source":"UGC NET Commerce, Jun 2023 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2023-Jun-M","explanation":"**Why A is correct — both statements are true in the source’s framing:** A certificate of incorporation is conclusive evidence that the company has been registered. A pre-incorporation contract is not automatically ratified by a company that did not yet exist; however, if the company enters into a fresh contract after incorporation on the same terms, that new contract can replace the promoter’s arrangement and end the promoter’s liability under the applicable principles. **Exam cue:** fresh post-incorporation contract/novation can shift the obligation.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2023-Jun-M","explanation":"The certificate is conclusive (s.9 of the 2013 Act, continuing old s.35 of the 1956 Act), and a fresh post-incorporation contract (novation) releases the promoters. [PYQ: UGC NET Commerce, 2023-Jun-M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"fee03f6c383ce95b3b1c8f77736430369df316c1d91d8e16f09e844d9012b8fb","kind":"pyq"},{"id":"pyq-356","sourceNumber":356,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A multinational company can use which prices to create profits in low tax regimes and loss in high tax regimes?","options":["Divisional prices","Inter-Divisional Prices","Holding company prices","Transfer prices"],"answer":3,"source":"UGC NET Commerce, Jun 2023","explanation":"**Why D is correct — Transfer prices:** Multinational groups may set transfer prices for transactions between related entities in different tax jurisdictions. If prices are manipulated, profits can be shifted toward low-tax jurisdictions and costs/losses toward high-tax jurisdictions. Tax rules require arm’s-length pricing and documentation to prevent improper profit shifting. **Exam cue:** cross-border related-party pricing → transfer pricing.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"2ffe163de430c1806eda0a6cd240e8c983b27ef6234259d807371bd4d27f5dd8","kind":"pyq"},{"id":"pyq-357","sourceNumber":357,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Based on which of the following concepts, is share capital account shown on the liabilities side of a balance sheet?","options":["Matching Concept","Going Concern Concept","Business Entity Concept","Accrual Concept"],"answer":2,"source":"ICMAI CMA Foundation, Jun 2026","explanation":"**Why C is correct — Business entity concept:** The company is treated as separate from its owners. Amounts invested by shareholders are therefore recorded as share capital in the company’s accounts, representing the owners’ claim against the separate business entity rather than the shareholders’ personal assets. **Exam cue:** business and owner are separate accounting entities.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"6df715b721783967a8f02e4e019984ff51c3d44e23f7f37f6fb67bccab2082e8","kind":"pyq"},{"id":"pyq-358","sourceNumber":358,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"According to Walter’s Model of Dividend, market value of the share of a declining firm (having r < ke) will be maximum at","options":["0% Dividend Payout","100% Dividend Payout","50% Dividend Payout","75% Dividend Payout"],"answer":1,"source":"UGC NET Commerce, Dec 2025","explanation":"**Why B is correct — 100% dividend payout:** Under Walter’s model, when the firm’s return on investment r is below shareholders’ required return (K_e), retained earnings earn less than investors could earn elsewhere. The model therefore predicts maximum share value when all earnings are distributed as dividends (100% payout). **Memory cue:** r < (K_e) → distribute; r > (K_e) → retain; r = (K_e) → payout policy irrelevant in the model.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e6e44956024652a8f62870398efa1b2657936ecdfff0bef646d5c2f5644f6f78","kind":"pyq"},{"id":"pyq-359","sourceNumber":359,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following types of FDI includes creation of new assets and production facilities in the country?","options":["Brownfield investment","Merger and Acquisition","Strategic alliances","Greenfield investment"],"answer":3,"source":"UGC NET Commerce, Jun 2025","explanation":"**Why D is correct — Greenfield investment:** Greenfield FDI involves creating new facilities, production capacity or business operations in the host country. Brownfield investment usually involves acquiring or using existing facilities/businesses, while mergers and acquisitions purchase existing assets or companies. **Exam cue:** new facility from the ground up → greenfield.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"4419970db2ffcd8e6f92b6a13f8b6093292b3813b08f5684167e4144f2eccb83","kind":"pyq"},{"id":"pyq-360","sourceNumber":360,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following statements are incorrect for amalgamation in the nature of merger? A. All the assets and liabilities of the transferor company are taken over by transferee company. B. Shareholders holding not less than 95% of the face value of the equity shares of the transferor company become equity shareholders of the transferee company. . Payment of purchase consideration may be made in cash per share. . Journal entries for recording the merger are passed by pooling of intrest method. E. The business of the transferor company is not intended to be carried on by the transferee company. ee Choose the correct answer from the options given below:","options":["A, B, and C Only","B, C and D Only","Aand D Only","B, C and E Only"],"answer":3,"source":"UGC NET Commerce, Jun 2025 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2025-Jun","explanation":"**Why D is correct — B, C and E are incorrect:** In a merger-type amalgamation, the transferee takes over the transferor’s assets and liabilities, and the transferor’s business is intended to continue. The applicable accounting standard uses the pooling-of-interests method for an amalgamation in the nature of merger. The shareholder-continuity threshold in statement B is misstated in the source, and consideration cannot simply be paid in cash per share under the classic merger conditions. **Exam cue:** merger → continuity + pooling; verify the exact shareholder threshold in AS 14.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"answer-key-review","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2025-Jun","explanation":"The merger conditions require 90% (not 95%) shareholder continuity, consideration wholly in equity shares (not cash), and intention to continue the business - so B, C and E are the incorrect statements. [PYQ: UGC NET Commerce, 2025-Jun]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"71c3bfe0a82e62a50a0155fd2a44def7ea676c7e20a8fa1754f39ca0f5064ee7","kind":"pyq"},{"id":"pyq-361","sourceNumber":361,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Who can file petition to the Tribunal for the Winding up of a Limited Liability Partnership? A. Secured Creditors B. LLP or any of its Partners C. Registrar of Companies D. Any person authorised by the central Government E. Any Voluntary Association Choose the correct answer from the options given below:","options":["A, B, C Only","Aand B Only","A, B, C and D Only","B, C and E Only"],"answer":2,"source":"UGC NET Commerce, Jun 2025","explanation":"**Why C is the supplied answer — A, B, C and D:** The LLP Act permits a winding-up petition to be made by specified parties, which may include the LLP or its partners, creditors, the Registrar and persons authorised by the Central Government, subject to the statutory grounds and conditions. A voluntary association as such is not automatically an eligible petitioner. **Legal note:** confirm the applicable version of the LLP Act and rules for current proceedings.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"answer-key-review","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e0cd60743772289822e816f145d9022d538255f74441725db4fd2a92fa8e529f","kind":"pyq"},{"id":"pyq-362","sourceNumber":362,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In case of transmission of shares, which of the following is correct? A. No instrument of transfer is required. B. Transmission of securities is generally made without any consideration. C. Shares continue to be subject to the original liabilities. D. Transmission takes place on death or insolvency of a holder of securities. E. Stamp duty is payable on transmission of securities. Choose the correct answer from the options given below:","options":["A, B, C and D Only","B, C and D Only","C, D and E Only","A, B, C Only"],"answer":0,"source":"UGC NET Commerce, Jun 2025 | Also from: Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2025-Jun","explanation":"**Why A is correct — A, B, C and D:** Transmission occurs by operation of law, such as on death or insolvency, rather than by a voluntary transfer instrument. It is generally without consideration, and the securities remain subject to the relevant rights/liabilities attached to them. Stamp duty applicable to a transfer instrument is generally not charged in the same way to transmission because no transfer instrument is required. **Exam distinction:** transfer = voluntary instrument; transmission = operation of law.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2025-Jun","explanation":"Transmission (by operation of law on death/insolvency) needs no transfer instrument or consideration, and the shares remain subject to their liabilities; stamp duty is NOT payable on transmission. [PYQ: UGC NET Commerce, 2025-Jun]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"2c2961db12240861f6f7c4abf3a77872ea50401965c30e54f8e5614fb36d16a6","kind":"pyq"},{"id":"pyq-363","sourceNumber":363,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"What would be the main concern for the company if it has to issue green bonds for financing?","options":["High interest rate","Less repayment period","Limited investor demand due to niche market","Goverment restriction"],"answer":2,"source":"UGC NET Commerce, Jun 2025","explanation":"**Why C is correct — Limited investor demand:** Green bonds finance eligible environmental projects and may appeal to investors with sustainability mandates. A company’s concern can be whether the investor base is sufficiently deep and whether the issuer can meet reporting/verification requirements; a niche market can limit demand. This does not mean green bonds always have higher interest rates or shorter repayment periods. **Exam cue:** specialised instrument → possible investor-demand constraint.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"What would be the main concern for the company if it has to issue green bonds for financing?","options":["High interest rate","Less repayment period","Limited investor demand due to niche market","Goverment restriction"],"answer":2,"explanation":"**Why C is correct — Limited investor demand:** Green bonds finance eligible environmental projects and may appeal to investors with sustainability mandates. A company’s concern can be whether the investor base is sufficiently deep and whether the issuer can meet reporting/verification requirements; a niche market can limit demand. This does not mean green bonds always have higher interest rates or shorter repayment periods. **Exam cue:** specialised instrument → possible investor-demand constraint.","revision":"original","contentSignature":"2df6c7492931c1328e72022c9aceac68c9559cc0bd7dbca7b1157e143b8755d4"}],"contentSignature":"2df6c7492931c1328e72022c9aceac68c9559cc0bd7dbca7b1157e143b8755d4","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"pyq"},{"id":"pyq-364","sourceNumber":364,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Periodic total of Purchase day book is posted to","options":["Creditor Account","Debtor Account","Purchase Account","Purchase Memorandum Account"],"answer":2,"source":"SSC CGL AAO, 2016","explanation":"**Why C is correct — Purchase Account:** The periodic total of the Purchase Day Book is posted to the debit of the Purchases Account. Individual supplier entries are credited to their personal/creditor accounts. **Exam cue:** credit purchase of goods → Purchases Dr, Supplier/Creditor Cr.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"4f14277d9ee8c2cfa1e862548fd1b82ca5c4c7709e3e57e9f9ccf6ee295e07f7","kind":"pyq"},{"id":"pyq-365","sourceNumber":365,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"If outside liability and owners equity are added we get:","options":["Total Liabilities","Net Worth","Share Holders Fund","Gross Block"],"answer":0,"source":"SSC CGL AAO, 2016","explanation":"**Why A is correct — Total liabilities:** The accounting equation is Assets = Liabilities + Owners’ Equity. When outside liabilities and owners’ equity are added, the total equals the total claims against the business, often presented as total liabilities/equity and liabilities side total. **Exam cue:** outsiders’ claims + owners’ claim = total financing of assets.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"d04f05d98f1694a1016ba192a8cdb2be53960ee12eed616a7584c8e0978591b0","kind":"pyq"},{"id":"pyq-366","sourceNumber":366,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The highest share in power generation in India is of","options":["Atomic power","Hydro power","Thermal power","Wind power"],"answer":2,"source":"SSC CGL AAO, 2016","explanation":"**Historical-data note:** The source exam’s intended answer is thermal power, which accounted for the largest share of electricity generation in India around the period of the 2016 exam. The mix changes over time as renewable and other capacity expands, so this should be treated as a source-era general-knowledge fact rather than an evergreen current statistic.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c24be9c127c181a132b45cd59208393d25dc3bdaa0c490aad38cb8ec1b441a3d","kind":"pyq"},{"id":"pyq-367","sourceNumber":367,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"NABARD’s primary role is –","options":["To act as an finance institution","To issue shares in the market","To underwrite shares of govt agencies","To act as a bank"],"answer":0,"source":"SSC CGL AAO, 2016","explanation":"**Why A is correct — Financial institution:** NABARD is India’s apex development financial institution for agriculture and rural development. It provides refinance, development support, supervision and credit planning for rural financial institutions; it is not primarily a share-issuing or share-underwriting agency. **Exam cue:** NABARD → agriculture/rural development finance.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"cc5aec28ade44855c7517c1afff0b14dffbd920906537dd5c116d4e1e9cc6a29","kind":"pyq"},{"id":"pyq-368","sourceNumber":368,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"If the partnership deed is silent, then what is the minimum salary or other remuneration paid to partner every month for taking part in the conduct of the business?","options":["Rs 10,000","Rs 20,000","10% of capital brought by partner","No salary"],"answer":3,"source":"SSC CGL AAO, 2017","explanation":"**Why D is correct — No salary:** If the partnership deed is silent, a partner is not entitled to remuneration merely for taking part in conducting the business under the default rule of the Indian Partnership Act, 1932. Salary or commission is payable only if agreed by the partners. **Exam cue:** no deed provision → no partner salary.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"972414dbe6a1a2d2cca70118bf0ddc026f734c6df938fd0ab82b32b4c6fa2c1a","kind":"pyq"},{"id":"pyq-369","sourceNumber":369,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which among the following is a capital receipts?","options":["Amount received by way of loans","Money obtained from sale of goods","Dividend received on investments","Commission and fees received for services rendered"],"answer":0,"source":"SSC CGL AAO, 2017","explanation":"**Why A is correct — Loan proceeds:** A loan is a capital receipt because it creates a financing liability and is not earned from the ordinary sale of goods or provision of services. Sales, dividends and service commission/fees are generally revenue receipts in the relevant accounting context. **Exam cue:** borrowing proceeds → capital receipt; operating income → revenue receipt.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"b181c3c9267c9d5bfcf1b0a1f92134418f994a797c06155334199a30172be204","kind":"pyq"},{"id":"pyq-370","sourceNumber":370,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following statement is NOT TRUE in regard to reserve and provision?","options":["A provision is a charge against profit whereas reserve is an appropriation of profit.","Provision reduces taxable profit whereas reserves increase taxable profit.","Provision cannot be used for distribution as dividend whereas reserve can be used for dividend distribution.","Provision is made for a known liability or expense pertaining to current accounting period where as reserve is created for strengthening the financial position of business."],"answer":1,"source":"SSC CGL AAO, 2017","explanation":"**Why B is correct — not true:** A provision is generally charged against profit for a known liability/expense or a probable loss, while a reserve is an appropriation of profit. However, it is not universally true that a provision reduces taxable profit and reserves increase taxable profit; tax deductibility depends on the relevant tax rules and nature of the provision. **Exam cue:** accounting treatment does not automatically determine tax treatment.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8de2d4cb2ab409db4e62f742eb149330eb512bc5e4ed556292c4b4ac0381509f","kind":"pyq"},{"id":"pyq-371","sourceNumber":371,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"According to Partnership Act 1932, which account is debited for the transfer of net loss?","options":["Profit and loss account","Capital account","Cash account","Owner’s account"],"answer":1,"source":"SSC CGL AAO, 2017 | Also from: Corporate Accounting 404 Bank — PYQ: SSC CGL AAO, 2017","explanation":"**Why B is correct — Capital Account:** When a partnership incurs a net loss, the loss is transferred to the partners’ capital accounts in their profit-sharing ratio (or current accounts under the relevant accounting system). The entry debits partners’ capital/current accounts and credits the Profit and Loss Account. **Exam cue:** net loss allocation reduces partners’ capital.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: SSC CGL AAO, 2017","explanation":"Net loss is transferred by debiting the partners capital accounts and crediting the profit and loss account. [PYQ: SSC CGL AAO, 2017]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e4536b1744ce830eefe632abc5eeb6c48031a604709ce3f48ce4e6f5719463e8","kind":"pyq"},{"id":"pyq-372","sourceNumber":372,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In order to compensate the investors, what kind of debentures are issued at substantial discount and the difference between the nominal value and the issue price is treated as the amount of interest related to the duration of the debentures?","options":["Zero coupon rate debenture","Bearer debentures","Specific coupon rate debentures","Naked debentures"],"answer":0,"source":"SSC CGL AAO, 2017 | Also from: Corporate Accounting 404 Bank — PYQ: SSC CGL AAO, 2017","explanation":"**Why A is correct — Zero-coupon debenture:** A zero-coupon debenture is issued at a substantial discount and redeemed at face value. The difference between issue price and redemption/nominal value represents the investor’s return over the term rather than periodic coupon interest. **Exam cue:** no periodic coupon; return arises from discount-to-redemption difference.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: SSC CGL AAO, 2017","explanation":"Zero coupon (deep discount) debentures pay no periodic interest - the issue discount is the entire interest.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c36d500f64896dfba6eb485ae0ba658bb5237691de75d72966ee4fc674c8e8fd","kind":"pyq"},{"id":"pyq-373","sourceNumber":373,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"If the value of debentures is less than the value of the net asset taken over, then the difference will be credited to:","options":["Goodwill account","Capital reserve account","General reserve account","Debenture account"],"answer":1,"source":"SSC CGL AAO, 2017","explanation":"**Why B is correct — Capital reserve:** If the value of net assets taken over exceeds the consideration represented by debentures in the relevant acquisition/amalgamation calculation, the excess is a capital gain/reserve rather than goodwill. Goodwill generally arises when consideration exceeds the acquired net assets. **Exam cue:** net assets > consideration → capital reserve; consideration > net assets → goodwill.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"2aeb2baf48dd32261bd3f4854e9bbdcf143b7a76f9701a4565a03a46b6990a20","kind":"pyq"},{"id":"pyq-374","sourceNumber":374,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The part of capital which is called-up only on winding up is called ______.","options":["Reserve capital","General reserve","Capital reserve","Capital redemption reserve"],"answer":0,"source":"SSC CGL AAO, 2017 | Also from: Corporate Accounting 404 Bank — PYQ: SSC CGL AAO, 2017","explanation":"**Why A is correct — Reserve capital:** Reserve capital is the portion of uncalled share capital that the company resolves to call only if it is wound up. It differs from general reserve, capital reserve and capital redemption reserve, which have different purposes and accounting/legal treatments. **Exam cue:** called only on winding-up → reserve capital.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: SSC CGL AAO, 2017","explanation":"Reserve capital is the uncalled portion resolved to be called only at winding up (s.65). [PYQ: SSC CGL AAO, 2017]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"f69a662b1dbbdc9da4a0ed155aa11f727980fc72469645ce43e880ab4d325de5","kind":"pyq"},{"id":"pyq-375","sourceNumber":375,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"From which of the following, companies cannot buy its own shares?","options":["Odd lot shareholders","Open market","Existing equity shareholders on a disproportionate basis","Employees of the company"],"answer":2,"source":"SSC CGL AAO, 2017","explanation":"**Why C is correct:** A company’s buy-back must follow the statutory routes and conditions, such as an offer to existing shareholders on a proportionate basis, open-market purchases where permitted, or purchase of odd lots/other specified methods. A buy-back cannot be conducted by selectively purchasing from existing equity shareholders on a disproportionate basis outside the permitted framework. **Exam cue:** proportionate offer, not arbitrary selective buy-back.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"From which of the following, companies cannot buy its own shares?","options":["Odd lot shareholders","Open market","Existing equity shareholders on a disproportionate basis","Employees of the company"],"answer":2,"explanation":"**Why C is correct:** A company’s buy-back must follow the statutory routes and conditions, such as an offer to existing shareholders on a proportionate basis, open-market purchases where permitted, or purchase of odd lots/other specified methods. A buy-back cannot be conducted by selectively purchasing from existing equity shareholders on a disproportionate basis outside the permitted framework. **Exam cue:** proportionate offer, not arbitrary selective buy-back.","revision":"original","contentSignature":"21a6eb1968f27de953b6be83a73d2f40ca1296e76ab2309d62989b18fe8a88d1"}],"contentSignature":"21a6eb1968f27de953b6be83a73d2f40ca1296e76ab2309d62989b18fe8a88d1","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"pyq"},{"id":"pyq-376","sourceNumber":376,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A and B share profit in the ratio of 5 : 2. C is admitted as a partner who sets 1/7 share. If C acquires 3/28 from A and 1/28 from B, then what will be the new profit sharing ratio?","options":["19 : 5 : 4","17 : 7 : 4","15 : 9 : 4","16 : 8 : 4"],"answer":1,"source":"SSC CGL AAO, 2017","explanation":"**Why B is correct — 17:7:4:** Old shares: A = 5/7 = 20/28 and B = 2/7 = 8/28. C receives 3/28 from A and 1/28 from B, so A’s new share = 20/28 − 3/28 = 17/28; B’s = 8/28 − 1/28 = 7/28; C’s = 4/28. New ratio = **17:7:4**.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"2a72d1b0d30d1cd826828e85cfc5faf12f96d6ac3ac5303e7fa56a6195aac2e7","kind":"pyq"},{"id":"pyq-377","sourceNumber":377,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"XYZ Corporation is a manufacturing company that sells its products to customers on credit. The company also incurs various expenses throughout the year, such as rent, utilities, and salaries. At the end of the accounting period, XYZ Corporation prepares its financial statements, which include the income statement and the balance sheet. Which accounting concept is applied when XYZ Corporation makes adjustments regarding prepaid expenses and outstanding expenses in its final accounts and when it recognizes deferred revenue expenditure?","options":["Realisation concept","Dual Aspect Concept","Conservatism Principle","Matching Concept"],"answer":3,"source":"JAIIB AFM, 2023","explanation":"**Why D is correct — Matching concept:** The matching concept aligns expenses with the revenues they help generate in the same accounting period. Prepaid expenses are carried forward as assets until the related benefit is consumed; outstanding expenses are accrued as liabilities and charged to the period; deferred revenue expenditure is allocated according to the applicable accounting treatment. **Exam cue:** expense belongs to the period in which its related benefit/revenue is recognised, subject to the accounting framework.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"7b93f0a543aa678a9cc1573590b8aef7e055c4788ce2221a6905a743d18cf12a","kind":"pyq"},{"id":"pyq-378","sourceNumber":378,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"ABC Manufacturing Company purchased a machine for Rs. 1,00,000 with an estimated useful life of 5 years and an estimated total production of 50,000 units. In the first year, the machine produced 6,500 units. Using the units of production method, what is the depreciation expense for the first year, if the salvage value of the machine is Rs. 10,000 ?","options":["Rs. 11,700","Rs. 11,500","Rs. 11,300","Rs. 11,900"],"answer":0,"source":"JAIIB AFM, 2023","explanation":"**Why A is correct — ₹11,700:** Depreciable amount = Cost ₹1,00,000 − Salvage value ₹10,000 = ₹90,000. Depreciation per unit = ₹90,000 ÷ 50,000 units = ₹1.80 per unit. First-year depreciation = 6,500 × ₹1.80 = **₹11,700**. **Formula:** units-of-production depreciation = (cost − residual value)/estimated total units × actual units produced.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"fba19764ac887b79808ecf53548c9dcada42d73356b4db4f28cb9a486f5c6e17","kind":"pyq"},{"id":"pyq-379","sourceNumber":379,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company issues preference shares for a period exceeding _____ years but less than _____ years for _____ projects.","options":["30, 40, commercial","30, 40, infrastructure","20,30, commercial","20,30, infrastructure"],"answer":3,"source":"JAIIB AFM, 2023 | Also from: Corporate Accounting 404 Bank — PYQ: JAIIB AFM, 2023","explanation":"**Why D is correct — 20, 30, infrastructure:** The general maximum redemption period for preference shares is 20 years under the Companies Act, 2013. A limited exception permits certain infrastructure-project preference shares to be issued for a period exceeding 20 years but not exceeding 30 years, subject to prescribed redemption requirements. **Legal note:** apply the statutory conditions and current rules when answering a real compliance question.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: JAIIB AFM, 2023","explanation":"The s.55 proviso lets infrastructure projects issue preference shares redeemable beyond 20 but within 30 years.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e418ba39349143029f6afb0e7178c01d5caf28a5b65f020184bf3efd0775f489","kind":"pyq"},{"id":"pyq-380","sourceNumber":380,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Company ABC has current assets of Rs. 1,50,000 and current liabilities of Rs. 75,000. Calculate the current ratio if inventory is Rs. 35,000.","options":["2:1 1","1.53: 1","1: 2","1:1.53"],"answer":0,"source":"JAIIB AFM, 2023","explanation":"**Why A is correct — 2:1:** Current ratio = Current assets ÷ Current liabilities = ₹1,50,000 ÷ ₹75,000 = **2:1**. Inventory is not needed for the current ratio; it is relevant when calculating the quick ratio. **Exam cue:** current ratio includes inventory; quick ratio generally excludes it.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"6e7b69138312407104f8ed42703904b65f70d3180021ddc0718e794e5670312f","kind":"pyq"},{"id":"pyq-381","sourceNumber":381,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following need not prepare a Cash Flow Statement?","options":["A publicly traded company","One Person Company","A government company","All of the above has to prepare a cash flow statement."],"answer":1,"source":"JAIIB AFM, 2023","explanation":"**Why B is correct — One Person Company:** Under the Companies Act, 2013, an OPC, small company and dormant company are generally exempt from preparing a cash flow statement as part of the financial statements, subject to the applicable statutory framework. Publicly traded and government companies generally must prepare one. **Legal note:** verify the current exemptions and rules for the company’s status.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"3153afd3ab934f60aba55b86caf3da347b2e9bea640e64a67a5c741e9f5171e8","kind":"pyq"},{"id":"pyq-382","sourceNumber":382,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Select the correct option which represents the classification of a company on the basis of ownership.","options":["Subsidiary Company","Holding Company","Chartered Company","Registered Company"],"answer":1,"source":"JAIIB AFM, 2023 | Also from: Corporate Accounting 404 Bank — PYQ: JAIIB AFM, 2023","explanation":"**Why B is the supplied answer — Holding company:** Holding/subsidiary status describes a relationship based on control or ownership and is a classification on the basis of ownership/control. Chartered and registered companies are classifications based on how a company is formed/registered. **Exam cue:** ownership/control classification → holding or subsidiary.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: JAIIB AFM, 2023","explanation":"Holding/subsidiary classification rests on ownership and control of another company; chartered and registered companies are classified by mode of incorporation. [PYQ: JAIIB AFM, 2023]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"dff8991eb49b3ebe483d55f99af87c77f410eb7ed6915af043d043a6e28286b5","kind":"pyq"},{"id":"pyq-383","sourceNumber":383,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"XYZ Corporation, a publicly listed company, is contemplating the issuance of bonus shares to its existing shareholders. The company has witnessed significant growth in its operations and wants to reward its shareholders by issuing bonus shares. The board of directors is in the process of evaluating this decision, considering various factors. As part of the decision-making process, the board is assessing the conditions that need to be met for the issuance of bonus shares. In the context of XYZ Corporation's consideration to issue bonus shares, which of the following is correct? I. No issue of bonus shares shall be made by capitalising reserves created by the revaluation of assets. II. A company which announces its bonus issue after the approval of the board of directors and does not require shareholders' approval for capitalisation of profits or reserves for making bonus issue as per the Articles of Association shall implement the bonus issue within thirty days from the date of such approval and shall not have the option of changing the decision. III. A company can issue bonus shares out of its free reserves and the securities premium account but not from the capital redemption reserve account. IV. The bonus shares shall not be issued in lieu of dividends.","options":["II and III only","I and IV only","II and IV only","I and III only"],"answer":1,"source":"JAIIB AFM, 2023","explanation":"**Why B is correct — I and IV only:** Bonus shares cannot be issued by capitalising reserves created by revaluation of assets, and bonus shares cannot be issued in lieu of dividend. Statement III is false because eligible free reserves, securities premium and capital redemption reserve may be used, subject to statutory conditions. Statement II is not correctly framed as a universal rule about approval and a 30-day implementation deadline. **Exam cue:** bonus issue uses eligible reserves; revaluation reserve is excluded.","auditStatus":"needs-review","auditNote":"Needs review: options A and D are duplicates, so the option set is defective.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"3275da42d5c2cab7b0e15aecd98be4efb028f847d8c357b2c550a1af08c3a35c","kind":"pyq"},{"id":"pyq-384","sourceNumber":384,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"If the present market value of equity shares of the firm is Rs. 150 and the expected earnings per share for the next year is Rs. 10. what will be the required rate of return on the firm's equity capital?","options":["15%","14.33%","6.67%","5%"],"answer":2,"source":"JAIIB AFM, 2023","explanation":"**Why C is correct — 6.67%:** The question uses the earnings-price ratio as the required return: EPS ÷ Market price per share = ₹10 ÷ ₹150 = 0.0667 = **6.67%**. This is a simplified earnings-yield approach; a full valuation may also consider growth, risk and dividend policy. **Exam cue:** earnings yield = EPS/market price.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"f0e7b50b915117a46f24d0ffa4c58f4a55ce24d750a35aab7104cfbf1ecf0dd9","kind":"pyq"},{"id":"pyq-385","sourceNumber":385,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Forfeiture of shares occurs when a shareholder fails to make the required payment for shares within the specified timeframe or as per the terms of the allotment. In such cases, the company has the right to forfeit, or cancel those shares. Which of the following journal entries is passed in case of forfeiture of shares?","options":["Share Capital A/c Dr. To Calls in Arrears A/c To Forfeited Shares A/c","Share Capital A/c Dr. Calls in Arrears A/c Dr. To Forfeited Shares A/c","Share Capital A/C Dr. To Forfeited Shares A/c","None of the above"],"answer":0,"source":"JAIIB AFM, 2023","explanation":"**Why A is correct:** On forfeiture, debit Share Capital for the called-up amount on the forfeited shares. Credit Calls in Arrears (or the relevant unpaid-call account) for the amount not received, and credit Share Forfeiture for the amount already received on share capital. **Typical entry:** Share Capital Dr → Calls in Arrears Cr → Share Forfeiture Cr.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"2ec2bfc1ef30287392ffb308e2e0d335b209eb830194525f824e89511ae5bf11","kind":"pyq"},{"id":"pyq-386","sourceNumber":386,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company is considering an investment project that requires an initial cash outflow of Rs. 1,00,000. The project is expected to generate cash inflows of Rs. 30,000 in the first year, Rs. 40,000 in the second year, and Rs. 50,000 in the third year. The discount rate is 10%. What is the Net Present Value (NPV) of the investment? Note: Discounting Factors (@10%) 0.909 0.826 0.751 Year 1 2 3","options":["2140","–2140","–1990","1990"],"answer":1,"source":"JAIIB AFM, 2023","explanation":"**Why B is correct — NPV = −₹2,140:** Present value of inflows = ₹30,000×0.909 + ₹40,000×0.826 + ₹50,000×0.751 = ₹27,270 + ₹33,040 + ₹37,550 = ₹97,860. NPV = PV of inflows − initial investment = ₹97,860 − ₹1,00,000 = **−₹2,140**. A negative NPV at the 10% discount rate means the project does not meet that required return under the given assumptions.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"852561388ad9605fa2d1e463a28659a2943beddc273dae66136325ed91b91ebb","kind":"pyq"},{"id":"pyq-387","sourceNumber":387,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The ROI is a concept that measures:","options":["The total revenue generated by a firm","The profit earned on investing a unit of capital","The market share of a company","The total assets owned by a business"],"answer":1,"source":"JAIIB AFM, 2023","explanation":"**Why B is correct:** Return on Investment (ROI) measures the profit/return generated relative to the capital invested. It is commonly expressed as a percentage of investment or capital employed, depending on the definition used. It is not the same as total revenue, market share or total assets. **Exam cue:** ROI = return ÷ investment.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"de36afbea4867b1e6ec12afe19485f0b32a9b818326454085248ffca8bc0f743","kind":"pyq"},{"id":"pyq-388","sourceNumber":388,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company which has been successful in its operations, can issue shares at a premium. When shares are issued at higher than the face value of the shares, they are said to be issued at a premium. Premium amount cannot be utilised for:","options":["Buy back of shares.","Issue of fully paid bonus shares.","Paying premium on redemption of preference shares or debentures.","Paying off dividends to shareholders"],"answer":3,"source":"JAIIB AFM, 2023 | Also from: Corporate Accounting 404 Bank — PYQ: JAIIB AFM, 2023","explanation":"**Why D is correct — Paying dividends:** The securities premium account may be used for specified purposes under section 52, such as issuing fully paid bonus shares, writing off eligible issue expenses/discount, paying premium on redemption, and buy-back subject to the law. It cannot be used to pay ordinary dividends to shareholders. **Legal cue:** securities premium uses are restricted by statute.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: JAIIB AFM, 2023","explanation":"Section 52(2) permits bonus issue, issue expenses, redemption premium and buy-back - dividend is not a permitted use of securities premium. [PYQ: JAIIB AFM, 2023]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"9e7f9862fc1b1408f22aa90daf4569b6813a40da95a32364ee4f92d4fe7a3267","kind":"pyq"},{"id":"pyq-389","sourceNumber":389,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following will be entered in the credit side of the Profit and Loss Appropriation A/c ?","options":["Transfer to reserve/general reserve.","Amount withdrawn from a general reserve or any other reserve.","Transfer to dividend/interim dividend/proposed dividend.","Surplus transferred to balance sheet."],"answer":1,"source":"JAIIB AFM, 2023","explanation":"**Why B is correct:** A transfer to reserve, dividends and surplus carried forward are appropriations/debits from the Profit and Loss Appropriation Account. An amount withdrawn from a general reserve or another reserve is credited back into the appropriation account in the conventional presentation. **Exam cue:** reserve created → debit appropriation; reserve used/withdrawn → credit appropriation.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"068a1f7fb087842cb204a54ea35a5e996c16ef1ffaebe5391d4ab65f0802619e","kind":"pyq"},{"id":"pyq-390","sourceNumber":390,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"ABC Company, a supplier of electronic components, has entered into a transaction with XYZ Corporation for the purchase of goods on credit. To formalize the credit arrangement and ensure payment at a later date, Company decided to draw a Bill of Exchange. In this scenario, Company is the","options":["Payee","Drawer","Drawee","Endorser"],"answer":1,"source":"JAIIB AFM, 2023","explanation":"**Why B is correct — Drawer:** The drawer is the party who draws/prepares the bill of exchange and orders the drawee to pay the specified amount. The drawee is the party directed to pay; the payee is the person who receives the payment; an endorser transfers the instrument by endorsement. **Exam cue:** draws the bill = drawer.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"2c2f6ba7c77cd9444115afa19ec9933fe4ab595ac5f962f08d44ee9a86946a43","kind":"pyq"},{"id":"pyq-391","sourceNumber":391,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In case of forfeiture of shares due to nonreceipt of payment by the shareholder, which of the following accounts will be credited?","options":["Share Capital A/c","Calls in Arrears A/c","Forfeited Shares A/c","Both B and C"],"answer":3,"source":"JAIIB AFM, 2023","explanation":"**Why D is correct — Both B and C:** On forfeiture, Share Capital is debited for the called-up amount. The unpaid calls are removed by crediting Calls in Arrears, and the amount already received on share capital is credited to Share Forfeiture. Therefore both Calls in Arrears and Share Forfeiture are credited in the usual entry. **Exam cue:** unpaid amount → Calls in Arrears Cr; amount received → Forfeiture Cr.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"147396a95912eba74da2fe80ea081622417989bca97cf063e52fc7cc713ac6eb","kind":"pyq"},{"id":"pyq-392","sourceNumber":392,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"First Annual General Meeting (AGM) must be held within __________ from the end of the first financial year of the company.","options":["6 months","9 months","12 months","15 months"],"answer":1,"source":"NABARD Grade A, 2020 | Also from: Corporate Accounting 404 Bank — PYQ: NABARD Grade A Finance, 2020","explanation":"**Why B is correct — 9 months:** Under the Companies Act, 2013, a company’s first AGM must generally be held within nine months from the close of its first financial year. Subsequent AGMs are generally held within six months from financial year-end, subject to the statutory rules and extensions where applicable. **Memory cue:** first AGM = 9 months; later AGMs = 6 months.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — PYQ: NABARD Grade A Finance, 2020","explanation":"Section 96(1): the first AGM within 9 months of the first financial year-end. [PYQ: NABARD Grade A Finance, 2020]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"b9b8c1ff01e1998fce6eab06daa4183a6b4ca45a0c7827ecb35d4a789cdad19b","kind":"pyq"},{"id":"pyq-393","sourceNumber":393,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company purchased machinery in order to increase production, it will be recorded under:","options":["Revenue expenditure","Capital expenditure","Deferred expenditure","Capital receipts"],"answer":1,"source":"NABARD Grade A, 2020","explanation":"**Why B is correct — Capital expenditure:** Machinery bought to increase production is a long-term operating asset that is expected to provide benefits over multiple accounting periods. Its purchase is therefore capital expenditure, and its cost is generally allocated over its useful life through depreciation. **Exam cue:** acquire/improve long-term productive asset → capital expenditure.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c05e53b3500306bc95d19135a83cd93f8cb229b2d1c3d75d94997bd7ef7905af","kind":"pyq"},{"id":"pyq-394","sourceNumber":394,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Calculate Net cashflow from the following details o Depreciation expenses= 10,000 o Proceeds from the sale of equipment used in the business= 6,000 o The proceeds from the sale of the automobiles= 50,000 o Purchase of Treasury Stock (company's own stock).= 20,000","options":["56,000","46,000","36,000","26,000"],"answer":2,"source":"NABARD Grade A, 2020","explanation":"**Why C is correct — ₹36,000 net cash flow:** Depreciation of ₹10,000 is a non-cash expense, so it is not itself a cash inflow/outflow in a net-cash calculation. Sale of equipment brings in ₹6,000; sale of automobiles brings in ₹50,000; purchase of treasury stock uses ₹20,000. Net cash flow from the listed cash transactions = ₹6,000 + ₹50,000 − ₹20,000 = **₹36,000**. Classification is investing for asset sales and financing for treasury-stock purchase.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"be33dcfc5b6d4c11c38bebe4e94dd44969f75d4338e0769e43ab5045fa9390c6","kind":"pyq"},{"id":"original-extra-011","sourceNumber":"EX-011","subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Securities premium is generally presented under:","options":["Current liabilities on the face of the balance sheet","Trade receivables among the current assets","Other equity/reserves and surplus","Share capital on the face of the balance sheet"],"answer":2,"source":"Original practice question (not a previous-year question)","explanation":"Securities premium is a reserve within equity, subject to applicable company-law presentation.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Securities premium is generally presented under:","options":["Current liabilities","Trade receivables","Other equity/reserves and surplus","Share capital"],"answer":2,"explanation":"Securities premium is a reserve within equity, subject to applicable company-law presentation.","revision":"original","contentSignature":"cc545e66047001c788bb6b857fa7cd80d1238f3e2dba1e8d93b9ef5d09d7e4c9"}],"contentSignature":"8a9ee1e15cc08ed0ba46b34a3ef3a02c4a20abbf4fdafabf497a91f9a674eded","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-012","sourceNumber":"EX-012","subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A bonus issue is made by capitalising:","options":["Trade payables outstanding at the date of the issue","Unpaid wages outstanding at the date of the issue","The bank overdraft outstanding at the date of the issue","Eligible reserves or securities premium as permitted"],"answer":3,"source":"Original practice question (not a previous-year question)","explanation":"A bonus issue converts eligible reserves into share capital without fresh cash from shareholders.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A bonus issue is made by capitalising:","options":["Trade payables","Unpaid wages","Bank overdraft","Eligible reserves or securities premium as permitted"],"answer":3,"explanation":"A bonus issue converts eligible reserves into share capital without fresh cash from shareholders.","revision":"original","contentSignature":"e2befa76cf7ca0fc615b40e6d9785d32bfa733e5ae128ff92e1710901a022ecf"}],"contentSignature":"a64187844719526114c5fdc358c3c781b388241dc54816a8c641d053162dfaf0","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-013","sourceNumber":"EX-013","subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In a rights issue, shares are first offered to:","options":["Existing equity shareholders in proportion as prescribed","The debenture holders of the company alone","The employees of the company alone","The general public, without any preference to existing holders"],"answer":0,"source":"Original practice question (not a previous-year question)","explanation":"Rights issues generally provide existing equity shareholders a proportionate entitlement, subject to law and offer terms.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In a rights issue, shares are first offered to:","options":["Existing equity shareholders in proportion as prescribed","Only debenture holders","Only employees","The general public without preference"],"answer":0,"explanation":"Rights issues generally provide existing equity shareholders a proportionate entitlement, subject to law and offer terms.","revision":"original","contentSignature":"f2da13b893efcf50da34130d45e708e884d5176da0c7b2b5682d58ddcb1c795e"}],"contentSignature":"3ccd807b60e7136ad2bbb7045d7c24f461f01846eae0960cec1be30fae15a53c","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-014","sourceNumber":"EX-014","subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Goodwill arising on acquisition is broadly the excess of:","options":["The cash paid over the liabilities taken over","Consideration over the acquirer's share of identifiable net assets","The share capital over the reserves","The identifiable net assets over the consideration paid by the acquirer"],"answer":1,"source":"Original practice question (not a previous-year question)","explanation":"Goodwill generally reflects consideration exceeding the fair value of the acquirer's share of identifiable net assets acquired.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Goodwill arising on acquisition is broadly the excess of:","options":["Cash over liabilities","Consideration over the acquirer's share of identifiable net assets","Share capital over reserves","Net identifiable assets over consideration"],"answer":1,"explanation":"Goodwill generally reflects consideration exceeding the fair value of the acquirer's share of identifiable net assets acquired.","revision":"original","contentSignature":"b2f9c4981f77c2d85edaf9f5b13ca0ec1090222b5908aca24e91a477d9265c15"}],"contentSignature":"4ab120ae8862f40ca1633d0efdb11e222d2bb2c8a6a5bc3feafaaef1198d1254","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-015","sourceNumber":"EX-015","subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A debenture is primarily a:","options":["Inventory item","Revenue reserve","Debt instrument","Ownership instrument"],"answer":2,"source":"Original practice question (not a previous-year question)","explanation":"Debenture holders are creditors, not owners merely by holding the debenture.","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8e6b03d2dfb18b704d2baad1948261f662283f1471eb60eefb9a928b1f18cb1d","kind":"mcq"},{"id":"original-extra-016","sourceNumber":"EX-016","subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Calls in arrears represent:","options":["Amount received from shareholders before it is due","Dividend declared but not yet paid","Premium received on the issue of shares","Amount called but not received from shareholders"],"answer":3,"source":"Original practice question (not a previous-year question) | Also from: Corporate Accounting 404 Bank — Original","explanation":"Calls in arrears are called-up amounts not paid by shareholders by the due date.","alternateExplanations":[{"source":"Corporate Accounting 404 Bank — Original","explanation":"Calls in arrears are shown as a deduction from called-up capital in the share-capital note to the balance sheet.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded"}],"revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Calls in arrears represent:","options":["Amount received before it is due","Dividend declared but unpaid","Premium received on shares","Amount called but not received from shareholders"],"answer":3,"explanation":"Calls in arrears are called-up amounts not paid by shareholders by the due date.","revision":"original","contentSignature":"8a12b784d72a155f11a515c5b687667497fbf1f139da6440228a782a84925dcd"}],"contentSignature":"536b6020f6e7b7d94628051f015c6ab86f988a29fb87a04fd08d73ab16c1c28c","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-017","sourceNumber":"EX-017","subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A cash flow statement classifies cash flows into:","options":["Operating, investing and financing activities","Assets, liabilities and equity","Direct, indirect and contingent costs","Fixed and variable activities"],"answer":0,"source":"Original practice question (not a previous-year question)","explanation":"These are the three standard activity classifications.","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"3795f7a07ec6600ca12762f7705b1d90d959d70491cd349a39488cca0b0ebba3","kind":"mcq"},{"id":"original-extra-018","sourceNumber":"EX-018","subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"When shares are issued at a premium, the premium is credited to:","options":["The Calls in Arrears Account of the company","Securities Premium Account/reserve","The General Expenses Account","The Sales Account"],"answer":1,"source":"Original practice question (not a previous-year question)","explanation":"Share premium is credited to the securities premium account/reserve, subject to applicable law.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"When shares are issued at a premium, the premium is credited to:","options":["Calls in Arrears","Securities Premium Account/reserve","General Expenses","Sales Account"],"answer":1,"explanation":"Share premium is credited to the securities premium account/reserve, subject to applicable law.","revision":"original","contentSignature":"a28afdf55313a714fa3f990309ebb86be2ed9cf2fc6a583238968febd92c71e0"}],"contentSignature":"6d5f7f7dfb95385137d042acd131f5515177858fd640fb0d8ddd1936c0cd0944","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-019","sourceNumber":"EX-019","subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A buy-back of shares generally results in:","options":["No change in share count in any case","Automatic conversion into debentures","A reduction in outstanding shares","An increase in outstanding shares"],"answer":2,"source":"Original practice question (not a previous-year question)","explanation":"Shares bought back and extinguished reduce the outstanding share count.","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"95739ad430658cf8f4a05b02d9dc878b99dcb523d72e997ded59954fc8333bb0","kind":"mcq"},{"id":"original-extra-020","sourceNumber":"EX-020","subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Dividend declared but not yet paid is generally recognised as:","options":["An item of inventory awaiting distribution to the members","An addition to the share premium","An item of revenue for the year","A liability when the declaration creates the obligation"],"answer":3,"source":"Original practice question (not a previous-year question)","explanation":"Once a valid declaration creates an obligation, the unpaid dividend is a liability.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Dividend declared but not yet paid is generally recognised as:","options":["Inventory","Share premium","Revenue","A liability when the declaration creates the obligation"],"answer":3,"explanation":"Once a valid declaration creates an obligation, the unpaid dividend is a liability.","revision":"original","contentSignature":"cd28ff0064cacaf5dea7a9315e4aaa2750b932acc778e09c49a50447db379abc"}],"contentSignature":"91096d2c167cd2574e42c2e0617bf00f57889575f66b0e11b05bdc9196b9bc4a","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-1","sourceNumber":1,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company is defined under which section of the Companies Act, 2013?","options":["Section 2(45)","Section 2(62)","Section 2(71)","Section 2(20)"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 2(20): \"company\" means a company incorporated under this Act or under any previous company law.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"005293f1e5ad9010d390bf1a9982d598de5ae005bce9e23ae5a23cca7c7c8de9","kind":"mcq"},{"id":"corp404-2","sourceNumber":2,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The most important feature that distinguishes a company from a partnership firm is:","options":["It prepares annual accounts","It is a separate legal entity distinct from its members","It has members who own shares","It carries on business for profit like a partnership firm"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Incorporation creates an artificial person in law: the company owns property, contracts, sues and is sued in its own name.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The most important feature that distinguishes a company from a partnership firm is:","options":["It prepares accounts","It is a separate legal entity distinct from its members","It has members","It carries on business"],"answer":1,"explanation":"Incorporation creates an artificial person in law: the company owns property, contracts, sues and is sued in its own name. [Original]","revision":"original","contentSignature":"a860700bce0670a3db662178163303fb7e9817ac1c6c34717322546519fd4b53"}],"contentSignature":"21e66214935f4267df2116351277db3b573285555dc315a4e8d77fa22943a256","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-3","sourceNumber":3,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The separate legal personality of a company was firmly established in:","options":["Salomon v. Salomon & Co. Ltd. (1897)","Royal British Bank v. Turquand","Foss v. Harbottle","Ashbury v. Riche"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Salomon held that once validly incorporated, the company is distinct from its subscribers - even a one-man-controlled company.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"bfafc0dc60c7837d411aaabc99655595238f5116cbc7182607bfd979bdfc3cf6","kind":"mcq"},{"id":"corp404-4","sourceNumber":4,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"\"Perpetual succession\" of a company means:","options":["The company can never be closed down","The directors hold office permanently","Its existence continues unaffected by the death, insolvency or retirement of any member","The shares of the company never change hands during the lifetime of the company, staying with the first holders"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Members may come and go; the company continues until wound up as per law - \"members may come, members may go, but the company goes on\".","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"\"Perpetual succession\" of a company means:","options":["The company can never be closed","Directors hold office permanently","Its existence continues unaffected by the death, insolvency or retirement of any member","Shares never change hands"],"answer":2,"explanation":"Members may come and go; the company continues until wound up as per law - \"members may come, members may go, but the company goes on\". [Original]","revision":"original","contentSignature":"fc5fe67f9e6e4446e581f23dea252bf63f91703c605daeeee6beba271ecc14ab"}],"contentSignature":"190c2bde8183484f6c967a55068a91f814b8698dca1628b8fc75f926a5ccc2bb","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-5","sourceNumber":5,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In a company limited by shares, a member's liability is limited to:","options":["The amount unpaid, if any, on the shares held by him","The total assets of the company","His proportionate share of the company's debts","The face value of all the shares of the company taken together"],"answer":0,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"Section 2(22) read with s.4(1)(d)(i): once shares are fully paid, the member owes nothing more, whatever the company's debts. [Recall 2021]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In a company limited by shares, a member's liability is limited to:","options":["The amount unpaid, if any, on the shares held by him","The total assets of the company","His proportionate share of company debts","The face value of all company shares"],"answer":0,"explanation":"Section 2(22) read with s.4(1)(d)(i): once shares are fully paid, the member owes nothing more, whatever the company's debts. [Recall 2021]","revision":"original","contentSignature":"c1ee89109b4689dc524b2bc748a3c397b1fe7a2e9b11395f29c045fa2395e853"}],"contentSignature":"89eca649dc8c8fffb473610851afcb6e2dbb736e1bd303a572c3eb99aadfd87c","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-6","sourceNumber":6,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company is called an \"artificial person\" because:","options":["It has no members at all","It is created by law and acts through human agency (its Board and officers)","It cannot own property in its name and must hold it through its members always","It cannot be sued in a court"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Law clothes it with personality, but being invisible it acts only through natural persons - the directors and employees.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A company is called an \"artificial person\" because:","options":["It has no members","It is created by law and acts through human agency (its Board and officers)","It cannot own property","It cannot be sued"],"answer":1,"explanation":"Law clothes it with personality, but being invisible it acts only through natural persons - the directors and employees. [Original]","revision":"original","contentSignature":"a14c19ac618b2dc661a1f2bb36e33f290daae45d822a8957386578d67832ae90"}],"contentSignature":"1db651c347c60f81f98dbd709151dd26254e082227bac6d395ecec9fe142fd70","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-7","sourceNumber":7,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The doctrine of \"lifting the corporate veil\" is applied when:","options":["Shares are issued by the company at a premium to the existing shareholders of the company","The separate personality is used to commit fraud, evade tax or avoid legal obligations","A new director is appointed to the Board","The company incurs a loss in a year"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Courts ignore separate personality in exceptional cases - fraud, sham, enemy character, tax evasion, statutory duty avoidance.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The doctrine of \"lifting the corporate veil\" is applied when:","options":["Shares are issued at premium","The separate personality is used to commit fraud, evade tax or avoid legal obligations","A new director is appointed","The company makes a loss"],"answer":1,"explanation":"Courts ignore separate personality in exceptional cases - fraud, sham, enemy character, tax evasion, statutory duty avoidance. [Original]","revision":"original","contentSignature":"66481b0a3c33c9f1de7ca3f7bee3106b3b55478fe34721f2ff547493da7b4023"}],"contentSignature":"7107b80e1f3f5d81b6428119766ca73c4eaec14db0b444606bf08554c89fa084","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-8","sourceNumber":8,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The \"common seal\" of a company under the Companies Act, 2013 is now:","options":["Required only by public companies","Compulsory for every company","Abolished for all purposes by the Act, and no company can use a seal on any document at all","Optional - companies may dispense with it (documents then signed by authorised persons)"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"The 2013 Act made the common seal optional; where a company has no seal, documents are signed by two directors or a director plus CS/authorised officer.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The \"common seal\" of a company under the Companies Act, 2013 is now:","options":["Required only by public companies","Compulsory for every company","Abolished for all purposes","Optional - companies may dispense with it (documents then signed by authorised persons)"],"answer":3,"explanation":"The 2013 Act made the common seal optional; where a company has no seal, documents are signed by two directors or a director plus CS/authorised officer. [Original]","revision":"original","contentSignature":"62d235a9234b19e6784f2d4117d98bc2d905ab0493f2c986834cd5af2890929a"}],"contentSignature":"3c8e4a193ff3c60e4c265ecfe1dcc496151904268bd50a92cdc3968b41a1ba12","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-9","sourceNumber":9,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following is NOT a characteristic of a company?","options":["Unlimited liability of members","Transferability of shares (public company)","Separate legal entity","Perpetual succession"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Members of a limited company enjoy LIMITED liability - unlimited liability is a partnership/sole-trade feature.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"0ac598a8e6c8ae4e30d1b9cb48b9af626cdf8013aca245725358bc8a9cb7a58d","kind":"mcq"},{"id":"corp404-10","sourceNumber":10,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A \"One Person Company\" (OPC) under Section 2(62) is a company which has:","options":["Only one person as a member","Only one shareholder at incorporation who must be a company","Only one employee","Only one director"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"OPC = one member (a natural person, Indian citizen); a nominee must be named in the memorandum.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"6996825be22785bfe0d9aef436d4729030d4c7f47c07978a19ccdc539c8474e1","kind":"mcq"},{"id":"corp404-11","sourceNumber":11,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The minimum number of members required to form a PUBLIC company is:","options":["Fifty","One","Two","Seven"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 3(1)(a): seven or more persons for a public company; two or more for a private company.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"b33b9c781bfc2e160ce1943afb8d3b06d53ca511e65543a62424ddd4fbaa62b4","kind":"mcq"},{"id":"corp404-12","sourceNumber":12,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The maximum number of members permitted in a PRIVATE company is:","options":["50","100","No limit","200"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 2(68)(ii): private companies cap members at 200 (excluding present and past employee-members).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"7f4759b51a493b841058b47e1de6c36c9a4ac53dce5333c67ce3227131efd999","kind":"mcq"},{"id":"corp404-13","sourceNumber":13,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A private company CANNOT:","options":["Earn profits from its business","Invite the public to subscribe to its securities","Issue equity shares of any class","Have more than two directors on its Board at all"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 2(68)(iii): the articles must prohibit any invitation to the public to subscribe for securities - the core private-company restriction.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A private company CANNOT:","options":["Earn profits","Invite the public to subscribe to its securities","Issue equity shares","Have more than two directors"],"answer":1,"explanation":"Section 2(68)(iii): the articles must prohibit any invitation to the public to subscribe for securities - the core private-company restriction. [Original]","revision":"original","contentSignature":"43f7cbe5a2761b0ded0a4e7dc355b52ea21ce909c6fad381ed89734e56d30966"}],"contentSignature":"a301edd5b85ac561f966d7106f8fecf438821aebf6ce588f76da7329d54c7f80","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-14","sourceNumber":14,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A \"small company\" under Section 2(85), as per the limits currently in force, is one whose paid-up capital and turnover do NOT exceed respectively:","options":["Rs.10 crore and Rs.100 crore","Rs.4 crore and Rs.40 crore","Rs.1 crore and Rs.10 crore","Rs.50 lakh and Rs.2 crore"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"G.S.R. 880(E) dated 1-12-2025 raised the small-company limits to paid-up capital Rs.10 crore and turnover Rs.100 crore (earlier Rs.4 crore/Rs.40 crore); holding/subsidiary, s.8 and special-act companies remain excluded.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c3df921866ddd37f03c5b83c515ab9c99ee2e8fca70b41f0f0f1cc751e439fd2","kind":"mcq"},{"id":"corp404-15","sourceNumber":15,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A \"Government company\" under Section 2(45) is one in which the paid-up share capital held by Central/State Government(s) is not less than:","options":["51%","26%","100%","75%"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"51% or more paid-up share capital held by the Central Government, or by any State Government(s), or partly by both, makes it a Government company.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"134165062cc66748942651f6cee780faed663af9a4221f550e0dde847478a939","kind":"mcq"},{"id":"corp404-16","sourceNumber":16,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A \"holding company\" under Section 2(46) is a company that:","options":["Holds any number of shares in another company","Holds debentures issued by another company","Holds land and buildings in another company's name","Controls the composition of the Board, or exercises/controls more than one-half of the total voting power of another company"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Control over the Board OR more than half of total voting power (alone or with subsidiaries) makes a company the holding company; the other is its subsidiary under s.2(87).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A \"holding company\" under Section 2(46) is a company that:","options":["Holds any number of shares of another company","Holds debentures of another company","Holds land and buildings","Controls the composition of the Board, or exercises/controls more than one-half of the total voting power of another company"],"answer":3,"explanation":"Control over the Board OR more than half of total voting power (alone or with subsidiaries) makes a company the holding company; the other is its subsidiary under s.2(87). [Original]","revision":"original","contentSignature":"f98083d034928a612e740687be3cd4a8f3722b19153e4e1dd53b214249ce524f"}],"contentSignature":"4c3504e88cdde31a53f5203f0ab6e25d5d3015a1c7c4d9774f4a3e4957b85256","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-17","sourceNumber":17,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A \"foreign company\" under Section 2(42) is:","options":["A company incorporated outside India which has a place of business in India (physically or electronically) and conducts business activity here","Any company whose shares are held by foreign shareholders","A company listed on a stock exchange outside India","A company that exports goods from India"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Foreign incorporation PLUS a place of business in India plus conduct of business - mere foreign shareholding does not make an Indian company foreign.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A \"foreign company\" under Section 2(42) is:","options":["A company incorporated outside India which has a place of business in India (physically or electronically) and conducts business activity here","Any company having foreign shareholders","A company listed on a foreign stock exchange","A company exporting goods from India"],"answer":0,"explanation":"Foreign incorporation PLUS a place of business in India plus conduct of business - mere foreign shareholding does not make an Indian company foreign. [Original]","revision":"original","contentSignature":"405856f4068c62f46ca508c47350cd1befff2457bd227fa741aca25d4d87b21b"}],"contentSignature":"d4c455239e4f48f1562833e127efdb5d987d14c8c5c3a2d69ef13e0d45fcdc7a","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-18","sourceNumber":18,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company formed for promoting commerce, art, science, charity etc. which applies its profits to its objects and prohibits dividend is registered under:","options":["Section 465 of the Companies Act, 2013","Section 8 of the Companies Act, 2013","Section 3 of the Companies Act, 2013","Section 12 of the Companies Act, 2013"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 8 companies are licensed non-profit companies (successor to the old s.25 companies); profits go to objects, no dividend to members.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A company formed for promoting commerce, art, science, charity etc. which applies its profits to its objects and prohibits dividend is registered under:","options":["Section 465","Section 8 of the Companies Act, 2013","Section 3","Section 12"],"answer":1,"explanation":"Section 8 companies are licensed non-profit companies (successor to the old s.25 companies); profits go to objects, no dividend to members. [Original]","revision":"original","contentSignature":"4ebfde11ab0f9637b000d2ab8995ff974f7a2e46ad227b2e8a090e57acc7e995"}],"contentSignature":"f4ac368223f2cbff4da2dd0f222a1c7b5d2c983c6a75701be8838c7a19930ee9","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-19","sourceNumber":19,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The \"minimum subscription\" requirement applies to:","options":["Issues of bonus shares","Private placements of shares alone","A public issue of shares - the offer cannot be allotted unless the minimum amount stated in the prospectus is subscribed","Rights issues of shares alone"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"SEBI ICDR and the Act: without minimum subscription (generally 90% of the offer) within the stipulated time, application money must be refunded.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The \"minimum subscription\" requirement applies to:","options":["Bonus issues","Private placement only","A public issue of shares - the offer cannot be allotted unless the minimum amount stated in the prospectus is subscribed","Rights issues only"],"answer":2,"explanation":"SEBI ICDR and the Act: without minimum subscription (generally 90% of the offer) within the stipulated time, application money must be refunded. [Original]","revision":"original","contentSignature":"5d143e70d0a0f4801e2b059cbcc6b00d91793c0c9cf73a38080330f63673267d"}],"contentSignature":"65e4eb980bbb1479d9c9471789a79062e5f179f63d3b90c055d3637aa3e90771","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-20","sourceNumber":20,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The FIRST stage in the formation of a company is:","options":["Promotion","Commencement of business","Allotment of shares","Raising of capital"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Sequence: promotion -> incorporation (registration) -> capital subscription -> commencement of business.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"6ed151b48743d7fb723e4ca7ee8da3069eccf537eda1e3cca69098679e79224a","kind":"mcq"},{"id":"corp404-21","sourceNumber":21,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A promoter is a person who:","options":["Only buys shares in the company","Conceives the business idea, takes preliminary steps for incorporation and is named as promoter in the prospectus/annual return","Audits the first accounts of the company","Is appointed by the Registrar of Companies"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 2(69): a person named as promoter in the prospectus or identified in the annual return, or who has control over the company's affairs, or on whose advice the Board acts.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A promoter is a person who:","options":["Only buys shares in the company","Conceives the business idea, takes preliminary steps for incorporation and is named as promoter in the prospectus/annual return","Audits the first accounts","Is appointed by the Registrar"],"answer":1,"explanation":"Section 2(69): a person named as promoter in the prospectus or identified in the annual return, or who has control over the company's affairs, or on whose advice the Board acts. [Original]","revision":"original","contentSignature":"63b229c269bf5424abf709d4b4140b4da92983cfc7542794e3fff6da5c8ea30c"}],"contentSignature":"6e397c0790bc002fb75f9710c0c34e91bb9476166b78d970c069c825e086024a","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-22","sourceNumber":22,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The certificate of incorporation issued by the Registrar is:","options":["Proof that the company has commenced its business and is entitled to carry on the objects stated in the memorandum","Required only in the case of public companies","Conclusive evidence that all requirements of the Act for registration have been complied with","Valid for a period of ten years from issue"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"The certificate is conclusive (s.9 of the 2013 Act, continuing old s.35 of the 1956 Act; Jubilee Cotton Mills): the incorporation cannot be challenged even if there were irregularities.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The certificate of incorporation issued by the Registrar is:","options":["Proof that the company has started business","Required only for public companies","Conclusive evidence that all requirements of the Act for registration have been complied with","Valid for 10 years"],"answer":2,"explanation":"The certificate is conclusive (s.9 of the 2013 Act, continuing old s.35 of the 1956 Act; Jubilee Cotton Mills): the incorporation cannot be challenged even if there were irregularities. [Original]","revision":"original","contentSignature":"d187f59df05859f2b7284ba09e352db2ca48e32bfdf53447405bdc1ee1f611b8"}],"contentSignature":"185a79dbedb0b66e38e66fafdfed27f54cd718f5b3a735d3ef482e69b158f86e","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-23","sourceNumber":23,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"From the date mentioned in the certificate of incorporation, the company comes into existence as a body corporate - this is called its:","options":["Date of incorporation (birth of the company)","Date of its first annual general meeting held","Date of listing on the stock exchange","Date of commencement of its business"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"The corporate personality begins on the date in the certificate; a company may even contract from that date.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"From the date mentioned in the certificate of incorporation, the company comes into existence as a body corporate - this is called its:","options":["Date of incorporation (birth of the company)","First AGM date","Listing date","Commencement of business date"],"answer":0,"explanation":"The corporate personality begins on the date in the certificate; a company may even contract from that date.","revision":"original","contentSignature":"2d82999a26489714a727fad90ac20b36be5a4be5434f4cef7714782a6ad960f4"}],"contentSignature":"d1469451412f474c3c7c95184caacb5f4f79d263e5f18dd75301a5662548d8ef","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-24","sourceNumber":24,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The Memorandum of Association is:","options":["The internal rule-book of the company","A certificate that the company is incorporated","The charter/constitution of the company defining the scope of its activities and its relation with the outside world","A list of the debtors of the company"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"The memorandum (s.4) states name, registered office, objects, liability, capital and subscription clauses - it fixes the area beyond which the company cannot go.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The Memorandum of Association is:","options":["The internal rule-book of the company","A certificate of incorporation","The charter/constitution of the company defining the scope of its activities and its relation with the outside world","A list of the company's debtors"],"answer":2,"explanation":"The memorandum (s.4) states name, registered office, objects, liability, capital and subscription clauses - it fixes the area beyond which the company cannot go. [Original]","revision":"original","contentSignature":"b2da593024f437c0f1f64ead6193e8f16d61836845846c9cecb313ab6c2b0c57"}],"contentSignature":"2ff1e9855db433c84f150d391dbd0b9bc479bb6578aa24a10dbce16592b3c5db","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-25","sourceNumber":25,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"An act done by a company BEYOND the objects clause of its memorandum is:","options":["Valid if it results in profits for the company and the shareholders alike","Ultra vires and void - it cannot be ratified even by all shareholders","Valid if approved by the Board of directors","Valid if ratified by the shareholders"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Ashbury v. Riche: ultra vires acts are void ab initio; intra vires but irregular acts can be ratified, ultra vires ones cannot.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An act done by a company BEYOND the objects clause of its memorandum is:","options":["Valid if profits result","Ultra vires and void - it cannot be ratified even by all shareholders","Valid if the Board approves","Valid if ratified by shareholders"],"answer":1,"explanation":"Ashbury v. Riche: ultra vires acts are void ab initio; intra vires but irregular acts can be ratified, ultra vires ones cannot. [Original]","revision":"original","contentSignature":"d940631f0a5fa608a1a4e0f1d0c5da131da41d0dbd0f56b0b9d41c6177ee40f3"}],"contentSignature":"4043c63ff53bb8e946936f02a3847d8d6acfbf0f94f959216702e84d13f2bdc8","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-26","sourceNumber":26,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The Articles of Association contain:","options":["The list of the creditors of the company","The internal regulations and rules for management of the company's affairs","The objects for which the company is formed and the limits of its operations","The prospectus issued to the public"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 5: articles are bye-laws governing internal management - rights of members, meetings, directors, dividends, etc.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The Articles of Association contain:","options":["The list of creditors","The internal regulations and rules for management of the company's affairs","The objects of the company","The prospectus"],"answer":1,"explanation":"Section 5: articles are bye-laws governing internal management - rights of members, meetings, directors, dividends, etc. [Original]","revision":"original","contentSignature":"9cb195d9d487b3fcdb2b43202ef68c1f36aee30f00b0b413aaedce6bbe02165a"}],"contentSignature":"65b45918e18fde06dea8500da008128b4d82735d0ef05753854ebb2e6d2f3058","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-27","sourceNumber":27,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"If the articles conflict with the memorandum, which prevails?","options":["The memorandum - it is the dominant document","Neither - the company is dissolved","The articles of association of the company itself","Whichever is later"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"The memorandum is supreme; articles must be consistent with it and with the Act.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"If the articles conflict with the memorandum, which prevails?","options":["The memorandum - it is the dominant document","Neither - the company is dissolved","The articles","Whichever is later"],"answer":0,"explanation":"The memorandum is supreme; articles must be consistent with it and with the Act. [Original]","revision":"original","contentSignature":"b50cee1c1d466a1d79fad064978d414964d27561c26ecddc4d550a1a45e18fb5"}],"contentSignature":"10794fb7399ce6f6d0c067e267b6c3e5464b1f72b380f391776affaf1b7fcf66","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-28","sourceNumber":28,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The doctrine of INDOOR MANAGEMENT (Royal British Bank v. Turquand) protects:","options":["The Registrar of Companies against fraud","The shareholders against loss of dividend","The directors acting beyond their authority","Outsiders dealing with the company, who may assume that internal requirements (e.g. resolutions) have been complied with"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Outsiders are bound to read the public documents (constructive notice) but are not affected by internal irregularities they cannot discover.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The doctrine of INDOOR MANAGEMENT (Royal British Bank v. Turquand) protects:","options":["The Registrar against fraud","Shareholders against dividends","Directors acting beyond authority","Outsiders dealing with the company, who may assume that internal requirements (e.g. resolutions) have been complied with"],"answer":3,"explanation":"Outsiders are bound to read the public documents (constructive notice) but are not affected by internal irregularities they cannot discover. [Original]","revision":"original","contentSignature":"af33ca45b55613265c74db72a3e50729571a4450b27ca62141a1399cdc2ec228"}],"contentSignature":"5ce8edca0ed560481e7d98c957f8ebaa5466879d80d5caa32512d856e320de34","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-29","sourceNumber":29,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"\"Constructive notice\" of the memorandum and articles means:","options":["The company must send copies of them to every citizen who deals with the company in any capacity","The Board must approve every contract of the company","Since these are public documents, outsiders are deemed to have notice of their contents","Notices of them are published in the newspapers"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Registration makes MOA/AOA public documents; dealing parties are presumed to know them - a limitation on the indoor-management protection.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"\"Constructive notice\" of the memorandum and articles means:","options":["The company must send copies to every citizen","The Board must approve every contract","Since these are public documents, outsiders are deemed to have notice of their contents","Notices are published in newspapers"],"answer":2,"explanation":"Registration makes MOA/AOA public documents; dealing parties are presumed to know them - a limitation on the indoor-management protection. [Original]","revision":"original","contentSignature":"9d5869334a9f199cc38db9a78445663165fc4f27726aaf71c5c1b24ec90b68e6"}],"contentSignature":"d271352f267480293c7c7d94823002179e4c1aecff66e1787477312a47cad738","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-30","sourceNumber":30,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A public company must file with the Registrar a declaration before commencing business, confirming that:","options":["Every subscriber to the memorandum has paid the value of the shares agreed to be taken by him (the s.10A declaration)","The registration under the GST law is complete","The audit of the first accounts is complete","A dividend has been declared to the members"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 10A: a company with share capital cannot commence business until the s.10A declaration (subscription money received) is filed within 180 days of incorporation.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A public company must file with the Registrar a declaration before commencing business, confirming that:","options":["Every subscriber to the memorandum has paid the value of the shares agreed to be taken by him (the s.10A declaration)","GST registration is done","The audit is complete","Dividend has been declared"],"answer":0,"explanation":"Section 10A: a company with share capital cannot commence business until the s.10A declaration (subscription money received) is filed within 180 days of incorporation. [Original]","revision":"original","contentSignature":"8d6254f46127c2d9bce210558fb3f5857a012a7aaa3b96471f4770f8e0846f90"}],"contentSignature":"fa67331f41b95944f309370d4629d3bcaff3e751256fcc5044bea14dc81a5e3f","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-31","sourceNumber":31,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The \"Table F\" of Schedule I of the Companies Act, 2013 gives a model set of:","options":["Annual return formats","Articles of a company limited by shares","Forms of debentures","Memorandum for a banking company"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Schedule I contains model memorandum and articles; Table F = model articles of a company limited by shares.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"173c7dec0df6752b96d893e6879960479dc3a9f84f57dc3abc589c2d6c89362f","kind":"mcq"},{"id":"corp404-32","sourceNumber":32,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The name clause of the memorandum of a public limited company must end with:","options":["Corporation","Private Limited","Limited","Association"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 4(1)(a): a public limited company's name ends with \"Limited\"; a private company's with \"Private Limited\".","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"596d25ad44b001742a33d804a928583d253a37eb1fbef7238f016c022dd1399d","kind":"mcq"},{"id":"corp404-33","sourceNumber":33,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The registered office clause of the memorandum specifies:","options":["Only the State in which the registered office is situated","The exact street address of the registered office of the company","The places where the branch offices are situated","The names of the directors of the company"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"The memorandum states only the State; the exact address is filed with the Registrar separately (s.12).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The registered office clause of the memorandum specifies:","options":["Only the State in which the registered office is situated","The exact street address of the office","The branch offices","The names of the directors"],"answer":0,"explanation":"The memorandum states only the State; the exact address is filed with the Registrar separately (s.12). [Original]","revision":"original","contentSignature":"f2315576877985542392ab7f692c53fb8cdcce5d363e8a04c0dcbda395ccd56b"}],"contentSignature":"9fb496799bcc1a749e9ffcc873200196c0fb4c57a6ce3cdce0153827b2d78cec","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-34","sourceNumber":34,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following documents must be filed with the Registrar at the time of incorporation of a company?","options":["Memorandum and Articles of Association","The sales tax returns of the promoters","The prospectus of the company","The bank statements of the subscribers"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 7: the memorandum and articles (with declarations and subscriber details) are filed for incorporation; a prospectus comes only with a public offer.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Company formation, types & constitutional documents","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following documents must be filed with the Registrar at the time of incorporation of a company?","options":["Memorandum and Articles of Association","Sales tax returns","Prospectus","Bank statements"],"answer":0,"explanation":"Section 7: the memorandum and articles (with declarations and subscriber details) are filed for incorporation; a prospectus comes only with a public offer. [Original]","revision":"original","contentSignature":"c3aa3aece59f3f710d3faf64206538933d7526d7abf30b04da377d5a37165452"}],"contentSignature":"caad5f050e5c4f981ebcc50db0363f05ffdcc70636da019a96298b2e78154b0f","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-35","sourceNumber":35,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Authorised (registered/nominal) capital is:","options":["The capital which the Board has called up","The maximum amount of share capital which the company is authorised by its memorandum to issue","The capital actually received from the shareholders against the calls made by the company on the shares allotted","The capital kept aside in reserve"],"answer":1,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"It is stated in the capital clause of the memorandum; the company cannot issue shares beyond it without altering the clause. [Recall 2021]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Authorised (registered/nominal) capital is:","options":["The capital called up by the Board","The maximum amount of share capital which the company is authorised by its memorandum to issue","The capital actually received from shareholders","The capital kept in reserve"],"answer":1,"explanation":"It is stated in the capital clause of the memorandum; the company cannot issue shares beyond it without altering the clause. [Recall 2021]","revision":"original","contentSignature":"5764b95cfcb2a598a75674a49117e319cb9450db6ea9604ce406e4a775faca08"}],"contentSignature":"16d54b39b5425a598bde65ac88c0f8abaf93b9f228e8c7836c859bec6ed96215","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-36","sourceNumber":36,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"No journal entry is passed in the books for:","options":["Issue of shares","Calls received","Forfeiture of shares","Authorised capital"],"answer":3,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Authorised capital is only a stated limit in the memorandum; entries begin with the issue/allotment of shares.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"228d5aa9dffdd6e5fe608ae427d4abfcec2674237251a19a385428ee5b6e5d23","kind":"mcq"},{"id":"corp404-37","sourceNumber":37,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Issued capital means:","options":["That part of the authorised capital which is actually offered (issued) to the public for subscription","The whole of the authorised capital","The capital that has not been issued","The amount actually paid by the shareholders"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Issued capital is the nominal value of shares offered; it can never exceed authorised capital.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Issued capital means:","options":["That part of the authorised capital which is actually offered (issued) to the public for subscription","The whole of the authorised capital","Unissued capital","The amount paid by shareholders"],"answer":0,"explanation":"Issued capital is the nominal value of shares offered; it can never exceed authorised capital. [Original]","revision":"original","contentSignature":"7802c4e20930bb62d77d385d2a7844e077b91efc2f2792063111f853cf6a41b2"}],"contentSignature":"47966afdcecdc1902106df2a4ef192efdd68cf2ba6cc3d8cba2b05c032db23f4","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-38","sourceNumber":38,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Subscribed capital is that part of the issued capital which is:","options":["Offered to the Central Government","Actually subscribed (taken up) by the public","Cancelled by the Board of directors","Reserved for the promoters of the company first"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Subscribed capital = shares applied for and allotted; it may be equal to or less than issued capital.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Subscribed capital is that part of the issued capital which is:","options":["Offered to the Government","Actually subscribed (taken up) by the public","Cancelled by the Board","Kept for the promoters"],"answer":1,"explanation":"Subscribed capital = shares applied for and allotted; it may be equal to or less than issued capital. [Original]","revision":"original","contentSignature":"6d4a7feb5b7830b24aec15828514ec2df8c8897ca139bdae16c0e499d01a68f8"}],"contentSignature":"2de80e2131ef52ce78681ea5f42981c938ae48704d86fb112a3e40dbfa88e446","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-39","sourceNumber":39,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Called-up capital is:","options":["The amount already received in cash from the shareholders on the shares allotted to them at the time","The capital kept in reserve for the future calls","The total face value of the shares issued","That part of the subscribed capital which the company has called upon shareholders to pay"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"The company may call the issue price in instalments; the portion demanded is called-up capital.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Called-up capital is:","options":["The amount already received in cash","The reserve capital","The total face value of shares issued","That part of the subscribed capital which the company has called upon shareholders to pay"],"answer":3,"explanation":"The company may call the issue price in instalments; the portion demanded is called-up capital. [Original]","revision":"original","contentSignature":"9dc41c4c94af2487a8d82f1156ac0e88a600bd18f53b8e54e1b9c70bb8cf4a8a"}],"contentSignature":"7ec84028b98a3f73b143fda17371f9b72f6d9aaaa95503a7325a485433d0fc44","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-40","sourceNumber":40,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Paid-up capital equals:","options":["Authorised capital minus the issued capital","The market value of the shares issued","Equal to the subscribed capital in all cases, whether calls are received in full or partly","Called-up capital minus calls in arrears (plus forfeited amount originally paid)"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Paid-up capital is what shareholders have actually paid; unpaid calls (arrears) reduce it below called-up capital.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Paid-up capital equals:","options":["Authorised capital minus issued capital","The market value of shares","Subscribed capital always","Called-up capital minus calls in arrears (plus forfeited amount originally paid)"],"answer":3,"explanation":"Paid-up capital is what shareholders have actually paid; unpaid calls (arrears) reduce it below called-up capital.","revision":"original","contentSignature":"65098cd854328e1be3db397eb9cccc8de4c4de5988e60ca03ddc560e3c2be01f"}],"contentSignature":"98f3d49c5a4c4b6a6b218072d61d09963e742b4db2a23bea318223f44fd2bcb1","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-41","sourceNumber":41,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Reserve capital is:","options":["That portion of uncalled capital which the company resolves (by special resolution) shall be called up only on winding up","The capital reserve shown in the balance sheet","The profit retained for the payment of dividend","The balance in the securities premium account"],"answer":0,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Under s.65, reserve capital cannot be uncalled or turned into ordinary capital during the company's life - it backs creditors at liquidation. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Reserve capital is:","options":["That portion of uncalled capital which the company resolves (by special resolution) shall be called up only on winding up","Capital reserve shown in the balance sheet","Profit retained for dividend","The security premium account"],"answer":0,"explanation":"Under s.65, reserve capital cannot be uncalled or turned into ordinary capital during the company's life - it backs creditors at liquidation. [Recall 2018]","revision":"original","contentSignature":"aaa8aa899a47fab51da29b7417d518da575acb067a27ceefdb7d58dabb7c1f20"}],"contentSignature":"c48ae8f28d605a16a39dbc4bc376fab9803cbe7fabb4c31c9b8d0e570896201a","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-42","sourceNumber":42,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In the balance sheet, share capital is shown at:","options":["The book value of the net assets of the company","Face (nominal) value of the shares - as authorised, issued, subscribed and paid-up amounts","The issue price of the shares including the premium received on the issue of the shares to the public","The market value of the shares"],"answer":1,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"Schedule III: capital is disclosed at nominal value in its various categories; premium goes to securities premium in reserves. [Recall 2021]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In the balance sheet, share capital is shown at:","options":["Book value of net assets","Face (nominal) value of the shares - as authorised, issued, subscribed and paid-up amounts","Issue price including premium","Market value"],"answer":1,"explanation":"Schedule III: capital is disclosed at nominal value in its various categories; premium goes to securities premium in reserves. [Recall 2021]","revision":"original","contentSignature":"9d2cd27a1eaeaa82e139880a4ff02d14dd8b58f56d8d3ce4c2076b062631c4df"}],"contentSignature":"9664e018add1c854b29a943be1887953c5f6ecf9711a03da23d82a2cdee25ff8","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-43","sourceNumber":43,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Equity share capital is that share capital which is:","options":["Guaranteed a dividend at a fixed rate by the memorandum of association of the company concerned","Carrying no voting rights at all","Not preference share capital - it carries residual rights to dividend and surplus","Redeemable at the end of twenty years"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 43: share capital is of two kinds - preference and equity; equity bears the highest risk and enjoys residual rewards.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Equity share capital is that share capital which is:","options":["Guaranteed a fixed dividend","Non-voting always","Not preference share capital - it carries residual rights to dividend and surplus","Redeemable after 20 years"],"answer":2,"explanation":"Section 43: share capital is of two kinds - preference and equity; equity bears the highest risk and enjoys residual rewards. [Original]","revision":"original","contentSignature":"40598caaec4e6abc79d7303a8c109b29a66ba8cf2c52e1754709a6e74d1fa25e"}],"contentSignature":"d89d9368512ee25fc5363d2c59394d363f70a36a36adf3ea5851afb778e302e0","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-44","sourceNumber":44,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Preference shareholders enjoy preferential rights as to:","options":["The appointment of the directors of the company at the annual general meeting of the company","The inspection of the books of account","Payment of dividend (fixed rate) and repayment of capital on winding up, before equity","Voting at every general meeting"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 43(b): the two preferences are dividend at a fixed rate/amount and priority in capital repayment on winding up.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Preference shareholders enjoy preferential rights as to:","options":["Appointment of directors","Inspection of books","Payment of dividend (fixed rate) and repayment of capital on winding up, before equity","Voting at every meeting"],"answer":2,"explanation":"Section 43(b): the two preferences are dividend at a fixed rate/amount and priority in capital repayment on winding up. [Original]","revision":"original","contentSignature":"78d9b3a3e89f1f9f62270ac86c3d2cb203d633c41528c31dde4ef000d5c048da"}],"contentSignature":"30f621581a16ce9205c2febbf9e90cb215cc8fa8c92a7d720a8cfacb05214e24","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-45","sourceNumber":45,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Preference shareholders can normally vote:","options":["Only on the resolution for the appointment of auditors","On all the resolutions at all the meetings","Only on resolutions directly affecting their rights (and on all resolutions if their dividend remains unpaid for the period specified in s.47(2))","Not at any meeting of the company"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Section 47(2): direct-effect resolutions always; ALL resolutions when preference dividend is unpaid for two years or more. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Preference shareholders can normally vote:","options":["Only for appointing auditors","On all resolutions at all meetings","Only on resolutions directly affecting their rights (and on all resolutions if their dividend remains unpaid for the period specified in s.47(2))","Never at any meeting"],"answer":2,"explanation":"Section 47(2): direct-effect resolutions always; ALL resolutions when preference dividend is unpaid for two years or more. [Recall 2018]","revision":"original","contentSignature":"a612b57675c3695f4c349d89d1125b7dd1f34b42fbb43ab214b604d40cbb01fe"}],"contentSignature":"bc0f2d710f4a77357ec5254fa89d332c186f1f988cf94b2416c76417f798e2b5","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-46","sourceNumber":46,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Cumulative preference shares carry the right that:","options":["The right to cast two votes per share","The right that they are never to be redeemed during the lifetime of the company","Unpaid dividend accumulates and is paid in later years before equity dividend","The right to convert into debentures"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Arrears of dividend accumulate; no equity dividend can be paid until cumulative arrears are cleared.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Cumulative preference shares carry the right that:","options":["They vote twice","They are never redeemed","Unpaid dividend accumulates and is paid in later years before equity dividend","They convert into debentures"],"answer":2,"explanation":"Arrears of dividend accumulate; no equity dividend can be paid until cumulative arrears are cleared. [Original]","revision":"original","contentSignature":"2773616c3fb42282049ad4085efa88e3a457517f3679e939eaf56c9e283ac307"}],"contentSignature":"aaa63ad82dd7b7c3ecbc2c4e9856d825e4adf6454c2e390b702a8a875db7ece4","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-47","sourceNumber":47,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Participating preference shares are entitled to:","options":["Attend the general meetings of the company","A share in surplus profits (and sometimes surplus assets) in addition to the fixed preference dividend","Convert into equity shares automatically","Participate in the management of the company"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Beyond the fixed dividend they \"participate\" in surplus left after equity has received an agreed rate.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Participating preference shares are entitled to:","options":["Attend meetings","A share in surplus profits (and sometimes surplus assets) in addition to the fixed preference dividend","Convert into equity automatically","Participate in management"],"answer":1,"explanation":"Beyond the fixed dividend they \"participate\" in surplus left after equity has received an agreed rate. [Original]","revision":"original","contentSignature":"1f8cdc67e66afa90b85d664277aacaf6c46252322a3b3357d1f82e569039ddb8"}],"contentSignature":"261ed0556df4be946291615df28f4a6ab430ecb5c3b5ce2fd67b7dfdb64c96e5","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-48","sourceNumber":48,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Redeemable preference shares in India can be issued with a maximum redemption period of:","options":["5 years from the date of issue","No limit on the period of redemption, which may even extend to perpetuity","10 years from the date of issue","20 years from the date of issue (30 years for infrastructure projects)"],"answer":3,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Section 55: irredeemable preference shares are prohibited; redemption within 20 years, extendable to 30 years for infrastructure projects. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Redeemable preference shares in India can be issued with a maximum redemption period of:","options":["5 years","No limit","10 years","20 years from the date of issue (30 years for infrastructure projects)"],"answer":3,"explanation":"Section 55: irredeemable preference shares are prohibited; redemption within 20 years, extendable to 30 years for infrastructure projects. [Recall 2018]","revision":"original","contentSignature":"3aea90bc33c1b99f66ac7d0b262f74bcb2c0688bd3855d2a92ccb1a366aef2b2"}],"contentSignature":"146ae62df702c66201296abf0655366566efda1daa94d8781487d6ff4d6c66d2","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-49","sourceNumber":49,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Variation of shareholders' rights under Section 48 requires consent of:","options":["The Central Government","Holders of at least three-fourths of the issued shares of that class (or a special resolution of that class) plus Tribunal dispensation rules","A simple majority of the Board of directors","The auditors of the company"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 48: class rights may be varied with written consent of 3/4 of that class or a special resolution passed at a separate class meeting.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Variation of shareholders' rights under Section 48 requires consent of:","options":["The Central Government in every case","Holders of at least three-fourths of the issued shares of that class (or a special resolution of that class) plus Tribunal dispensation rules","Simple majority of the Board","The auditors"],"answer":1,"explanation":"Section 48: class rights may be varied with written consent of 3/4 of that class or a special resolution passed at a separate class meeting. [Original]","revision":"original","contentSignature":"175dc9a5346c95ad3083835a96678111427cf8f1a40143eaa1c1dafdb7a74afa"}],"contentSignature":"31323a3510ad7ed32960bc4d8235d96018c2a2ecc9b19ac67733fa3bc1e65d29","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-50","sourceNumber":50,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Shares issued at a price ABOVE their face value are said to be issued at:","options":["A premium","Book value","A discount","Par"],"answer":0,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Premium = excess of issue price over face value; it is credited to the securities premium account (s.52). [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"be4e1ac9428436bb99f790e6c1a794a1904ae8a819eec788d40135c4547d57eb","kind":"mcq"},{"id":"corp404-51","sourceNumber":51,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The minimum number of DIRECTORS required in a public company / private company / OPC respectively is:","options":["7, 2, 1","3, 2, 1","2, 2, 1","3, 3, 1"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 149(1): public - 3, private - 2, OPC - 1; maximum 15 (more with special resolution).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"3044c149954b37b4992a8411094473a4815361471894583022b1b68efef553c1","kind":"mcq"},{"id":"corp404-52","sourceNumber":52,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The liability clause of the memorandum of a company limited by shares states that members' liability is limited to:","options":["The amount unpaid on the shares held by them","The total debts of the company","Nothing at all","The authorised capital of the company for the time"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 4(1)(d): the liability clause declares the limit - unpaid amount on shares held.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The liability clause of the memorandum of a company limited by shares states that members' liability is limited to:","options":["The amount unpaid on the shares held by them","Company's total debts","Nothing","The authorised capital"],"answer":0,"explanation":"Section 4(1)(d): the liability clause declares the limit - unpaid amount on shares held. [Original]","revision":"original","contentSignature":"f8bc8b6ec1da1b275fb8c67e0c1edbbb90db863389e968be04e7d83a2cbfb7cb"}],"contentSignature":"e11181058cf1c13322671f069da0f78ef17bf2c643ceccfa6de360ae1aa88b52","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-53","sourceNumber":53,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following is shown under \"Share Capital\" notes in Schedule III as a SEPARATE item?","options":["Depreciation on fixed assets held","Fees paid to the auditors","Loose tools on hand","Calls unpaid (calls in arrears)"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"The share-capital note discloses authorised/issued/subscribed/paid-up capital, calls unpaid, forfeited shares, rights attached, and reconciliation of shares.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share capital fundamentals","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is shown under \"Share Capital\" notes in Schedule III as a SEPARATE item?","options":["Depreciation","Audit fees","Loose tools","Calls unpaid (calls in arrears)"],"answer":3,"explanation":"The share-capital note discloses authorised/issued/subscribed/paid-up capital, calls unpaid, forfeited shares, rights attached, and reconciliation of shares. [Original]","revision":"original","contentSignature":"a3ded0048d821f5474f59a1bc41a1a692f364233b986e42a0110642e7b5b18ee"}],"contentSignature":"b625ac154fa32d50e2646c12887751a62e3f6dc878571fbf7dd67383a7d4dc91","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-54","sourceNumber":54,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A person whose name is entered in the register of members is called a:","options":["Creditor","Director","Subscriber only","Member of the company"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 2(55): subscribers to the memorandum and persons agreeing in writing whose names are entered in the register of members are members.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"a2f2c3d540a6ffc4838a8f4f3e24943b4d256a11e0cd6d06a3c88c47c7eb250d","kind":"mcq"},{"id":"corp404-55","sourceNumber":55,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A \"prospectus\" under Section 2(70) of the Companies Act, 2013 is: of any securities","options":["The annual report of the company","Any document issued as a notice, circular, advertisement or other document inviting offers from the public for the subscription or purchase","A receipt for the application money paid","The memorandum of association of the company"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"The prospectus invites the public to subscribe; the definition includes a red herring prospectus and a shelf prospectus.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A \"prospectus\" under Section 2(70) of the Companies Act, 2013 is: of any securities","options":["The annual report of the company","Any document issued as a notice, circular, advertisement or other document inviting offers from the public for the subscription or purchase","A receipt for application money","The memorandum of association"],"answer":1,"explanation":"The prospectus invites the public to subscribe; the definition includes a red herring prospectus and a shelf prospectus. [Original]","revision":"original","contentSignature":"9e2843311d69a24e4af826b7d15323c02255799f5b1a41f2408a69c2db1b919b"}],"contentSignature":"e470eae6ea360f75eaa08d833be4e0d3fa065a09879339df9357e824266fc4c5","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-56","sourceNumber":56,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A \"red herring prospectus\" under Section 32 is a prospectus which:","options":["Issued only for an offer of debentures","Does not include complete particulars of the quantum or price of the securities offered","Issued after the allotment is completed and the securities have already been issued to the public","Printed wholly in red ink"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"In book-built issues the price and quantity are finalised later; the FINAL prospectus with complete details is filed with the Registrar after the issue closes.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A \"red herring prospectus\" under Section 32 is a prospectus which:","options":["Is issued only for debentures","Does not include complete particulars of the quantum or price of the securities offered","Is issued after allotment","Is printed in red ink"],"answer":1,"explanation":"In book-built issues the price and quantity are finalised later; the FINAL prospectus with complete details is filed with the Registrar after the issue closes. [Original]","revision":"original","contentSignature":"43634232141f0cba455791759cc0754cd4edfd3616eea58728d14439545a339f"}],"contentSignature":"13bc69c558123e1ac388933c386e1bb9113f67cdffbdda91815189332d988533","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-57","sourceNumber":57,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A \"shelf prospectus\" under Section 31, issued by eligible entities, remains valid for a maximum period of:","options":["One year from the date of opening of the first offer","5 years from the first offer","3 months from the first offer made under the prospectus","180 days from the first offer"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Eligible banks and financial institutions file a shelf prospectus valid up to one year; an information memorandum accompanies each tranche.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A \"shelf prospectus\" under Section 31, issued by eligible entities, remains valid for a maximum period of:","options":["One year from the date of opening of the first offer","5 years","3 months","180 days"],"answer":0,"explanation":"Eligible banks and financial institutions file a shelf prospectus valid up to one year; an information memorandum accompanies each tranche. [Original]","revision":"original","contentSignature":"ccf6c0579a3d81db9730801c9b348c9a4d3f8fa0e41cc9126409348b935aa9a4"}],"contentSignature":"29adb5122452719db0fef1d6592cdf48a535671c4050db362995697ca716eb5d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-58","sourceNumber":58,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"An \"abridged prospectus\" is:","options":["The report of the auditors of the company","The annual return filed by the company","A prospectus containing false statements","A memorandum containing the salient features of the prospectus, attached to every application form"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 33: no application form for securities may be issued unless accompanied by an abridged prospectus.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An \"abridged prospectus\" is:","options":["The auditor's report","The annual return","A false prospectus","A memorandum containing the salient features of the prospectus, attached to every application form"],"answer":3,"explanation":"Section 33: no application form for securities may be issued unless accompanied by an abridged prospectus.","revision":"original","contentSignature":"92322d58730a1713427d4cb21df447e46c23ad9fff7864761d0706bd134c7a4a"}],"contentSignature":"c22321d7ed51f68559941312ebbac4b37da1f36f084d55c66dd10485e233cc3d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-59","sourceNumber":59,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A document by which a company allots or agrees to allot securities with a view to their being offered for sale to the public is \"deemed\" a prospectus under:","options":["Section 25","Section 117","Section 44","Section 61"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 25: such offers through an intermediary carry full prospectus liability as if the document were a prospectus issued by the company.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"a25125e2d8fb0cb38b53573ab1fff1a2ddb7220cf96d6efdcbe440dfc5adfd73","kind":"mcq"},{"id":"corp404-60","sourceNumber":60,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The \"golden rule\" for framing a prospectus (New Brunswick and Canada Rly. Co. v. Muggeridge) requires:","options":["Printing the key figures prominently in bold on the front page of the prospectus","Full, true and fair disclosure of all material facts with utmost good faith","Giving the minimum information to save cost","Disclosing the profits of the company alone"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Persons inviting the public to subscribe must state everything with strict accuracy - nothing material may be concealed.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The \"golden rule\" for framing a prospectus (New Brunswick and Canada Rly. Co. v. Muggeridge) requires:","options":["Printing key figures prominently","Full, true and fair disclosure of all material facts with utmost good faith","Minimum information to save cost","Disclosure of profits only"],"answer":1,"explanation":"Persons inviting the public to subscribe must state everything with strict accuracy - nothing material may be concealed. [Original]","revision":"original","contentSignature":"3520d6cca7fbb176d3b021548b5f87e7fe8939945a709519ce5c790f74df987d"}],"contentSignature":"675a111fd046f1068e504c0966cf86c8f24a5c21fbeb4ae3abc53c2bb42bb0b2","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-61","sourceNumber":61,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Civil liability for misstatements in a prospectus arises under ________ and criminal liability under ________ of the Companies Act, 2013.","options":["Section 26; Section 27","Section 34; Section 35","Section 447; Section 448","Section 62; Section 63"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 34 = civil liability to compensate subscribers; Section 35 = criminal liability, fraudulent misstatements attracting Section 447 punishment.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e62c861ab8943d941e37aaa787b2b1c1eb8530cf920aadaf89ab9cfdd834f4da","kind":"mcq"},{"id":"corp404-62","sourceNumber":62,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"As per SEBI regulations, the MINIMUM SUBSCRIPTION for a public issue is:","options":["25% of the authorised capital","50% of the issued capital","75% of the paid-up capital","90% of the offer"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"If applications fall below 90% of the offer, no allotment can be made and the entire application money must be refunded within the prescribed time.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"f7ad113e832405e7479b4c0efc3da39392946909eb99bda9573690b2d31475a4","kind":"mcq"},{"id":"corp404-63","sourceNumber":63,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"If the minimum subscription is not received within the specified period, application money must be refunded within:","options":["6 months of the closure of the issue","One year of the closure of the issue","90 days of incorporation","15 days of the closure of the issue"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 39(3): refund within 15 days of closure; delay attracts interest at 15% p.a. on the company and defaulting officers.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"If the minimum subscription is not received within the specified period, application money must be refunded within:","options":["6 months","One year","90 days of incorporation","15 days of the closure of the issue"],"answer":3,"explanation":"Section 39(3): refund within 15 days of closure; delay attracts interest at 15% p.a. on the company and defaulting officers. [Original]","revision":"original","contentSignature":"131ba8ce4f8d4b813d45e3db3623708db33e2fd2738276e22b8d810918174b6f"}],"contentSignature":"788354e54e0e9f80a2278e2d775ab497e33f3a7787c0442a1b6a9a26fa20ca7b","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-64","sourceNumber":64,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The minimum application money payable with a share application, as per SEBI norms, is:","options":["25% of the issue price","5% of the nominal value","100% of the issue price","10% of the premium"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"SEBI ICDR norms require at least 25% of the issue price with the application for shares offered to the public.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c542e55b44f7c9905ffe447a22fafa5d06ef15279b8707119c57c7bc8629d5a7","kind":"mcq"},{"id":"corp404-65","sourceNumber":65,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Application money received on a public issue must be kept:","options":["Invested immediately in marketable securities","In the petty cash box of the company","In the personal bank account of the directors","In a separate bank account with a scheduled bank, usable only for adjustment against allotment or for refund"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Sections 39-40: application money stays in a separate scheduled-bank account until allotment and refund formalities are complete.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Application money received on a public issue must be kept:","options":["Invested immediately in securities","In the petty cash of the company","In the personal account of the directors","In a separate bank account with a scheduled bank, usable only for adjustment against allotment or for refund"],"answer":3,"explanation":"Sections 39-40: application money stays in a separate scheduled-bank account until allotment and refund formalities are complete. [Original]","revision":"original","contentSignature":"fa0aedc17a66ec5a1eb8eec04c9945c414505c63ee5d981050c19f7e304c5be0"}],"contentSignature":"74b769255c83d375fc9b44d6d27e2c97c905ff0a7b5455d97beb4bd561856842","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-66","sourceNumber":66,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The return of allotment of shares (Form PAS-3) must be filed with the Registrar within:","options":["30 days of allotment","15 days of allotment","60 days of allotment","90 days of allotment"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 39(4): the return of allotment with full details is filed within 30 days; default attracts penalty.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c2b57653ded8df51b0480b8c393013408f92261486a7cab64332522aa59f07a3","kind":"mcq"},{"id":"corp404-67","sourceNumber":67,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Private placement of securities under Section 42 can be made to a select group of persons NOT exceeding, in a financial year:","options":["50 persons","1,000 persons","200 (excluding qualified institutional buyers and employees offered securities under an ESOP)","500 persons"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 42: offers go by private placement offer letter to identified persons, capped at 200 per type of security in a year, QIBs and ESOP offerees excluded.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Private placement of securities under Section 42 can be made to a select group of persons NOT exceeding, in a financial year:","options":["50","1,000","200 (excluding qualified institutional buyers and employees offered securities under an ESOP)","500"],"answer":2,"explanation":"Section 42: offers go by private placement offer letter to identified persons, capped at 200 per type of security in a year, QIBs and ESOP offerees excluded. [Original]","revision":"original","contentSignature":"8c3d718410ebae474d6fbe95c76a4bb1b2fe6a92ff4e74fd741044db252f6fe6"}],"contentSignature":"9bf007aaa6354d96ae4eb319a19032df718aee4d54ea60a70268e8bffa591a31","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-68","sourceNumber":68,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under Section 42, a company making a private placement must allot securities within ________ of receipt of application money, failing which money must be refunded within 15 days with interest.","options":["15 days","60 days","90 days","30 days"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 42(6): allot within 60 days of receipt; default means refund within the next 15 days with interest at 12% p.a.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"1dbddb91c2a43cc98cfbc6f0c523f1a674931564a7ed16ad7247534de5ba09aa","kind":"mcq"},{"id":"corp404-69","sourceNumber":69,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company issued 80,000 equity shares to the public. The minimum number of shares that must be subscribed for a valid allotment is:","options":["60,000","40,000","72,000","80,000"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Minimum subscription = 90% of the offer = 90% x 80,000 = 72,000 shares.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"b1e9f3fe1f26bb001bbf408a163f054639604dd4e26081d977942ab721eb02bd","kind":"mcq"},{"id":"corp404-70","sourceNumber":70,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"When shares are issued at a premium, the premium received is credited to:","options":["Profit and loss account","Share capital account","Capital redemption reserve account of the company issuing the shares","Securities premium account, shown under Reserves and Surplus"],"answer":3,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Section 52: aggregate premium goes to the securities premium account; only face value goes to share capital.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Prospectus, issue & allotment","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"When shares are issued at a premium, the premium received is credited to:","options":["Profit and loss account","Share capital account","Capital redemption reserve","Securities premium account, shown under Reserves and Surplus"],"answer":3,"explanation":"Section 52: aggregate premium goes to the securities premium account; only face value goes to share capital.","revision":"original","contentSignature":"6b592d6794691237357dc45c7727c8ff8cf4e43608b610c14b2fc72a7cf21e12"}],"contentSignature":"9873510356218d5bf396a90dd1e03e819039e382da2213b4c8db59e6a026adc2","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-71","sourceNumber":71,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Section 53 of the Companies Act, 2013 PROHIBITS issue of shares:","options":["To the promoters of the company","In a dematerialised form","At a discount - any share issued at a discounted price is void, except as permitted for sweat equity","At a premium over the face value"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"A general discount issue is void; sweat equity under Section 54 may be issued at a discount or for consideration other than cash. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 53 of the Companies Act, 2013 PROHIBITS issue of shares:","options":["To promoters","In dematerialised form","At a discount - any share issued at a discounted price is void, except as permitted for sweat equity","At a premium"],"answer":2,"explanation":"A general discount issue is void; sweat equity under Section 54 may be issued at a discount or for consideration other than cash. [Recall 2018]","revision":"original","contentSignature":"69a7dd03f59b49a8a730529df3f80c306c6400cf80ce8db2de57cfffbe847330"}],"contentSignature":"d45ef46a35c2667fbff19b86d445e3eb851753675af9c89919d9f28eba765d29","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-72","sourceNumber":72,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Sweat equity shares under Section 54 are issued to directors or employees:","options":["For cash at their face value alone","At a discount or for consideration other than cash, for providing know-how or making available intellectual property rights or value additions","Only to the debenture holders of the company","Only at the time of winding up of the company"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Sweat equity rewards know-how, IP and value additions; Rule 8 of the Share Capital and Debentures Rules, 2014 permits issue at a discount or for non-cash consideration.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Sweat equity shares under Section 54 are issued to directors or employees:","options":["For cash at par only","At a discount or for consideration other than cash, for providing know-how or making available intellectual property rights or value additions","Only to debenture holders","Only on winding up"],"answer":1,"explanation":"Sweat equity rewards know-how, IP and value additions; Rule 8 of the Share Capital and Debentures Rules, 2014 permits issue at a discount or for non-cash consideration. [Original]","revision":"original","contentSignature":"ba733946e8d047b18c8f291d0993b1c8be1fdd6b4a0d4ca0764320a0999b0404"}],"contentSignature":"146403d2e169694b8ebbb1a7693a49e2dad824c733203a087870d77072c0b99d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-73","sourceNumber":73,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company purchased machinery worth Rs.5,00,000 and paid the vendor by issuing equity shares of Rs.10 each at Rs.12.50 per share. The number of shares issued is:","options":["40,000","50,000","62,500","45,000"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Shares issued = 5,00,000 / 12.50 = 40,000 shares (face Rs.4,00,000 to share capital; Rs.1,00,000 to securities premium).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"bd5e306fc768131d198454879fcb9f9029a172294e9e6d076c7a26130fe8b54c","kind":"mcq"},{"id":"corp404-74","sourceNumber":74,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"When shares are issued for consideration other than cash, the fact must be:","options":["Approved by the Comptroller and Auditor General of India beforehand","Disclosed in the return of allotment and the balance sheet notes","Ignored in the books of account","Kept confidential from the shareholders"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Non-cash issues are disclosed in Form PAS-3 and in the notes to accounts, so users know no cash came in against those shares.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"When shares are issued for consideration other than cash, the fact must be:","options":["Approved by the Comptroller and Auditor General","Disclosed in the return of allotment and the balance sheet notes","Ignored in accounts","Kept confidential"],"answer":1,"explanation":"Non-cash issues are disclosed in Form PAS-3 and in the notes to accounts, so users know no cash came in against those shares. [Original]","revision":"original","contentSignature":"a66a76406ee0e2d0027fa056fb8a55e41401129ed703f6d7a9a284b87ca8d247"}],"contentSignature":"486864227e870f7bdbf77aa543d4a10c084b727eaf358a9506560bb6d0ec83c1","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-75","sourceNumber":75,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"When applications exceed the shares offered (oversubscription) and full allotment to all is impossible, the company usually makes:","options":["No allotment to any of the applicants","Allotment by drawing lots among the applicants","Pro-rata allotment - shares allotted in proportion to applications, excess application money adjusted or refunded","Allotment to the promoters alone"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Pro-rata allotment distributes the shortfall fairly; surplus application money is adjusted towards allotment and calls or refunded.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"When applications exceed the shares offered (oversubscription) and full allotment to all is impossible, the company usually makes:","options":["No allotment at all","Lottery allotment always","Pro-rata allotment - shares allotted in proportion to applications, excess application money adjusted or refunded","Allotment only to promoters"],"answer":2,"explanation":"Pro-rata allotment distributes the shortfall fairly; surplus application money is adjusted towards allotment and calls or refunded. [Original]","revision":"original","contentSignature":"d27166b699d8a2814afe95d0ab1aa667edad285580a6e2892aae8d446b69390a"}],"contentSignature":"0adb5793bff99517b7ab9c4421323a514264d4e585e77b1cd92dbd54d8df39a4","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-76","sourceNumber":76,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"X Ltd issued 10,000 shares. Applications were received for 14,000 shares and allotment was made pro-rata. A person who was allotted 300 shares must have applied for:","options":["214 shares","500 shares","420 shares","300 shares"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Allotment ratio = 10,000 : 14,000 = 5:7. Applied = 300 x 7/5 = 420 shares. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"a64d31a499a29ae9514d79b6ddb5192b014a0ffe035134b91b1e396da0e92fc0","kind":"mcq"},{"id":"corp404-77","sourceNumber":77,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Y Ltd issued 20,000 shares of Rs.10 each at Rs.12, payable: Rs.3 on application, Rs.5 on allotment (including premium), Rs.4 on first and final call. Applications came for 30,000 shares; pro-rata allotment to all. Mohan applied for 3,000 shares. Amount payable by him on allotment is:","options":["Rs.7,000","Rs.9,000","Rs.10,000","Rs.5,000"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Allotted = 3,000 x 2/3 = 2,000 shares. Application paid Rs.9,000; due on application Rs.6,000, so Rs.3,000 excess adjusts to allotment. Allotment due Rs.10,000; payable = 10,000 - 3,000 = Rs.7,000.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"be2da0b42372b248832bddc253a19541ea9d01532140705b7517d8b900bee353","kind":"mcq"},{"id":"corp404-78","sourceNumber":78,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Calls on shares of the same class, as per Section 49, must be made:","options":["Only once in a financial year","Only with the approval of the shareholders","At different rates on different shareholders of the same class","On a uniform basis on all shares falling under the same class"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 49: shares of the same class must be treated alike - the basis of calls must be uniform.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Calls on shares of the same class, as per Section 49, must be made:","options":["Only once a year","Only with shareholder approval","At different rates per shareholder","On a uniform basis on all shares falling under the same class"],"answer":3,"explanation":"Section 49: shares of the same class must be treated alike - the basis of calls must be uniform. [Original]","revision":"original","contentSignature":"a4ab7998004ab88b54930e4f4e5bdd0a88d67ebd1ff48a7de89c465d32ef8aaa"}],"contentSignature":"66fca359fabe0eb716989a558eba1079428dc1d12a828f413816504b084c797c","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-79","sourceNumber":79,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"As per Table F (model articles), a call cannot exceed ________ of the nominal value of a share, and at least ________ must pass between two successive calls.","options":["One-half; 15 days","One-tenth; three months","Full amount; one week","One-fourth; one month"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Table F limits each call to one-fourth of nominal value with a minimum one-month gap, unless the articles provide otherwise.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"fdacadf750e3f5b44abe01cb62c464ef0125d99a987f2c7613ce4d5d3abae107","kind":"mcq"},{"id":"corp404-81","sourceNumber":81,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Interest on calls in arrears, as per Table F, is chargeable at:","options":["12% per annum","10% per annum","18% per annum","6% per annum"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Table F: members in default pay interest at 10% p.a. (or such lower rate as the Board fixes) from the due date to payment.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8e627cc0ba4c3e02317203f953d397eecff46b66cf7d7d71f4cfd0d9ea123665","kind":"mcq"},{"id":"corp404-82","sourceNumber":82,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Calls in advance (money received before calls are made) can be accepted by a company:","options":["Only from its directors","Never, under any circumstances during the life of the company","Always, without any condition","Only if authorised by its articles (Section 50)"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 50: a company may accept uncalled amounts only if its articles so authorise; Table F carries such a clause.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Calls in advance (money received before calls are made) can be accepted by a company:","options":["Only from directors","Never","Always, unconditionally","Only if authorised by its articles (Section 50)"],"answer":3,"explanation":"Section 50: a company may accept uncalled amounts only if its articles so authorise; Table F carries such a clause. [Original]","revision":"original","contentSignature":"b1d137d74896e229b00e3a81ceceeddddaadbadfd17e3cdc158314f7cd974774"}],"contentSignature":"9c03eb728d7ad6d0331102560b0e614096fb016b6bc2327c9aec4c45e8d204c9","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-83","sourceNumber":83,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Interest payable on calls in advance, as per Table F, is:","options":["6% per annum","12% per annum","No interest is payable","10% per annum"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Table F provides 12% p.a. on amounts paid in advance of calls; such advances carry no dividend right.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"971e43ea576f79047a0a5226d71a7bce8e86b3d3d8c58ff73b77970348bbeda5","kind":"mcq"},{"id":"corp404-84","sourceNumber":84,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Calls in advance are shown in the balance sheet under:","options":["Reserves and surplus","Share capital","Other current liabilities","Secured loans"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Calls in advance are not part of share capital (the call is not yet made); they appear as other current liabilities.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"fba37746e742321e994e277ab8109f89e40275e0c9f6dbd5b81a05d46331acfc","kind":"mcq"},{"id":"corp404-85","sourceNumber":85,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A shareholder paying calls in advance is entitled to:","options":["Interest but NO dividend on the advance amount","A bonus share for the advance paid","Dividend on the advance amount","Double the voting rights on his shares at meetings"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Dividend is paid only on called-up and paid capital; advances earn interest (12% per Table F) instead.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A shareholder paying calls in advance is entitled to:","options":["Interest but NO dividend on the advance amount","A bonus share","Dividend on the advance","Double voting rights"],"answer":0,"explanation":"Dividend is paid only on called-up and paid capital; advances earn interest (12% per Table F) instead. [Original]","revision":"original","contentSignature":"f10c919058f531c7a8b9012807080c47d218ecf549dafaa8f16717b5ff054a1e"}],"contentSignature":"665522b15d7d7245f84da14e7f07417aae45d4abe8175cf4c681dfbf2cba9f98","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-86","sourceNumber":86,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"As per Section 51, a company may pay dividend in proportion to the amount PAID-UP on each share:","options":["If authorised by its articles","Only for preference shares","Never","In all cases mandatorily"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 51: with article authorisation, dividend is paid proportionately to amounts paid up, not to nominal values.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"ea25f5946b8bfaad4854a94bed9a7103b396c18d4dbf60ecc4100ef067ff3963","kind":"mcq"},{"id":"corp404-87","sourceNumber":87,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Voting rights of equity shareholders under Section 47(1) are:","options":["Decided by the Board of directors","In proportion to the paid-up share capital held by the member","One vote for every member irrespective of his holding of shares","One vote for every ten shares held"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 47(1): every equity member may vote on every resolution, in proportion to his share of the paid-up equity capital.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Voting rights of equity shareholders under Section 47(1) are:","options":["Decided by the Board","In proportion to the paid-up share capital held by the member","One vote per member irrespective of shares","One vote per ten shares"],"answer":1,"explanation":"Section 47(1): every equity member may vote on every resolution, in proportion to his share of the paid-up equity capital. [Original]","revision":"original","contentSignature":"2af591742ecec1d1c73eaada4b76d3a735e17b6849be2006cc7a3a2bd2f24a17"}],"contentSignature":"f5f3aa05efe1423ac0ed0c6da340f316693a160085e1fb032fcb54b773118a45","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-88","sourceNumber":88,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company issued 50,000 shares of Rs.10 at par: Rs.4 on application, Rs.3 on allotment, Rs.2 on first call, Rs.1 on final call. All money was received except the final call on 1,000 shares. Paid-up capital is:","options":["Rs.5,00,000","Rs.4,95,000","Rs.4,99,000","Rs.4,90,000"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Paid-up = 50,000 x 10 - (1,000 x 1) = 5,00,000 - 1,000 = Rs.4,99,000.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"4c951ce07342fe473d8bd433ee97bfd1d00be4c07dda8c43c1b2b44ec41320f5","kind":"mcq"},{"id":"corp404-89","sourceNumber":89,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A shareholder paid Rs.2,000 as calls in advance four months before the call was made. Interest payable to him (Table F rate) is:","options":["Rs.80","Rs.200","Rs.120","Rs.40"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Interest = 2,000 x 12% x 4/12 = Rs.80.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"4a68f32a4522864714b10e44198b219666286b0d2ef3d45ad87e9711e41855a4","kind":"mcq"},{"id":"corp404-90","sourceNumber":90,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Interest on calls in arrears of Rs.500 outstanding for six months (Table F rate) is:","options":["Rs.60","Rs.25","Rs.30","Rs.50"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Interest = 500 x 10% x 6/12 = Rs.25.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Share issue, calls & numerical problems","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"d7da4e01392eade97ff0dd2fa6d88a32a5844d45fdbc5043672ef0c589e3d1d9","kind":"mcq"},{"id":"corp404-91","sourceNumber":91,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Forfeiture of shares means:","options":["Conversion of the shares into debentures","Voluntary surrender of the shares by the shareholder","Sale of the shares by the company in the market","Compulsory termination of membership and seizure of the amount already paid, for non-payment of calls after due notice"],"answer":3,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Forfeiture is a penalty for call default: the shares are cancelled, amounts paid are forfeited, and membership ends. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Forfeiture of shares means:","options":["Conversion of shares into debentures","Voluntary surrender by the shareholder always","Sale of shares by the company in the market","Compulsory termination of membership and seizure of the amount already paid, for non-payment of calls after due notice"],"answer":3,"explanation":"Forfeiture is a penalty for call default: the shares are cancelled, amounts paid are forfeited, and membership ends. [Recall 2018]","revision":"original","contentSignature":"cac966fe0f122e40ed6858ca9ef14446bff9272cdd705893c14d4d1c01f634df"}],"contentSignature":"cb7589374f03b10ca40fb693622c1425d81c6ef09565b0d41ac60e0c28cea004","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-92","sourceNumber":92,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company can forfeit shares only if:","options":["The shareholder gives his consent in writing","The articles of association authorise forfeiture, a proper 14-day notice has been given, and a Board resolution is passed","The Board of directors so desires","The Registrar of Companies approves it"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Forfeiture needs: article authorisation, a notice demanding payment within not less than 14 days, and a Board resolution.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A company can forfeit shares only if:","options":["The shareholder agrees in writing","The articles of association authorise forfeiture, a proper 14-day notice has been given, and a Board resolution is passed","The Board wishes so in any case","The Registrar approves"],"answer":1,"explanation":"Forfeiture needs: article authorisation, a notice demanding payment within not less than 14 days, and a Board resolution. [Original]","revision":"original","contentSignature":"46474e6ca2f043cd7dc69d35b9be61463a563b68ca9bbec82520680804537df0"}],"contentSignature":"855e2db6981a6a323946b2436997ca468a7d8fdccd3750d9a0fbeea1f47a8a92","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-93","sourceNumber":93,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"On forfeiture of a share, the Share Capital account is debited with:","options":["The face value of the shares","The market value of the shares","The CALLED-UP amount on the forfeited shares","Only the amount remaining unpaid on the shares"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Share capital is reduced by the amount called up to date; the unpaid call goes to calls-in-arrears and the paid part to forfeited shares account.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"On forfeiture of a share, the Share Capital account is debited with:","options":["The face value of the share","The market value","The CALLED-UP amount on the forfeited shares","Only the amount unpaid"],"answer":2,"explanation":"Share capital is reduced by the amount called up to date; the unpaid call goes to calls-in-arrears and the paid part to forfeited shares account. [Original]","revision":"original","contentSignature":"e85d4ed213168789415f073e0afee8ccb2c0be2cc6f7fd4791e2c94832bdbba6"}],"contentSignature":"05f115f039efed5f1bce1c1d8f99b5548523c7327e4745e9d1a086994da1cc9a","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-94","sourceNumber":94,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"100 shares of Rs.10 each, on which Rs.8 per share has been called (Rs.3 application, Rs.3 allotment, Rs.2 first call), are forfeited, the holder having paid only application and allotment money. The Share Capital account is debited with:","options":["Rs.1,000","Rs.200","Rs.600","Rs.800"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Debit share capital with called-up amount: 100 x 8 = Rs.800; credit calls in arrears Rs.200 and forfeited shares account Rs.600.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e29ef043fd1952220f57e45346f75f7410270a63e59cfe7551a8b0be29800ad2","kind":"mcq"},{"id":"corp404-95","sourceNumber":95,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In the above case, the Forfeited Shares account is credited with:","options":["Rs.1,000","Rs.200","Rs.800","Rs.600"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Amount actually paid = 100 x 6 = Rs.600 is forfeited and credited to the forfeited shares (share forfeiture) account.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"4ed42e00949198c26190dcfbe5ef49f5b45dbc31ef231e7dabff8e8cee1e6ee8","kind":"mcq"},{"id":"corp404-96","sourceNumber":96,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The maximum DISCOUNT at which a forfeited share can be reissued is:","options":["Rs.10 per share","50% of the face value of the share so reissued","The amount forfeited (received) on that share","10% of the face value of the share"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Reissue discount cannot exceed the amount standing to the credit of the forfeited shares account for those shares - so the company never credits less than face value overall.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The maximum DISCOUNT at which a forfeited share can be reissued is:","options":["Rs.10 per share","50% of face value","The amount forfeited (received) on that share","10% of face value"],"answer":2,"explanation":"Reissue discount cannot exceed the amount standing to the credit of the forfeited shares account for those shares - so the company never credits less than face value overall. [Original]","revision":"original","contentSignature":"daaadc179e2f18ebad7cdce8ba9de3496ae8fe5a16e8e91d2fafdbe9276a1cda"}],"contentSignature":"f624481b2cf13f4c1def8b0b99c7d9150f043edaa6f64e36756b6d51b651fc46","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-97","sourceNumber":97,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A share of Rs.10 (fully called) on which Rs.6 was paid is forfeited. The MINIMUM price at which it can be reissued as fully paid is:","options":["Rs.10","Rs.4","Rs.8","Rs.6"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Minimum reissue price = face value - amount already paid = 10 - 6 = Rs.4 (discount equals the forfeited amount).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"1d21cbb3bc9d97b7a959ae72415ebb777c842b643f3834739784c80ddd48542c","kind":"mcq"},{"id":"corp404-98","sourceNumber":98,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"200 shares of Rs.10 each, fully called, were forfeited for non-payment of the final call of Rs.4 (Rs.6 paid). All were reissued at Rs.7 per share as fully paid. The amount transferred to CAPITAL RESERVE is:","options":["Rs.600","Rs.800","Rs.1,200","Rs.400"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Gain per share on reissue = forfeited 6 - discount (10 - 7 = 3) = Rs.3; capital reserve = 200 x 3 = Rs.600.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"80963aec03abeaad5ad85ed649153883bacd97f1ca314dc546fc2e193371b346","kind":"mcq"},{"id":"corp404-99","sourceNumber":99,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"500 shares of Rs.10 each on which Rs.8 per share was paid were forfeited. 300 of them were reissued at Rs.9 per share as fully paid. Capital reserve and the balance left in the forfeited shares account are respectively:","options":["Rs.700 and Rs.1,600","Rs.2,100 and Rs.4,000","Rs.2,400 and Rs.1,000","Rs.2,100 and Rs.1,600"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Discount per reissued share = 10 - 9 = Rs.1, so gain = 8 - 1 = Rs.7; capital reserve = 300 x 7 = Rs.2,100. The balance left relates to the 200 shares not yet reissued: 200 x 8 = Rs.1,600.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"5232429025f63ac4be170c303f38479dcdc78507edddf744fe09fa6981c085d5","kind":"mcq"},{"id":"corp404-100","sourceNumber":100,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"If forfeited shares are reissued at a price HIGHER than face value, the excess over face value is credited to:","options":["Profit and loss account","Securities premium account","Capital reserve","General reserve"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Premium on reissue goes to securities premium; the forfeiture balance (net of discount) still goes to capital reserve.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"99e94f877dd2d03d4187d095bdca90d441e0642166d212921d0147a2dd044187","kind":"mcq"},{"id":"corp404-101","sourceNumber":101,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The balance of the Forfeited Shares account, until the shares are reissued or cancelled, is shown:","options":["As a separate non-current asset under investments in the balance sheet","As other income in the statement of profit and loss for the year of forfeiture","As a current liability under other financial liabilities until the shares are dealt with","As an addition to paid-up share capital in the notes to accounts"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"The forfeiture credit is part of owners funds pending disposal - disclosed as an addition under share capital in the notes.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The balance of the Forfeited Shares account, until the shares are reissued or cancelled, is shown:","options":["As an asset","In the profit and loss account","As a current liability","As an addition to paid-up share capital in the notes to accounts"],"answer":3,"explanation":"The forfeiture credit is part of owners funds pending disposal - disclosed as an addition under share capital in the notes. [Original]","revision":"original","contentSignature":"166da3d1c5efe7c5151ea0517190d266b6ff386f607436c3492c89d4764b8cfe"}],"contentSignature":"8320127cdaf696982df1b61f11cab787f6aebe287a8f3e4e151cf612dc4e0ff0","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-102","sourceNumber":102,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"After reissue of ALL forfeited shares, the credit balance left in the forfeited shares account is transferred to:","options":["Dividend equalisation fund of the company","General reserve","Capital reserve - it is a capital profit","Share capital account"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"The net gain on forfeiture and reissue is a capital profit, transferred to capital reserve. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"After reissue of ALL forfeited shares, the credit balance left in the forfeited shares account is transferred to:","options":["Dividend equalisation fund","General reserve","Capital reserve - it is a capital profit","Share capital"],"answer":2,"explanation":"The net gain on forfeiture and reissue is a capital profit, transferred to capital reserve. [Recall 2018]","revision":"original","contentSignature":"a4d97f949e894539ccaacf1ca5642d355ba7474f2c1d6fec46702b9535b3da25"}],"contentSignature":"5c0b9bf31fc1f46b0b13bd2d863dd9089d9b4cd38d2c158d1e0f1d82f69e8d0d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-103","sourceNumber":103,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Surrender of shares means:","options":["Voluntary return of shares by a shareholder to the company for cancellation, accepted where the circumstances would justify forfeiture","Compulsory cancellation of the shares by the company","Sale of the shares on a recognised stock exchange","A gift of the shares to the directors of the company"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"The company accepts surrender only in cases where shares are liable to forfeiture - it saves the formal forfeiture procedure.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Surrender of shares means:","options":["Voluntary return of shares by a shareholder to the company for cancellation, accepted where the circumstances would justify forfeiture","Forced cancellation by the company","Sale of shares on the stock exchange","Gift of shares to directors"],"answer":0,"explanation":"The company accepts surrender only in cases where shares are liable to forfeiture - it saves the formal forfeiture procedure. [Original]","revision":"original","contentSignature":"69e33f6a9adc20d3554ea5ebce4e8cfe9accc7772dc43c1d20cbe0cd9c5b6ac0"}],"contentSignature":"b4eacedf7707efa5a1e0b503cb9aeb40cc068cbfe8035684ca745666b7703f4d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-104","sourceNumber":104,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company has a LIEN on partly-paid shares for:","options":["The dividend payable on those shares to the shareholders","Amounts unpaid on those shares (calls and instalments)","All private debts of the shareholder to anyone","Premium already paid"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Table F gives the company a first and paramount lien on partly-paid shares for all moneys called/payable on them.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A company has a LIEN on partly-paid shares for:","options":["Dividend payable","Amounts unpaid on those shares (calls and instalments)","All private debts of the shareholder to anyone","Premium already paid"],"answer":1,"explanation":"Table F gives the company a first and paramount lien on partly-paid shares for all moneys called/payable on them. [Original]","revision":"original","contentSignature":"e1a746bd17b2fb95a36b146df0c7a36898b7655837abeb958ce5bb1f18691ae7"}],"contentSignature":"54d98de00d34bb5670967ef9d4afd4ee5926a6112c9948efbfb95f22873e47bf","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-105","sourceNumber":105,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A share certificate under the common seal/signature of the company, stating the shares held by a member, must normally be issued within ________ of allotment and is:","options":["6 months; it settles the question of payment once and for all for the member concerned","2 months; prima facie evidence of the member's title to the shares","1 year; compulsory only for the preference shares","15 days; a negotiable instrument"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 56(4): share certificates are delivered within two months of allotment; the certificate is prima facie evidence of title.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A share certificate under the common seal/signature of the company, stating the shares held by a member, must normally be issued within ________ of allotment and is:","options":["6 months; conclusive proof of payment","2 months; prima facie evidence of the member's title to the shares","1 year; compulsory only for preference shares","15 days; a negotiable instrument"],"answer":1,"explanation":"Section 56(4): share certificates are delivered within two months of allotment; the certificate is prima facie evidence of title. [Original]","revision":"original","contentSignature":"4d3e02301b9b029170ef82567035be735da5611dcdf5d3f4e074d6748c880cf2"}],"contentSignature":"8f82f8c93ad66d09f52f7df39178a289f4a26a308bb38188ce244533484d725d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-106","sourceNumber":106,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"\"Stock\" differs from \"shares\" in that stock:","options":["Is always issued in a partly-paid form","Carries no right to any dividend, whether a dividend is declared or not by the company in that financial year","Is the consolidated value of fully-paid shares, divisible into any amount and transferable in fractions","Cannot be transferred from one person to another"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Fully-paid shares may be converted into stock (s.61); stock is divisible into any denomination, unlike shares with fixed numbers.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"\"Stock\" differs from \"shares\" in that stock:","options":["Is always partly paid","Carries no dividend","Is the consolidated value of fully-paid shares, divisible into any amount and transferable in fractions","Cannot be transferred"],"answer":2,"explanation":"Fully-paid shares may be converted into stock (s.61); stock is divisible into any denomination, unlike shares with fixed numbers. [Original] C2. Securities Premium, Bonus, Rights Issue, ESOP & Buy-Back Covers: the five permitted uses of securities premium (s.52); bonus shares - permitted sources, conditions, entries and effects (s.63); rights issue mechanics and renunciation (s.62(1)(a)); ESOP and preferential offers (s.62(1)(b)/(c), Rule 12); buy-back sources, 25% limit, 2:1 debt-equity test, extinguishment and capital redemption reserve (ss.68-70) - with numericals. Double-verified against the Companies Act, 2013 and the Share Capital and Debentures Rules, 2014.","revision":"original","contentSignature":"9e7607d46ff09ca606b41825f52ea6b99129b97a91773b1ab56b5cb2d13dd351"}],"contentSignature":"7f1240af6c18b4844bf5b31c3efcda2a95496972136d692ac3214471081de1fb","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-107","sourceNumber":107,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Section 52 of the Companies Act, 2013 permits the securities premium account to be used for all of the following EXCEPT:","options":["Issue of fully paid bonus shares","Premium payable on redemption of debentures","Writing off preliminary expenses","Payment of DIVIDEND to shareholders"],"answer":3,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Section 52(2) lists five uses: bonus issue, preliminary expenses, issue expenses/commission/discount, premium on redemption of preference shares or debentures, and buy-back. Dividend is NOT a permitted use. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"01ed93061272f7ba013f7bef3a3dd0bcb9c3bb9ee268ef5567cda65b2fb3d9ca","kind":"mcq"},{"id":"corp404-108","sourceNumber":108,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The securities premium account is shown in the balance sheet under:","options":["Reserves and surplus","Contingent liabilities","Share capital","Current liabilities"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"It is a capital reserve disclosed under Reserves and Surplus in the equity section of Schedule III.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c2596244c9c5d7796a5939d423cc385c2d468e5aec01afaa28df1352a280e06d","kind":"mcq"},{"id":"corp404-109","sourceNumber":109,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Premium received on issue of DEBENTURES is credited to:","options":["Profit and loss account","Discount on issue account","Debentures account","Securities premium account"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 52 applies to premium on any securities - shares or debentures; the premium on debentures also goes to securities premium.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"427310ab3ed480d5b4b6720cf30e0c811fc9f2fb313d92fb7d25cdb4411f6c92","kind":"mcq"},{"id":"corp404-110","sourceNumber":110,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Expenses and commission paid on the issue of shares may be written off against:","options":["Capital redemption reserve","Securities premium account","Share capital","General reserve only"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 52(2)(c): expenses, commission and discount on issue of shares or debentures can be written off out of securities premium.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"9c44b538c1508418a7c92526c6c41777525fa9eebff5f104912ba8b5bd805edb","kind":"mcq"},{"id":"corp404-111","sourceNumber":111,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Bonus shares under Section 63 can be issued only as:","options":["Fully paid-up shares, out of free reserves, securities premium or capital redemption reserve","Preference shares of the company alone","Partly paid-up shares of the company","Shares issued at a discount to the face value, the discount being adjusted against the free reserves"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 63(1): bonus shares are fully paid and funded from free reserves, the securities premium account or the capital redemption reserve account.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Bonus shares under Section 63 can be issued only as:","options":["Fully paid-up shares, out of free reserves, securities premium or capital redemption reserve","Preference shares only","Partly paid shares","Shares issued at a discount"],"answer":0,"explanation":"Section 63(1): bonus shares are fully paid and funded from free reserves, the securities premium account or the capital redemption reserve account. [Original]","revision":"original","contentSignature":"83807c1f8bc93a816c20ae6a734eea58590f63013b1170c44c7947146d1a12c8"}],"contentSignature":"3586ac3440a566cafa97a515ae787fdac4039be859a3be0788a1341c898a6be8","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-112","sourceNumber":112,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company CANNOT issue bonus shares out of:","options":["Capital redemption reserve account of the company at all","Revaluation reserve (created by revaluing fixed assets)","Securities premium account","Free reserves of the company"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Revaluation reserve is an unrealised, notional surplus - Section 63(1) expressly bars capitalising it for a bonus issue.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A company CANNOT issue bonus shares out of:","options":["Capital redemption reserve","Revaluation reserve (created by revaluing fixed assets)","Securities premium account","Free reserves"],"answer":1,"explanation":"Revaluation reserve is an unrealised, notional surplus - Section 63(1) expressly bars capitalising it for a bonus issue. [Original]","revision":"original","contentSignature":"7e796e6dc6673c4e379419339c3f2ecae6d38cdf0de036075a95b696ae2fd4b0"}],"contentSignature":"7b367d08539fdd400c7d97ba947613da37045b7b035a502cc86be31e7fe9786b","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-113","sourceNumber":113,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Before recommending a bonus issue, a company must ensure that: interest/principal on debt or statutory dues","options":["Its articles authorise a bonus issue, shareholders approve on Board recommendation, and it has not defaulted in payment of","It carries no reserves on its balance sheet","Its shares are quoted at a premium on the exchange","It declared a dividend in the immediately preceding year"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 63(2) and Rule 14: articles authorisation, Board recommendation, general-meeting approval and no default in debt/statutory payments are pre-conditions.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Before recommending a bonus issue, a company must ensure that: interest/principal on debt or statutory dues","options":["Its articles authorise a bonus issue, shareholders approve on Board recommendation, and it has not defaulted in payment of","It has no reserves","Its shares are quoted at a premium","It has declared dividend in the previous year"],"answer":0,"explanation":"Section 63(2) and Rule 14: articles authorisation, Board recommendation, general-meeting approval and no default in debt/statutory payments are pre-conditions. [Original]","revision":"original","contentSignature":"64563edaba29e06bcc4e4777b4183aa2ec5718179afe659a31e98419863dc7b4"}],"contentSignature":"437899be5932c6b9530e17c574e91d658de27c37fa184ebcf8e3a7a116b50957","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-114","sourceNumber":114,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A bonus issue results in:","options":["A reduction in the share capital of the company and a corresponding fall in the number of shares in issue","Conversion of reserves into share capital - total net worth unchanged, number of shares increased","An inflow of cash into the company","An increase in the net worth of the company"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Bonus capitalises reserves: reserves fall, share capital rises by the same amount; the equity total and net worth stay the same.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A bonus issue results in:","options":["Reduction of share capital","Conversion of reserves into share capital - total net worth unchanged, number of shares increased","Cash inflow to the company","Increase in the net worth of the company"],"answer":1,"explanation":"Bonus capitalises reserves: reserves fall, share capital rises by the same amount; the equity total and net worth stay the same. [Original]","revision":"original","contentSignature":"332035b6395f03de14df3017ad68fb11c1b96ffbb09336c384a75a5e740a7cc6"}],"contentSignature":"04dd71992cf2f72753ed02edc83459095525c9b848465cc1507509668f544895","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-115","sourceNumber":115,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The journal entry on issue of bonus shares is:","options":["Free Reserves/Securities Premium/CRR Dr. -> Bonus to Shareholders; then Bonus to Shareholders Dr. -> To Share Capital","Share Capital Account Dr. To Reserves Account","Bank Account Dr. To Share Capital Account","No entry is passed in the books for the bonus issue"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Reserves are debited (capitalised) and share capital credited through the bonus-to-shareholders (dividend equalisation) route.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The journal entry on issue of bonus shares is:","options":["Free Reserves/Securities Premium/CRR Dr. -> Bonus to Shareholders; then Bonus to Shareholders Dr. -> To Share Capital","Share Capital Dr. To Reserves","Bank Dr. To Share Capital","No entry is passed"],"answer":0,"explanation":"Reserves are debited (capitalised) and share capital credited through the bonus-to-shareholders (dividend equalisation) route. [Original]","revision":"original","contentSignature":"09597855bd100ea597ce5d6f9638d0ed4caeef219608917185fa79b44ecfa8a1"}],"contentSignature":"3e3252f30c71f86ef847c8ce7bd4e4500a6a166e8c549851cdeeb87404a4003b","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-116","sourceNumber":116,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company has: securities premium Rs.8 lakh, free reserves Rs.12 lakh, capital redemption reserve Rs.2 lakh and revaluation reserve Rs.5 lakh. The MAXIMUM bonus it can issue is:","options":["Rs.20 lakh","Rs.25 lakh","Rs.22 lakh","Rs.27 lakh"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Permitted sources = 8 + 12 + 2 = Rs.22 lakh; the revaluation reserve of Rs.5 lakh cannot be used.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"de319376bc7060f1f24bc92221caf4add4fa5258f7193567394783501c9461a3","kind":"mcq"},{"id":"corp404-117","sourceNumber":117,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company with 2,00,000 equity shares of Rs.10 each (fully paid) declares a bonus of 1 share for every 2 held. The amount capitalised out of reserves is:","options":["Rs.5 lakh","Rs.30 lakh","Rs.20 lakh","Rs.10 lakh"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Bonus shares = 2,00,000 x 1/2 = 1,00,000 shares of Rs.10 = Rs.10,00,000 capitalised.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"208d64a890c14feafec05e43fdd0226c7cdfa9b43cd2bc952b1c3d9a3c822855","kind":"mcq"},{"id":"corp404-118","sourceNumber":118,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"After a bonus issue, the earnings per share (EPS) of the company will normally:","options":["Fall, because the same profit now spreads over more shares","Rise, since the reserves have been capitalised in the books","Become negative, since reserves are exhausted","Remain exactly the same as before the issue"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Total profit is unchanged but the share count rises, so EPS (and market price per share) adjust downward proportionately.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"After a bonus issue, the earnings per share (EPS) of the company will normally:","options":["Fall, because the same profit now spreads over more shares","Rise","Become negative","Remain exactly the same"],"answer":0,"explanation":"Total profit is unchanged but the share count rises, so EPS (and market price per share) adjust downward proportionately. [Original]","revision":"original","contentSignature":"ca439ec80c153703fe0a3eee55db0798dbdefd90fde0cbb35530b125defd6eae"}],"contentSignature":"6b1690fb693a3f09dffb6009e1f12dcb19491b0fd8a9d443091a0bfb3b9d8603","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-119","sourceNumber":119,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Existing shares must be ________ before a company can issue bonus shares.","options":["Quoted","Partly paid","Fully paid-up","Held for one year"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Bonus can only fund FULLY paid shares; a company cannot issue bonus against partly paid shares without first making them fully paid.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Forfeiture, securities premium & bonus shares","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"6940dcb64c78cfbcadc52945e92d5f004f98edfa50f80e04dab1001290bce6b5","kind":"mcq"},{"id":"corp404-120","sourceNumber":120,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A rights issue under Section 62(1)(a) is an offer of further shares to:","options":["The directors of the company alone, in equal proportions among themselves","EXISTING equity shareholders in proportion to their holdings","Institutional investors alone","The general public at large"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Existing members get the pre-emptive right to subscribe in proportion to their paid-up capital - protecting them from dilution.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A rights issue under Section 62(1)(a) is an offer of further shares to:","options":["Only the directors","EXISTING equity shareholders in proportion to their holdings","Only institutional investors","The general public"],"answer":1,"explanation":"Existing members get the pre-emptive right to subscribe in proportion to their paid-up capital - protecting them from dilution. [Original]","revision":"original","contentSignature":"de4d14ebab859dc5cbb00337ec9615fbd3c790490ca97564b753bab7a128556c"}],"contentSignature":"4024cd1055513e0f34f1b642b963bac1bd1fd78b376650e688ceb492005b2cf6","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-121","sourceNumber":121,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The offer letter of a rights issue must remain open for acceptance for at least ________ and not more than ________.","options":["30 days; 60 days","15 days; 30 days","7 days; 15 days","10 days; 90 days"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 62(1)(a): the offer stays open a minimum of 15 days and a maximum of 30 days; if not accepted it is deemed declined.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"64e33ac640944a814f6c52509f2a4a50825605e889963122f25c3fc18b32331d","kind":"mcq"},{"id":"corp404-122","sourceNumber":122,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A rights shareholder who does not wish to subscribe may:","options":["Do nothing - the shares offered to him stand forfeited at once by the Board of the company","Demand a refund of the face value from the company","Convert the offer into debentures of the company","Renounce the offer in favour of any other person, unless the articles provide otherwise"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"The rights offer letter includes a right of renunciation; the member may sell/transfer his entitlement.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A rights shareholder who does not wish to subscribe may:","options":["Do nothing - the shares are forfeited","Demand a refund of face value","Convert the offer into debentures","Renounce the offer in favour of any other person, unless the articles provide otherwise"],"answer":3,"explanation":"The rights offer letter includes a right of renunciation; the member may sell/transfer his entitlement. [Original]","revision":"original","contentSignature":"08e5a53be8f385143d592f8a7186cc553fae0010831b7094f08771b02ff8db76"}],"contentSignature":"e2f40f1b8de5161f7967495105222e4c676c9cf23dd9b3fc14026ee92447a8f6","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-123","sourceNumber":123,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company declares a rights issue of 1 share for every 4 shares held. A member holding 800 shares is entitled to subscribe to:","options":["200 shares","400 shares","800 shares","100 shares"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Entitlement = 800 / 4 = 200 right shares.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"1b9c37528836ff0d5a4c5181d730cdf15ea19e12d5c117a2ec1a2f70854d4ef3","kind":"mcq"},{"id":"corp404-124","sourceNumber":124,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company share quotes at Rs.90. It announces a rights issue of 1 for 4 at Rs.60 per share. The theoretical ex-rights price and the value of one right are:","options":["Rs.86 and Rs.4","Rs.80 and Rs.10","Rs.84 and Rs.6","Rs.75 and Rs.15"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Ex-rights price = (4 x 90 + 1 x 60)/5 = 420/5 = Rs.84; value of a right = 90 - 84 = Rs.6 per old share.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"ee26cbe5e73dcaa57ae26e107f4be49ae89549a3be90e2daeb015aef1d44ab75","kind":"mcq"},{"id":"corp404-125","sourceNumber":125,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"An employee stock option scheme (ESOP) under Section 62(1)(b) requires approval by:","options":["Special resolution of the shareholders","The Registrar of Companies","A resolution of the Board of directors alone","The stock exchange on which it is listed"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"ESOP offers shares to employees/directors (other than promoters and 10%+ holders) and needs a special resolution; unlisted companies follow Rule 12.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An employee stock option scheme (ESOP) under Section 62(1)(b) requires approval by:","options":["Special resolution of the shareholders","The Registrar","Board resolution only","The stock exchange"],"answer":0,"explanation":"ESOP offers shares to employees/directors (other than promoters and 10%+ holders) and needs a special resolution; unlisted companies follow Rule 12. [Original]","revision":"original","contentSignature":"8f427af00e758b4f08e50ab918926b14ec8d96938436ac3428f72f0481871b65"}],"contentSignature":"0febc1c5aaccbb28f5bc060e8246089548bcba0817e7878c5f8ed62e671063a9","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-126","sourceNumber":126,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under the rules for unlisted companies, the minimum period between the GRANT of an option and its VESTING is:","options":["No minimum","6 months","One year","Three years"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Rule 12 of the Share Capital and Debentures Rules, 2014: a minimum one-year gap between grant and vesting of options.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"4fca8e855a2cadfa0e2d105883c291e6c781784d2489b521d0f28a9ea6dd5e6a","kind":"mcq"},{"id":"corp404-127","sourceNumber":127,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A preferential offer of shares under Section 62(1)(c) to persons other than existing shareholders requires:","options":["No approval from any quarter","The permission of the High Court","The approval of all the creditors of the company obtained in writing","A special resolution and compliance with the pricing and other rules"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Preferential allotment to outsiders needs a special resolution plus Rule 13 conditions, including price determined by a registered valuer.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A preferential offer of shares under Section 62(1)(c) to persons other than existing shareholders requires:","options":["No approval","Permission of the High Court","Approval of all creditors","A special resolution and compliance with the pricing and other rules"],"answer":3,"explanation":"Preferential allotment to outsiders needs a special resolution plus Rule 13 conditions, including price determined by a registered valuer. [Original]","revision":"original","contentSignature":"91b848ced1094aa25691b3db8573dfd9d67fdec88f906db3c972bbde463cb471"}],"contentSignature":"14422273762d153524e13019c3874f3e197245e211f0edd0f58fa11f75c44b0f","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-128","sourceNumber":128,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company may fund a buy-back of its own shares under Section 68 out of:","options":["Free reserves, the securities premium account, or proceeds of an earlier issue of securities of a DIFFERENT kind","A fresh issue of shares of the same kind","Long-term borrowings raised for the purpose","Amounts standing to the credit of trade creditors"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 68(1): buy-back sources are free reserves, securities premium, or proceeds of an earlier issue of other (not the same kind of) securities.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A company may fund a buy-back of its own shares under Section 68 out of:","options":["Free reserves, the securities premium account, or proceeds of an earlier issue of securities of a DIFFERENT kind","A fresh issue of shares of the SAME kind","Long-term borrowings","Trade creditors"],"answer":0,"explanation":"Section 68(1): buy-back sources are free reserves, securities premium, or proceeds of an earlier issue of other (not the same kind of) securities. [Original]","revision":"original","contentSignature":"d0897299c6c64667ab078e71342d7aff14a7b0df17a54fbd140e81ae3e471651"}],"contentSignature":"27ae3715dba2725b9b0c077fb9d7637fba1c88ed3b5cd9a4f930c3a877fce5be","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-129","sourceNumber":129,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The maximum buy-back in a financial year under Section 68(2) is:","options":["25% of the aggregate of paid-up capital and free reserves","100% of the balance in the securities premium account only","10% of the paid-up capital of the company","50% of the free reserves of the company"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"The 25% cap applies to the aggregate of paid-up capital plus free reserves (Board-approval route alone covers up to 10% with special conditions).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The maximum buy-back in a financial year under Section 68(2) is:","options":["25% of the aggregate of paid-up capital and free reserves","100% of securities premium","10% of paid-up capital","50% of free reserves"],"answer":0,"explanation":"The 25% cap applies to the aggregate of paid-up capital plus free reserves (Board-approval route alone covers up to 10% with special conditions). [Original]","revision":"original","contentSignature":"b042d9fa918020bebe0d6413e50fd16e2e1732ebf9255eb1a405fe38b16a89ab"}],"contentSignature":"f3eab34475f85c14fef78f979d3f7beedd36dc29551e798b742082189fed62d7","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-130","sourceNumber":130,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"After a buy-back, the ratio of debt to equity (paid-up capital and free reserves) of the company must not exceed:","options":["1:1","2:1","4:1","3:1"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 68(2)(d): post-buy-back debt-equity ratio cannot exceed 2:1 (a higher ratio may be notified for specified classes).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"cea7bc18680b4de2c2658466398303107df63058ac0ac9613f4ba6ff22ae78f4","kind":"mcq"},{"id":"corp404-131","sourceNumber":131,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"For a buy-back, the shares must be ________, and the articles must ________.","options":["Preference; permit premium","Fully paid-up; authorise the buy-back","Listed; prohibit it","Partly paid; be silent"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 68(2): buy-back needs article authorisation, a special resolution (except the 10% Board route), fully paid shares and other conditions.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"7582d44c8f4c98179e8b97ae3658b53b7019a9e0bb452c38c5a46c504266952b","kind":"mcq"},{"id":"corp404-132","sourceNumber":132,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Shares bought back must be extinguished and physically destroyed within ________ of the completion of the buy-back.","options":["6 months","30 days","90 days","7 days"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 68(7): the bought-back securities are extinguished and destroyed within 7 days of the last date of completion.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"976503cae8cf69684e7dc174dc6a1cb2f95906eac69b37eaeb9b2d91b543756f","kind":"mcq"},{"id":"corp404-133","sourceNumber":133,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Where a company buys back shares out of FREE RESERVES, an amount equal to the nominal value of shares bought back is transferred to:","options":["General reserve account","Capital redemption reserve account","Dividend reserve account of the company","Sinking fund account"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 69: buying back out of free reserves requires a transfer of the nominal value to the capital redemption reserve - keeping capital intact for creditors.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Where a company buys back shares out of FREE RESERVES, an amount equal to the nominal value of shares bought back is transferred to:","options":["General reserve","Capital redemption reserve account","Dividend reserve","Sinking fund"],"answer":1,"explanation":"Section 69: buying back out of free reserves requires a transfer of the nominal value to the capital redemption reserve - keeping capital intact for creditors. [Original]","revision":"original","contentSignature":"43304cab5b5315c0ab6940f43a439410e8e9ddbc3dedc938a2e20cb5df385b02"}],"contentSignature":"9b5b0d99257609d4c0890637047a52085b56c657e5f768109dd35d0d9b7d3614","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-134","sourceNumber":134,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company has paid-up capital of Rs.40 lakh and free reserves of Rs.20 lakh. The maximum amount it can deploy in a buy-back during the year is:","options":["Rs.15 lakh","Rs.5 lakh","Rs.10 lakh","Rs.20 lakh"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"25% of (40 + 20) lakh = 25% of 60 lakh = Rs.15 lakh.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"bbc3ee5b708f1394ae7ca70aef1e0c93aa78b757dc0bcc4d5993d9916010b35c","kind":"mcq"},{"id":"corp404-135","sourceNumber":135,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In the above case, if the buy-back price is fixed at Rs.50 per share, the maximum number of shares that can be bought back is:","options":["50,000","20,000","15,000","30,000"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Shares = Rs.15,00,000 / Rs.50 = 30,000 shares.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"9f6c150a7470a7d490d8cee0a0f769d0509f60dcd0c9315f2a169e1ae0e29970","kind":"mcq"},{"id":"corp404-136","sourceNumber":136,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company buys back shares of nominal value Rs.10 lakh entirely out of free reserves. The amount to be transferred to the capital redemption reserve is:","options":["Nil","Rs.10 lakh","Rs.5 lakh","Rs.15 lakh"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 69: nominal value of shares bought back out of free reserves = Rs.10 lakh, transferred to CRR to maintain the capital base.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"31048c399a340e7dd424cbb29a8d216481a4aa9a8e70aed5efc683ba8972dc29","kind":"mcq"},{"id":"corp404-137","sourceNumber":137,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Section 70 restricts buy-back in certain cases - a company CANNOT buy back: shares/loans (until the default is remedied and 3 years pass)","options":["Shares that are held by small investors","Through any subsidiary company or investment company, or when it has defaulted in repayment of deposits/debentures/preference","Preference shares that were redeemed on time","Fully paid shares with the approval of shareholders"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 70 bars buy-back via subsidiaries/investment companies and by companies in continuing default (default must be cured plus a three-year cooling period).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 70 restricts buy-back in certain cases - a company CANNOT buy back: shares/loans (until the default is remedied and 3 years pass)","options":["Shares held by small investors","Through any subsidiary company or investment company, or when it has defaulted in repayment of deposits/debentures/preference","Preference shares redeemed on time","Fully paid shares with shareholder approval"],"answer":1,"explanation":"Section 70 bars buy-back via subsidiaries/investment companies and by companies in continuing default (default must be cured plus a three-year cooling period). [Original]","revision":"original","contentSignature":"946e9094faaa064c3c962df3310a55cf00882ca03324f84b8163dca840b832e2"}],"contentSignature":"e6188b689e40d9f9346060dc0a33ead6ddf709ac4d890e8da4201fabaa7a3b38","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-138","sourceNumber":138,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"After completing a buy-back, a company is prohibited from making a further issue of the SAME kind of securities within ________, except by way of bonus issue or discharge of existing obligations.","options":["6 months","3 years","2 years","1 month"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 68(8): no fresh issue of the same kind within 6 months, except bonus issues and conversion of warrants/loans/preference into equity.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"29ceba3a38a732f3e6b64f07910c5f6dfe0374a92579ab3d24463544656ee182","kind":"mcq"},{"id":"corp404-139","sourceNumber":139,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Before a buy-back, the company files with the Registrar (and SEBI for listed companies) a declaration of solvency in Form:","options":["MGT-14","PAS-3","AOC-4","SH-9"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"The Board declares solvency (ability to pay debts) in Form SH-9, verified by affidavit, before the buy-back proceeds.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Rights issue, ESOP & buy-back","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"66c862b40e0cbbbccc7e3237cc6b1fb1ea42ba0e9c6f359855d627db93e81796","kind":"mcq"},{"id":"corp404-140","sourceNumber":140,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A debenture, as per Section 2(30) of the Companies Act, 2013, is:","options":["A share in the share capital of the company","A warrant for the payment of dividend","An instrument evidencing a debt - including debenture stock, bonds or any other securities constituting a charge on the assets or not","A certificate of ownership of the company's assets"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"A debenture acknowledges a loan: the holder is a creditor, not an owner, of the company.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A debenture, as per Section 2(30) of the Companies Act, 2013, is:","options":["A share in the capital of the company","A dividend warrant","An instrument evidencing a debt - including debenture stock, bonds or any other securities constituting a charge on the assets or not","A certificate of ownership"],"answer":2,"explanation":"A debenture acknowledges a loan: the holder is a creditor, not an owner, of the company. [Original]","revision":"original","contentSignature":"5cd7eef416232405ea010e40afa6b08ce711dd8d9c51287c6522bc01b66b66a7"}],"contentSignature":"0d347189df0f1fada1a93a489afa2be4506d4ff4eae78b980c6389a1f176d856","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-141","sourceNumber":141,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The fundamental difference between a shareholder and a debenture holder is that a debenture holder is:","options":["An owner of the company","A CREDITOR (lender) of the company","A director of the company","An employee of the company"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Shareholders own the company and share residual profits; debenture holders lend money and earn a fixed interest.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"40275fe71a5b0c39fe8f72796bc00f2bf161886f91c14a7905a3fa6de498ece3","kind":"mcq"},{"id":"corp404-142","sourceNumber":142,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Interest on debentures is payable:","options":["At the discretion of the Board of directors","Only out of the profits earned by the company","Whether or not the company earns profits - it is a charge against profits","Only after the dividend on shares has been paid to the shareholders of the company"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Interest is a debt-service obligation, paid even out of capital if needed - unlike dividend, which needs profits.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest on debentures is payable:","options":["At the discretion of the Board","Only if the company earns profits","Whether or not the company earns profits - it is a charge against profits","Only after dividend is paid"],"answer":2,"explanation":"Interest is a debt-service obligation, paid even out of capital if needed - unlike dividend, which needs profits.","revision":"original","contentSignature":"ca7fd29041d3233ac43aa253eb82131a8b2e9a450f011d314d6928b894249573"}],"contentSignature":"9c8363e622bdb641ab16e375cf6e832c5956539babeb4e7865b14a616681e2f7","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-143","sourceNumber":143,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Registered debentures differ from bearer debentures in that bearer debentures are transferred:","options":["Only through a recognised stock exchange","Only with the approval of the Board of directors and entry in the register of members","By a transfer deed followed by registration","By mere DELIVERY - the holder (bearer) is entitled to interest and principal"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Bearer debentures are negotiable by delivery; registered debentures transfer by instrument and entry in the register.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Registered debentures differ from bearer debentures in that bearer debentures are transferred:","options":["Only on a stock exchange","Only with Board approval","By a transfer deed and registration","By mere DELIVERY - the holder (bearer) is entitled to interest and principal"],"answer":3,"explanation":"Bearer debentures are negotiable by delivery; registered debentures transfer by instrument and entry in the register. [Original]","revision":"original","contentSignature":"f02798fe5f0f5afd3859989b14a4b3b1b631c5186481851179d936d6baf74655"}],"contentSignature":"ca3f72a55162b487438e6e1f559acdeceecc4f41968ef43f946b5a5895225f5e","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-144","sourceNumber":144,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Secured (mortgage) debentures carry:","options":["A guarantee given by the Central Government for the repayment","The personal liability of the directors","A fixed or floating charge over the assets of the company","No charge over any of the assets"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Secured debentures are backed by a charge on company assets; on default, holders can enforce the security.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Secured (mortgage) debentures carry:","options":["A guarantee by the Government","Personal liability of directors","A fixed or floating charge over the assets of the company","No charge on assets"],"answer":2,"explanation":"Secured debentures are backed by a charge on company assets; on default, holders can enforce the security.","revision":"original","contentSignature":"bfeb27f7646ea5281d851ee9a033b80ed6ced4a0f7250f339c93aabbc54d872f"}],"contentSignature":"66fa770b67aa48897c8edfef82d441a0ac69684ebf78ce9c407fc19a513a6082","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-145","sourceNumber":145,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A FLOATING charge is one that:","options":["Is always illegal and void","Covers only the land and buildings of the company","Hovers over a changing class of assets (like stock or debtors), leaving the company free to deal with them until it crystallises","Attaches to one specific machine identified at the outset"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"A floating charge covers a shifting pool of assets; it crystallises into a fixed charge on default, winding up or cessation of business.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A FLOATING charge is one that:","options":["Is always illegal","Covers only land","Hovers over a changing class of assets (like stock or debtors), leaving the company free to deal with them until it crystallises","Attaches to a specific machine"],"answer":2,"explanation":"A floating charge covers a shifting pool of assets; it crystallises into a fixed charge on default, winding up or cessation of business. [Original]","revision":"original","contentSignature":"ddabd01bdc9a946f329c10f5697c7470e1370ed934bee40f8ed3e5f2481c0329"}],"contentSignature":"2f9c9955d947f88144f04162606d6130e2d7178a840df4847c2c2f581be5efbd","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-146","sourceNumber":146,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A floating charge CRYSTALLISES (becomes fixed) when:","options":["The company is wound up, defaults, or ceases business, or a receiver is appointed","The Board of directors holds a meeting","The interest on the debentures is paid","The charge is registered with the Registrar of Companies within the period allowed by the Act"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"On crystallisation the charge fastens on the assets then present, and the company can no longer deal with them freely.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A floating charge CRYSTALLISES (becomes fixed) when:","options":["The company is wound up, defaults, or ceases business, or a receiver is appointed","The Board meets","Interest is paid","It is registered"],"answer":0,"explanation":"On crystallisation the charge fastens on the assets then present, and the company can no longer deal with them freely. [Original]","revision":"original","contentSignature":"348f520114ba6adb71e19bc8f2a6c0a6bd882cef209a4e8e7db66283c1926a9d"}],"contentSignature":"e756687671f9065713aacdcbd542d86cf8eaa69fec8418987e1f7e860f564faa","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-147","sourceNumber":147,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Debentures which carry an option to convert into equity shares are called:","options":["Bearer debentures","Convertible debentures (fully or partly)","Redeemable debentures of the company itself","Naked debentures"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Convertible debentures convert into equity at a fixed ratio/date; partly convertible ones convert only a portion.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Debentures which carry an option to convert into equity shares are called:","options":["Bearer debentures","Convertible debentures (fully or partly)","Redeemable debentures","Naked debentures"],"answer":1,"explanation":"Convertible debentures convert into equity at a fixed ratio/date; partly convertible ones convert only a portion.","revision":"original","contentSignature":"c8f53c9c88daebf46144500519c5f2e90f1ce22f76c800664badffa09c3a3105"}],"contentSignature":"8e0987b6a1c6f569b7beae162df2adf86c63d698b6a7b46c490feee4f138766d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-148","sourceNumber":148,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Deep discount (zero coupon) bonds/debentures are:","options":["Issued at their face value and redeemed at the same value, the holder earning interest by way of coupon payments","Never redeemed during the life of the company","Issued at a SUBSTANTIAL discount and redeemed at face value - the discount represents the total interest","Issued free of cost to the company"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2017","explanation":"No periodic interest is paid; the difference between the low issue price and the face redemption value is the implicit interest. [Recall 2017]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Deep discount (zero coupon) bonds/debentures are:","options":["Issued at face value","Never redeemed","Issued at a SUBSTANTIAL discount and redeemed at face value - the discount represents the total interest","Free of cost to the company"],"answer":2,"explanation":"No periodic interest is paid; the difference between the low issue price and the face redemption value is the implicit interest. [Recall 2017]","revision":"original","contentSignature":"7fdce6253a42f6b0f8cdb022f8ee2c343a1ad1237ae24a166efdb650d206f292"}],"contentSignature":"56420ae0af0bf45bb708fd913d24a4902e4532faab313f3d23612689b81cf4f0","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-149","sourceNumber":149,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Debenture holders do NOT have the right to:","options":["Vote at general meetings of the company","Sue the company for their money","Enforce their security on default of payment","Receive interest at a fixed rate"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Being creditors, not members, debenture holders have no voting rights in company general meetings.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Debenture holders do NOT have the right to:","options":["Vote at general meetings of the company","Sue for their money","Enforce security on default","Receive fixed interest"],"answer":0,"explanation":"Being creditors, not members, debenture holders have no voting rights in company general meetings. [Original]","revision":"original","contentSignature":"f24e1597eecbbb764a1c2b58843e05c276ef169bbff867ef70a3106828431a1d"}],"contentSignature":"283e2ac198977d999ed0aaf5656e02681053c37026dc97e4fa58c440750d522f","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-150","sourceNumber":150,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company issuing debentures to the public (or to more than 500 persons) must appoint:","options":["A DEBENTURE TRUSTEE to protect the interests of debenture holders","A nominee of the Central Government to look after the debenture issue","A managing director for the issue","A cost auditor for the issue"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 71(5): a debenture trustee is mandatory for prospectus issues and issues to more than 500 persons; the trust deed is executed before the issue.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A company issuing debentures to the public (or to more than 500 persons) must appoint:","options":["A DEBENTURE TRUSTEE to protect the interests of debenture holders","A government nominee","A managing director","A cost auditor"],"answer":0,"explanation":"Section 71(5): a debenture trustee is mandatory for prospectus issues and issues to more than 500 persons; the trust deed is executed before the issue. [Original]","revision":"original","contentSignature":"8a9a58a603b13a66979cdae93adc73e53eb8ed89b98a83415a50aabf1945b8e8"}],"contentSignature":"ed94e61bce9c75844232c04e448347a176e204989c2b45dc4360cae4b2fceb20","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-151","sourceNumber":151,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under the Companies (Share Capital and Debentures) Rules, 2014, SECURED debentures may be issued with a maximum redemption period of:","options":["20 years from the date of issue for all companies","10 years from the date of issue (up to 30 years for companies engaged in infrastructure projects and specified finance companies)","No limit on the period of redemption","5 years from the date of issue"],"answer":1,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Rule 18(1): secured debentures must be redeemed within 10 years; the proviso allows up to 30 years for infrastructure and certain finance companies. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the Companies (Share Capital and Debentures) Rules, 2014, SECURED debentures may be issued with a maximum redemption period of:","options":["20 years for all companies","10 years from the date of issue (up to 30 years for companies engaged in infrastructure projects and specified finance companies)","There is no limit","5 years"],"answer":1,"explanation":"Rule 18(1): secured debentures must be redeemed within 10 years; the proviso allows up to 30 years for infrastructure and certain finance companies. [Recall 2018]","revision":"original","contentSignature":"fe6a70b1a7c63a67a9af65ec51f45ca36e3852b585eafcdd8dfd9f375e5b2b55"}],"contentSignature":"9a63fd68c5f7c2a9ef5bfb734f329db4d5650d0cb1c316391dd10ec5aa8c875c","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-152","sourceNumber":152,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Irredeemable (perpetual) debentures are:","options":["Payable only after one hundred years","Redeemable only by conversion into shares","Prohibited, like irredeemable preference shares, under the Companies Act, 2013","Permitted - there is no maximum period for redemption of debentures as such"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Unlike preference shares (max 20/30 years under s.55), debentures may be issued without a fixed redemption date, subject to Rule 18 for secured issues.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Irredeemable (perpetual) debentures are:","options":["Payable only after 100 years","Redeemable only by conversion","Prohibited in India like irredeemable preference shares","Permitted - there is no maximum period for redemption of debentures as such"],"answer":3,"explanation":"Unlike preference shares (max 20/30 years under s.55), debentures may be issued without a fixed redemption date, subject to Rule 18 for secured issues. [Original]","revision":"original","contentSignature":"c93fa78cb490e1fbfc334afd00fa3acf25420a31bbb311232302ee9f0a20ffea"}],"contentSignature":"95e26bbddcb7694c140606dd7c018ad674462ca6bd8676f580c09b72b1734a42","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-153","sourceNumber":153,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A debenture redemption reserve (DRR) for an unlisted company (other than exempted classes) is created at:","options":["10% of the value of the outstanding debentures","50% of the value of the outstanding debentures","25% of the paid-up capital of the company","100% of the value of the outstanding debentures"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Rule 18(7): companies other than exempt classes (listed companies, NBFCs, HFCs, FIs) create DRR equal to 10% of outstanding debentures.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A debenture redemption reserve (DRR) for an unlisted company (other than exempted classes) is created at:","options":["10% of the value of the outstanding debentures","50% of the outstanding debentures","25% of paid-up capital","100% of the issue"],"answer":0,"explanation":"Rule 18(7): companies other than exempt classes (listed companies, NBFCs, HFCs, FIs) create DRR equal to 10% of outstanding debentures. [Original]","revision":"original","contentSignature":"9acb5662af5101478fd15ed02fded8559cedd4ba68e616d3ccec4def02780ca7"}],"contentSignature":"397cde8127c181a0080a3fc346752bacf6443669f821fb38b59865e5ee9b4226","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-154","sourceNumber":154,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Redemption of debentures can be effected by all of the following EXCEPT:","options":["Redemption by annual instalments (draw by lot)","Payment in one lump sum at maturity","Forfeiture of debentures by the company","Purchase of own debentures in the open market and cancellation"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Debentures are redeemed by lump sum, instalments, market purchase or conversion - forfeiture is a concept that applies to shares, not debentures.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"2eac4a71cd30eb4ea835ff0d4905c6fcb1de07828dc839988876c79c0ea140ce","kind":"mcq"},{"id":"corp404-155","sourceNumber":155,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Debentures issued as COLLATERAL SECURITY for a loan mean that:","options":["The loan becomes free of interest","The directors become personally liable for the loan","On default in repaying the loan, the lender may realise the debentures, but otherwise no interest is payable on them","The debentures earn interest at double the normal rate"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Collateral debentures are secondary security: they become active only if the main loan defaults; no interest accrues while the loan is serviced.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Debentures issued as COLLATERAL SECURITY for a loan mean that:","options":["The loan becomes interest-free","Directors are personally liable","On default in repaying the loan, the lender may realise the debentures, but otherwise no interest is payable on them","The debentures earn double interest"],"answer":2,"explanation":"Collateral debentures are secondary security: they become active only if the main loan defaults; no interest accrues while the loan is serviced. [Original]","revision":"original","contentSignature":"be9e87cc70ad286ce2cdc4245db4f96fa0590fabb469a6564451ae3ae11a4b44"}],"contentSignature":"86c56abbe1c5db4f90c44d696e53c7260513d768811ae3fd31efb2a5968d12e8","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-156","sourceNumber":156,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Interest on debentures is, for the issuing company, a:","options":["A personal expense of the directors","An appropriation of the profits of the company made at the year end","An item of capital expenditure","Charge against profits (allowable expense even if there is a loss)"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Being a borrowing cost, debenture interest is charged to the statement of profit and loss irrespective of profits - unlike dividend, which is an appropriation.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest on debentures is, for the issuing company, a:","options":["Personal expense of directors","Appropriation of profits","Capital expenditure","Charge against profits (allowable expense even if there is a loss)"],"answer":3,"explanation":"Being a borrowing cost, debenture interest is charged to the statement of profit and loss irrespective of profits - unlike dividend, which is an appropriation. [Original]","revision":"original","contentSignature":"b7b1675e06fbf01f4de2e930e20e39b5c7e6d067f9d08e726375bdc8442f206f"}],"contentSignature":"c0078ebc57a94d2920d25112bafba4cbfbfdb246da3615a52461c68f3af7e4e4","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-157","sourceNumber":157,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Premium payable on REDEMPTION of debentures is:","options":["Ignored in the books of account","A loss/liability provided for at the time of issue (premium on redemption account) and payable out of profits or securities premium","An income of the debenture holders","A capital receipt of the company"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Premium on redemption is a known future loss: a liability is created at issue, and it can be met from profits or the securities premium account (s.52).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Premium payable on REDEMPTION of debentures is:","options":["Ignored in accounts","A loss/liability provided for at the time of issue (premium on redemption account) and payable out of profits or securities premium","An income for holders","A capital receipt"],"answer":1,"explanation":"Premium on redemption is a known future loss: a liability is created at issue, and it can be met from profits or the securities premium account (s.52). [Original]","revision":"original","contentSignature":"55bfe64c619d9603ca6e2fab1d83d04dfbba644f91fc0ab02f00cc1e6b9ae229"}],"contentSignature":"6eef5f0d872744adb1074485687922485c87dc8268de8996b4a03cc81b18c231","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-158","sourceNumber":158,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company issued 10,000 debentures of Rs.100 each at a discount of 5%, redeemable at a premium of 5%. Amount received on issue and the TOTAL loss on issue are respectively:","options":["Rs.10,00,000 and Rs.50,000","Rs.9,00,000 and Rs.1,50,000","Rs.10,50,000 and Nil","Rs.9,50,000 and Rs.1,00,000"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Cash received = 10,000 x 95 = Rs.9,50,000. Loss = discount 50,000 + premium on redemption 50,000 = Rs.1,00,000 (written off over the debenture period).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"ee16ee382517138248537269990701cbfe8eec8c9e038119832c051063e591e6","kind":"mcq"},{"id":"corp404-159","sourceNumber":159,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Half-yearly interest on Rs.5,00,000 of 10% debentures is:","options":["Rs.10,000","Rs.50,000","Rs.5,000","Rs.25,000"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Interest = 5,00,000 x 10% x 6/12 = Rs.25,000.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"bdaf78c1353519aa72e9cab30cf7990d0f16ea3f69056253d3cdbcf655762293","kind":"mcq"},{"id":"corp404-160","sourceNumber":160,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Discount on issue of debentures is a:","options":["A reserve of the company","FICTITIOUS asset - written off over the life of the debentures","A real asset of the company","A current liability of the company till redemption of the debentures"],"answer":1,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"It is a notional loss with no realisable value, amortised to the statement of profit and loss over the debenture period. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Discount on issue of debentures is a:","options":["Reserve","FICTITIOUS asset - written off over the life of the debentures","Real asset","Current liability"],"answer":1,"explanation":"It is a notional loss with no realisable value, amortised to the statement of profit and loss over the debenture period. [Recall 2018]","revision":"original","contentSignature":"0829872efd956cd86db128ef9ce27e7a3510f9061b72e1ffadffeb50ba10f3d1"}],"contentSignature":"dc84f67e65aee21b73cadd17f583ec7c5959006d62a47135ee7f1b45b3b72ffc","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-161","sourceNumber":161,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"When a company purchases its own debentures in the open market at Rs.94 (face Rs.100) and cancels them, the difference of Rs.6 per debenture is:","options":["A revenue income of the company","A loss on cancellation, debited to the capital reserve account of the company","Ignored in the books of account","A profit on cancellation, credited to capital reserve (capital profit)"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Buying back debt below face value is a capital profit, credited to capital reserve on cancellation.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"When a company purchases its own debentures in the open market at Rs.94 (face Rs.100) and cancels them, the difference of Rs.6 per debenture is:","options":["Revenue income","A loss, debited to capital reserve","Ignored","A profit on cancellation, credited to capital reserve (capital profit)"],"answer":3,"explanation":"Buying back debt below face value is a capital profit, credited to capital reserve on cancellation. [Original] C4. Underwriting of Shares Covers: meaning and purpose of underwriting; commission limits (5% shares / 2.5% debentures, s.40(6)); commission vs brokerage; firm underwriting; marked and unmarked applications; net-liability computation with numericals. Double-verified against the Companies Act, 2013 and standard underwriting practice.","revision":"original","contentSignature":"9b48fb7e17d679d7bcc46aab1b150b4bc604b6e7502927c54d3fb689e9d3e38d"}],"contentSignature":"c66201a757b5b9b60d70d2a8377e74110cfb76e2694102376e971657111024ad","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-162","sourceNumber":162,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Underwriting is an agreement by which a person (the underwriter) undertakes that:","options":["He will guarantee the payment of dividends","If the public does not subscribe for the shares offered, he will himself take up the unsubscribed shares, for a commission","He will audit the accounts of the issue","He will print the prospectus of the issue"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Underwriting is insurance for the issue: the underwriter takes the unsubscribed portion and earns commission for bearing the risk.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Underwriting is an agreement by which a person (the underwriter) undertakes that:","options":["He will guarantee dividends","If the public does not subscribe for the shares offered, he will himself take up the unsubscribed shares, for a commission","He will audit the issue","He will print the prospectus"],"answer":1,"explanation":"Underwriting is insurance for the issue: the underwriter takes the unsubscribed portion and earns commission for bearing the risk. [Original]","revision":"original","contentSignature":"f78fdd0c0f2e326cb4f7ffe7ff12e79736fb3f17a23d7c57f6667cd85b01e231"}],"contentSignature":"e320797c88c0d7ec17969d0aa482cd2c84b1efa8db6e9e4def0a9974f603a442","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-163","sourceNumber":163,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The maximum UNDERWRITING COMMISSION payable on shares, as per Section 40(6) and the model articles, is:","options":["5% of the issue price of the shares (or the rate in the articles, whichever is LESS)","Any amount agreed between the parties, with no ceiling laid down by the Companies Act or the articles","2.5% of the issue price of the shares","10% of the issue price of the shares"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 40(6) caps commission at the article-authorised rate, not exceeding 5% of the issue price of shares and 2.5% for debentures.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The maximum UNDERWRITING COMMISSION payable on shares, as per Section 40(6) and the model articles, is:","options":["5% of the issue price of the shares (or the rate in the articles, whichever is LESS)","Any amount agreed","2.5% of the issue price","10% of the issue price"],"answer":0,"explanation":"Section 40(6) caps commission at the article-authorised rate, not exceeding 5% of the issue price of shares and 2.5% for debentures. [Original]","revision":"original","contentSignature":"af2987bae201620307cf8cd86cd57be9b518d89fb78ab692dd9311faff689ec9"}],"contentSignature":"bab7ba590cedff5c22463565847d243b8e5604d72373d83e3ac32c44eb831c92","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-164","sourceNumber":164,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Underwriting commission differs from BROKERAGE in that brokerage is paid:","options":["To the auditor of the company","To a broker for PROCURING subscriptions - only on shares actually subscribed through him","For agreeing to bear the risk of the issue, whether or not any shares are subscribed through him at all","For forfeiting the shares of defaulters"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Commission rewards risk-bearing (payable even if the public takes all shares); brokerage rewards placing - paid only on subscriptions procured.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Underwriting commission differs from BROKERAGE in that brokerage is paid:","options":["To the auditor","To a broker for PROCURING subscriptions - only on shares actually subscribed through him","For agreeing to take risk","For forfeiting shares"],"answer":1,"explanation":"Commission rewards risk-bearing (payable even if the public takes all shares); brokerage rewards placing - paid only on subscriptions procured. [Original]","revision":"original","contentSignature":"58c55c9abab285fed33c1297698e518c5dbf6dde76f52bcf55080d2f44ee1e01"}],"contentSignature":"57bbe03e50ddd4f0dd4a2bcb6946c5f099b7b5724af1dc0429c9a07089b3c7b4","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-165","sourceNumber":165,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"\"Firm underwriting\" means the underwriter agrees to take:","options":["Only the preference shares of the issue","A definite number of shares IN ADDITION to (or irrespective of) his net liability under the agreement","No shares under the agreement at all","Only the balance of shares left unsubscribed"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Under firm underwriting the agreed number must be taken whatever the public response - it is over and above the ordinary net liability.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"\"Firm underwriting\" means the underwriter agrees to take:","options":["Only preference shares","A definite number of shares IN ADDITION to (or irrespective of) his net liability under the agreement","No shares at all","Only the unsubscribed balance"],"answer":1,"explanation":"Under firm underwriting the agreed number must be taken whatever the public response - it is over and above the ordinary net liability. [Original]","revision":"original","contentSignature":"ed123423cd3460addcc32b646145b8b27f6d747d863817f699cae2abb44375bb"}],"contentSignature":"e70b5f9ae9e35872d4d07e8c216c2f082a2446ab2f64a6b37fdf991aa5bcfe14","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-166","sourceNumber":166,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Marked applications are those which:","options":["Are rejected by the company","Are forged applications","Bear the stamp/name of a particular underwriter, so the benefit goes to that underwriter","Come from the directors of the company and their relatives who wish to apply for the shares themselves"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Marked forms identify the underwriter who procured them; unmarked forms are credited to underwriters in their gross-liability ratio (unless the agreement says otherwise).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Marked applications are those which:","options":["Are rejected by the company","Are forged","Bear the stamp/name of a particular underwriter, so the benefit goes to that underwriter","Come from directors"],"answer":2,"explanation":"Marked forms identify the underwriter who procured them; unmarked forms are credited to underwriters in their gross-liability ratio (unless the agreement says otherwise). [Original]","revision":"original","contentSignature":"158a283b90bb00e3e5e7f96fbb995531ceae36991c7191855117fda4fa5f1dac"}],"contentSignature":"2fea7188c14c931a849fad8a52de899d0a2f05263d20d18760599b81efe02e11","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-167","sourceNumber":167,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company issues 1,00,000 shares, fully underwritten by a single underwriter. Total applications received are 80,000. The underwriter must take up:","options":["80,000 shares","Nil","20,000 shares","1,00,000 shares"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"Net liability = gross liability 1,00,000 - applications 80,000 = 20,000 shares. [Recall 2021]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"bb35e0fb4ceca1bcd3e6d1b00f08b018e79c6079725369d89d9dd37ca66aefbb","kind":"mcq"},{"id":"corp404-168","sourceNumber":168,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"X underwrites 60,000 of the 1,00,000 shares issued. Marked applications through X are 30,000 and unmarked applications are 20,000, credited in the gross-liability ratio. Net liability of X is:","options":["10,000","18,000","12,000","30,000"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Net liability = 60,000 - 30,000 marked - (20,000 x 60/100 = 12,000 unmarked) = 18,000 shares.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"2fe2ece290e04aa2117eafaebc2592799e1101adbb01e682082e1f17fc913a31","kind":"mcq"},{"id":"corp404-169","sourceNumber":169,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Underwriting commission is calculated on:","options":["The applications bearing his mark alone","Only the shares actually taken up by him","The face value of the shares underwritten","The issue price of the WHOLE amount underwritten, whether or not the underwriter has to take any shares"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Commission compensates the risk assumed on the entire underwritten amount, not merely the devolved shares.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Underwriting commission is calculated on:","options":["The applications marked","Only the shares actually taken up by the underwriter","The face value only","The issue price of the WHOLE amount underwritten, whether or not the underwriter has to take any shares"],"answer":3,"explanation":"Commission compensates the risk assumed on the entire underwritten amount, not merely the devolved shares.","revision":"original","contentSignature":"8e934573a7cc636d509559420d7747a112627abee138c012aa08a3341d4b2c1d"}],"contentSignature":"4b9d7460172b315e94d8a79d2de2457c8b6dcb3afdacd85c60535aab4f31ffb2","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-170","sourceNumber":170,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Sub-underwriters are:","options":["Shareholders holding small numbers of shares in the company itself","Employees of the issuing company","Persons engaged by the MAIN underwriter to share his risk and work","Nominees of the Central Government"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Main underwriters spread their risk through sub-underwriting agreements with brokers/institutions.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Debentures & underwriting","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Sub-underwriters are:","options":["Small shareholders","Employees of the company","Persons engaged by the MAIN underwriter to share his risk and work","Government nominees"],"answer":2,"explanation":"Main underwriters spread their risk through sub-underwriting agreements with brokers/institutions. [Original] C5. Company Final Accounts, Dividends & Managerial Remuneration Covers: Schedule III formats and true-and-fair requirements; CFS duty; financial year, AGM timelines, AOC-4/MGT-7 filings, 8-year record retention; dividends - sources, depreciation-first rule, final vs interim, 30-day payment, unpaid dividend account and 7-year IEPF transfer; managerial remuneration caps (s.197-198) and CSR triggers/spend (s.135) - with numericals. Double-verified against the Companies Act, 2013 as amended.","revision":"original","contentSignature":"a71c9bc080e0b35851bb9bf002aa0051626c39e891de8c93695b39ece0e721c5"}],"contentSignature":"bc2583d5244f4fca88eb61e398bb1f6a2fb185baaf36e566ed088ffe8a1edb13","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-171","sourceNumber":171,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The form and contents of the balance sheet and statement of profit and loss of a company are prescribed by:","options":["SEBI alone","Schedule III of the Companies Act, 2013 (Division I for non-Ind AS and Division II for Ind AS companies)","The Indian Partnership Act, 1932","Schedule VI of the Companies Act, 1956"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Schedule III gives the vertical formats; Division I applies to companies following Accounting Standards, Division II to Ind AS companies.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The form and contents of the balance sheet and statement of profit and loss of a company are prescribed by:","options":["SEBI alone","Schedule III of the Companies Act, 2013 (Division I for non-Ind AS and Division II for Ind AS companies)","The Partnership Act","Schedule VI of the Companies Act, 1956"],"answer":1,"explanation":"Schedule III gives the vertical formats; Division I applies to companies following Accounting Standards, Division II to Ind AS companies. [Original]","revision":"original","contentSignature":"273e84bf5bf8841cc9816102122e03622fd72942353f3a167412645e26c5eaae"}],"contentSignature":"9dfc05a959db631f5c2e6f6f6f23761e07d949cfd49cd2232f5636f23e6e1a4a","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-172","sourceNumber":172,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under Section 129, the financial statements must give a true and fair view and comply with:","options":["The income-tax rules in force","The accounting standards notified under Section 133","The wishes of the board of directors","The bye-laws of the stock exchanges alone in the country"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 129 + 133: financial statements must present a true and fair view and follow notified Accounting Standards/Ind AS.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under Section 129, the financial statements must give a true and fair view and comply with:","options":["Income-tax rules","The accounting standards notified under Section 133","The wishes of the directors","Stock-exchange bye-laws only"],"answer":1,"explanation":"Section 129 + 133: financial statements must present a true and fair view and follow notified Accounting Standards/Ind AS. [Original]","revision":"original","contentSignature":"4e87a20883b1b64161379e1d7b34e836da5bd830bee742b3a83506b6bb6321cb"}],"contentSignature":"e29a6440e9cee8c73b3f36490535bbc3054ad1a44d2885b08ed9e108a0502716","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-173","sourceNumber":173,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company having subsidiaries must, in addition to its own statements, prepare:","options":["Only a cash budget for the coming year","CONSOLIDATED financial statements of itself and all subsidiaries, laid before the AGM along with its own","No statements of any kind","Only the statements of the subsidiary companies"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 129(3): CFS covering the company and all subsidiaries/associates/joint ventures are mandatory at the AGM.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A company having subsidiaries must, in addition to its own statements, prepare:","options":["Only a cash budget","CONSOLIDATED financial statements of itself and all subsidiaries, laid before the AGM along with its own","No statements at all","Only the subsidiary statements"],"answer":1,"explanation":"Section 129(3): CFS covering the company and all subsidiaries/associates/joint ventures are mandatory at the AGM. [Original]","revision":"original","contentSignature":"3af8b8067c4cca955944affddc48aea32bcdc152ebd06ad3032174b50c7c8841"}],"contentSignature":"ae7a36578b72b988f97d336f8cfcd2843de40da15f00830bc5ae6ffbcebed2df","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-174","sourceNumber":174,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The financial year of an Indian company, as per Section 2(41), ends on:","options":["Any date chosen by directors","31st March (calendar April-March)","31st December","30th June"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 2(41): the uniform financial year is 1 April to 31 March; NCLT approval is needed for a different year (e.g. to align with a foreign holding company).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e800f199500f23e352568a2cb62c62ee22ce082b01d58b287aac45f752f7625e","kind":"mcq"},{"id":"corp404-175","sourceNumber":175,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Books of account of a company must be preserved, under Section 128(5), for at least:","options":["3 financial years","8 financial years immediately preceding the relevant year","20 financial years from the end of the relevant financial year concerned","1 financial year"],"answer":1,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"Section 128(5): books and vouchers are kept for not less than eight financial years. [Recall 2021]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Books of account of a company must be preserved, under Section 128(5), for at least:","options":["3 years","8 financial years immediately preceding the relevant year","20 years","1 year"],"answer":1,"explanation":"Section 128(5): books and vouchers are kept for not less than eight financial years. [Recall 2021]","revision":"original","contentSignature":"096219a0e2424c5cdb8c428c4bb336ace092b13b64817f97549c46fd5e0d7898"}],"contentSignature":"ee322b9191fdbb20544f45f2f48c4bf80102a893fb65fe8664123a7bf90bc0b4","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-176","sourceNumber":176,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The first Annual General Meeting of a company must be held within ________ of the close of its first financial year; later AGMs within ________ of each financial year-end, with a gap not exceeding 15 months.","options":["12 months; 3 months","9 months; 6 months","9 months; 9 months","6 months; 6 months"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 96: first AGM within 9 months of the first FY-end; subsequent AGMs within 6 months of the FY-end, maximum gap 15 months.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"1e22a0364bff9c6976731d69e982f76b7870188495e16d7e0b1ea4b7881772f9","kind":"mcq"},{"id":"corp404-177","sourceNumber":177,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The financial statements, after adoption at the AGM, are filed with the Registrar in Form AOC-4 within:","options":["15 days of the AGM","6 months of the AGM","90 days of the AGM","30 days of the AGM"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 137: AOC-4 with financial statements and attachments is filed within 30 days of the AGM.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"16ed164278cba6e59758ee8da4a1c41ad1d02a05a73838d12ac4e88172e41c47","kind":"mcq"},{"id":"corp404-178","sourceNumber":178,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The annual return of a company is filed in Form:","options":["PAS-3","SH-9","AOC-4","MGT-7"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 92: the annual return goes in Form MGT-7 within 60 days of the AGM.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"17f4c99e7842baf5011ece5fbc8a1a4e9430ae2c3b5b92d3cdc3d323edf33fe2","kind":"mcq"},{"id":"corp404-179","sourceNumber":179,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The Board report under Section 134 must be attached to every balance sheet laid before the AGM and includes, among other things:","options":["The daily cash balances of the company","The personal details of all the employees","State of company affairs, dividend recommended, reserves transfers, material changes, directors responsibility statement and CSR details","The working papers of the auditors"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 134 lists the Board report contents, including the Directors Responsibility Statement and, where applicable, CSR reporting.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The Board report under Section 134 must be attached to every balance sheet laid before the AGM and includes, among other things:","options":["Daily cash balances","The personal details of all employees","State of company affairs, dividend recommended, reserves transfers, material changes, directors responsibility statement and CSR details","The auditor working papers"],"answer":2,"explanation":"Section 134 lists the Board report contents, including the Directors Responsibility Statement and, where applicable, CSR reporting. [Original]","revision":"original","contentSignature":"2c70469d9c4c38866dae4c57dc532820c444824ad8946b098e145fbbc8ee3562"}],"contentSignature":"c2535b61e5c469a34d37102949af8950af627203e72d0000bb3893f0b06834f6","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-180","sourceNumber":180,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under Section 123, dividend can be declared only out of:","options":["Profits of the current year (after providing depreciation), undistributed past profits, or money provided by Government for dividend","Capital receipts of the company","The sale proceeds of fixed assets","Calls received in advance from shareholders"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 123(1): dividend needs profits - current or accumulated (after depreciation per Schedule II) - or Central/State Government money provided for the purpose.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under Section 123, dividend can be declared only out of:","options":["Profits of the current year (after providing depreciation), undistributed past profits, or money provided by Government for dividend","Capital receipts","Sale proceeds of fixed assets","Calls in advance"],"answer":0,"explanation":"Section 123(1): dividend needs profits - current or accumulated (after depreciation per Schedule II) - or Central/State Government money provided for the purpose. [Original]","revision":"original","contentSignature":"259487c204310b3680347b5ff0ef5a453a69d024ff931017d5ff75da9668ee28"}],"contentSignature":"8ef0674d2734e4d02778a2dafb05bd4931ba9017a3493c23ba67660c592f03aa","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-181","sourceNumber":181,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Before declaring any dividend, a company must provide for:","options":["The audit fees of the following year as well","An issue of bonus shares","DEPRECIATION in accordance with Schedule II","The sitting fees of the directors"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Depreciation as per Schedule II (useful-life basis) is a mandatory charge before profits are available for dividend.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Before declaring any dividend, a company must provide for:","options":["Audit fees of next year","Bonus shares","DEPRECIATION in accordance with Schedule II","Directors sitting fees"],"answer":2,"explanation":"Depreciation as per Schedule II (useful-life basis) is a mandatory charge before profits are available for dividend. [Original]","revision":"original","contentSignature":"c9d0521b183d230a92624425e22b3bb550cc00882fb0a20a24a3ac38ec1a043f"}],"contentSignature":"de7b92a7c4b4e4ce851c08c34b53a50485da6962a1fc5247666bcfd214d28056","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-182","sourceNumber":182,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The FINAL dividend is:","options":["Paid without any meeting being held","Declared by the auditors of the company","Recommended by the Board and declared by the shareholders at the AGM, who cannot exceed the Board recommendation","Declared by the Board of directors alone"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"The Board proposes; the AGM declares. Members may reduce but cannot increase the recommended rate.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The FINAL dividend is:","options":["Paid without any meeting","Declared by the auditors","Recommended by the Board and declared by the shareholders at the AGM, who cannot exceed the Board recommendation","Declared by the Board alone"],"answer":2,"explanation":"The Board proposes; the AGM declares. Members may reduce but cannot increase the recommended rate.","revision":"original","contentSignature":"17a1c687bc8428f5f08ca7092eeb97ba8c80775d7e7307471c73da3169739098"}],"contentSignature":"996530ae0cc5fadd179f32ad514961742398eb926302f74b9bbbc66d54b6b49d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-183","sourceNumber":183,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"An INTERIM dividend under Section 123(3) is declared by:","options":["The Registrar of Companies","The BOARD OF DIRECTORS between two AGMs, out of surplus/profits","The shareholders at the annual general meeting by an ordinary resolution","The stock exchange where the shares are listed"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"The Board may declare interim dividend during a financial year out of surplus in the P&L account and current-year profits.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An INTERIM dividend under Section 123(3) is declared by:","options":["The Registrar","The BOARD OF DIRECTORS between two AGMs, out of surplus/profits","The shareholders at the AGM","The stock exchange"],"answer":1,"explanation":"The Board may declare interim dividend during a financial year out of surplus in the P&L account and current-year profits. [Original]","revision":"original","contentSignature":"b133c0dc0aef3113366ac79399e41c78fe1ae259cc12338a3b13b42d74fcbed0"}],"contentSignature":"97434b7a42561b81ae9b104330600590fe16da879b10fa78f52a7994c64ff8af","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-184","sourceNumber":184,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Dividend once declared must be paid within ________ of declaration, failing which defaulting directors face punishment under Section 127.","options":["One year","7 days","30 days","90 days"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 127: warrant posted/payment made within 30 days; default attracts imprisonment up to 2 years and interest at 18% p.a. for the company.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"56b4bef995981b8242f3a38bc917b8ee1dc0164d13748f98280e05d539365591","kind":"mcq"},{"id":"corp404-185","sourceNumber":185,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Dividend remaining unpaid or unclaimed within 30 days of declaration must be transferred to:","options":["The Unpaid Dividend Account in a scheduled bank within 7 days of the expiry of the 30-day period","The profit and loss account of the company and added back to the profits available for future dividends","The capital redemption reserve account","The general reserve of the company"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 124(1): the company opens a separate Unpaid Dividend Account and deposits the unpaid amount within 7 days after the 30-day window.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Dividend remaining unpaid or unclaimed within 30 days of declaration must be transferred to:","options":["The Unpaid Dividend Account in a scheduled bank within 7 days of the expiry of the 30-day period","The profit and loss account","The capital redemption reserve","General reserve"],"answer":0,"explanation":"Section 124(1): the company opens a separate Unpaid Dividend Account and deposits the unpaid amount within 7 days after the 30-day window. [Original]","revision":"original","contentSignature":"b0efd4a962c90a8ad4c5c7484ec791ce32c5512898ed7e489bf6158904e3e3e7"}],"contentSignature":"c884601e741179af56dd127ce363c8fe962db9cdce431fa3e444688b4aa6f06f","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-186","sourceNumber":186,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Amounts lying unclaimed in the Unpaid Dividend Account for ________ are transferred to the Investor Education and Protection Fund (IEPF), along with the related shares.","options":["3 years","10 years","1 year","7 years"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 124(5)-(6): seven years unclaimed means transfer to IEPF; the corresponding shares also move to the IEPF Authority.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"9cd6b83ab1687112413343db83e566462f87a11272f8d50b940e99e182babedf","kind":"mcq"},{"id":"corp404-187","sourceNumber":187,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A proposed dividend (recommended by the Board but not yet declared) is:","options":["Deducted from the share capital of the company","Recorded as a current liability as soon as it is recommended","NOT a liability until declared by shareholders - it is only disclosed (AS-4: no provision for dividends proposed after the balance sheet date)","Paid to the preference shareholders alone"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Final dividend becomes an obligation only on AGM declaration; proposals are disclosed in notes, not provided for.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A proposed dividend (recommended by the Board but not yet declared) is:","options":["Deducted from capital","Recorded as a current liability when recommended","NOT a liability until declared by shareholders - it is only disclosed (AS-4: no provision for dividends proposed after the balance sheet date)","Paid to preference holders only"],"answer":2,"explanation":"Final dividend becomes an obligation only on AGM declaration; proposals are disclosed in notes, not provided for. [Original]","revision":"original","contentSignature":"9aecb286b3de975010d40eafd83be92c9bc228a1c3248a7b7f9f71bc4c254812"}],"contentSignature":"161f355052f7605f6ac5950a59524a8b951e4b1242abe0b92bdbe7b9340acf79","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-188","sourceNumber":188,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company has 10,000 equity shares of Rs.10 each on which Rs.7 per share is paid up. Its articles permit dividend on paid-up amounts (s.51). A 20% dividend works out to:","options":["Rs.10,000","Rs.7,000","Rs.20,000","Rs.14,000"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Dividend = 20% of paid-up 70,000 = Rs.14,000 (nominal value is irrelevant where s.51 applies).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"45c671b424a83ccb763c5ea15487b2d48be8588afdcd4f24ccd4741891f20a20","kind":"mcq"},{"id":"corp404-189","sourceNumber":189,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Dividend can be paid in the form of:","options":["Goods manufactured by the company","Cash (including cheque/warrant/electronic mode) - or fully paid bonus shares as a share dividend","Promissory notes signed by the directors of the company in favour of each shareholder entitled to the dividend","Services rendered by the company"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Dividend is payable in cash; distribution as fully paid bonus shares is the permitted non-cash route - never out of capital.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Dividend can be paid in the form of:","options":["Goods of the company","Cash (including cheque/warrant/electronic mode) - or fully paid bonus shares as a share dividend","Promissory notes of directors","Services"],"answer":1,"explanation":"Dividend is payable in cash; distribution as fully paid bonus shares is the permitted non-cash route - never out of capital. [Original]","revision":"original","contentSignature":"bd107f40515232a01b88f006e19c25f12b080272af156b44e7983687f37a2e3d"}],"contentSignature":"37cde8888ddd5551ca01174045c526256a42dc24a46b0f4ce22cee8bf402ffba","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-190","sourceNumber":190,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Capital profits (e.g. profit on sale of a fixed asset) can be distributed as dividend only if:","options":["The auditor objects to the distribution","They are REALISED in cash, the articles permit, and a surplus remains after revaluation of all assets","They can never be distributed","They exceed one crore rupees"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Realised capital profits may be distributed where articles authorise and the company remains solvent with no overall capital loss.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Capital profits (e.g. profit on sale of a fixed asset) can be distributed as dividend only if:","options":["The auditor objects","They are REALISED in cash, the articles permit, and a surplus remains after revaluation of all assets","Never, in any case","They exceed Rs.1 crore"],"answer":1,"explanation":"Realised capital profits may be distributed where articles authorise and the company remains solvent with no overall capital loss. [Original]","revision":"original","contentSignature":"26c747a2e07e2d83148d10f30e631274dd6fdb16499ecf435824cf13142a186b"}],"contentSignature":"a741db833d79c03453515cd007ea7b5eb9c20093dd47ce0ee4f6be95a6099d3a","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-191","sourceNumber":191,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The OVERALL maximum managerial remuneration payable by a public company to its directors (including MD, WTD and manager) in a financial year, as per Section 197, is:","options":["25% of the turnover of the company for the year","5% of the net profits of that year","A flat sum of Rs.50 lakh","11% of the net profits of that financial year"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 197(1): total managerial remuneration cannot exceed 11% of net profits computed under Section 198 (higher with Central Government approval).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The OVERALL maximum managerial remuneration payable by a public company to its directors (including MD, WTD and manager) in a financial year, as per Section 197, is:","options":["25% of turnover","5% of net profits","Rs.50 lakh flat","11% of the net profits of that financial year"],"answer":3,"explanation":"Section 197(1): total managerial remuneration cannot exceed 11% of net profits computed under Section 198 (higher with Central Government approval). [Original]","revision":"original","contentSignature":"be4989cf4a48482ef572a362ce7447cf4a02768baee5a82909a61b25e08adf46"}],"contentSignature":"d110298d715be1568c102b721577b1467de0067ff65a4ff72ce80c973c184b2d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-192","sourceNumber":192,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"If a public company has a managing director, the maximum remuneration payable to ALL OTHER directors (who are neither MD nor WTD) is:","options":["1% of net profits (3% with a special resolution)","10% of the net profits of the company for the year","5% of the net profits","11% of the net profits"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 197(1)(ii): non-MD/WTD directors share 1% (or 3% on special resolution) where there is an MD/WTD/manager.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"If a public company has a managing director, the maximum remuneration payable to ALL OTHER directors (who are neither MD nor WTD) is:","options":["1% of net profits (3% with a special resolution)","10% of net profits","5% of net profits","11%"],"answer":0,"explanation":"Section 197(1)(ii): non-MD/WTD directors share 1% (or 3% on special resolution) where there is an MD/WTD/manager. [Original]","revision":"original","contentSignature":"906d5aec2603254faa11862892220428463e31e98111717aee09ff7555c0df41"}],"contentSignature":"6a31d139b84cb32b6732a635446695034673d1bc73c5f6f820f7633bbba7d7d1","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-193","sourceNumber":193,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A public company earned net profits of Rs.2 crore (computed under s.198). The maximum total managerial remuneration permissible without government approval is:","options":["Rs.1 crore","Rs.22 lakh","Rs.2 lakh","Rs.10 lakh"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"11% of Rs.2,00,00,000 = Rs.22,00,000.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"604fff4313cc0bac525dc64e4f562e934403e88fe1ac9d60955e8d0ec19b7b0d","kind":"mcq"},{"id":"corp404-194","sourceNumber":194,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Net profit for the purpose of managerial remuneration is calculated as per:","options":["The norms prescribed by SEBI","The Income-tax Act, 1961","Schedule III to the Companies Act, 2013","Section 198 of the Companies Act, 2013"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 198 prescribes the computation - with specified additions and exclusions (e.g. capital profits excluded, usual working charges deducted).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Net profit for the purpose of managerial remuneration is calculated as per:","options":["SEBI norms","The Income-tax Act","Schedule III","Section 198 of the Companies Act, 2013"],"answer":3,"explanation":"Section 198 prescribes the computation - with specified additions and exclusions (e.g. capital profits excluded, usual working charges deducted). [Original]","revision":"original","contentSignature":"94749f4dfa899e10205498eb401000a28fb7b17c903b23bb607bcf56e8279adb"}],"contentSignature":"fc37fd12b77adbbb4abf1320f414c1010b23ebaeb4c6d176b827ec4f639b8d4c","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-195","sourceNumber":195,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The CSR obligation under Section 135 applies to a company having, in any financial year: net worth of ________, turnover of ________, or net profit of ________ or more.","options":["Rs.1,000 crore; Rs.5,000 crore; Rs.10 crore","Rs.100 crore; Rs.500 crore; Rs.1 crore","Rs.50 crore; Rs.100 crore; Rs.50 lakh","Rs.500 crore; Rs.1,000 crore; Rs.5 crore"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 135(1): net worth Rs.500 crore+, turnover Rs.1,000 crore+, or net profit Rs.5 crore+ triggers the CSR committee and spending duty.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"1e3fc6aee165b97f8f3b4bf70f417fb84ffecb8ad8a11aee8ecfaf4f885e0ea5","kind":"mcq"},{"id":"corp404-196","sourceNumber":196,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company covered by Section 135 must spend on CSR, every financial year, at least:","options":["10% of the turnover of the company for the immediately preceding financial year, computed as per the books","5% of the net profit of the year","2% of the AVERAGE NET PROFITS of the three immediately preceding financial years","A flat sum of Rs.10 lakh"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 135(5): at least 2% of average net profits of the preceding three years, with Board disclosure of the policy and spends.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Financial statements, dividends & managerial remuneration","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A company covered by Section 135 must spend on CSR, every financial year, at least:","options":["10% of turnover","5% of its net profit","2% of the AVERAGE NET PROFITS of the three immediately preceding financial years","Rs.10 lakh"],"answer":2,"explanation":"Section 135(5): at least 2% of average net profits of the preceding three years, with Board disclosure of the policy and spends. [Original] C6. Amalgamation, Absorption & External Reconstruction Covers: forms of combination; AS-14 merger vs purchase and the five merger conditions (incl. the 90% test); pooling vs purchase accounting; purchase consideration, net assets, goodwill and capital reserve; amalgamation adjustment for statutory reserves; horizontal/vertical/conglomerate/reverse mergers, synergy and swap ratios; transferor and transferee entries - with numericals. Double-verified against AS-14 and standard advanced-accounts practice.","revision":"original","contentSignature":"903c1c18e84b74d063d747a8f38057a61a767afd00e2deae3c1cc5d3dcf68cf9"}],"contentSignature":"cdd257cbba6ed5214981c9c8aaad4db1d77f7f43e7800630a9b45d821cf2a0dd","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-197","sourceNumber":197,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Amalgamation means:","options":["One company purchasing the shares of another company from the open market over a period of time","Selling all the assets of the company for cash","Two or more companies combining to form a NEW company, or one merging into another","The issue of bonus shares to the members"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"In amalgamation two or more companies unite - either forming a new company (A + B = C) or one absorbing the other (A + B = A).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Amalgamation means:","options":["One company purchasing shares of another","Selling all assets for cash","Two or more companies combining to form a NEW company, or one merging into another","Issuing bonus shares"],"answer":2,"explanation":"In amalgamation two or more companies unite - either forming a new company (A + B = C) or one absorbing the other (A + B = A). [Original]","revision":"original","contentSignature":"f032d0cd78ebfe3d5cb4663dffff4e2f3f0d09d686c711d15f2e738714d31bfa"}],"contentSignature":"2f8480a7ba823ef139d67a2772fe9e6de8f1fe0d2ec54dbe5f0007e5fef1283b","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-198","sourceNumber":198,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Absorption differs from amalgamation in that in absorption:","options":["A new company is always formed as a result","Both the combining companies continue to survive","Only the assets of the company are sold off","An EXISTING company takes over the business of another company, which is then dissolved - no new company is formed"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Absorption = existing transferee swallows the transferor; amalgamation in the strict sense forms a new company. Both fall under AS-14.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Absorption differs from amalgamation in that in absorption:","options":["A new company is always formed","Both companies survive","Only assets are sold","An EXISTING company takes over the business of another company, which is then dissolved - no new company is formed"],"answer":3,"explanation":"Absorption = existing transferee swallows the transferor; amalgamation in the strict sense forms a new company. Both fall under AS-14. [Original]","revision":"original","contentSignature":"dccbf75fe6d1960b494f0629deec4f90444bff9e1d095eba0b5f4db7f601dda6"}],"contentSignature":"f67aac6ddb37aab2e001d0e5acfabd9dd59ff0a6e140918e6fd11ee4f4b0663b","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-199","sourceNumber":199,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"External reconstruction means:","options":["Reducing the share capital without winding up the company","Converting the debentures of the company into shares","Merging the company with a foreign company","An existing company is wound up and a NEW company is formed to take over the SAME business, with substantially the same shareholders"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"External reconstruction liquidates the old company and reincarnates its business in a new one (e.g. A Ltd -> New A Ltd); internal reconstruction (s.61-66) avoids liquidation.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"External reconstruction means:","options":["Reducing share capital without winding up","Converting debentures into shares","Merging with a foreign company","An existing company is wound up and a NEW company is formed to take over the SAME business, with substantially the same shareholders"],"answer":3,"explanation":"External reconstruction liquidates the old company and reincarnates its business in a new one (e.g. A Ltd -> New A Ltd); internal reconstruction (s.61-66) avoids liquidation. [Original]","revision":"original","contentSignature":"0c4969f83b23ddfceba7268e5bb66039f50415fa44c518265b117e1cbdaf2b3b"}],"contentSignature":"94323e6f9cfb7437da8fcb25d0aae1e9fe1a87aa7b3bc624ee46fcaba4e8f377","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-200","sourceNumber":200,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"AS-14 (Accounting for Amalgamations) prescribes TWO methods of accounting:","options":["Merger method and absorption method","Cost method and equity method","Pooling of interests method and purchase method","Straight line method and written down value method"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"Pooling of interests applies to amalgamations in the nature of MERGER; the purchase method to amalgamations in the nature of PURCHASE. [Recall 2021]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"AS-14 (Accounting for Amalgamations) prescribes TWO methods of accounting:","options":["Merger method and absorption method","Cost method and equity method","Pooling of interests method and purchase method","SLM and WDV"],"answer":2,"explanation":"Pooling of interests applies to amalgamations in the nature of MERGER; the purchase method to amalgamations in the nature of PURCHASE. [Recall 2021]","revision":"original","contentSignature":"0422186fae514a0a7490f574ec5404fde5ac5a6d48edd5ebe9b94f0e8b5dadac"}],"contentSignature":"0fd0d6ab79d52c7ce3944b9e28b093b49197692ffbadde4384e9b190993a16c0","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-201","sourceNumber":201,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The pooling of interests method is used when the amalgamation is in the nature of:","options":["Merger","Absorption of a sick unit","Purchase","A hostile takeover"],"answer":0,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"If all five AS-14 conditions are met, the amalgamation is a merger and pooling applies - book values and reserve identities are preserved. [Recall 2021]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"0379bccdf36dd6063cc0b8e8ab7ad663388c672b8739ac38c1e14d49d6c1cd94","kind":"mcq"},{"id":"corp404-202","sourceNumber":202,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following is NOT one of the five AS-14 conditions for an amalgamation in the nature of merger?","options":["Equity shareholders holding at least 90% of the face value of equity shares become equity shareholders of the transferee","All assets and liabilities of the transferor become those of the transferee","The business of the transferor is intended to be carried on","Consideration is discharged wholly in CASH"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Merger consideration must be discharged wholly by issue of EQUITY SHARES (except cash for fractional shares) - a cash buyout points to purchase, not merger.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"9305e0813fa1a92adeddf767a6bb839068d7e69a4c5a0fde6fcb53efdf864b8b","kind":"mcq"},{"id":"corp404-203","sourceNumber":203,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"For merger treatment, shareholders holding not less than ________ of the face value of the EQUITY shares of the transferor (other than shares already held by the transferee or its nominees) must become equity shareholders of the transferee.","options":["90%","51%","100%","75%"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"The 90% continuity-of-ownership test ensures the merger genuinely unites the two ownership groups.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e3d0e402c23638c76fa6a9cc3159a423b46fe45171219544b25050f8c2ad545c","kind":"mcq"},{"id":"corp404-204","sourceNumber":204,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"X Ltd (transferor) has 10,000 equity shares of which Y Ltd (transferee) already holds 1,000. For an amalgamation in the nature of merger, equity shareholders holding at least how many shares of X Ltd must become shareholders of Y Ltd?","options":["10,000","7,500","8,100","9,000"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Exclude the 1,000 already held: 10,000 - 1,000 = 9,000; 90% of 9,000 = 8,100 shares must move into Y Ltd equity.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"453cfa13b74fd2686630fb05929ec0d6ecfd78b685d0c6526f34390abb42beea","kind":"mcq"},{"id":"corp404-205","sourceNumber":205,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under the pooling of interests method, the assets and liabilities of the transferor are recorded by the transferee at:","options":["Their existing BOOK values","Scrap values","Fair values","Revalued figures"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Pooling continues the books as they were: book values carry over, reserves retain their identity, and only uniform accounting policies are aligned.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"a07180302d39d7f81e8a815918f4dff766bd868c53b33f9a3023484bd2c45438","kind":"mcq"},{"id":"corp404-206","sourceNumber":206,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under the purchase method, the excess of purchase consideration over the NET ASSETS taken over is treated as:","options":["Capital reserve of the transferee company","A revenue profit of the transferee company arising from the bargain of the purchase itself","GOODWILL (amortised over its useful life, not exceeding 5 years as a prudent norm)","Share premium of the transferee company"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Paying more than net asset value buys the super-earning capacity of the business - recorded as goodwill; a shortfall is capital reserve.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the purchase method, the excess of purchase consideration over the NET ASSETS taken over is treated as:","options":["Capital reserve","Revenue profit","GOODWILL (amortised over its useful life, not exceeding 5 years as a prudent norm)","Share premium"],"answer":2,"explanation":"Paying more than net asset value buys the super-earning capacity of the business - recorded as goodwill; a shortfall is capital reserve. [Original]","revision":"original","contentSignature":"89d4350bc147a7f8b7ae28d21b2bccfcf672d4b3df633a591085f38936c85b23"}],"contentSignature":"3b1f8c91b872a9948925e1698f38739f5c7f7b1f4fb3aa12b25175bd2128d121","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-207","sourceNumber":207,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under the purchase method, if purchase consideration is LESS than net assets taken over, the difference is credited to:","options":["Goodwill","General reserve","Capital reserve","Profit and loss account"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"A bargain purchase creates a capital reserve - a capital profit, not available for dividend.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"972d651206ab6657bd8ab8a32d15e60d0cdf575b54a652218618459763b71f17","kind":"mcq"},{"id":"corp404-208","sourceNumber":208,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The \"amalgamation adjustment account\" is debited when: method","options":["Goodwill arises on the amalgamation","Inter-company debts are cancelled on amalgamation","Shares are issued at a discount by the transferee","A STATUTORY RESERVE of the transferor (e.g. investment allowance reserve) is to be maintained in the transferee books under the purchase"],"answer":3,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"AS-14: statutory reserves retained for compliance are brought in by debiting amalgamation adjustment account (shown under miscellaneous expenditure/other non- current assets) and crediting the statutory reserve. [Recall 2021]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The \"amalgamation adjustment account\" is debited when: method","options":["Goodwill arises on amalgamation","Inter-company debts are cancelled","Shares are issued at a discount","A STATUTORY RESERVE of the transferor (e.g. investment allowance reserve) is to be maintained in the transferee books under the purchase"],"answer":3,"explanation":"AS-14: statutory reserves retained for compliance are brought in by debiting amalgamation adjustment account (shown under miscellaneous expenditure/other non- current assets) and crediting the statutory reserve. [Recall 2021]","revision":"original","contentSignature":"a07187de137da5c2db9361ca5793a0d9a2770bc073ee6998a85c07784c74f84c"}],"contentSignature":"b9fdce22aa1c4a1fd90cb19af8689a666eb20f3001d14ba5ac043f3eebc18888","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-209","sourceNumber":209,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Purchase consideration under AS-14 means the aggregate of:","options":["The liabilities taken over by the transferee","Shares, securities and cash paid by the transferee to the SHAREHOLDERS of the transferor company","Payments to the shareholders and the debenture holders of the transferor company in full at once","The book value of the assets taken over"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"PC counts only what the OWNERS receive; payments to debenture holders and creditors are settlements of liabilities, excluded from PC.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Purchase consideration under AS-14 means the aggregate of:","options":["Liabilities taken over","Shares, securities and cash paid by the transferee to the SHAREHOLDERS of the transferor company","Payments to shareholders AND debenture holders of the transferor","The book value of assets taken over"],"answer":1,"explanation":"PC counts only what the OWNERS receive; payments to debenture holders and creditors are settlements of liabilities, excluded from PC. [Original]","revision":"original","contentSignature":"37990d28b993331c7ff936d1bad24cb3d7d3491b28b3ecb06b0f9574b5e69208"}],"contentSignature":"fc9d38482bc4f7062bd53707b56b236f451b03d87fff715c9367c9a7676d2990","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-210","sourceNumber":210,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The \"net assets\" of the transferor for computing goodwill/capital reserve equal:","options":["Turnover of the year minus the expenses","Assets taken over (at agreed values) MINUS liabilities taken over","Share capital plus the debentures outstanding on the date of the takeover","The total assets of the transferor alone"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Net assets taken over is compared with purchase consideration to determine goodwill (PC > NA) or capital reserve (PC < NA).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The \"net assets\" of the transferor for computing goodwill/capital reserve equal:","options":["Turnover minus expenses","Assets taken over (at agreed values) MINUS liabilities taken over","Share capital plus debentures","Total assets only"],"answer":1,"explanation":"Net assets taken over is compared with purchase consideration to determine goodwill (PC > NA) or capital reserve (PC < NA). [Original]","revision":"original","contentSignature":"8d7b81c516fbeb0f27a28147eb165003213bed3a53fd51d62716ec1b761673f1"}],"contentSignature":"b7ff536ef6c84cd2d167436cf8d44ee6333bef38b5b69e168799b206be22fd83","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-211","sourceNumber":211,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A merger between two companies engaged in the SAME line of business (e.g. two cement manufacturers) is called a:","options":["HORIZONTAL merger","Vertical merger","Reverse merger","Conglomerate merger"],"answer":0,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Horizontal mergers unite competitors at the same stage - for market share and economies of scale. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"5215ef33adf1d7c1d4f9e3bfa8fa40c5e7ce402c32c65d63e3309c22b2c615b3","kind":"mcq"},{"id":"corp404-212","sourceNumber":212,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A merger between companies in totally UNRELATED businesses is called a:","options":["Vertical merger","CONGLOMERATE merger","Horizontal merger","Co-generic merger"],"answer":1,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"Conglomerate mergers diversify risk across unrelated products/markets (e.g. a textile company merging with a software firm). [Recall 2021]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"bb0bdcd8cb003a4fc4bb0b1cb97b3c7cad3f527f183fbe99d8094cf3f57fe2d4","kind":"mcq"},{"id":"corp404-213","sourceNumber":213,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A vertical merger is one between companies:","options":["Incorporated in different countries","At the same stage of the production chain","In industries unrelated to each other","At DIFFERENT STAGES of the same production chain (e.g. a manufacturer merging with its supplier or distributor)"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Vertical integration links buyer and seller stages - forward (towards customers) or backward (towards suppliers).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A vertical merger is one between companies:","options":["In different countries only","At the same stage of production","In unrelated industries","At DIFFERENT STAGES of the same production chain (e.g. a manufacturer merging with its supplier or distributor)"],"answer":3,"explanation":"Vertical integration links buyer and seller stages - forward (towards customers) or backward (towards suppliers). [Original]","revision":"original","contentSignature":"793f1bd75648bb0b88a14270c05853d455747775493ca8c88a2f6dce58b134f7"}],"contentSignature":"893035d6c84f77ebcb5d53909330567e8acc4e00d5d98e88961d043621651ee3","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-214","sourceNumber":214,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"\"Synergy\" in mergers refers to:","options":["The additional value created when the combined entity is worth MORE than the sum of the separate companies (the 2 + 2 = 5 effect)","The legal fee payable for the merger","The balance in the share premium account","The expenses of winding up a company"],"answer":0,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"Synergy is the economic rationale of mergers - cost savings, market power and complementary strengths that raise combined value. [Recall 2021]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"\"Synergy\" in mergers refers to:","options":["The additional value created when the combined entity is worth MORE than the sum of the separate companies (the 2 + 2 = 5 effect)","The legal fee for merger","The share premium account","Winding-up expenses"],"answer":0,"explanation":"Synergy is the economic rationale of mergers - cost savings, market power and complementary strengths that raise combined value. [Recall 2021]","revision":"original","contentSignature":"5ba46386cd031483af5cd864a3ff0735e056cd008d439c742d6dfb81da046901"}],"contentSignature":"f7e7bcdca8a9bcd8bf0234f17ba8c6eeca63cee4e00c342400e4a2bfd5cabdfd","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-215","sourceNumber":215,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A reverse merger means: or a private company merges into a listed shell (backdoor listing)","options":["Two companies dissolving themselves together","A company buying back its own shares","A large company taking over a small company","A merger in the UNUSUAL direction - a smaller or sick company absorbs a larger or profit-making one and survives (e.g. for tax-loss benefits),"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"In a reverse merger the smaller or weaker entity survives over the larger or stronger - used for sick-company tax losses or backdoor listing.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A reverse merger means: or a private company merges into a listed shell (backdoor listing)","options":["Two companies dissolving together","Buying back shares","A large company taking over a small one","A merger in the UNUSUAL direction - a smaller or sick company absorbs a larger or profit-making one and survives (e.g. for tax-loss benefits),"],"answer":3,"explanation":"In a reverse merger the smaller or weaker entity survives over the larger or stronger - used for sick-company tax losses or backdoor listing. [Original]","revision":"original","contentSignature":"5bb6b4ecc6f79da17d08bcaed26a2674cca313d79250d33f47c65498cb3deae5"}],"contentSignature":"07d978b59abe3d9fbaa60d5ec7a500073293b483ce304f8d94dd290f76ef50c2","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-216","sourceNumber":216,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A Ltds share trades at Rs.50 and B Ltds at Rs.25. If A takes over B on market-price terms, the swap (exchange) ratio is:","options":["2 shares of A for 1 share of B","3 for 1","1 share of A for 2 shares of B","1 for 1"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Swap ratio = 25 : 50 = 1:2 - one share of A (Rs.50) for every two shares of B (2 x 25 = Rs.50).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"28ca5f53c7f95f9acf2c6b8309d87ecd973b3efbe79a6d032478b10ba2ffb35b","kind":"mcq"},{"id":"corp404-217","sourceNumber":217,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Cross-holdings between the transferor and transferee, and inter-company balances (debtors/creditors between them), are, on amalgamation:","options":["Shown as contingent liabilities of the combined entity in its books","Doubled in the combined balance sheet","Cancelled/eliminated while preparing the combined balance sheet","Converted into goodwill of the combined entity"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"A single combined entity cannot owe money to itself or own its own shares - inter-company owings and unrealised profits in stock are eliminated.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Cross-holdings between the transferor and transferee, and inter-company balances (debtors/creditors between them), are, on amalgamation:","options":["Shown as contingent liabilities","Doubled","Cancelled/eliminated while preparing the combined balance sheet","Converted into goodwill"],"answer":2,"explanation":"A single combined entity cannot owe money to itself or own its own shares - inter-company owings and unrealised profits in stock are eliminated. [Original]","revision":"original","contentSignature":"f920397128d7a77b78a842f0a138a9977d384e8d2f7696db0394846e4a7e09fa"}],"contentSignature":"a73d893c11b42d247cd0121294b3c6d79e83825fa602c05794a1b0784e3b4f5d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-218","sourceNumber":218,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A Ltd takes over B Ltd. Consideration agreed: 50,000 equity shares of Rs.10 each issued at Rs.15 per share, plus Rs.1,00,000 in cash to the shareholders of B Ltd. Purchase consideration is:","options":["Rs.8,50,000","Rs.6,00,000","Rs.5,00,000","Rs.7,50,000"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"PC = 50,000 x 15 + 1,00,000 = 7,50,000 + 1,00,000 = Rs.8,50,000 (shares valued at agreed issue price).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"7d60d06366d63858c744f92d6cdffa6fcd543d6202969d137003d85d5d2e929f","kind":"mcq"},{"id":"corp404-219","sourceNumber":219,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"C Ltd takes over the business of D Ltd: assets agreed at Rs.12,00,000, liabilities taken over Rs.4,00,000, purchase consideration Rs.10,00,000. Goodwill on acquisition is:","options":["Rs.6,00,000","Rs.2,00,000","Nil","Rs.8,00,000"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Net assets = 12 - 4 = Rs.8,00,000; goodwill = PC 10,00,000 - 8,00,000 = Rs.2,00,000.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"6b309b8f96f116d95226f3cfdecf9732fa0432700de21e48a86b83b50fd266f2","kind":"mcq"},{"id":"corp404-220","sourceNumber":220,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"If in the above case the purchase consideration were Rs.7,00,000 instead, the difference would be:","options":["Goodwill Rs.1,00,000","Loss Rs.1,00,000","Share premium Rs.1,00,000","Capital reserve Rs.1,00,000"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"PC 7,00,000 < net assets 8,00,000, so the Rs.1,00,000 bargain goes to capital reserve.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"3e9e966e14bb75d6f23cde3fd62151073a1c63d32b65dfe97724ca9670f9dff5","kind":"mcq"},{"id":"corp404-221","sourceNumber":221,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Payment made by the transferee to the DEBENTURE HOLDERS of the transferor is:","options":["NOT part of purchase consideration - it is a settlement of a liability taken over","Part of the purchase consideration","Treated as dividend paid by the transferee to the debenture holders out of its own profits","Added to the goodwill of the transferee"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"AS-14 confines PC to payments to shareholders; settling creditors and debenture holders merely discharges liabilities assumed.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Payment made by the transferee to the DEBENTURE HOLDERS of the transferor is:","options":["NOT part of purchase consideration - it is a settlement of a liability taken over","Part of purchase consideration","Treated as dividend","Added to goodwill"],"answer":0,"explanation":"AS-14 confines PC to payments to shareholders; settling creditors and debenture holders merely discharges liabilities assumed. [Original]","revision":"original","contentSignature":"12617ecb5e73c557b50dc381ec70398cf39b77a5b9d1090192718fbb6d694121"}],"contentSignature":"39bbb4db59a5ac6268754787bd28d36dd28d506b58ef2e186399422a886db75e","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-222","sourceNumber":222,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In the books of the transferor company, assets and liabilities are closed by transfer to the:","options":["General reserve","Realisation account","Revaluation account","Share capital account"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"The vendor company winds up through a realisation account; the balance of profit/loss on realisation goes to the shareholders.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c21104dd8eaf24760a28fe7c306e41ce9b67decf863fba707fa00879b5cb7bf3","kind":"mcq"},{"id":"corp404-223","sourceNumber":223,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In the books of the transferee (purchase method), the entry to record the business taken over at agreed values, with goodwill, is:","options":["Business Purchase Account Dr. To Share Capital Account in the books of the transferee company","No entry is passed at all in the books of the company for the takeover","Sundry Assets Account Dr. To Sundry Liabilities Account, To Business Purchase Account, without any goodwill","Sundry Assets Dr., Goodwill Dr. -> To Sundry Liabilities, To Business Purchase A/c"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Assets and goodwill are debited; liabilities and the business purchase (PC) account are credited; payment then closes the PC account.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In the books of the transferee (purchase method), the entry to record the business taken over at agreed values, with goodwill, is:","options":["Business Purchase Dr. To Share Capital","No entry","Assets Dr. To Liabilities, To Business Purchase","Sundry Assets Dr., Goodwill Dr. -> To Sundry Liabilities, To Business Purchase A/c"],"answer":3,"explanation":"Assets and goodwill are debited; liabilities and the business purchase (PC) account are credited; payment then closes the PC account. [Original]","revision":"original","contentSignature":"c654fd5cefedf69de0ca214fa1d097c088de445fda5c45c0ce7ff3362e7cbe54"}],"contentSignature":"36a6490f35fe3ecf1e66b963d5a50dd187bd821bf0c3a601b6f51c3c4b9fc13d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-224","sourceNumber":224,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"When the transferee discharges the purchase consideration by issuing shares at a premium, the Share Capital account is credited with:","options":["The FACE VALUE of shares issued, and securities premium with the premium element","The goodwill recorded on the acquisition","The market value of the assets taken over","The full amount of the purchase consideration, the premium being ignored altogether"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Face value goes to share capital; the excess of agreed issue price over face value goes to securities premium (s.52).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"When the transferee discharges the purchase consideration by issuing shares at a premium, the Share Capital account is credited with:","options":["The FACE VALUE of shares issued, and securities premium with the premium element","Goodwill","The market value of assets","The full purchase consideration"],"answer":0,"explanation":"Face value goes to share capital; the excess of agreed issue price over face value goes to securities premium (s.52). [Original]","revision":"original","contentSignature":"107239279dfa06340f48120812b3de7a9eaa5927287f760def41fe524faeef1e"}],"contentSignature":"aba18c7b77eec0842474a99ae960d24693f4924e649b5735b69d4d38cd80d5e1","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-225","sourceNumber":225,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Unrealised profit included in STOCK transferred from the transferor and still held by the transferee at the balance sheet date is:","options":["Eliminated (reduced from stock and from profits/reserves) in the combined accounts","Ignored in the combined accounts","Treated as revenue of the combined entity","Added to the goodwill in the combined accounts of the transferee company at the year end"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Within one economic entity, inter-company profit in unsold stock is unrealised and must be reversed.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Unrealised profit included in STOCK transferred from the transferor and still held by the transferee at the balance sheet date is:","options":["Eliminated (reduced from stock and from profits/reserves) in the combined accounts","Ignored","Treated as revenue","Added to goodwill"],"answer":0,"explanation":"Within one economic entity, inter-company profit in unsold stock is unrealised and must be reversed. [Original]","revision":"original","contentSignature":"e21e845577c8962e23a8471712e1559cc75dc7a4f70c5b687cd5f8f3db5295c9"}],"contentSignature":"2cd038550bf6b0740eafa2b7a367d05f877916bdc2c683c16118ed3df8be02af","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-226","sourceNumber":226,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"AS-14 does NOT apply to: framework)","options":["Absorption of one company by another company","Amalgamations sanctioned by the Tribunal","External reconstruction of a company","Acquisitions of CONTROL by purchase of shares of another company, where no amalgamation results (covered by AS-21/consolidation"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Buying a controlling stake without merging creates a holding-subsidiary relationship (consolidation territory), not an amalgamation.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"AS-14 does NOT apply to: framework)","options":["Absorption of one company by another","Amalgamations sanctioned by the Tribunal","External reconstruction","Acquisitions of CONTROL by purchase of shares of another company, where no amalgamation results (covered by AS-21/consolidation"],"answer":3,"explanation":"Buying a controlling stake without merging creates a holding-subsidiary relationship (consolidation territory), not an amalgamation. [Original] C7. Internal Reconstruction & Capital Reduction Covers: internal vs external reconstruction; alteration of capital (sub-division, consolidation, cancellation of unissued shares, s.61); reduction of share capital (s.66) - special resolution, NCLT confirmation, the three modes; capital reduction account entries and the capital-reserve destination of any balance; schemes under ss.230-232 - with numericals. Double-verified against the Companies Act, 2013.","revision":"original","contentSignature":"cd01508e6e4baa42e4f07040638a57f2d2bcf1394872af8cff69a32c923698c0"}],"contentSignature":"1863f98cceffa9cd6fefdc26257c4d661330282acb0595c6f21d6da863c7d242","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-227","sourceNumber":227,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Internal reconstruction differs from external reconstruction in that internal reconstruction is carried out:","options":["By issuing fresh debentures to the public","WITHOUT liquidating the company or forming a new one - the same company reorganises its capital structure","Only by an order of the Central Government","By winding up the existing company"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Internal reconstruction (ss.61-66, 230) reshuffles capital within the existing company; external reconstruction needs a new company.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Internal reconstruction differs from external reconstruction in that internal reconstruction is carried out:","options":["By issuing debentures","WITHOUT liquidating the company or forming a new one - the same company reorganises its capital structure","Only by the Government","By winding up the company"],"answer":1,"explanation":"Internal reconstruction (ss.61-66, 230) reshuffles capital within the existing company; external reconstruction needs a new company. [Original]","revision":"original","contentSignature":"2efd54f8e8984ca5d54489e40b84a247124c1ec5833984e28892f608feb7353d"}],"contentSignature":"ded9999e6218e8a00e027e8f4b34ad2245f257d4d846822cf5de1668096bff39","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-228","sourceNumber":228,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Sub-division of shares means:","options":["Splitting shares of larger face value into shares of SMALLER face value (e.g. one Rs.100 share into ten Rs.10 shares)","Combining shares into shares of larger denominations","Issuing bonus shares to the existing members","Cancelling the unpaid capital of the company"],"answer":0,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Sub-division (split) under s.61 raises the number of shares and lowers face value; consolidation is the reverse.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Sub-division of shares means:","options":["Splitting shares of larger face value into shares of SMALLER face value (e.g. one Rs.100 share into ten Rs.10 shares)","Combining shares into larger denominations","Issuing bonus shares","Cancelling unpaid capital"],"answer":0,"explanation":"Sub-division (split) under s.61 raises the number of shares and lowers face value; consolidation is the reverse.","revision":"original","contentSignature":"bb26132aeeeb71e22152261082fc08fe326799044861dd60804e32d77982d010"}],"contentSignature":"73eb9e39b3b131cc8280356cf36e3427c10614a245d0bc078d1eb97904a01d99","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-229","sourceNumber":229,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Consolidation of shares is:","options":["Buying back its own shares from the market","Splitting one share into a number of shares of smaller denomination than the original share","Converting the shares into debentures","Combining shares of smaller denomination into shares of LARGER denomination"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Consolidation merges small shares into bigger ones (ten Rs.10 shares into one Rs.100 share), under s.61(1)(b).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Amalgamation and reconstruction","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Consolidation of shares is:","options":["Buying back shares","Splitting one share into many","Converting shares into debentures","Combining shares of smaller denomination into shares of LARGER denomination"],"answer":3,"explanation":"Consolidation merges small shares into bigger ones (ten Rs.10 shares into one Rs.100 share), under s.61(1)(b).","revision":"original","contentSignature":"68b70f8751609e934f3f49951e99c078ca2de93fa2e07bf50547e38f1b82e2bb"}],"contentSignature":"0c287ad235a107ae0115317b06372431e1c3eb504c5ddd6fb97e3a77505d383a","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-230","sourceNumber":230,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Cancellation of UNISSUED share capital under Section 61(1)(e) is:","options":["NOT a reduction of capital - it merely dims the authorised limit and needs only an ordinary resolution","Illegal under the Companies Act","A reduction of share capital needing confirmation by the Tribunal under Section 66 of the Companies Act, 2013","A buy-back of its own shares by the company"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Cancelling shares never issued does not touch issued/paid capital or creditors, so the simple s.61 route applies, not s.66.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Cancellation of UNISSUED share capital under Section 61(1)(e) is:","options":["NOT a reduction of capital - it merely dims the authorised limit and needs only an ordinary resolution","Illegal","A reduction of share capital needing Tribunal confirmation","A buy-back"],"answer":0,"explanation":"Cancelling shares never issued does not touch issued/paid capital or creditors, so the simple s.61 route applies, not s.66. [Original]","revision":"original","contentSignature":"17a130849c4bef489efd2876dd5f82582058782c1e448137589e592291301ccb"}],"contentSignature":"0c65f4d052bc4f36f0129dbdfa0cd6a1d56e6be435ff13c03f5dcdf62b3e79da","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-231","sourceNumber":231,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Reduction of share capital under Section 66 requires:","options":["A SPECIAL RESOLUTION and confirmation by the National Company Law Tribunal (NCLT)","The approval of the stock exchange","A resolution of the Board of directors alone, the shareholders having no say in the matter","The unanimous consent of all the employees"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 66: special resolution plus NCLT confirmation, after settling creditor objections - then the minute is registered with the ROC.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Reduction of share capital under Section 66 requires:","options":["A SPECIAL RESOLUTION and confirmation by the National Company Law Tribunal (NCLT)","Approval of the stock exchange","Board resolution only","Unanimous consent of employees"],"answer":0,"explanation":"Section 66: special resolution plus NCLT confirmation, after settling creditor objections - then the minute is registered with the ROC. [Original]","revision":"original","contentSignature":"7332b44f4bf35e6a93663da940d798aa0091f2203e54e9234b3c21b0b1f672ae"}],"contentSignature":"b43c91af0dc9744818239d0756a847df2d4461b1785e14c49532253633f102f4","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-232","sourceNumber":232,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company may reduce share capital in which of the following ways?","options":["Only by issuing bonus shares to the members","Extinguishing liability on unpaid capital, cancelling capital lost (unrepresented by assets), or paying off capital in excess of wants","Only by converting its shares into stock","By purchasing government bonds out of capital"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 66(1) lists exactly these three modes: write off uncalled liability, cancel lost capital, or return surplus capital.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A company may reduce share capital in which of the following ways?","options":["Only by issuing bonus shares","Extinguishing liability on unpaid capital, cancelling capital lost (unrepresented by assets), or paying off capital in excess of wants","Only by converting shares into stock","By buying government bonds"],"answer":1,"explanation":"Section 66(1) lists exactly these three modes: write off uncalled liability, cancel lost capital, or return surplus capital. [Original]","revision":"original","contentSignature":"6f85e9395371132aa825babfccec7cca5d45903a03aae1a5db7eb9fee1a6b7cd"}],"contentSignature":"c6785328a912071f2ce06a8e6d8fc0eed042fa31bac19033e45928c54ceb78c7","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-233","sourceNumber":233,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"On capital reduction, the Capital Reduction account is used to write off:","options":["The current assets of the company","The investments held by the company","The secured loans of the company","Accumulated losses (debit balance of P&L), goodwill, fictitious assets like preliminary expenses and discount on issue, and overvalued assets"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"The scheme cleans the balance sheet: the credit created by reducing capital absorbs past losses and fictitious/overvalued assets.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"On capital reduction, the Capital Reduction account is used to write off:","options":["Current assets","Investments","Secured loans","Accumulated losses (debit balance of P&L), goodwill, fictitious assets like preliminary expenses and discount on issue, and overvalued assets"],"answer":3,"explanation":"The scheme cleans the balance sheet: the credit created by reducing capital absorbs past losses and fictitious/overvalued assets. [Original]","revision":"original","contentSignature":"c77fee7649cff2a7479aa625f829604e11bb6712fadb3218fc0bbe30c028c582"}],"contentSignature":"b3d9768cbc0d0acfc99b515504888dcc82f9bb7ab89426bfa96912f8ef2b67b1","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-234","sourceNumber":234,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Any balance left in the Capital Reduction account after writing off losses and fictitious assets is transferred to:","options":["Share capital","CAPITAL RESERVE","General reserve","Profit and loss account"],"answer":1,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"A surplus on capital reduction is a capital profit - credited to capital reserve. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"4f88b9c49ae6c91250afe17318cb2b87f246528839335230c548c13dc52a1cf2","kind":"mcq"},{"id":"corp404-235","sourceNumber":235,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"1,00,000 equity shares of Rs.10 each, fully paid, are reduced to shares of Rs.6 each fully paid. The credit to the Capital Reduction account is:","options":["Rs.1,00,000","Rs.6,00,000","Rs.4,00,000","Rs.10,00,000"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Reduction = 1,00,000 x (10 - 6) = Rs.4,00,000, credited to capital reduction account for writing off losses.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"58c5558ec67ffd0e69b5362175dd147a2f6182157346c9acb38ce51d89494002","kind":"mcq"},{"id":"corp404-236","sourceNumber":236,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Continuing the above, the company writes off accumulated losses Rs.2,50,000, goodwill Rs.1,00,000 and preliminary expenses Rs.30,000. The amount transferred to capital reserve is:","options":["Rs.50,000","Rs.3,80,000","Nil","Rs.20,000"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Balance = 4,00,000 - (2,50,000 + 1,00,000 + 30,000) = Rs.20,000, transferred to capital reserve.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"db58c3e06b5fb2ec75defc0a4f8463a49db95a4e19294c454d50d170ac680436","kind":"mcq"},{"id":"corp404-237","sourceNumber":237,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A scheme of compromise or arrangement between a company and its creditors/members is governed by Sections ________ of the Companies Act, 2013.","options":["100 to 105","61 to 64","149 to 152","230 to 232"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Sections 230-232 cover compromises, arrangements and amalgamations sanctioned by the NCLT.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"cc9a48e7057f908fb17d65c064c70b740e0e520d97f4198113ee075eea9b6923","kind":"mcq"},{"id":"corp404-238","sourceNumber":238,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"After a capital reduction is confirmed, the company adds the words ________ to its name for such period as the Tribunal directs.","options":["in Liquidation","and Reduced","and Reconstructed","and Limited"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 66(3)(b): the Tribunal may direct adding \"and Reduced\" to the company name and publication of the reduction reasons.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"370290997c89db3da605dbc2f3b7f388d7c1d37ae4f0d807a955e45116585c8c","kind":"mcq"},{"id":"corp404-239","sourceNumber":239,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Goodwill is:","options":["An INTANGIBLE asset representing the value of the reputation and super-earning capacity of a business","A reserve created by operation of law","A current asset of the business","A fictitious liability of the business"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Goodwill is the present value of expected SUPER profits - the capacity to earn above the normal return on capital employed.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Goodwill is:","options":["An INTANGIBLE asset representing the value of the reputation and super-earning capacity of a business","A reserve created by law","A current asset","A fictitious liability"],"answer":0,"explanation":"Goodwill is the present value of expected SUPER profits - the capacity to earn above the normal return on capital employed. [Original]","revision":"original","contentSignature":"a87d7472cd2384bf2d137221829224281ce4f825c828eac7309890a3f721248e"}],"contentSignature":"b757c40ad74498e43eb2bf95b2b74f47266dd67e62820f14dc7f29204d5e7e5b","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-240","sourceNumber":240,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Only ________ goodwill is recorded in the books of account.","options":["Old goodwill built up over the years","Estimated goodwill of the business","Self-generated goodwill of the business over the years","PURCHASED (paid for on acquisition of a business)"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"AS-26/AS-10: self-generated goodwill is NOT recognised; purchased goodwill, for which consideration was paid, is recorded.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Only ________ goodwill is recorded in the books of account.","options":["Old","Estimated","Self-generated","PURCHASED (paid for on acquisition of a business)"],"answer":3,"explanation":"AS-26/AS-10: self-generated goodwill is NOT recognised; purchased goodwill, for which consideration was paid, is recorded. [Original]","revision":"original","contentSignature":"eb5f09d569b9c82833f5356b1134481acc44fbf1f3cb2f4c1bb9a546accedf4d"}],"contentSignature":"bbc4f4e477243597d80d7012024dc50a9bf205902404cfac05bd5e462fb9767e","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-241","sourceNumber":241,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Goodwill needs valuation when:","options":["Depreciation is charged on the assets","Salaries are paid to the employees","A partner is admitted/retires/dies, a firm is sold or converted into a company, or companies amalgamate","Cash is deposited in the bank account"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Change in ownership structure or business combinations require sharing/paying for the goodwill built up.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Goodwill needs valuation when:","options":["Depreciation is charged","Salaries are paid","A partner is admitted/retires/dies, a firm is sold or converted into a company, or companies amalgamate","Cash is deposited in the bank"],"answer":2,"explanation":"Change in ownership structure or business combinations require sharing/paying for the goodwill built up.","revision":"original","contentSignature":"d7c35084a664f7e90c784c6a44269d7b21afa593bc74ff88f02d31ef606fa21b"}],"contentSignature":"a2c4914b98bb816baeecfda8331e4d42d9e4d9a9c6f6e98d50d45f8a63be8e92","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-242","sourceNumber":242,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under the simple AVERAGE PROFIT method, goodwill equals:","options":["Super profit / normal rate","Average profit x NUMBER OF YEARS PURCHASE","Average profit / years","Capital employed x normal rate"],"answer":1,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Goodwill = average maintainable profit multiplied by the agreed number of years purchase. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"24d3251caabddd85ca49f9012b0ce105405f6df2f3bd336b22194988d25cb04a","kind":"mcq"},{"id":"corp404-243","sourceNumber":243,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The average profits of a firm for the last few years are Rs.60,000. Goodwill at 3 years purchase of average profits is:","options":["Rs.3,00,000","Rs.20,000","Rs.60,000","Rs.1,80,000"],"answer":3,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Goodwill = 60,000 x 3 = Rs.1,80,000. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"548f164b628101cc15dcbb23774293a1e644fdd8bc58cf7c2273325515d815ee","kind":"mcq"},{"id":"corp404-244","sourceNumber":244,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Profits of the last four years are Rs.10,000, Rs.20,000, Rs.30,000 and Rs.40,000 with weights 1, 2, 3 and 4 respectively. Weighted average profit and goodwill at 3 years purchase are:","options":["Rs.25,000 and Rs.75,000","Rs.30,000 and Rs.60,000","Rs.30,000 and Rs.90,000","Rs.40,000 and Rs.1,20,000"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Weighted average = (10,000x1 + 20,000x2 + 30,000x3 + 40,000x4)/(1+2+3+4) = 3,00,000/10 = Rs.30,000; goodwill = 30,000 x 3 = Rs.90,000.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c98180a160529669b9d3240c20992c4f891a261ee1493639e5c4327524dcbf3e","kind":"mcq"},{"id":"corp404-245","sourceNumber":245,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"SUPER PROFIT means:","options":["The EXCESS of average actual profit over the NORMAL profit expected on capital employed at the normal rate of return","The profit of the business before tax","An abnormal gain on the sale of assets","The total profit earned during the year"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Super profit = average profit - normal profit (capital employed x normal rate); goodwill is built on this excess.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"SUPER PROFIT means:","options":["The EXCESS of average actual profit over the NORMAL profit expected on capital employed at the normal rate of return","Profit before tax","Abnormal gain on sale of assets","Total profit of the year"],"answer":0,"explanation":"Super profit = average profit - normal profit (capital employed x normal rate); goodwill is built on this excess.","revision":"original","contentSignature":"36b257127c47fa6c421ae0fbe549736024a15ddd4e3da7d5552041c382b67873"}],"contentSignature":"ba1b35fcac6be3233885a11f115a119d990c4eaa9486d20fbd4914b78c1b9fc0","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-246","sourceNumber":246,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Average profit of a business is Rs.90,000; capital employed is Rs.5,00,000; normal rate of return is 12%. Super profit and goodwill at 2 years purchase of super profit are:","options":["Rs.90,000 and Rs.1,80,000","Rs.60,000 and Rs.1,20,000","Rs.12,000 and Rs.24,000","Rs.30,000 and Rs.60,000"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Normal profit = 5,00,000 x 12% = 60,000; super profit = 90,000 - 60,000 = 30,000; goodwill = 30,000 x 2 = Rs.60,000.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"5a5edc6f5f7272b8ced59db68440c2c333cb7a37b1e9e9fa366562c14ccaa18d","kind":"mcq"},{"id":"corp404-247","sourceNumber":247,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under the CAPITALISATION OF SUPER PROFIT method, goodwill equals:","options":["Average profit multiplied by the years of purchase","SUPER PROFIT / NORMAL RATE OF RETURN","Net assets multiplied by the normal rate","Super profit multiplied by the years of purchase"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Capitalising the super profit at the normal rate gives the value of the business attributable to goodwill: 30,000/12% = Rs.2,50,000 in the above case.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the CAPITALISATION OF SUPER PROFIT method, goodwill equals:","options":["Average profit x years","SUPER PROFIT / NORMAL RATE OF RETURN","Net assets x normal rate","Super profit x years"],"answer":1,"explanation":"Capitalising the super profit at the normal rate gives the value of the business attributable to goodwill: 30,000/12% = Rs.2,50,000 in the above case. [Original]","revision":"original","contentSignature":"db76cfa9eb4967755d05bb23c208024d623d8a63d8f68bc97999e18a7b88ec2f"}],"contentSignature":"6a939c8bdb1dad4d7d77acca247950fe0f248e81fdc95957947b28b61f246497","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-248","sourceNumber":248,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under the CAPITALISATION OF AVERAGE PROFIT method, goodwill equals:","options":["(Average profit / normal rate) MINUS net assets (capital employed)","Average profit divided by the normal rate alone","Net assets multiplied by the years of purchase","Super profit multiplied by the years of purchase of the goodwill value"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Capitalised value of the whole business minus the net tangible assets leaves goodwill - e.g. 90,000/12% = 7,50,000 less 5,00,000 = Rs.2,50,000.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the CAPITALISATION OF AVERAGE PROFIT method, goodwill equals:","options":["(Average profit / normal rate) MINUS net assets (capital employed)","Average profit / normal rate","Net assets x years purchase","Super profit x years"],"answer":0,"explanation":"Capitalised value of the whole business minus the net tangible assets leaves goodwill - e.g. 90,000/12% = 7,50,000 less 5,00,000 = Rs.2,50,000. [Original]","revision":"original","contentSignature":"fa57cbba083853e7fb7be4abdf8aa94ddff0468c77185245adb5bb6de3f9cdfc"}],"contentSignature":"13538a651a02af167f39a36f324ed5f5db194aa1acd32a3d269cdd8a9bb25934","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-249","sourceNumber":249,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under the ANNUITY method, goodwill equals:","options":["Average profit divided by the annuity rate","The profit expected in the first future year alone, without discounting any later year","Super profit x annuity factor (present value of Re.1 per year for the agreed years)","Net assets multiplied by the annuity rate"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"The annuity method values super profit as a series of equal receipts discounted at the normal rate - super profit x PV annuity factor.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the ANNUITY method, goodwill equals:","options":["Average profit / annuity rate","Future profit in year one","Super profit x annuity factor (present value of Re.1 per year for the agreed years)","Net assets x annuity rate"],"answer":2,"explanation":"The annuity method values super profit as a series of equal receipts discounted at the normal rate - super profit x PV annuity factor. [Original]","revision":"original","contentSignature":"dba0ca8fa7d45c726dfabb49f3cb91dd6d66d216a80373450af3d3675542ca06"}],"contentSignature":"450f5776efd190e9c2a39ea7bf48bc59840c30e85be204c7e4c43ef6ea908f0c","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-250","sourceNumber":250,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Capital employed for goodwill valuation is generally computed as: trade investments","options":["Fixed assets + net working capital (current assets - current liabilities), OR equity + reserves + long-term debt - fictitious assets and non-","The sales of the business for the year","The cash in hand of the business","The share capital of the company alone"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Both the assets-side and liabilities-side approaches arrive at the funds actually used in the business to earn profits.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Capital employed for goodwill valuation is generally computed as: trade investments","options":["Fixed assets + net working capital (current assets - current liabilities), OR equity + reserves + long-term debt - fictitious assets and non-","Sales of the year","Cash in hand","Share capital only"],"answer":0,"explanation":"Both the assets-side and liabilities-side approaches arrive at the funds actually used in the business to earn profits. [Original]","revision":"original","contentSignature":"04c56ed4a079d9105bbc76bb938f39396eefebd4d1018208c8e682898b89bb17"}],"contentSignature":"8b2e5ba05e7fc79b8dac9aa80930f25526d214af21cf2e2a787b51bad8b19f3d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-251","sourceNumber":251,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following does NOT enhance the value of goodwill?","options":["Favourable location of the business","Monopoly advantage and ownership of patents, and a wide network of customers","Quality products and efficient management","Frequent changes in management and poor customer relations"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Stable, capable management and strong customer ties build goodwill; instability and poor relations destroy it.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following does NOT enhance the value of goodwill?","options":["Favourable location","Monopoly advantage and patents","Quality products and efficient management","Frequent changes in management and poor customer relations"],"answer":3,"explanation":"Stable, capable management and strong customer ties build goodwill; instability and poor relations destroy it.","revision":"original","contentSignature":"31f4dc01c27368ebebb9a1437157ecd0d40f96aba9ca4ad57b97fb5a99bfa85c"}],"contentSignature":"441c6862c47b630b933370c14bcb4a2838b5f6a7593c6c8e504f85f8966f97fd","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-252","sourceNumber":252,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The NET ASSET (intrinsic) value per equity share equals:","options":["The market price of the equity share","The face value of the equity share","Dividend per share divided by the market rate","(Total assets at realisable values - outside liabilities - preference capital) / number of equity shares"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"NAV measures what each equity share would get if assets were realised and outsiders and preference holders paid off.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The NET ASSET (intrinsic) value per equity share equals:","options":["Market price of the share","Face value always","Dividend per share / market rate","(Total assets at realisable values - outside liabilities - preference capital) / number of equity shares"],"answer":3,"explanation":"NAV measures what each equity share would get if assets were realised and outsiders and preference holders paid off. [Original]","revision":"original","contentSignature":"df2940bed400643955af86666fee74cd2c3ad5b8ff03438100c67dbc2ed50529"}],"contentSignature":"78a114db229a20087d8af62ac88b6c8ef86abdbec85833160298f6560338332b","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-253","sourceNumber":253,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company has assets (realisable) Rs.15,00,000, outside liabilities Rs.5,00,000, preference capital Rs.2,00,000 and 8,000 equity shares. Intrinsic value per equity share is:","options":["Rs.100","Rs.80","Rs.150","Rs.187.50"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Equity backing = 15,00,000 - 5,00,000 - 2,00,000 = 8,00,000; NAV = 8,00,000/8,000 = Rs.100.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e0bd417a6b0df2717c22473a56508465ccc4f99268a9f4fdb9f9150cd04c4c70","kind":"mcq"},{"id":"corp404-254","sourceNumber":254,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The YIELD method values a share as:","options":["Face value multiplied by the years of purchase of the expected future profits","Dividend divided by the face value","Total assets divided by the number of shares","(EXPECTED RATE OF RETURN / NORMAL RATE OF RETURN) x paid-up value per share"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Value = (expected earning rate / normal rate) x paid-up value - earnings above normal lift the value above par.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The YIELD method values a share as:","options":["Face value x years purchase","Dividend / face value","Assets / shares","(EXPECTED RATE OF RETURN / NORMAL RATE OF RETURN) x paid-up value per share"],"answer":3,"explanation":"Value = (expected earning rate / normal rate) x paid-up value - earnings above normal lift the value above par.","revision":"original","contentSignature":"485664f4497d16829f14d0b3b0c6cac24c1366c8402e6e3f8a34633159d74479"}],"contentSignature":"764b651508aa903b74d2e00fdd47d9538489bd2a367e752c8dd3b57e9c625f72","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-255","sourceNumber":255,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A companys shares of Rs.100 (fully paid) earn an expected rate of return of 15% while the normal rate in the industry is 10%. Value per share under the yield method is:","options":["Rs.115","Rs.66.67","Rs.150","Rs.100"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Value = 15/10 x 100 = Rs.150.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"36dda5b8a718427f56fed896bd7a0c776ebd71b3d27c0cfd2f0d2e4b718dc6d4","kind":"mcq"},{"id":"corp404-256","sourceNumber":256,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The FAIR VALUE of a share is:","options":["The price at which the share was issued","The face value of the share","The market price of the share on any given day of trading","The AVERAGE of the net asset value and the yield value"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Fair value = (intrinsic value + yield value)/2 - e.g. (100 + 150)/2 = Rs.125 - balancing asset backing and earning capacity.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The FAIR VALUE of a share is:","options":["The issue price","Its face value","Its market price on any day","The AVERAGE of the net asset value and the yield value"],"answer":3,"explanation":"Fair value = (intrinsic value + yield value)/2 - e.g. (100 + 150)/2 = Rs.125 - balancing asset backing and earning capacity. [Original]","revision":"original","contentSignature":"0ab4c7e88affb9bc48d9ee0ebfa41662f3a52983fa803c338af65b35fe6d21bf"}],"contentSignature":"4e93cc6d3ece157744f18e87f58bfa7ee54ff6321bd4b091b458309c595b1cbf","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-257","sourceNumber":257,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Shares are generally required to be valued when:","options":["A bonus issue is declared by the company","A dividend is declared by the company","They are UNLISTED, or for amalgamation, wealth transfer, gift, or when one class is converted","They are listed on a recognised stock exchange and are traded regularly in the market from day to day"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Quoted prices serve listed shares; unquoted shares and special events (merger, taxation, conversion) need formal valuation.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Shares are generally required to be valued when:","options":["A bonus is declared","Dividend is declared","They are UNLISTED, or for amalgamation, wealth transfer, gift, or when one class is converted","They are listed"],"answer":2,"explanation":"Quoted prices serve listed shares; unquoted shares and special events (merger, taxation, conversion) need formal valuation. [Original]","revision":"original","contentSignature":"13af30c02f880fa8be4dbbaf9180bd78aa1ef41e56b1297347c645a86415021a"}],"contentSignature":"94e3d50bd5c0562682840cfa379128f55ed81488b310df20bbcde18e7bd2bafe","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-258","sourceNumber":258,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Non-trading investments (e.g. quoted investments held as surplus) are, in net asset valuation:","options":["Ignored in the valuation altogether","Deducted from the capital employed","Valued at their MARKET/realisable value and added separately, with income from them excluded from normal business profits","Valued at their original cost of purchase"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Non-trading assets do not generate operating profit, so they enter NAV at realisable value while their income is stripped from maintainable profits.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Non-trading investments (e.g. quoted investments held as surplus) are, in net asset valuation:","options":["Ignored","Deducted from capital","Valued at their MARKET/realisable value and added separately, with income from them excluded from normal business profits","Valued at cost only"],"answer":2,"explanation":"Non-trading assets do not generate operating profit, so they enter NAV at realisable value while their income is stripped from maintainable profits. [Original]","revision":"original","contentSignature":"85da55eeb0363356e18f388687f5717c50110de016971114150421edbf55a20a"}],"contentSignature":"1ef000977a63125cc8ab6a12144f8fff2e26924554ebcd25c35935554f0bd921","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-259","sourceNumber":259,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"While computing maintainable profits for valuation, abnormal and non-recurring items (e.g. profit on sale of a fixed asset) are:","options":["Written off against the capital of the business in the accounts","Doubled before being taken into account","EXCLUDED, so that only normal recurring business profits remain","Added to the profits of the business"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Valuation rests on sustainable earnings - one-time gains/losses and non-operating income are adjusted out.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"While computing maintainable profits for valuation, abnormal and non-recurring items (e.g. profit on sale of a fixed asset) are:","options":["Written off to capital","Doubled","EXCLUDED, so that only normal recurring business profits remain","Added to profits"],"answer":2,"explanation":"Valuation rests on sustainable earnings - one-time gains/losses and non-operating income are adjusted out.","revision":"original","contentSignature":"f20d240a5fb0b395df36ca0f8f1936070084e6bbc7dfaa8c52194d5d36abae55"}],"contentSignature":"f12daca98bde761b327821c264bb7f1a2c1465996ae4370e90ddf1dc50e52673","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-260","sourceNumber":260,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Partnership is defined in Section 4 of the Indian Partnership Act, 1932 as the relation between persons who have agreed to:","options":["Share the PROFITS of a business carried on by all or any of them acting for all","Work together in the same office premises throughout the year on a regular basis","Hold shares of one and the same company","Lend money to a firm at interest"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"The definition has five essentials: two or more persons, an agreement, a business, sharing of profits, and business carried on by all or any acting for all (mutual agency).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Partnership is defined in Section 4 of the Indian Partnership Act, 1932 as the relation between persons who have agreed to:","options":["Share the PROFITS of a business carried on by all or any of them acting for all","Work in the same office","Hold shares of one company","Lend money to a firm"],"answer":0,"explanation":"The definition has five essentials: two or more persons, an agreement, a business, sharing of profits, and business carried on by all or any acting for all (mutual agency). [Original]","revision":"original","contentSignature":"62b127512dcb905b667d13fc6f7ba11d93ed6f61d1f218a3a3bcf6e39515a4a7"}],"contentSignature":"973638ac829c1bd25aa39e0a4766c808943fee4da7f697b48304c4f310c40f1b","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-261","sourceNumber":261,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The most distinctive feature of a partnership, making every partner both principal and agent, is:","options":["Limited liability","MUTUAL AGENCY","Perpetual succession","Separate legal entity"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Each partner binds the firm by acts done in the usual course - he is an agent of the firm and of the other partners, and a principal for his own acts.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"33d422cf544da3c8d754ea10a5059d01b764a3f1194f8e03c7a2988ec8ce3280","kind":"mcq"},{"id":"corp404-262","sourceNumber":262,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A partnership firm in India:","options":["Must be registered before it can carry on business at all","Has NO separate legal personality apart from its partners","Is never liable to pay tax on its income","Is a separate legal entity like a company"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Unlike a company, the firm is not distinct from its partners in general law - partners own the property and are personally liable.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A partnership firm in India:","options":["Must always be registered","Has NO separate legal personality apart from its partners","Never pays tax","Is a separate legal entity like a company"],"answer":1,"explanation":"Unlike a company, the firm is not distinct from its partners in general law - partners own the property and are personally liable. [Original]","revision":"original","contentSignature":"bedaf0d985be45ebcd3e0453d600d1955e8bb6e632919746a5b748e69c43f76f"}],"contentSignature":"a618f7c6ddd21f3498e9f4c8c5295e7d8c9f6fcc01b605913a1c7247562924c0","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-263","sourceNumber":263,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The minimum and maximum number of partners in a partnership firm (as per the cap in the Companies Act, 2013 read with Rule 10 of the Companies (Miscellaneous) Rules, 2014) are:","options":["2 and 50","2 and 20","2 and no limit","7 and 100"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 464 bars associations of more than 50 persons for business unless incorporated - so the effective range is 2 to 50 partners.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consolidated financial statements","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"766556dad5c7d5eb952f4eda8ed3a9d954398f36c6db836432577bb7cd4ea660","kind":"mcq"},{"id":"corp404-264","sourceNumber":264,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A partnership agreement may be:","options":["Made only through a registered company formed under the Companies Act, 2013, for that purpose by the partners","Oral OR written - though a written deed is advisable and needed for registration benefits","Made only before a magistrate","Valid only if it is in writing"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"The Act does not demand a written agreement; the written partnership deed governs capital, ratios, interest, salary and other terms.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A partnership agreement may be:","options":["Only through a company","Oral OR written - though a written deed is advisable and needed for registration benefits","Only before a magistrate","Only in writing"],"answer":1,"explanation":"The Act does not demand a written agreement; the written partnership deed governs capital, ratios, interest, salary and other terms. [Original]","revision":"original","contentSignature":"858219289cdcd0ee76c8896c716e64c64603aacc82b57ed2b12c968a06aa4c4d"}],"contentSignature":"e7a3cafa70a049fa18eba7bcca6d37491476bb68599b63271b4a35851fdd69c0","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-265","sourceNumber":265,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Registration of a partnership firm is:","options":["Done with the Securities and Exchange Board of India before the firm can commence its business anywhere in India","Compulsory before the firm starts business","Valid for a period of one year only","OPTIONAL - but an unregistered firm cannot sue third parties to enforce contractual rights (s.69)"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 69: non-registration bars the firm and partners from enforcing contract claims in court, though the firm can still be sued and can claim set-off.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Registration of a partnership firm is:","options":["Done with SEBI","Compulsory before starting business","Valid for one year","OPTIONAL - but an unregistered firm cannot sue third parties to enforce contractual rights (s.69)"],"answer":3,"explanation":"Section 69: non-registration bars the firm and partners from enforcing contract claims in court, though the firm can still be sued and can claim set-off. [Original]","revision":"original","contentSignature":"91f145869b6eb0f0198434a75a813ef3244fdc364594ae301a6f6504c940a04b"}],"contentSignature":"3a3dcc4b14cee10feea4c766a4defc117ff36815335580a04a4fd2e22bcc4e68","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-266","sourceNumber":266,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The document containing the terms of a partnership is called the:","options":["Partnership DEED","Memorandum","Prospectus","Trust deed"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"The deed records capital, profit-sharing ratio, interest on capital/drawings, salaries, admission and dissolution terms.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"4edfbbccf773e8d8e54954048766a3363e4f1e0db8758bf997c33de25feac312","kind":"mcq"},{"id":"corp404-267","sourceNumber":267,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A MINOR admitted to the benefits of partnership under Section 30: partner","options":["Cannot inspect the books of the firm","Is personally liable for all the debts of the firm","Can sign contracts binding the firm","Shares the property and profits but is NOT personally liable; on attaining majority he must elect within six months whether to become a full"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"A minor may be admitted to benefits with the consent of all partners; his liability is limited to his share, and he elects within 6 months of majority.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A MINOR admitted to the benefits of partnership under Section 30: partner","options":["Cannot inspect the books","Is personally liable for all firm debts","Can sign contracts for the firm","Shares the property and profits but is NOT personally liable; on attaining majority he must elect within six months whether to become a full"],"answer":3,"explanation":"A minor may be admitted to benefits with the consent of all partners; his liability is limited to his share, and he elects within 6 months of majority. [Original]","revision":"original","contentSignature":"9fd30a084be7752f2ad03536c9fd235e60ca5ccaa6bbdafd17981cd4a448d874"}],"contentSignature":"04f1df4ba4d8f3f4135870382571f4df2b266553597344d9915f90bff90dae70","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-268","sourceNumber":268,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A partner by ESTOPPEL (holding out) is liable because:","options":["He signed the partnership deed","He invested in the debentures of a company","He represented himself (or allowed himself to be represented) as a partner, and outsiders gave credit on that faith","He is a minor admitted to the benefits of the firm"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 28: a person held out as a partner is liable like a partner to anyone who acted on the representation - though he gets no partner rights.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A partner by ESTOPPEL (holding out) is liable because:","options":["He signed the deed","He invested in debentures","He represented himself (or allowed himself to be represented) as a partner, and outsiders gave credit on that faith","He is a minor"],"answer":2,"explanation":"Section 28: a person held out as a partner is liable like a partner to anyone who acted on the representation - though he gets no partner rights. [Original]","revision":"original","contentSignature":"c632e893c3c30fd4ef1dc3c1c7341fa209860efba6a059495b9f791213eb1f57"}],"contentSignature":"880cdd74f7a0bad98a6f4137b7e1fccbe1cc9b128130d5c812fa2bf19f3d9bda","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-269","sourceNumber":269,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A NOMINAL partner is one who:","options":["Is always a minor under the law","Manages the day-to-day business of the firm","Only lends his name to the firm, contributing neither capital nor sharing profits, yet liable to outsiders as a partner","Contributes the full capital of the firm"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Nominal partners lend their name/reputation; despite no real interest, they are liable to third parties as partners.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A NOMINAL partner is one who:","options":["Is always a minor","Manages the business","Only lends his name to the firm, contributing neither capital nor sharing profits, yet liable to outsiders as a partner","Contributes full capital"],"answer":2,"explanation":"Nominal partners lend their name/reputation; despite no real interest, they are liable to third parties as partners.","revision":"original","contentSignature":"ff415875f508c65854654c5a11373fe55d4d4e0f319365f0bd5885d498145e31"}],"contentSignature":"1a32729ca03fa544825f32f9cc9993d7c42a121369f1b202f33c744d1bce5225","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-270","sourceNumber":270,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Sharing of profits alone is ________ evidence of partnership.","options":["Of no weight in the eyes of the law, however the parties may describe it","It does not by itself amount to any evidence of the relationship at all","By itself it settles the matter of partnership once and for all, whatever else may appear from the conduct of the parties in the dealings between them","PRIMA FACIE but not conclusive - e.g. sharing gross returns, or paying annuity to a widow, does not by itself create partnership"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 6: profit-sharing raises a presumption, not proof - servants paid from profits, lenders taking a profit share, and annuity recipients are not thereby partners.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Sharing of profits alone is ________ evidence of partnership.","options":["Irrelevant","No","Conclusive","PRIMA FACIE but not conclusive - e.g. sharing gross returns, or paying annuity to a widow, does not by itself create partnership"],"answer":3,"explanation":"Section 6: profit-sharing raises a presumption, not proof - servants paid from profits, lenders taking a profit share, and annuity recipients are not thereby partners. [Original]","revision":"original","contentSignature":"93f30856a851a0b59ff4a3072ab480d32b871a02d7e8a1be5dc12be238e89f0a"}],"contentSignature":"2d7fe7b9e5b63d7824f54f4701c17674f794a99355893201d1b6216d2034751a","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-271","sourceNumber":271,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Partnership property (goodwill included) must be used:","options":["By each partner freely for personal ends","Only by the managing partner","Only after dissolution","Exclusively for the purposes of the FIRM (s.15)"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 15: firm property is held and applied exclusively for the business of the firm; personal use breaches partner duties.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"32eb5f3f64349dff298acf6fc056503dbcc7dfcccc3b93869c48ee01c7364c7d","kind":"mcq"},{"id":"corp404-272","sourceNumber":272,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In the ABSENCE of a partnership deed, profits and losses are shared:","options":["By seniority","In capital ratio","EQUALLY among all partners","As decided by the eldest partner"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Section 13(b): partners share profits equally and contribute equally to losses, whatever their capital contribution. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8739c59389002e70d05e56bce5d6bdff1e402cef47622dd1f246db846c8188ca","kind":"mcq"},{"id":"corp404-273","sourceNumber":273,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"X and Y are partners without any agreement. X withdraws Rs.55,000 from his capital as drawings. The interest on drawings that may be charged from X by the firm is:","options":["Interest at 5% per annum","Interest at 6% per month","Interest at 6% per annum","NO interest to be charged"],"answer":3,"source":"Corporate Accounting 404 Bank — PYQ: SSC CGL Tier-2 AAO, 2022-Jan","explanation":"Without an agreement, no interest is charged on drawings (and none is allowed on capital either) - ss.13(c) applies only to advances beyond capital. [PYQ: SSC CGL Tier-2 AAO, 2022-Jan]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c1deb7c1d3bfd7324331b04bc3ead023dcaee83b478a0909608871b96a3ef537","kind":"pyq"},{"id":"corp404-274","sourceNumber":274,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In the absence of an agreement, interest on the CAPITAL of partners is:","options":["Allowed at 6% p.a.","Allowed at 12% p.a.","NOT allowed at all","Allowed at bank rate"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Interest on capital is payable only if the deed provides for it; it is an appropriation of profit, not a charge. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"3fae2b73110d0946d802f33f78754ca464481920c660e8d7a79446d727b572ae","kind":"mcq"},{"id":"corp404-275","sourceNumber":275,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A partner who lends money to the firm BEYOND his capital is entitled, in the absence of an agreement, to interest at:","options":["18% p.a.","12% p.a.","6% p.a.","No interest"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 13(d): advances beyond capital earn 6% p.a. as a matter of right - and this interest is a charge payable even out of capital.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8ebcdc434ff231836204bf8dc26b9da37198d0d9e20f0d9a3ca1f860e27fd053","kind":"mcq"},{"id":"corp404-276","sourceNumber":276,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A working partner, where the deed is silent, is entitled to:","options":["A commission on the sales he makes","NO salary or remuneration for taking part in the conduct of the business","A bonus at the end of every year","A salary at the prevailing market rate for comparable work in a similar firm"],"answer":1,"source":"Corporate Accounting 404 Bank — Recall 2017","explanation":"Section 13(a): no partner is entitled to remuneration for conducting business unless the agreement says so.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A working partner, where the deed is silent, is entitled to:","options":["Commission on sales","NO salary or remuneration for taking part in the conduct of the business","A bonus every year","Salary at market rate"],"answer":1,"explanation":"Section 13(a): no partner is entitled to remuneration for conducting business unless the agreement says so.","revision":"original","contentSignature":"f58c1ca2dc8fc8f8bd74442a6d3ac8774f4c5435cfa3278520f514aff101d757"}],"contentSignature":"4961be04cfe542fc35edd6f36af6e15068d7048787121d52586863337cc40eb8","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-277","sourceNumber":277,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Interest on capital, partner salary and interest on drawings are recorded in the:","options":["PROFIT AND LOSS APPROPRIATION account","Realisation account of the dissolved firm","Trading account","Balance sheet only"],"answer":0,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"These are appropriations of profit between partners - they appear in the P&L Appropriation Account, which distributes the net profit. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest on capital, partner salary and interest on drawings are recorded in the:","options":["PROFIT AND LOSS APPROPRIATION account","Realisation account","Trading account","Balance sheet only"],"answer":0,"explanation":"These are appropriations of profit between partners - they appear in the P&L Appropriation Account, which distributes the net profit. [Recall 2018]","revision":"original","contentSignature":"760d09900f073df154d12cafae1629ca1741fc7c6477b857e7209782fe4f428f"}],"contentSignature":"5ca0a41d5a9a83382e97c694e85a48656401e3bf1beabcbbe298b804ff658ad6","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-278","sourceNumber":278,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under FLUCTUATING capital accounts, all adjustments (interest, salary, drawings, share of profit) are recorded in:","options":["A separate current account","The CAPITAL account itself","The cash book","The goodwill account"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Fixed capital keeps the capital account untouched with adjustments in current accounts; fluctuating capital posts everything to one account.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"0fa09b9d80f18b5da0371dd235189add0f1cf42e933125576a8ea0be3b800a1c","kind":"mcq"},{"id":"corp404-279","sourceNumber":279,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A partner is entitled, under Section 12(d), to:","options":["Bind the firm by his personal contracts made outside the firm's business","Sell the business of the firm","Draw salary without any limit","Have access to and INSPECT AND COPY any of the books of the firm"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Inspection and copying of books is a statutory right of every partner, whether active or sleeping.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A partner is entitled, under Section 12(d), to:","options":["Bind the firm in personal contracts","Sell the firm","Draw unlimited salary","Have access to and INSPECT AND COPY any of the books of the firm"],"answer":3,"explanation":"Inspection and copying of books is a statutory right of every partner, whether active or sleeping. [Original]","revision":"original","contentSignature":"1218bfd9d358608576657de7796f22651fbd71115b6ad7320aabbbfd1f2e7629"}],"contentSignature":"a126b5446195bd90b812ee5079e91a9bfb912234b5fb345468a9f1885fba86aa","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-280","sourceNumber":280,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A partner earning secret profits from a competing business must, under Section 16(b):","options":["Pay double the salary to the firm for the whole year","Leave the firm automatically","Account for and PAY OVER those profits to the firm","Keep the profits for himself"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"A partner must not carry on a competing business; any profit from one belongs to the firm.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A partner earning secret profits from a competing business must, under Section 16(b):","options":["Pay double salary","Leave the firm automatically","Account for and PAY OVER those profits to the firm","Keep them"],"answer":2,"explanation":"A partner must not carry on a competing business; any profit from one belongs to the firm. [Original]","revision":"original","contentSignature":"7615d94e7a02b9435ee73bc4cd20e720e9eca71d7c2063ab499b12a77191d4ad"}],"contentSignature":"02fd272507f486571bd618a3008104fac2ca5fab152610824651804764727574","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-281","sourceNumber":281,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Every partner is bound, under Section 9, to carry on the business of the firm to the greatest common advantage and to be:","options":["JUST AND FAITHFUL (utmost good faith) to each other","Absent from the meetings of the partners","Silent about the affairs of the firm","Competitive with the business of the firm in the market"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Sections 9-10 impose the duties of utmost good faith, full and true information, and indemnity for fraud.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Every partner is bound, under Section 9, to carry on the business of the firm to the greatest common advantage and to be:","options":["JUST AND FAITHFUL (utmost good faith) to each other","Absent from meetings","Silent","Competitive with the firm"],"answer":0,"explanation":"Sections 9-10 impose the duties of utmost good faith, full and true information, and indemnity for fraud.","revision":"original","contentSignature":"b83866d96ec824ef2f5626e8b3c6cb5b2c18883481d73b7b8168e44ee43ecad1"}],"contentSignature":"5340da5f6ff1e00c0aa12648e57aaf5d30363fad503c1ab0ac99125b361d5826","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-282","sourceNumber":282,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A partner indemnifies the firm for losses caused by his ________, and the firm indemnifies a partner for payments made in the ________ course of business.","options":["Salary; illegal payments","Absence; foreign transactions of the firm abroad","Negligence; unusual course","FRAUD/WILFUL NEGLECT; ordinary and prudent"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 13(f)-(e): partners indemnify the firm for fraud/wilful neglect; the firm indemnifies partners for ordinary business payments and liabilities.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A partner indemnifies the firm for losses caused by his ________, and the firm indemnifies a partner for payments made in the ________ course of business.","options":["Salary; illegal","Absence; foreign","Negligence; unusual","FRAUD/WILFUL NEGLECT; ordinary and prudent"],"answer":3,"explanation":"Section 13(f)-(e): partners indemnify the firm for fraud/wilful neglect; the firm indemnifies partners for ordinary business payments and liabilities. [Original]","revision":"original","contentSignature":"f56978e7ec5d26785b5a5b27f42576c3030e6833ba57a92634a9444c2f037c4a"}],"contentSignature":"b17d8f06a1b00d711428323f54bc3047cb1126f8123cc1632954f42dc96e942a","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-283","sourceNumber":283,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following is beyond the IMPLIED AUTHORITY of a partner (Section 19(2))?","options":["Buying goods for the business of the firm","Engaging employees for the business of the firm","Receiving payment of the debts due to the firm","SUBMITTING A DISPUTE RELATING TO THE FIRM TO ARBITRATION, or acquiring/transferring immovable property of the firm"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 19(2) lists barred acts without express authority: arbitration submissions, opening personal bank accounts for firm money, compromising claims, withdrawing suits, admitting liability, and dealing in immovable property.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is beyond the IMPLIED AUTHORITY of a partner (Section 19(2))?","options":["Buying goods for the firm","Engaging employees","Receiving payment of firm debts","SUBMITTING A DISPUTE RELATING TO THE FIRM TO ARBITRATION, or acquiring/transferring immovable property of the firm"],"answer":3,"explanation":"Section 19(2) lists barred acts without express authority: arbitration submissions, opening personal bank accounts for firm money, compromising claims, withdrawing suits, admitting liability, and dealing in immovable property.","revision":"original","contentSignature":"233b5c92f444a9efc5bfa8968374f2dfe622b8a02eec0f4faa88a3e04bf494e7"}],"contentSignature":"1870155a2bc1c2fe255fab9c904b1064dd8f920422e9b3b4be9db622766060a6","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-284","sourceNumber":284,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"An act done by a partner within his implied authority in the usual way of the firm business binds:","options":["Only sleeping partners","THE FIRM AND ALL PARTNERS","Only that partner","No one"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 18-19: a partner is the agent of the firm; acts in the usual course within implied authority bind the firm.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"7e82989ca6d5c472eb4097786a5e813ec03f2141a2b0db0b64647f7792b1e3f8","kind":"mcq"},{"id":"corp404-285","sourceNumber":285,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"On the admission of a new partner, the SACRIFICING RATIO equals:","options":["The gaining ratio of the incoming partner","The capital ratio of the existing partners","OLD RATIO minus NEW RATIO of the existing partners","New ratio minus old ratio of the existing partners"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Sacrifice = old share - new share for each continuing partner; goodwill compensation is distributed in this ratio.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"On the admission of a new partner, the SACRIFICING RATIO equals:","options":["Gaining ratio of the newcomer","Capital ratio","OLD RATIO minus NEW RATIO of the existing partners","New ratio minus old ratio"],"answer":2,"explanation":"Sacrifice = old share - new share for each continuing partner; goodwill compensation is distributed in this ratio.","revision":"original","contentSignature":"c1b4a5d9880977c35137d61ee93e25e2352f049005319838d2d32d38cd8ff3a9"}],"contentSignature":"4f81a817b11ccbd7b2f33f68b759916f492b404fb0bbf25eb8414803cb513693","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-286","sourceNumber":286,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"X and Y share profits 3:2. They admit Z for a 1/4 share, the old partners continuing in their relative ratio. The new profit-sharing ratio is:","options":["5:3:2","3:2:1","2:3:5","9:6:5"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Z takes 1/4 = 5/20; remaining 3/4 goes 3:2, i.e. X = 3/5 x 3/4 = 9/20, Y = 2/5 x 3/4 = 6/20. Ratio 9:6:5.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"1588b827a9982c6fae53e9c1aa114252417b7adfa6ea2144a207bccd4788798f","kind":"mcq"},{"id":"corp404-287","sourceNumber":287,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A and B share profits 4:3. C is admitted for a 1/6 share, acquiring it EQUALLY from A and B. The sacrificing ratio is:","options":["1:1","3:1","2:1","4:3"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Equal acquisition from both means each sacrifices half of 1/6 - sacrifice ratio 1:1, independent of the old ratio.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"b26d299fa12d16d88ef1e6032106e8844475683c3dff34666295def6280a2163","kind":"mcq"},{"id":"corp404-288","sourceNumber":288,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"When the incoming partner cannot bring in his share of goodwill (premium) in cash, the adjustment is made through:","options":["The bank account of the firm","The CAPITAL (or current) ACCOUNTS of the partners - new partner debited, sacrificing partners credited in sacrificing ratio","A loan taken from the bank","The trading account of the firm"],"answer":1,"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2022-Oct-29M","explanation":"If premium is not brought in cash, an adjusting entry passes goodwill value through the partner capital/current accounts. [PYQ: UGC NET Commerce, 2022-Oct-29M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"When the incoming partner cannot bring in his share of goodwill (premium) in cash, the adjustment is made through:","options":["The bank account","The CAPITAL (or current) ACCOUNTS of the partners - new partner debited, sacrificing partners credited in sacrificing ratio","A loan from the bank","The trading account"],"answer":1,"explanation":"If premium is not brought in cash, an adjusting entry passes goodwill value through the partner capital/current accounts. [PYQ: UGC NET Commerce, 2022-Oct-29M]","revision":"original","contentSignature":"a3f58ce2b40aa9f0711e999a2e5f66a068ac7ccd951745ece94f590d5c7ab1d2"}],"contentSignature":"a194a45ea1c07ac0e134764b3f7ec6ca2f78a6afe9134757dfb74e76cfe4ac2f","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"pyq"},{"id":"corp404-289","sourceNumber":289,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"On admission, profits or losses on REVALUATION of assets and liabilities belong to:","options":["The OLD partners in the OLD profit-sharing ratio","The incoming partner alone","All the partners in equal shares","The firm, carried to the capital reserve account directly"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Value changes up to the admission date were earned before the newcomer joined - they go to old partners in the old ratio.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"On admission, profits or losses on REVALUATION of assets and liabilities belong to:","options":["The OLD partners in the OLD profit-sharing ratio","The new partner","All partners equally","The firm as capital reserve"],"answer":0,"explanation":"Value changes up to the admission date were earned before the newcomer joined - they go to old partners in the old ratio. [Original]","revision":"original","contentSignature":"b6a08f3f462b72c22fdeafa3af80996de7fecaffbcbe8ba7f1b8e555eec5c61e"}],"contentSignature":"392de1aebb49be09c8247d2b380f19faaa62ca70e50133f3496ec1260b87427e","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-290","sourceNumber":290,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"On the RETIREMENT of a partner, the continuing partners share of goodwill compensation is borne in their:","options":["Sacrificing ratio of the continuing partners","Capital ratio","GAINING ratio (new share minus old share)","Equal ratio"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Retirement benefits those who stay: they compensate the outgoing partner for goodwill in their gaining ratio.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"On the RETIREMENT of a partner, the continuing partners share of goodwill compensation is borne in their:","options":["Sacrificing ratio","Capital ratio","GAINING ratio (new share minus old share)","Equal ratio always"],"answer":2,"explanation":"Retirement benefits those who stay: they compensate the outgoing partner for goodwill in their gaining ratio.","revision":"original","contentSignature":"42f9548e7c1b4d634989b9f2071e269893abdb8d3265a0800b7a66a5cdbd4c1f"}],"contentSignature":"c69fc645ed3132e0b034ac2efa549d56d62f80b13d4677abcb7126b69edc2695","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-291","sourceNumber":291,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The amount due to a retiring partner, if not paid immediately, is transferred to his:","options":["LOAN account, carrying interest (6% p.a. in the absence of agreement) until paid","Drawings account, without any interest, to be recovered from his share of future profits","Capital reserve account of the firm","Goodwill account of the firm"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 37: the outgoing partner (or estate) gets interest at 6% p.a. or a share of profits attributable to use of his share, at his option, until settlement.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The amount due to a retiring partner, if not paid immediately, is transferred to his:","options":["LOAN account, carrying interest (6% p.a. in the absence of agreement) until paid","Drawings account","Capital reserve","Goodwill account"],"answer":0,"explanation":"Section 37: the outgoing partner (or estate) gets interest at 6% p.a. or a share of profits attributable to use of his share, at his option, until settlement. [Original]","revision":"original","contentSignature":"df9577da8aea0f07cfbb7d6b47a2b45325f19b1f792efa571397a61526e76b8e"}],"contentSignature":"3a723b1504963755df5d41105c77467955470ea93d0861c46e2ef65c4b5f64d7","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-292","sourceNumber":292,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"On the DEATH of a partner, his legal representatives are entitled to his capital, share of goodwill, share of profit up to the date of death, and:","options":["The premises of the firm","His share in reserves and revaluation surplus standing to his credit","A seat on the Board of the firm","Nothing beyond his capital balance standing in the books of the firm at his death"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"The deceased partner estate settles for capital plus all credits: goodwill, accumulated reserves, revaluation gains and profit to the date of death.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"On the DEATH of a partner, his legal representatives are entitled to his capital, share of goodwill, share of profit up to the date of death, and:","options":["The firm premises","His share in reserves and revaluation surplus standing to his credit","A seat on the Board","Nothing else"],"answer":1,"explanation":"The deceased partner estate settles for capital plus all credits: goodwill, accumulated reserves, revaluation gains and profit to the date of death. [Original]","revision":"original","contentSignature":"7f7086fbb9614c149f8c49d60f8790d25a11051f3dd155a4fb66b2283ac891a5"}],"contentSignature":"f55e240742498942e41ff9c0cf298cab62a88d9fbde911bf093dcc772bbefbe6","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-293","sourceNumber":293,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Goodwill brought in cash by an incoming partner is credited to:","options":["All the partners in equal shares","The bank account of the firm as income of the firm","The OLD partners in their SACRIFICING ratio","The incoming partner himself"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Premium for goodwill compensates those who gave up share - old partners in sacrificing ratio.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Goodwill brought in cash by an incoming partner is credited to:","options":["All partners equally","The firm bank account as income","The OLD partners in their SACRIFICING ratio","The new partner"],"answer":2,"explanation":"Premium for goodwill compensates those who gave up share - old partners in sacrificing ratio. [Original]","revision":"original","contentSignature":"0fd117a9d279fd8baef55c8223752cadd594ba1809c0a37b93186ba928bee258"}],"contentSignature":"0e916c7074ef85a73960fa975252110a9196c564f54afdd8914c5ddff16f1ca0","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-294","sourceNumber":294,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Dissolution of the FIRM, as distinct from dissolution of PARTNERSHIP, means:","options":["The retirement of a partner from the firm","A change in the profit-sharing ratio of the partners alone, the firm continuing","The business relationship between ALL partners ends - the firm is wound up","The admission of a new partner into the firm"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Dissolution of partnership = a partner leaves but the firm continues; dissolution of the firm = complete termination for all.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Dissolution of the FIRM, as distinct from dissolution of PARTNERSHIP, means:","options":["A partner retires","A change in profit ratio","The business relationship between ALL partners ends - the firm is wound up","Admission of a partner"],"answer":2,"explanation":"Dissolution of partnership = a partner leaves but the firm continues; dissolution of the firm = complete termination for all. [Original]","revision":"original","contentSignature":"6b2d21ca8ee813031acf2f33a4db3432c5e033a3674202b0c9c2c43b5abaa00c"}],"contentSignature":"8b6407265b82e474f99d65d88b221aec7119f196a97cef070d3dcfb70fefa8b1","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-295","sourceNumber":295,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A firm is compulsorily dissolved under Section 41 when:","options":["A partner proceeds on a long holiday","A new partner is admitted into the firm with the consent of all the existing partners","All partners, or all but one, become INSOLVENT, or the business becomes UNLAWFUL","The profits of the firm decline sharply"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Compulsory dissolution follows illegality of the business or insolvency of all/all-but-one partners.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A firm is compulsorily dissolved under Section 41 when:","options":["A partner takes a holiday","A new partner joins","All partners, or all but one, become INSOLVENT, or the business becomes UNLAWFUL","Profits fall"],"answer":2,"explanation":"Compulsory dissolution follows illegality of the business or insolvency of all/all-but-one partners. [Original]","revision":"original","contentSignature":"5773293bd453c325534cfaccfd47736dd52ec911619aa11aaf0f518fa8454f6f"}],"contentSignature":"b37f7480457349f42919aaecd0f7da01f8ffe8069010a25c736bac6c40fddec4","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-296","sourceNumber":296,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A partnership AT WILL may be dissolved by:","options":["Any partner giving NOTICE in writing to all other partners of his intention to dissolve (s.43)","A majority vote of the creditors of the firm at a meeting called for the purpose by the senior partner","An order of the court alone","A direction of the Registrar of Firms"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 43: a partnership at will ends by notice; dissolution runs from the date in the notice or communication.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A partnership AT WILL may be dissolved by:","options":["Any partner giving NOTICE in writing to all other partners of his intention to dissolve (s.43)","A majority vote of creditors","Court order only","The registrar"],"answer":0,"explanation":"Section 43: a partnership at will ends by notice; dissolution runs from the date in the notice or communication.","revision":"original","contentSignature":"4305a8b7ae329d61cb29ba661593ee7f3a7663edefb4e60382f65f80b5c51956"}],"contentSignature":"d905fb3842b8afee6a1ab33402f927d92cdc5bb0fa38dc1bad0529fde66141e9","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-297","sourceNumber":297,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The Court may order dissolution under Section 44 on all of the following grounds EXCEPT:","options":["Business that can only be carried on at a loss","Misconduct affecting the business, persistent breach of the agreement, or transfer of the whole interest to an outsider","Permanent incapacity or insanity of a partner","A partner asking for his capital back once"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Court grounds: insanity, permanent incapacity, misconduct, wilful breach, whole-interest transfer, perpetual loss, and just-and-equitable - not a mere demand for capital.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"e8d6c47d1c7bf5c56fd2b5195073584a1ff06604a8b6a4d5747936db942a958c","kind":"mcq"},{"id":"corp404-298","sourceNumber":298,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"On dissolution, the assets of the firm (including sums contributed to make up capital deficiencies) are applied in which order (Section 48)?","options":["Government dues are paid last of all","All claimants are paid equally at the same time","(i) Outside debts, (ii) partner loans to the firm, (iii) partner capitals, (iv) surplus among partners in profit-sharing ratio","The capitals of the partners are repaid first"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Section 48(a) fixes the waterfall: third-party debts, then advances from partners, then capitals, then surplus in profit ratio. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"On dissolution, the assets of the firm (including sums contributed to make up capital deficiencies) are applied in which order (Section 48)?","options":["Government dues last","Equally to all at once","(i) Outside debts, (ii) partner loans to the firm, (iii) partner capitals, (iv) surplus among partners in profit-sharing ratio","Partners capitals first"],"answer":2,"explanation":"Section 48(a) fixes the waterfall: third-party debts, then advances from partners, then capitals, then surplus in profit ratio. [Recall 2018]","revision":"original","contentSignature":"eb11908e6e521a096679d585f1e4c576b92ebfe0dad29f3eec2f541c54b5db4c"}],"contentSignature":"61b4765a31e5e2c7cd8ce6d3aa7d065ff6d56e5e65b93f2b3dab34e81870fc69","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-299","sourceNumber":299,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Losses on dissolution (including capital deficiency) are borne in which order?","options":["By the creditors of the firm","Only by the working partner of the firm","Out of the capitals of the partners first","First out of PROFITS, then out of CAPITAL, and finally by the partners individually in their PROFIT-SHARING ratio"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 48(b): losses are paid from profits, then capital, then by partners in profit ratio - the mirror image of the asset waterfall.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Losses on dissolution (including capital deficiency) are borne in which order?","options":["By creditors","Only by the working partner","Capitals first","First out of PROFITS, then out of CAPITAL, and finally by the partners individually in their PROFIT-SHARING ratio"],"answer":3,"explanation":"Section 48(b): losses are paid from profits, then capital, then by partners in profit ratio - the mirror image of the asset waterfall. [Original]","revision":"original","contentSignature":"3c74fa7a096edc7dbf215f319294128a2531bb2522a619561ba2c6a4b1b37dbb"}],"contentSignature":"5a32480f94ec9da8dd3f3c29b3df815b5918a5759ce21910b063d0b2b6439d85","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-300","sourceNumber":300,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The rule in GARNER v MURRAY applies when a partner is INSOLVENT on dissolution: his capital deficiency is borne by the solvent partners in their:","options":["Profit-sharing ratio of the partners just before dissolution","CAPITAL ratio (ratio of capitals just before dissolution)","Equal ratio among themselves","Gaining ratio among themselves"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Garner v Murray: the insolvent partner deficiency is a capital loss, shared by solvent partners in capital ratio, not profit ratio.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The rule in GARNER v MURRAY applies when a partner is INSOLVENT on dissolution: his capital deficiency is borne by the solvent partners in their:","options":["Profit-sharing ratio","CAPITAL ratio (ratio of capitals just before dissolution)","Equal ratio","Gaining ratio"],"answer":1,"explanation":"Garner v Murray: the insolvent partner deficiency is a capital loss, shared by solvent partners in capital ratio, not profit ratio. [Original]","revision":"original","contentSignature":"2f140fa506ccf3cff0e12a43316fa6fc595272a7facc7a750b2721ed717ca0d4"}],"contentSignature":"88e19ac4dcba32b87f6bdaa223d1484cb06ecfe32ed81dc8e3a33b2d7e17326c","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-301","sourceNumber":301,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"On dissolution, the account prepared to record the sale of assets and settlement of liabilities is the:","options":["REALISATION account","Trading account","Revaluation account","P&L appropriation account"],"answer":0,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"The realisation account collects assets sold and liabilities discharged; its balance (profit/loss on dissolution) goes to partner capitals in profit ratio. [Recall 2021]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounts & dissolution","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"551194dafd1c279577e54a345c98071b061fe96b92f93b0d606d020fdaa5b427","kind":"mcq"},{"id":"corp404-302","sourceNumber":302,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"An LLP under the LLP Act, 2008 is:","options":["A society registered under the Societies Registration Act, 1860, carrying on its activities on a non-profit basis for the members","A BODY CORPORATE with separate legal personality and perpetual succession, whose partners have LIMITED liability","A company limited by guarantee","A partnership whose partners have unlimited liability"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 3: an LLP is a body corporate, a legal entity separate from its partners, with perpetual succession - combining partnership flexibility with company-style limited liability.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Limited Liability Partnership (LLP)","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An LLP under the LLP Act, 2008 is:","options":["A society","A BODY CORPORATE with separate legal personality and perpetual succession, whose partners have LIMITED liability","A company limited by guarantee","A partnership with unlimited liability"],"answer":1,"explanation":"Section 3: an LLP is a body corporate, a legal entity separate from its partners, with perpetual succession - combining partnership flexibility with company-style limited liability. [Original]","revision":"original","contentSignature":"3209d2f6ad5a0f86a07aa8eaed66132c2d66323a31f1617781b1e772ce306a55"}],"contentSignature":"d2a5b0b78605a99794ea85090d1c717b354676bd26be12473d5052e909d7e3a3","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-303","sourceNumber":303,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The liability of a partner of an LLP is limited to:","options":["His AGREED CONTRIBUTION to the LLP","The total debts of the firm","Nothing at all","Ten times the capital he contributed"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Partners are liable only up to their agreed contribution - unlike traditional partners, who are personally and unlimitedly liable.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Limited Liability Partnership (LLP)","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The liability of a partner of an LLP is limited to:","options":["His AGREED CONTRIBUTION to the LLP","The firm total debts","Nothing at all","Ten times his capital"],"answer":0,"explanation":"Partners are liable only up to their agreed contribution - unlike traditional partners, who are personally and unlimitedly liable. [Original]","revision":"original","contentSignature":"e16098eddd9381b7742e5bbd32ba8c7e0fbf17d4ccdb00a12f9b5b5ba7cc2d9a"}],"contentSignature":"4f9d686925534a43c0f15886dccdb5171ecc770d6f1b810dc283c1a85a5be571","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-304","sourceNumber":304,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In an LLP, a partner is an agent of:","options":["The Registrar of Companies","The creditors of the LLP","The LLP - but NOT of the other partners","The other partners of the LLP, and never the LLP itself"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 26-27: a partner binds the LLP by his acts, but one partner is not liable for the unauthorised or wrongful acts of another - mutual agency is curtailed.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Limited Liability Partnership (LLP)","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In an LLP, a partner is an agent of:","options":["The Registrar","The creditors","The LLP - but NOT of the other partners","The other partners"],"answer":2,"explanation":"Section 26-27: a partner binds the LLP by his acts, but one partner is not liable for the unauthorised or wrongful acts of another - mutual agency is curtailed. [Original]","revision":"original","contentSignature":"d31bbc32d5735da1c1717c6b13845cb4fbac8b1e0872354dfb7171053ba544c8"}],"contentSignature":"1b63130e99f5d37d3a3fd6e01526530d90ab7417c9cc6ca4e02a4a0000184955","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-305","sourceNumber":305,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The minimum number of partners in an LLP is ________, of whom at least ________ must be DESIGNATED partners who are individuals, at least one of them resident in India.","options":["2; 2","50; 5","2; 1","7; 2"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"LLP Act ss.5-7: minimum two partners and at least two designated individual partners, one resident in India; there is no maximum.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Limited Liability Partnership (LLP)","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"c3f8570a0a7ef704278bd2805cf5886a47fae0354c1216851db03ec7a45c664c","kind":"mcq"},{"id":"corp404-306","sourceNumber":306,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The internal mutual rights and duties of an LLP and its partners are governed by:","options":["The deed of settlement executed by the partners at the time of the formation of the LLP","The Indian Partnership Act, 1932","Table F of the Companies Act","The LLP AGREEMENT (the Act applies default rules where the agreement is silent)"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"The LLP agreement is the charter of mutual rights; Schedule I default rules fill the gaps.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Limited Liability Partnership (LLP)","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The internal mutual rights and duties of an LLP and its partners are governed by:","options":["The deed of settlement","The Partnership Act, 1932","Table F","The LLP AGREEMENT (the Act applies default rules where the agreement is silent)"],"answer":3,"explanation":"The LLP agreement is the charter of mutual rights; Schedule I default rules fill the gaps. [Original]","revision":"original","contentSignature":"a56dc4acdac4c3119a8f24b31f044712a909021a62ab5f843b34a22b95a26ac7"}],"contentSignature":"960464f4558a0ed064b2dda51bf60dc82d89840dd47b797cce51c18c5778d4d6","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-307","sourceNumber":307,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The accounts of an LLP must be audited when its contribution exceeds ________ OR its turnover exceeds ________ (Rule 24(8) of the LLP Rules).","options":["Rs.1 crore; Rs.10 crore","Rs.40 lakh; Rs.25 lakh","Rs.5 lakh; Rs.10 lakh","Rs.25 lakh; Rs.40 lakh"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Rule 24(8): audit is mandatory when contribution exceeds Rs.25 lakh or turnover exceeds Rs.40 lakh - verified unchanged as of 2025.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Limited Liability Partnership (LLP)","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"ac991e2a4e0ed4cd170d2cb4aa5be1a6d6d3d80e37cdb6d5c26ae2199aa99d76","kind":"mcq"},{"id":"corp404-308","sourceNumber":308,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"An LLP may be wound up by the ________ on grounds including inability to pay debts, acting against sovereignty/security, or just and equitable grounds.","options":["Registrar of Firms of the State concerned","District Collector","NATIONAL COMPANY LAW TRIBUNAL (Tribunal)","High Court"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"Sections 63-64: the Tribunal winds up LLPs; petitions may be filed by the LLP, partners, creditors, the Registrar or the Central Government in specified cases. [Recall 2021]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Limited Liability Partnership (LLP)","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An LLP may be wound up by the ________ on grounds including inability to pay debts, acting against sovereignty/security, or just and equitable grounds.","options":["Registrar of Firms","District Collector","NATIONAL COMPANY LAW TRIBUNAL (Tribunal)","High Court"],"answer":2,"explanation":"Sections 63-64: the Tribunal winds up LLPs; petitions may be filed by the LLP, partners, creditors, the Registrar or the Central Government in specified cases. [Recall 2021]","revision":"original","contentSignature":"7ac9aa96acf819e8b0843479b763e672f42ee8e9115373b3faa50894571837c4"}],"contentSignature":"6c2f4835447e1f7e729c0b113023fbc4c0a836a035f905ef136ea3d1f6714bac","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-309","sourceNumber":309,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following is NOT valid for an LLP under the LLP Act, 2008?","options":["It must have at least two partners","It is a body corporate with perpetual succession and a common seal","It can be formed to carry on CHARITABLE or non-profit activities","Its partners carry limited liability"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2022","explanation":"An LLP is formed to carry on a lawful BUSINESS WITH A VIEW TO PROFIT (s.2(1)(e)) - charitable/non-profit ventures cannot use the LLP form. [Recall 2022]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Limited Liability Partnership (LLP)","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is NOT valid for an LLP under the LLP Act, 2008?","options":["It must have at least two partners","It is a body corporate with perpetual succession","It can be formed to carry on CHARITABLE or non-profit activities","Its partners have limited liability"],"answer":2,"explanation":"An LLP is formed to carry on a lawful BUSINESS WITH A VIEW TO PROFIT (s.2(1)(e)) - charitable/non-profit ventures cannot use the LLP form. [Recall 2022]","revision":"original","contentSignature":"9e9a3f7d060eeef43b3a5eb3daa5e21e4483850e5f7b2ce6c163a23381a90425"}],"contentSignature":"3716cb83f1e538368b55e5cb7f240746cf863f4721a00cac5f6cf1bd2e59387f","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-310","sourceNumber":310,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Making a FALSE STATEMENT in any return, statement or document under the LLP Act, knowing it to be false, is punishable under:","options":["Section 447 of the Companies Act, 2013, alone and by itself, and no other provision","No provision of any enactment","SECTION 37 of the LLP Act, 2008 (imprisonment up to 2 years and fine)","Section 11 of the LLP Act, 2008"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"Section 37 penalises false statements made knowingly to mislead - imprisonment up to two years plus fine.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Limited Liability Partnership (LLP)","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Making a FALSE STATEMENT in any return, statement or document under the LLP Act, knowing it to be false, is punishable under:","options":["Section 447 of the Companies Act only","No section","SECTION 37 of the LLP Act, 2008 (imprisonment up to 2 years and fine)","Section 11"],"answer":2,"explanation":"Section 37 penalises false statements made knowingly to mislead - imprisonment up to two years plus fine.","revision":"original","contentSignature":"70d601e0fbe4e8d57ceac749e8467b26f0e572d6c294b3b940e8e977751087b7"}],"contentSignature":"a3fa7b385ef0e7aeeb5f2a312efaa1267dd9c02407ab972542401488c26d059b","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-311","sourceNumber":311,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A partnership firm or a private/unlisted company CAN be converted into an LLP under Sections ________ of the LLP Act, subject to conditions.","options":["55 to 57","70 to 72","63 to 65","1 to 3"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Sections 55-57 with the Second-Fourth Schedules allow conversion of firms and companies into LLPs, with licences and property vesting in the LLP.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8ae87565a2886439871f80d00baf0d637fa53e8f17bc76b29fb643e98004d5c1","kind":"mcq"},{"id":"corp404-312","sourceNumber":312,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Every company must have at least one director who has stayed in India for a total period of not less than ________ in the financial year (resident director).","options":["182 days","365 days","90 days","30 days"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 149(3): every company needs at least one director who stayed in India for 182 days or more in the financial year.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"4152b759bf041ea793894e94541907371814a77c8408cdd5685b1fbfc7c60771","kind":"mcq"},{"id":"corp404-313","sourceNumber":313,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Every LISTED public company must have at least ________ of the total number of directors as INDEPENDENT directors.","options":["one-fourth","one-half","two-thirds","one-third"],"answer":3,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Section 149(4): listed public companies need at least one-third independent directors; specified large unlisted public companies need at least two (Rule 4). [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8b806fed0ad180f026f6bfdf88d3064b7da19a642568c17acfec292a671aa7fa","kind":"mcq"},{"id":"corp404-314","sourceNumber":314,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following companies must appoint at least one WOMAN director?","options":["All private companies registered in India","Only the companies registered under Section 8","Only the banking companies","Every LISTED company and every public company with paid-up capital of Rs.100 crore+ or turnover of Rs.300 crore+"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 149(1) proviso with Rule 3: the woman-director rule covers listed companies and the large public-company class.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following companies must appoint at least one WOMAN director?","options":["All private companies","Only Section 8 companies","Only banks","Every LISTED company and every public company with paid-up capital of Rs.100 crore+ or turnover of Rs.300 crore+"],"answer":3,"explanation":"Section 149(1) proviso with Rule 3: the woman-director rule covers listed companies and the large public-company class. [Original]","revision":"original","contentSignature":"dca945e5dfe48605745472b53417c9f55e6a3ba99eb90d748baf4333c7c215e3"}],"contentSignature":"f5eca1d199057f0080df2306b4e0e1552f4d12051f4f57eaad5e91207a69ad01","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-315","sourceNumber":315,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"\"Key managerial personnel\" under Section 2(51) includes all of the following EXCEPT:","options":["Chief Executive Officer / Managing Director / Manager","The statutory auditor","Chief Financial Officer","Company Secretary"],"answer":1,"source":"Corporate Accounting 404 Bank — Recall 2022","explanation":"KMP = MD/CEO/manager, whole-time director, CFO, CS and designated officers - the auditor is an independent outsider, not KMP. [Recall 2022]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"13563ddbd0c153c60fd2fbc13f0b4a24f32cb9271986a42a9a42d25330767f9b","kind":"mcq"},{"id":"corp404-316","sourceNumber":316,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A person is appointed as a director through allotment of a:","options":["DIN (Director Identification Number) under Section 153","TAN (Tax Deduction Account Number) of the company concerned","PAN (Permanent Account Number)","GSTIN under the GST law"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 153: no person can be appointed director without a DIN allotted on application to the Central Government.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A person is appointed as a director through allotment of a:","options":["DIN (Director Identification Number) under Section 153","TAN","PAN","GSTIN"],"answer":0,"explanation":"Section 153: no person can be appointed director without a DIN allotted on application to the Central Government. [Original]","revision":"original","contentSignature":"b26886ea74b445fcb533dbf59aeb9ff54d715db008e585a815cc7a473f5261ca"}],"contentSignature":"f247bd3594785e675560e3fb673c5137c77a700ca367eb80b868c389bfed95cb","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-317","sourceNumber":317,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under Section 152(6), at least ________ of the total directors of a public company are liable to retire by rotation, and ________ of them retire at each AGM.","options":["two-thirds; one-third of that rotational class","three-fourths; one-fourth of that class of directors","one-half; one-half of that class","one-third; the whole of that class"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Two-thirds of directors are rotational; one-third of the rotational directors (nearest to that number) retire by rotation at every AGM and may be re-appointed.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under Section 152(6), at least ________ of the total directors of a public company are liable to retire by rotation, and ________ of them retire at each AGM.","options":["two-thirds; one-third of that rotational class","three-fourths; one-fourth","one-half; one-half","one-third; all"],"answer":0,"explanation":"Two-thirds of directors are rotational; one-third of the rotational directors (nearest to that number) retire by rotation at every AGM and may be re-appointed. [Original]","revision":"original","contentSignature":"5310a6112745d2246fba2a64f194503fba317c4ebbac56ff455aa206ed2c7cad"}],"contentSignature":"6c6be279b3bce3067dea48600c33bc67baa2ba164197ed2a174afeb8b6c6310d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-318","sourceNumber":318,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"An independent director holds office for a term of up to ________ consecutive years, renewable for one more term by special resolution.","options":["5","10","3","2"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 149(10)-(11): an independent director serves up to five consecutive years per term, two terms maximum on the Board (then a 3-year cooling off).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"eb6c14570979661c5a431e3f270e749722eb6fa9510bb76d5df532309a3e991a","kind":"mcq"},{"id":"corp404-319","sourceNumber":319,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"At the FIRST Board meeting of every financial year, and whenever there is a change, every director discloses his concern or interest in other entities in Form:","options":["AOC-4","SH-9","DIR-12","MBP-1"],"answer":3,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Section 184(1) with Rule 9: disclosure of interest by directors goes in Form MBP-1 - the classic recall item.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"07ac40d5b12f51f9038ea1d4a96904c325d5245109caa9962bf0d8789ad14fa7","kind":"mcq"},{"id":"corp404-320","sourceNumber":320,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Contracts or arrangements with RELATED PARTIES (s.188) generally require:","options":["No approval from any quarter","The permission of the Reserve Bank of India","The approval of all the employees","Consent of the BOARD at a meeting (and prior shareholder approval for prescribed large transactions), with related parties abstaining"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 188: Board approval for listed related-party transactions; prescribed thresholds need an ordinary resolution, interested members abstaining.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Contracts or arrangements with RELATED PARTIES (s.188) generally require:","options":["No approval ever","Permission of the RBI","Approval of all employees","Consent of the BOARD at a meeting (and prior shareholder approval for prescribed large transactions), with related parties abstaining"],"answer":3,"explanation":"Section 188: Board approval for listed related-party transactions; prescribed thresholds need an ordinary resolution, interested members abstaining. [Original]","revision":"original","contentSignature":"22fb46e8f3292748a860cacce415367afae42a8f973687deee528527ae4e82b0"}],"contentSignature":"183cd46e7d58f7e31371400f344846043032b209f3f58b98e7e10de199db05fe","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-321","sourceNumber":321,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The gap between two consecutive Board meetings of a company must NOT exceed:","options":["90 days","120 days","60 days","180 days"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 173(1): at least four Board meetings every year, with not more than 120 days between two meetings.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"bd640ad11bae19c6448570456d8acdad1ec18a0c4057d17ad3bdb981ad7c4d26","kind":"mcq"},{"id":"corp404-322","sourceNumber":322,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The first Board meeting of a company must be held within ________ of the date of incorporation.","options":["60 days","30 days","180 days","90 days"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 173(1): the first Board meeting is held within 30 days of incorporation.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"a21c05b90f2cd296ed1799bb1b705cf042e010d5d80d3f5602780375b93e8ab0","kind":"mcq"},{"id":"corp404-323","sourceNumber":323,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The Registrar of Companies (ROC) functions under the administrative control of the:","options":["Ministry of Corporate Affairs (MCA)","The Finance Commission","The Securities and Exchange Board of India","The Reserve Bank of India"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 396: ROCs covering the States/UTs are appointed under the Ministry of Corporate Affairs; incorporations and filings go to them.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The Registrar of Companies (ROC) functions under the administrative control of the:","options":["Ministry of Corporate Affairs (MCA)","Finance Commission","SEBI","RBI"],"answer":0,"explanation":"Section 396: ROCs covering the States/UTs are appointed under the Ministry of Corporate Affairs; incorporations and filings go to them. [Original]","revision":"original","contentSignature":"3a7aba36593865975191a8dac361f68fc989c00c4313999ac802eeb91ea0a75a"}],"contentSignature":"16c84aae68e76e4bf726b5ea8dba943ae53620a53803e24ccea12c71e034a293","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-324","sourceNumber":324,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"MCA21 is:","options":["A database of directors maintained by SEBI","An index of the stock exchange","The e-governance PORTAL of the Ministry of Corporate Affairs for online filing of company documents and compliances","A form for filing tax returns"],"answer":2,"source":"Corporate Accounting 404 Bank — PYQ: SSC CGL Tier-2 AAO, 2019-Sep","explanation":"MCA21 lets companies file incorporation forms, annual returns and financial statements online with the ROC.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"MCA21 is:","options":["A directors database of SEBI","A stock exchange index","The e-governance PORTAL of the Ministry of Corporate Affairs for online filing of company documents and compliances","A tax return form"],"answer":2,"explanation":"MCA21 lets companies file incorporation forms, annual returns and financial statements online with the ROC.","revision":"original","contentSignature":"a304420bc573a168ffac28c45a9ba90f7cf1309f15b29deaee6e1d19ce4c9878"}],"contentSignature":"11d271d9645d41313998cac304b7e5a2209c274e8bf8c11542cddeaea2094333","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"pyq"},{"id":"corp404-325","sourceNumber":325,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Under SEBI (Substantial Acquisition of Shares and Takeovers) Regulations, any person acquiring shares carrying ________ or more of the voting rights of a listed company must make an event-based disclosure.","options":["25%","1%","5%","10%"],"answer":2,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"SAST Regulation 29: the initial disclosure trigger is 5% of shares or voting rights (the open-offer trigger is 25% under Regulation 3). [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"00808d76858bf4d1b0d16d036758cb35222c11bae58f915d7d6ae25ff736df69","kind":"mcq"},{"id":"corp404-326","sourceNumber":326,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A company may be wound up by the NCLT (Tribunal) under Section 271 on all the following grounds EXCEPT:","options":["Acts against the sovereignty/integrity of India or public order","Failure to file financial statements or annual returns for five consecutive financial years","Special resolution to be wound up by the Tribunal","A fall in the market price of its shares"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 271 grounds: special resolution, acts against the State, fraudulent conduct, five-year filing default, and just-and-equitable - not market-price movements.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"dcc2773d2bb4cbb803da9906ee80af7b7d622b3daa7bdb116fa213e4d22e4453","kind":"mcq"},{"id":"corp404-327","sourceNumber":327,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Corporate insolvency resolution and liquidation of companies in default is now primarily governed by:","options":["The Insolvency and Bankruptcy Code, 2016","The Companies Act, 1956","The SARFAESI Act, 2002 alone","The Indian Partnership Act, 1932, as amended"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"The IBC 2016 took over insolvency resolution and liquidation of corporate debtors before the NCLT; the Companies Act voluntary-winding-up provisions were omitted.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Corporate insolvency resolution and liquidation of companies in default is now primarily governed by:","options":["The Insolvency and Bankruptcy Code, 2016","The Companies Act, 1956","SARFAESI only","The Partnership Act, 1932"],"answer":0,"explanation":"The IBC 2016 took over insolvency resolution and liquidation of corporate debtors before the NCLT; the Companies Act voluntary-winding-up provisions were omitted. [Original]","revision":"original","contentSignature":"e64affc27f0ef9082a0172772b2ceda1dc2ae2410a7c45069af8947b477f1633"}],"contentSignature":"4fb76753e26b0411df47bc89097f969eb07811a4b8eae0f71329868ab6225d5a","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-328","sourceNumber":328,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A \"dormant company\" under Section 455 is one which is:","options":["In the course of liquidation","Incorporated outside India","Formed for a future project or to hold an asset/IP and has no significant accounting transactions, and obtains dormant status from the ROC","Owned by the Central or a State Government"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 455: companies with no significant transactions may apply for dormant status, reducing compliance burden while retaining corporate existence.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A \"dormant company\" under Section 455 is one which is:","options":["In liquidation","A foreign company","Formed for a future project or to hold an asset/IP and has no significant accounting transactions, and obtains dormant status from the ROC","A Government company"],"answer":2,"explanation":"Section 455: companies with no significant transactions may apply for dormant status, reducing compliance burden while retaining corporate existence. [Original]","revision":"original","contentSignature":"629efc7dbd38e7bb649be92d4272149b62dd69f57845f53e2ef83e751e3c4bd3"}],"contentSignature":"19ba64937b5744d34cb18c3dde8a3b6ab11ead3eacab8a97c740524ae6b3612c","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-329","sourceNumber":329,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A PRODUCER company (Part IXA, Sections 378A-378ZU) can be formed by:","options":["Any ten traders engaged in the produce trade","Ten or more PRODUCERS (farmers/producers of primary produce) or two or more producer institutions, dealing in produce of its members","State Governments alone","Listed companies alone"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Producer companies organise farmers/producers; membership is open only to primary producers or producer institutions.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A PRODUCER company (Part IXA, Sections 378A-378ZU) can be formed by:","options":["Any ten traders","Ten or more PRODUCERS (farmers/producers of primary produce) or two or more producer institutions, dealing in produce of its members","Only State Governments","Only listed companies"],"answer":1,"explanation":"Producer companies organise farmers/producers; membership is open only to primary producers or producer institutions. [Original]","revision":"original","contentSignature":"be07e86e4f475f8d9d159c67ff9e1f4e354c3d2ee8ed5f71624c771c4584c21d"}],"contentSignature":"abdeca0b22a3df0c32fdbc54484ed64ace751d661bf94ed3f0383b0ce64a834c","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-330","sourceNumber":330,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The registered office of a company must be verified with the Registrar within ________ of incorporation.","options":["One year","30 days","90 days","15 days"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Section 12(2): verification of the registered office is filed within 30 days of incorporation; changes are also notified.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Directors, governance & company compliance","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"f7589114e8bbe57c5cd6eb54949754bd2371d37525b12ca16b23dd1b93f94ad4","kind":"mcq"},{"id":"corp404-331","sourceNumber":331,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A bill of exchange, under Section 5 of the Negotiable Instruments Act, 1881, is: order of) a certain person or the bearer","options":["An instrument in writing containing an UNCONDITIONAL ORDER, signed by the maker, directing a person to pay a certain sum to (or to the","An order addressed to a bank to pay","A letter of credit issued by a bank","A receipt acknowledging delivery of goods"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Three parties: the DRAWER (maker), the DRAWEE (directed to pay, who becomes acceptor) and the PAYEE.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A bill of exchange, under Section 5 of the Negotiable Instruments Act, 1881, is: order of) a certain person or the bearer","options":["An instrument in writing containing an UNCONDITIONAL ORDER, signed by the maker, directing a person to pay a certain sum to (or to the","An order to pay a bank","A letter of credit","A receipt for goods"],"answer":0,"explanation":"Three parties: the DRAWER (maker), the DRAWEE (directed to pay, who becomes acceptor) and the PAYEE.","revision":"original","contentSignature":"c182e7b5ed4140106cf87e7b1b104067d3de97626ab0fef8d1b3890c885f1348"}],"contentSignature":"278f885f5a4bc2d9647187f42b282aac4c47e274284e7ebf5bbcdf081292f785","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-332","sourceNumber":332,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The drawee of a bill becomes liable on it only after he:","options":["ACCEPTS it by signing (usually writing accepted) on the face of the bill","Pays the stamp duty on the bill","Registers the bill with the authority concerned for recording its execution","Receives the bill from the drawer"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Acceptance is the drawee assent to the order; before acceptance the drawer alone is liable on the bill.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The drawee of a bill becomes liable on it only after he:","options":["ACCEPTS it by signing (usually writing accepted) on the face of the bill","Pays stamp duty","Registers the bill","Receives the bill"],"answer":0,"explanation":"Acceptance is the drawee assent to the order; before acceptance the drawer alone is liable on the bill. [Original]","revision":"original","contentSignature":"3303c4d8f20b5a3d4130dd66fe54077b6207bbc6f56139c00ae85f948fb401a8"}],"contentSignature":"47df2e86757b8c6aee7adb2dd4bc9df7c66113ac1b3d7539e8daf65c9aca3963","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-333","sourceNumber":333,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Days of grace allowed on a usance bill of exchange are:","options":["Seven days added to the nominal due date","Nil; the bill matures on the nominal due date","THREE days added to the nominal due date","Thirty days added to the nominal due date"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Every usance bill matures three days after the day it is nominally due - e.g. a 2-month bill dated 30 November falls due on 2 February.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Days of grace allowed on a usance bill of exchange are:","options":["Seven days","Nil","THREE days added to the nominal due date","Thirty days"],"answer":2,"explanation":"Every usance bill matures three days after the day it is nominally due - e.g. a 2-month bill dated 30 November falls due on 2 February. [Original]","revision":"original","contentSignature":"c21363ab57df9167f1b5e9b3bc842a6bbca6bf57887b3336391146a30173db6a"}],"contentSignature":"e05ad859fc862aeef1056694802ff1997a99d1c2f138216abc7fbe2a2d7ee126","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-334","sourceNumber":334,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A bill dated 15 January at 3 months matures on:","options":["15 March","15 April","17 April","18 April"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Nominal due date 15 April + 3 days of grace = 18 April.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"3f70227011522df627ba89d5d287140ff2681b8257f8584e04f041ac345a95ce","kind":"mcq"},{"id":"corp404-335","sourceNumber":335,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A bill drawn for a fixed period AFTER SIGHT is payable:","options":["After acceptance, with the period counted from the date of ACCEPTANCE (or noting for non-acceptance)","Immediately on presentation to the drawee","From the date on which the bill is drawn","On presentation at any time at the holder's choice, whether or not the drawee has accepted the bill drawn"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"An after-sight bill needs acceptance to fix its start date; an after-date bill runs from its date.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A bill drawn for a fixed period AFTER SIGHT is payable:","options":["After acceptance, with the period counted from the date of ACCEPTANCE (or noting for non-acceptance)","Immediately","From the date of drawing","On presentation at any time"],"answer":0,"explanation":"An after-sight bill needs acceptance to fix its start date; an after-date bill runs from its date. [Original]","revision":"original","contentSignature":"99aba6f7b9d78f2ed4d68c6e0240fcdaf9ba466cd4fb31a6267dd266ba34a87a"}],"contentSignature":"922760ba97313977bea67e6b1967225953180952a2039ac97fcd0e952b632d32","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-336","sourceNumber":336,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"When a bill is DISHONOURED by non-payment, the payee gets the fact officially recorded by a Notary Public - this is called:","options":["Discounting of the bill by the payee with the bank","Retirement of the bill","NOTING (and the certificate is the PROTEST)","Endorsement of the bill"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Noting records the dishonour with a notary; the protest is the formal notarial certificate of dishonour - strong evidence in court.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"When a bill is DISHONOURED by non-payment, the payee gets the fact officially recorded by a Notary Public - this is called:","options":["Discounting","Retirement","NOTING (and the certificate is the PROTEST)","Endorsement"],"answer":2,"explanation":"Noting records the dishonour with a notary; the protest is the formal notarial certificate of dishonour - strong evidence in court. [Original]","revision":"original","contentSignature":"3a8e978dc60920f3e406473a390d5cb1c07b870ac40c64bf0f2fb4e77317a0f9"}],"contentSignature":"8fbd69d3e5388bd8ba522caf2ca4c7b6e4cc2acac95f75c5cc51eb1bcaf22f67","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-337","sourceNumber":337,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Noting charges on a dishonoured bill are ultimately borne by:","options":["The notary public who records the dishonour of the bill of exchange","The bank where the bill was presented","The DRAWEE (acceptor), because the dishonour is his default","The drawer of the bill"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"The holder pays the notary first but recovers noting charges from the defaulting acceptor along with the bill amount.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Noting charges on a dishonoured bill are ultimately borne by:","options":["The notary","The bank","The DRAWEE (acceptor), because the dishonour is his default","The drawer"],"answer":2,"explanation":"The holder pays the notary first but recovers noting charges from the defaulting acceptor along with the bill amount. [Original]","revision":"original","contentSignature":"07a04b0aad3865aab0d97b9167049321bfd2af8823313f74dc585911d1329a77"}],"contentSignature":"c03160156e42468f842c272e199d19220ff922a3c13dc94a0b51a275a5422638","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-338","sourceNumber":338,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A bill of Rs.10,000 is dishonoured on maturity and noting charges of Rs.100 are paid. The drawee account is debited with:","options":["Rs.10,100","Rs.9,900","Rs.100","Rs.10,000"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Drawee Dr. 10,100 (bill 10,000 + noting 100) -> To Bills Receivable 10,000, To Cash 100.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"2a55fcc9caa2ed876a43e55cb7f2554fa73370a7e9fe67b4c6849107d2b2a230","kind":"mcq"},{"id":"corp404-339","sourceNumber":339,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"When a bill is DISCOUNTED with a bank, the drawer receives:","options":["Twice the face value of the bill from the bank that discounts the bill for him","Face value MINUS discounting charges (interest for the unexpired period)","Nothing until the bill matures","The full face value of the bill"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Bank Dr. and Discount A/c Dr. -> To Bills Receivable; discount = face x rate x unexpired period.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"When a bill is DISCOUNTED with a bank, the drawer receives:","options":["Twice the value","Face value MINUS discounting charges (interest for the unexpired period)","Nothing until maturity","The full face value always"],"answer":1,"explanation":"Bank Dr. and Discount A/c Dr. -> To Bills Receivable; discount = face x rate x unexpired period. [Original]","revision":"original","contentSignature":"5e1feaa8160fc2f6552fa60f123274c44aac8da43174e01272f3f2db59c395d0"}],"contentSignature":"c6a4b6b30d2b7bbd5e7fab77f30a4d507ef6c68a8eedbbcca40de45e27a907de","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-340","sourceNumber":340,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A bill of Rs.10,000 due after 2 months is discounted with a bank at 12% p.a. The discount charged is:","options":["Rs.100","Rs.600","Rs.1,200","Rs.200"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Discount = 10,000 x 12% x 2/12 = Rs.200.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"426ac973d34d37d8e3ce5fc0456627b8af6be6f9384cb64be0f42d7ed90b1671","kind":"mcq"},{"id":"corp404-341","sourceNumber":341,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"If a discounted bill is dishonoured at maturity, the bank recovers from the:","options":["PERSON WHO DISCOUNTED IT (the drawer/customer) with noting charges","The notary public who noted the dishonour of the bill on its maturity","The payee of the bill alone","The acceptor of the bill alone"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"The bank debits the customer: Drawee Dr. (face + noting) -> To Bank; the drawer then pursues the acceptor.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"If a discounted bill is dishonoured at maturity, the bank recovers from the:","options":["PERSON WHO DISCOUNTED IT (the drawer/customer) with noting charges","Notary","Payee only","Acceptor only"],"answer":0,"explanation":"The bank debits the customer: Drawee Dr. (face + noting) -> To Bank; the drawer then pursues the acceptor.","revision":"original","contentSignature":"4380e6e10981b224a98ec1669cf1a1b46c2ffb90c5cf6398b6ffdd6a426ee050"}],"contentSignature":"e7c77d94d08026d52ba9f33daf98b2098f18d6f4ddd33a90726d0eb92c99b2a5","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-342","sourceNumber":342,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Renewal of a bill means:","options":["Paying the bill before its due date","Getting the bill formally protested","Cancelling the old bill (as dishonoured), charging interest for delay, and drawing a NEW bill for the extended period","Endorsing the bill in favour of a friend"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"On the drawee request, the old bill is cancelled, interest for the extension is settled, and a fresh bill (amount + interest) is drawn.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Renewal of a bill means:","options":["Paying the bill early","Protesting it","Cancelling the old bill (as dishonoured), charging interest for delay, and drawing a NEW bill for the extended period","Endorsing it to a friend"],"answer":2,"explanation":"On the drawee request, the old bill is cancelled, interest for the extension is settled, and a fresh bill (amount + interest) is drawn. [Original]","revision":"original","contentSignature":"687a45a6258edcb79a29c392a57f4c601f02d5adf612a2d3d20fb29e9f4f9b9a"}],"contentSignature":"ab99f76a341b43e224aae7125aac0e0eeb7f0ded995f2774d44bf8d255c35f5d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-343","sourceNumber":343,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"When a bill is RETIRED (paid) before its due date, the acceptor is generally allowed a:","options":["A bonus share of the company","A noting charge for early payment","A penalty for early payment","REBATE/discount for early payment"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Rebate at the agreed rate for the unexpired period is deducted from the payment made on early retirement.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"When a bill is RETIRED (paid) before its due date, the acceptor is generally allowed a:","options":["Bonus share","Noting charge","Penalty","REBATE/discount for early payment"],"answer":3,"explanation":"Rebate at the agreed rate for the unexpired period is deducted from the payment made on early retirement.","revision":"original","contentSignature":"3301fd9e2914863e54501fbbb8003f64fbf479ed41bd33336d9d135f0f2ef6a9"}],"contentSignature":"5aeb78fff3d8577c9e4aea2d5dde9225888b7ac088dd7a6bbef64daaedcadc46","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-344","sourceNumber":344,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"An ACCOMMODATION bill differs from a trade bill in that it is drawn:","options":["WITHOUT any trade consideration - to provide finance to one or both parties","By the Government for its transactions of a public nature with the citizens","Against an actual sale of goods","Only on the banking companies"],"answer":0,"source":"Corporate Accounting 404 Bank — Original","explanation":"Accommodation (kite) bills raise money through mutual accommodation; the drawer and acceptor share the proceeds as agreed.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An ACCOMMODATION bill differs from a trade bill in that it is drawn:","options":["WITHOUT any trade consideration - to provide finance to one or both parties","By the Government","Against actual sale of goods","Only on banks"],"answer":0,"explanation":"Accommodation (kite) bills raise money through mutual accommodation; the drawer and acceptor share the proceeds as agreed. [Original]","revision":"original","contentSignature":"89e1931781bb99cb581fb6f0da34baa8864f0d22f8bbdaf41275c84548b93886"}],"contentSignature":"2b72388a01f3328d99e0709c7075d944c245ced944d06b324eeaddd41dbaab82","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-345","sourceNumber":345,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Endorsement of a bill means:","options":["Affixing the stamp required by law on the instrument before it is presented for payment at maturity","Cancelling the instrument so that it cannot be used","Refusing to make payment on the instrument","Signing on the back (or face) of the instrument to TRANSFER the right to receive payment to another"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"The endorser transfers his rights to the endorsee by signing - with or without restricting further negotiation.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Bills of exchange","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Endorsement of a bill means:","options":["Stamping it","Cancelling it","Dishonouring it","Signing on the back (or face) of the instrument to TRANSFER the right to receive payment to another"],"answer":3,"explanation":"The endorser transfers his rights to the endorsee by signing - with or without restricting further negotiation.","revision":"original","contentSignature":"60b334626b4cb140c3c3be8218a6d53e0f84e11de65739d272cee5e82ba30fb8"}],"contentSignature":"c2a600fb43792e135d2b8ffceea0cc1992683afed11c9fa95e82924c9203f51f","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-346","sourceNumber":346,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Consignment is: remains with the consignor","options":["The despatch of goods by the owner (consignor) to his agent (consignee) to sell on the consignors account and at his risk - ownership","An outright sale of the goods to the agent","A gift of the stock to the consignee","A hire-purchase transaction with the agent"],"answer":0,"source":"Corporate Accounting 404 Bank — Recall 2018","explanation":"Possession passes, property does not: the consignee is a commission agent, and unsold goods remain the consignors stock. [Recall 2018]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consignment accounts","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Consignment is: remains with the consignor","options":["The despatch of goods by the owner (consignor) to his agent (consignee) to sell on the consignors account and at his risk - ownership","A sale to an agent","A gift of stock","A hire-purchase deal"],"answer":0,"explanation":"Possession passes, property does not: the consignee is a commission agent, and unsold goods remain the consignors stock. [Recall 2018]","revision":"original","contentSignature":"d9cda3e82577eb40d7fecd2b0c9311db128a2e0a0f6e0cf5021adbff3fed65db"}],"contentSignature":"b4227dc8a4fb64032a9095b4f5e2da97efa1510528c0b7560fb928775f9be77f","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-347","sourceNumber":347,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The document sent by the consignor along with the goods, giving details of goods and their price, is the:","options":["Debit note","PROFORMA INVOICE","Bill of lading only","Account sales"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"A proforma invoice accompanies the goods (not a real invoice, since there is no sale); the consignee reports back through account sales.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consignment accounts","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"bfbbaf764c2f62b627e3b51e0e82aac4d2ed31c9cc3fd22798aefae9ebba3054","kind":"mcq"},{"id":"corp404-348","sourceNumber":348,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"ACCOUNT SALES is a statement prepared by the:","options":["Consignor, showing the goods purchased for the period","CONSIGNEE, showing goods sold, expenses incurred, commission charged and the net proceeds due to the consignor","Bank, showing the interest earned and charged","Auditor, showing the stock held at the year-end"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"The consignee periodically renders account sales; the consignor records sales, expenses and commission from it.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consignment accounts","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"ACCOUNT SALES is a statement prepared by the:","options":["Consignor, showing purchases","CONSIGNEE, showing goods sold, expenses incurred, commission charged and the net proceeds due to the consignor","Bank, showing interest","Auditor, showing stock"],"answer":1,"explanation":"The consignee periodically renders account sales; the consignor records sales, expenses and commission from it. [Original]","revision":"original","contentSignature":"01c351d6d40ea7a9fdec3e19a119beae091e47e1670d6e082d017449f8dc7bd6"}],"contentSignature":"4f4b6cf852b96a0f8685da1482ea1a2db02be573cf1e0f510101a04238c95d94","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-349","sourceNumber":349,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"DEL CREDERE commission is paid to the consignee for:","options":["Storing the goods in his godown","Selling the goods at prices above the list price fixed by the consignor in the invoice","Advertising the goods of the consignor","GUARANTEEING COLLECTION of sale proceeds - he bears any bad debts on credit sales"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"With del credere commission, bad debts on consignment credit sales fall on the consignee, not the consignor.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consignment accounts","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"DEL CREDERE commission is paid to the consignee for:","options":["Storing goods","Selling at higher prices","Advertising","GUARANTEEING COLLECTION of sale proceeds - he bears any bad debts on credit sales"],"answer":3,"explanation":"With del credere commission, bad debts on consignment credit sales fall on the consignee, not the consignor.","revision":"original","contentSignature":"750c1f8ee22ee9cdd6bc3eaf3092f019e27dfc3224876ae89bb63b501d391913"}],"contentSignature":"80a5aac20b0b0efd3255acb2416609a20fdd50858692bd319836fba0b78caacd","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-350","sourceNumber":350,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Goods costing Rs.50,000 are sent on consignment; the consignor pays freight Rs.5,000 and the consignee pays unloading Rs.1,000 (non- recurring). If one-fifth of the goods remain unsold, the value of closing stock on consignment is:","options":["Rs.11,000","Rs.11,200","Rs.50,000","Rs.10,000"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"Cost of goods = 50,000 + 5,000 + 1,000 = 56,000; stock = 56,000 x 1/5 = Rs.11,200 (non-recurring expenses are added, selling expenses are not).","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consignment accounts","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"7bf9458a97e5a0e05122cb5f73bb1e0ee8a7b035d7b1df60928038b4294972d1","kind":"mcq"},{"id":"corp404-351","sourceNumber":351,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"NORMAL loss on consignment (evaporation, leakage inherent in the goods) is treated by:","options":["Claiming the amount from the insurer","Charging it to the personal account of the consignee","Debiting it to the profit and loss account of the consignee for the period of the consignment in question","Spreading its cost over the GOOD units - inflating their per-unit cost, with no separate entry"],"answer":3,"source":"Corporate Accounting 404 Bank — Original","explanation":"Normal loss is unavoidable, so the good units absorb it; abnormal loss (theft, fire) is separately costed and charged to abnormal loss account/P&L or insurance claim.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consignment accounts","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"NORMAL loss on consignment (evaporation, leakage inherent in the goods) is treated by:","options":["Claiming it from insurance","Charging it to the consignee","Debiting the P&L account of the consignee always","Spreading its cost over the GOOD units - inflating their per-unit cost, with no separate entry"],"answer":3,"explanation":"Normal loss is unavoidable, so the good units absorb it; abnormal loss (theft, fire) is separately costed and charged to abnormal loss account/P&L or insurance claim. [Original]","revision":"original","contentSignature":"6cc4c810e94fbfe4d5b38265e4006670855d3f53f0d594e28587366015804be1"}],"contentSignature":"564d15fe31d95988459c6a8fc3ea7a19b89fa6faf3bc19060e444172e2bd1c83","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-352","sourceNumber":352,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"ABNORMAL loss of goods on consignment is valued at:","options":["The selling price of the goods fixed by the consignor in the proforma invoice sent","The market price of the goods","COST plus proportionate non-recurring expenses up to the loss point","A nominal value of one rupee"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"Like closing stock, abnormal lost units are costed with their share of direct non-recurring costs; the abnormal loss account is closed to P&L or insurance claim.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consignment accounts","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"ABNORMAL loss of goods on consignment is valued at:","options":["Selling price","Market price","COST plus proportionate non-recurring expenses up to the loss point","Zero"],"answer":2,"explanation":"Like closing stock, abnormal lost units are costed with their share of direct non-recurring costs; the abnormal loss account is closed to P&L or insurance claim. [Original]","revision":"original","contentSignature":"9c15982f72a139e12cb7747e5fe22b51e8a34a2b744c2ac5f740d95f90a8456a"}],"contentSignature":"50ed0c48335c4506ff2ce9d5ecf1a62a096b2d7ede810e128418ea0fff8b5916","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-353","sourceNumber":353,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"When goods are sent on consignment at INVOICE PRICE (above cost), the loading (profit element) in unsold stock is adjusted through:","options":["Ignoring the loading altogether","A stock reserve, so closing stock appears at cost","Charging the loading to the consignee","Adding the loading to the capital account of the firm"],"answer":1,"source":"Corporate Accounting 404 Bank — Original","explanation":"A consignment stock reserve removes the unrealised profit in unsold goods; the consignment account then shows true profit.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consignment accounts","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"When goods are sent on consignment at INVOICE PRICE (above cost), the loading (profit element) in unsold stock is adjusted through:","options":["Ignoring it","A stock reserve, so closing stock appears at cost","Charging it to the consignee","Adding it to capital"],"answer":1,"explanation":"A consignment stock reserve removes the unrealised profit in unsold goods; the consignment account then shows true profit. [Original]","revision":"original","contentSignature":"e45f4961f1bbf468758514b1de1947f1b5869d467585073065f3848e308ab4cc"}],"contentSignature":"71e9a242bdf3de2cd44ff67b34f538ccd1eed2a7515470e890aad983e0d5d37b","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"mcq"},{"id":"corp404-354","sourceNumber":354,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Sales on consignment were Rs.1,00,000. Ordinary commission is 5% and del credere commission 2%. Total commission of the consignee and the party bearing bad debts of Rs.3,000 are:","options":["Rs.7,000; consignor","Rs.2,000; consignee","Rs.5,000; consignor","Rs.7,000; CONSIGNEE"],"answer":3,"source":"Corporate Accounting 404 Bank — Recall 2021","explanation":"Commission = 5% + 2% = 7% of 1,00,000 = Rs.7,000; because del credere commission is paid, the consignee absorbs the Rs.3,000 bad debt. [Recall 2021]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consignment accounts","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8cd89d2326ea8bf149ae07b9c463b71b2de1486103fe2b547b21b76009e001c7","kind":"mcq"},{"id":"corp404-355","sourceNumber":355,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In the books of the consignor, the profit or loss on consignment is transferred to the:","options":["Balance sheet","Capital reserve","PROFIT AND LOSS account","Trading account"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"The consignment account works like a mini trading-cum-P&L; its balance is transferred to the consignor profit and loss account.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consignment accounts","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"852351c0ca1c9e91f9098e55c465032f43dbf2de74f22fd26ba6b1b8dcc092db","kind":"mcq"},{"id":"corp404-356","sourceNumber":356,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The consignee is remunerated by way of:","options":["Salary","Dividend","COMMISSION on sales","Interest"],"answer":2,"source":"Corporate Accounting 404 Bank — Original","explanation":"The consignee works for commission (ordinary, and del credere/overriding where agreed), not for a share of consignment profit.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Consignment accounts","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"161c9f1e7a4f0ba472dd33e000ded6ab0fef4eb640b23c9aceb6b20a2d3b0bf6","kind":"mcq"},{"id":"corp404-363","sourceNumber":363,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following distinction(s) is/are NOT correct between public issue and rights issue? (1) In a public issue, applications are invited from the general public and in a rights issue shares are offered to existing shareholders. (2) In a public issue there is no question of any over- subscription and in a rights issue the shares may be under-subscribed or over-subscribed leading to pro-rata allotment. (3) The price of a public issue is generally less than the market price and in a rights issue the price is deliberately made less than the market price. (4) In a public issue, communication is through prospectus or advertisements and in a rights issue the communication is between the company and the existing members.","options":["4 only","2 only","3 and 4 only","1 and 3 only"],"answer":1,"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-25M","explanation":"Statement (2) is wrong: PUBLIC issues can also be over-subscribed - pro-rata allotment applies there too. [PYQ: UGC NET Commerce, 2021-Nov-25M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Corporate Accounting mixed revision questions","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"8d5c48abd35545f9ca8ca967dd2032b95ca0dd4b8597dff69eff1ea1055d14fa","kind":"pyq"},{"id":"corp404-364","sourceNumber":364,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following order is followed in the issue of shares under the Fixed Price Offer Method? (1) Issue of a prospectus (2) Receipt by the company of applications for shares (3) Selection of merchant banker (4) Issue of share certificates (5) Allotment of shares to the applicants","options":["3, 2, 1, 4, 5","3, 1, 2, 5, 4","1, 4, 5, 3, 2","5, 2, 1, 3, 4"],"answer":1,"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-26M","explanation":"Merchant banker first, then prospectus, applications, allotment, and finally share certificates. [PYQ: UGC NET Commerce, 2021-Nov-26M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Corporate Accounting mixed revision questions","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"34913234b05e211969798595c6ff1ecfb030b13662d4b32fcfaa715f15c8f8b4","kind":"pyq"},{"id":"corp404-366","sourceNumber":366,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Section 61 to 64 of the Companies Act, 2013 ('alteration proper') include: a) cancellation of the unissued shares b) cancellation of issued shares c) increase in share capital by issue of new shares d) decrease of share capital by redemption of shares e) conversion of fully paid shares into stock and vice versa.","options":["a, b and c only","b, c and d only","c, d and e only","a, c and e only"],"answer":3,"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2023-Jun-M - official key corrected","explanation":"Section 61 covers increase by new issue, consolidation/sub-division, conversion into stock, and cancellation of UNISSUED shares. Cancelling ISSUED shares or reduction by redemption falls under section 66 (reduction of capital). The correct set is **(a), (c) and (e)**.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Corporate Accounting mixed revision questions","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"d46c935e3da91983244334d464198a86b69c9e7aeae30abd37423082e96eb45b","kind":"pyq"},{"id":"corp404-367","sourceNumber":367,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Preference shares in India are issued by a company for a maximum period of:","options":["10 years","20 years","15 years","Unlimited period"],"answer":1,"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2022-Oct-29E","explanation":"Section 55 caps redemption at 20 years (30 years for infrastructure projects). [PYQ: UGC NET Commerce, 2022-Oct-29E]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Corporate Accounting mixed revision questions","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"efb17161f67b032e5fbd65055b79a4ed814d71409b655ddcf7ede17515a3a3ce","kind":"pyq"},{"id":"corp404-371","sourceNumber":371,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"As per Section 68 of the Companies Act, a company may purchase its own shares out of: (a) free reserves (b) securities premium account (c) general reserve (d) proceeds of any other shares (e) proceeds of the same kind of shares.","options":["b, c, d and e only","a, b, d and e only","a, b, c and d only","a, b, c and e only"],"answer":2,"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2022-Oct-29E","explanation":"Buy-back sources: free reserves (general reserve is one), securities premium, and proceeds of an earlier issue of a DIFFERENT kind - never the same kind. [PYQ: UGC NET Commerce, 2022-Oct-29E]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Corporate Accounting mixed revision questions","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"d01f8dfbfcc3f23c53fc0e55311f6531b69ae6f819039abeba02b79cd25a2286","kind":"pyq"},{"id":"corp404-372","sourceNumber":372,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"From which of the following can a company NOT buy back its own shares?","options":["Through the open market","From the employees of the company under a stock option scheme","From the odd lot shareholders","Existing equity shareholders on a disproportionate basis"],"answer":3,"source":"Corporate Accounting 404 Bank — PYQ: SSC CGL AAO, 2017","explanation":"Permitted routes: proportionately from existing shareholders, open market, odd lots, and employees - disproportionate buy-back from existing holders is barred. [PYQ: SSC CGL AAO, 2017]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Corporate Accounting mixed revision questions","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"From which of the following can a company NOT buy back its own shares?","options":["Open market","Employees of the company","Odd lot shareholders","Existing equity shareholders on a disproportionate basis"],"answer":3,"explanation":"Permitted routes: proportionately from existing shareholders, open market, odd lots, and employees - disproportionate buy-back from existing holders is barred. [PYQ: SSC CGL AAO, 2017]","revision":"original","contentSignature":"579d77afda3215762691a87c055a9f3eb0a8d7d96f6a98760a86bdbbddedeaf3"}],"contentSignature":"4772c4a5448f94bab76a844b36ec91967f5cb0cc8c0a56c8f40dd5f1844190e3","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"pyq"},{"id":"corp404-374","sourceNumber":374,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Forfeiture of shares occurs when a shareholder fails to make the required payment within the specified timeframe or as per the terms of allotment. Which journal entry is passed on forfeiture?","options":["Share Capital A/c Dr. -> To Calls in Arrears A/c, To Forfeited Shares A/c","Share Capital A/c Dr., Calls in Arrears A/c Dr. -> To Forfeited Shares A/c","Share Capital A/c Dr. -> To Forfeited Shares A/c","None of the above"],"answer":0,"source":"Corporate Accounting 404 Bank — PYQ: JAIIB AFM, 2023","explanation":"Share capital is debited with the called-up amount; calls in arrears (unpaid) and forfeited shares (paid amount) are credited. [PYQ: JAIIB AFM, 2023]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Corporate Accounting mixed revision questions","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"00d30d26ee836aa336caa91be6e9303d524bee3940e13480c8d3fc3e89fd7785","kind":"pyq"},{"id":"corp404-375","sourceNumber":375,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"In case of forfeiture of shares due to non-receipt of payment by the shareholder, which of the following accounts will be credited?","options":["Calls in Arrears A/c","Forfeited Shares A/c","Both B and C","Share Capital A/c"],"answer":2,"source":"Corporate Accounting 404 Bank — PYQ: JAIIB AFM, 2023","explanation":"Both the unpaid calls (calls in arrears) and the amount actually received (forfeited shares) are credited; share capital is debited. [PYQ: JAIIB AFM, 2023]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Corporate Accounting mixed revision questions","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"d29ed81b4a1747337cb2622904be53d35a1a6384bbc14bce28e303ba49d4a410","kind":"pyq"},{"id":"corp404-382","sourceNumber":382,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"If the value of debentures issued as purchase consideration is less than the value of the net assets taken over, the difference is credited to:","options":["Debenture account","Capital reserve account","General reserve account","Goodwill account"],"answer":1,"source":"Corporate Accounting 404 Bank — PYQ: SSC CGL AAO, 2017","explanation":"Consideration below net assets taken over is a capital profit - credited to capital reserve. [PYQ: SSC CGL AAO, 2017]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Corporate Accounting mixed revision questions","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"495054b0f60d12dbef096c46d3018916f7aa6ebd7cee8f3c4ee533ed7d5f6181","kind":"pyq"},{"id":"corp404-383","sourceNumber":383,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Who among the following are identified as Key Managerial Personnel in the Companies Act, 2013? (a) Chief Executive Officer (b) Whole Time Director (c) Company Secretary (d) Chief Risk Officer (e) Manager","options":["a, b, c and e only","a and b only","a, b and d only","a, b, c and d only"],"answer":0,"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2022-Oct-29E","explanation":"Section 2(51): CEO/MD/manager, whole-time director, CFO and CS are KMP - Chief Risk Officer is not in the list.","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Corporate Accounting mixed revision questions","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"4d1ec0f209d1a66fe2dfee12dabc162868f14ee9e8756e03098089c471549455","kind":"pyq"},{"id":"corp404-385","sourceNumber":385,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which one of the following duties is NOT a general duty of directors of a company under Section 166?","options":["Duty of good faith in order to promote the objects of the company","Duty not to delegate or assign his office","Duty to attend Board meetings","Duty of due and reasonable care, skill and diligence and to exercise independent judgement"],"answer":2,"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2022-Oct-29M","explanation":"Section 166 lists good faith, care/skill/diligence, avoiding conflict, no undue gain and no assignment of office - attending Board meetings is not a statutory duty there. [PYQ: UGC NET Commerce, 2022-Oct-29M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Corporate Accounting mixed revision questions","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"59e5aea25cba2938b662687ff5511b35ee270675553fcceb7c73e14fd9bf3358","kind":"pyq"},{"id":"corp404-388","sourceNumber":388,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"The following information is given for a company: Net profit before tax Rs.1,00,000; 10% preference share capital (Rs.10 each) Rs.1,00,000; equity share capital (Rs.10 each) Rs.1,00,000; tax at 50% of net profit. The earnings per share is:","options":["Rs.4","Zero","Rs.40","Rs.10"],"answer":0,"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2022-Oct-14M","explanation":"PAT = 50,000; preference dividend = 10,000; equity earnings = 40,000 over 10,000 equity shares = Rs.4. [PYQ: UGC NET Commerce, 2022-Oct-14M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Corporate Accounting mixed revision questions","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"196b18552feceff68bf979339dd39a65a197370ec5b65c3624f49afcd1a5ddf6","kind":"pyq"},{"id":"corp404-393","sourceNumber":393,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Which of the following will be entered on the CREDIT side of the Profit and Loss Appropriation A/c?","options":["Surplus transferred to balance sheet","Transfer to dividend/interim dividend/proposed dividend","Amount withdrawn from a general reserve or any other reserve","Transfer to reserve/general reserve"],"answer":2,"source":"Corporate Accounting 404 Bank — PYQ: JAIIB AFM, 2023","explanation":"Withdrawals FROM reserves are credited (they add to distributable profit); transfers to reserves and dividends are debits. [PYQ: JAIIB AFM, 2023]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounting revision","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"5eae61a98fefbc7f9edf3ad43e7433b70185c4c23d6237c73919c0378b3730b7","kind":"pyq"},{"id":"corp404-396","sourceNumber":396,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A, B and C are partners sharing profits in the ratio of 3:2:1. D is admitted for a 1/6 share and C retains his original share. The sacrificing ratio of A and B is:","options":["2:3","1:2","2:1","3:2"],"answer":3,"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2021-Nov-26M","explanation":"With C retaining 1/6, D's 1/6 comes wholly from A and B in their old ratio - so they sacrifice 3:2. [PYQ: UGC NET Commerce, 2021-Nov-26M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounting revision","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"9ca94fafc87e5128f6c0247f00247df29c7374b5d0766edd998a64472b3ce3f8","kind":"pyq"},{"id":"corp404-398","sourceNumber":398,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A and B share profits in the ratio 5:2. C is admitted as a partner who gets a 1/7 share, acquiring 3/28 from A and 1/28 from B. The new profit-sharing ratio is:","options":["17:7:4","16:8:4","19:5:4","15:9:4"],"answer":0,"source":"Corporate Accounting 404 Bank — PYQ: SSC CGL AAO, 2017","explanation":"A new = 5/7 - 3/28 = 17/28; B new = 2/7 - 1/28 = 7/28; C = 4/28 - ratio 17:7:4. [PYQ: SSC CGL AAO, 2017]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounting revision","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"439b0766de10bc8ade81b3453b1f783d0a70dce39285709b31d9a3cc0faf8907","kind":"pyq"},{"id":"corp404-399","sourceNumber":399,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A and B are equal partners. When the partnership is dissolved, their capitals are Rs.40,000 and Rs.50,000. After all assets are sold and liabilities paid, the cash balance is Rs.80,000. The profit or loss on realisation is:","options":["Rs.30,000 profit","Rs.20,000 profit","Rs.10,000 loss","Rs.10,000 profit"],"answer":2,"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2023-Jun-M","explanation":"Capitals owed = 90,000 but cash available = 80,000, so realisation resulted in a loss of Rs.10,000. [PYQ: UGC NET Commerce, 2023-Jun-M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"Partnership accounting revision","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"4b63f7da3627bb3b52aed9e49afc86ed6d6b24aa8fc785d3ce353346891a6046","kind":"pyq"},{"id":"corp404-401","sourceNumber":401,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"A limited liability partnership may be wound up by which one of the following?","options":["By the Registrar if the firm fails to file the annual return within 60 days of the close of the financial year","By the Tribunal established under the Companies Act, 2013","Voluntarily by its partners alone","Either voluntarily or by the Tribunal established under the Companies Act, 2013"],"answer":3,"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2022-Oct-14M","explanation":"Sections 63-64 of the LLP Act: an LLP may be wound up voluntarily or by the Tribunal. [PYQ: UGC NET Commerce, 2022-Oct-14M]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"LLP revision","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A limited liability partnership may be wound up by which one of the following?","options":["By the Registrar if the firm fails to file the annual return within 60 days of the close of the financial year","By the Tribunal established under the Companies Act, 2013","Voluntarily only","Either voluntarily or by the Tribunal established under the Companies Act, 2013"],"answer":3,"explanation":"Sections 63-64 of the LLP Act: an LLP may be wound up voluntarily or by the Tribunal. [PYQ: UGC NET Commerce, 2022-Oct-14M]","revision":"original","contentSignature":"453a6bcb10cccc8a6f10bfa0cf4a3c4fe793d130aaf63b3177a04ea89bd598ef"}],"contentSignature":"a8f7923c3373bff27f4bb99cc3a395663ad6033fc846c9e3694118cbd65f252d","legacySubject":"corporate-accounting","sourceBank":"shared","kind":"pyq"},{"id":"corp404-403","sourceNumber":403,"subject":"corporate-accounting","subjectName":"Corporate Accounting","question":"Who can file a petition to the Tribunal for the winding up of a Limited Liability Partnership? A. Secured creditors B. The LLP or any of its partners C. Registrar of Companies D. Any person authorised by the Central Government E. Any voluntary association","options":["B, C and D only","A and B only","A, B, C and D only","A, B and C only"],"answer":2,"source":"Corporate Accounting 404 Bank — PYQ: UGC NET Commerce, 2025-Jun","explanation":"Section 64: petitions may be filed by the LLP or its partners, creditors (secured or unsecured), the Registrar, or a person authorised by the Central Government - not by any voluntary association. [PYQ: UGC NET Commerce, 2025-Jun]","sourceVersion":"JVVNL Corporate Accounting 404 Expanded Explanations v1 (13 Oct 2026)","explanationStatus":"source-expanded","topic":"LLP revision","legacySubject":"corporate-accounting","sourceBank":"shared","contentSignature":"2f226853d1b10531d5ff57405b087a37e1867d1e753ffcb4362e514171816c3c","kind":"pyq"}]};
